{"content": "// zip 中央目录读取 + 写入（零依赖，只用 node:zlib）
//
// 【为什么要共享】
// verify-zip.mjs 早就会**读** zip 中央目录（不依赖 PowerShell、不解压，因为它们踩过
// "Compress-Archive 写反斜杠导致 -like '*a/b/*' 匹配到 0 = 假警报"这个坑）。
// 第 46 轮加 make-release.mjs 时，如果它自己再写一份读法，就会出现这个仓库反复记过的
// 「同一个逻辑复制成两份，就一定会分叉」。所以抽到这里，两边 import 同一份。
//
// 用法:
//   import { listZip, checkZip } from './lib/zip-central.mjs'
//   const names = listZip(path)            // string[]，`\` 已统一成 `/`
//   const r = checkZip(path, rules)        // { pass, fail, names } —— 带正例自证
import fs from 'node:fs'
import zlib from 'node:zlib'

/** 找 EOCD（End of Central Directory）。有注释的 zip 会把 EOCD 顶到后面，所以要往回扫 64 KB。 */
function findEocd(buf) {
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 66000); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) return i
  }
  return -1
}

/** 读出全部条目名（`\` 统一成 `/`）。读不出就抛，绝不返回"空数组"当成功。 */
export function listZip(zipPath) {
  const buf = fs.readFileSync(zipPath)
  const eocd = findEocd(buf)
  if (eocd < 0) throw new Error('不是有效的 zip（找不到 EOCD）: ' + zipPath)
  const count = buf.readUInt16LE(eocd + 10)
  let off = buf.readUInt32LE(eocd + 16)
  const names = []
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) throw new Error(`第 ${i} 条中央目录头损坏: ${zipPath}`)
    const nameLen = buf.readUInt16LE(off + 28)
    const extraLen = buf.readUInt16LE(off + 30)
    const commentLen = buf.readUInt16LE(off + 32)
    names.push(buf.toString('utf8', off + 46, off + 46 + nameLen).replace(/\\/g, '/'))
    off += 46 + nameLen + extraLen + commentLen
  }
  if (names.length !== count) throw new Error(`条目数与中央目录不一致（${names.length} vs ${count}）`)
  return names
}

/** 从 zip 里取一个文本文件的内容（不开子进程、不解压到磁盘）。 */
export function readZipText(zipPath, entryName) {
  const buf = fs.readFileSync(zipPath)
  const want = entryName.replace(/\\/g, '/')
  const eocd = findEocd(buf)
  if (eocd < 0) throw new Error('不是有效的 zip: ' + zipPath)
  const count = buf.readUInt16LE(eocd + 10)
  let off = buf.readUInt32LE(eocd + 16)
  for (let i = 0; i < count; i++) {
    const nameLen = buf.readUInt16LE(off + 28)
    const extraLen = buf.readUInt16LE(off + 30)
    const commentLen = buf.readUInt16LE(off + 32)
    const localOff = buf.readUInt32LE(off + 42)
    const method = buf.readUInt16LE(off + 10)
    const compSize = buf.readUInt32LE(off + 20)
    const nm = buf.toString('utf8', off + 46, off + 46 + nameLen).replace(/\\/g, '/')
    if (nm === want) {
      // 本地头：30 字节固定 + 文件名 + 扩展区（本地头的长度字段可能与中央目录不同，必须读本地的）
      const lNameLen = buf.readUInt16LE(localOff + 26)
      const lExtraLen = buf.readUInt16LE(localOff + 28)
      const dataAt = localOff + 30 + lNameLen + lExtraLen
      const raw = buf.subarray(dataAt, dataAt + compSize)
      return (method === 0 ? raw : zlib.inflateRawSync(raw)).toString('utf8')
    }
    off += 46 + nameLen + extraLen + commentLen
  }
  return null
}

/**
 * 按规则核对一个 zip。
 * rules: { 'web/game.html': 1, 'web/assets/scenes/': 80 } —— 值是最小条目数（子串匹配）。
 * 返回 { pass, fail, checks, names }；**必做正例自证**：exe 必须在包内（R5）。
 */
export function checkZip(zipPath, rules = {}) {
  const st = fs.statSync(zipPath)
  const names = listZip(zipPath)
  const checks = []
  const ok = (c, msg, extra) => { checks.push({ ok: !!c, msg, extra }); return !!c }
  ok(st.size > 0, 'zip 非空（字节数 > 0）', st.size + ' 字节')
  ok(names.length > 0, '条目数 > 0', names.length + ' 条目')
  ok(names.some((n) => n.endsWith('多克多比.exe')), '正例自证：启动器 exe 在包内')
  for (const [pat, min] of Object.entries(rules)) {
    const c = names.filter((n) => n.includes(pat)).length
    ok(c >= min, `${pat} 至少 ${min} 项`, `实际 ${c}`)
  }
  const pass = checks.filter((c) => c.ok).length
  return { pass, fail: checks.length - pass, checks, names, bytes: st.size }
}
", "file_path": "_tools\lib\zip-central.mjs"}

{"content": "// 发布（R11 的执行体 · 00-PLAN.md §6 第 ⑥ 条）
//
// 【为什么必须存在】
// `多克多比v0.6单机版.zip` 曾经实测 **0 字节**，而 `STATE.md` 写着"exe 已实测启动、
// /__ping 200、game.html 200" —— 躺在仓库根目录 5 个小时没人发现。
// 根因不是某次意外，而是**打包这一步从来不是一个脚本**：
//   · 组装 dist 有脚本（_build/make-dist.mjs）；
//   · 产出 zip 是每次手敲的 PowerShell 命令 —— 手敲的东西失败了不会有人知道；
//   · 校验发布包的 verify-zip.mjs 又"自动挑最新包"，于是它挑中了那个 0 字节残包，白验。
// 所以 R11 的落法就是这一个脚本：**打包 + 校验 + 打印验收凭据，任何一步不对就非 0 退出。**
//
// 用法:
//   node _tools/make-release.mjs              # 用 STATE.md 里写的版本号打包
//   node _tools/make-release.mjs --no-build   # 跳过 make-dist（dist 已经是最新的，快速重打包）
//   node _tools/make-release.mjs --ver v0.7   # 显式版本号（版本号会**同时**写回 STATE.md 与 00-PLAN.md，
//                                             #   这是"状态单一事实源"的直接落地，不许手动改一处）
// 退出码: 0 = 包有效；1 = 任何一步失败（含 0 字节、缺 exe、状态表版本不一致）
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { checkZip, listZip } from './lib/zip-central.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const P = (...p) => path.join(ROOT, ...p)
const ARGS = process.argv.slice(2)
const NO_BUILD = ARGS.includes('--no-build')
const VER_ARG = (ARGS.find((a) => a.startsWith('--ver=')) || '').split('=')[1] || null
const read = (p) => fs.readFileSync(P(p), 'utf8').replace(/^\uFEFF/, '')

let failed = 0
const step = (s) => console.log('\n=== ' + s + ' ===')
const ok = (c, msg, extra) => {
  console.log((c ? '  ✓ ' : '  ✗ ') + msg + (extra ? ' → ' + extra : ''))
  if (!c) failed++
  return c
}

// ─────────────────────────── 1) 版本号 ───────────────────────────
step('1) 版本号（单一事实源：STATE.md）')
const stateRaw = read('STATE.md')
const stateVer = VER_ARG || ((stateRaw.match(/\*\*当前版本\*\*：\s*v([\d.]+)/) || [])[1])
if (!stateVer) {
  console.error('  ✗ STATE.md 里找不到「**当前版本**：vX.Y」—— 先把它写上，不要靠参数猜')
  process.exit(1)
}
const zipName = `多克多比v${stateVer}单机版.zip`
console.log(`  STATE.md 当前版本 = v${stateVer}   →   目标包: ${zipName}`)
if (VER_ARG) {
  // 显式换版本：同时改 STATE.md 与 00-PLAN.md，避免"两处版本号"分叉（v3 §2）
  const newState = stateRaw.replace(/(\*\*当前版本\*\*：\s*v)[\d.]+/, `$1${stateVer}`)
  const planRaw = read('00-PLAN.md')
  const newPlan = planRaw
    .replace(/(\*\*当前基线版本\*\*：\s*v)[\d.]+/, `$1${stateVer}`)
    .replace(/(\|\s*\*\*当前版本\*\*\s*\|\s*\*\*v)[\d.]+/, `$1${stateVer}`)
  fs.writeFileSync(P('STATE.md'), newState, 'utf8')
  fs.writeFileSync(P('00-PLAN.md'), newPlan, 'utf8')
  console.log(`  已把 v${stateVer} 写回 STATE.md 与 00-PLAN.md`)
}

// ─────────────────────────── 2) 组装 dist ───────────────────────────
if (!NO_BUILD) {
  step('2) 组装 dist（_build/make-dist.mjs）')
  const r = spawnSync(process.execPath, [P('_build', 'make-dist.mjs')], { cwd: ROOT, stdio: 'inherit' })
  if (r.status !== 0) { console.error(`  ✗ make-dist 退出码 ${r.status}`); process.exit(1) }
} else {
  step('2) 组装 dist（--no-build，跳过）')
}
const dist = P('dist')
if (!fs.existsSync(path.join(dist, '多克多比.exe'))) { console.error('  ✗ dist/多克多比.exe 不存在'); process.exit(1) }
ok(fs.existsSync(path.join(dist, 'web', 'game.html')), 'dist/web/game.html 在')
ok(fs.existsSync(path.join(dist, 'web', 'game', 'skills-official.js')), 'dist/web/game/skills-official.js 在')

// ─────────────────────────── 3) 打包（自己写 zip，零依赖）───────────────────────────
// 为什么不用 Compress-Archive：① 它写反斜杠条目名（本项目踩过，导致统计假警报）；
// ② 它是外部 PowerShell 命令，失败时不一定有人看；③ 走 SDK 的 ZipFile 在本机沙箱里加载不稳定。
// 自己写 zip 反而最短：本地头 + 数据 + 中央目录 + EOCD，全部用 node:zlib 压。
step('3) 打包 zip')
const CRC_TABLE = (() => {
  const t = new Int32Array(256)
  for (let n = 0; n < 256; n++) {
    let c = n
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1
    t[n] = c
  }
  return t
})()
function crc32(buf) {
  let c = -1
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8)
  return (c ^ -1) >>> 0
}
function dosTime(d) {
  const time = ((d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() / 2)) & 0xFFFF
  const date = (((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate()) & 0xFFFF
  return { time, date }
}

// 收集条目（文件 + 目录），目录也要有条目（解压时才会创建空目录）
const entries = []
;(function walk(dir, rel) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const full = path.join(dir, e.name)
    const name = rel ? rel + '/' + e.name : e.name
    if (e.isDirectory()) { entries.push({ name: name + '/', dir: true }); walk(full, name) }
    else entries.push({ name, full })
  }
})(dist, '')
console.log(`  条目: ${entries.length} 个（含目录）`)

const zipPath = P(zipName)
if (fs.existsSync(zipPath)) fs.rmSync(zipPath)          // 先删旧包：绝不留下"新旧混合"或 0 字节残包
const out = fs.openSync(zipPath, 'w')
const central = []
let offset = 0
const { time: dTime, date: dDate } = dosTime(new Date())

function writeBuf(b) { fs.writeSync(out, b); offset += b.length }

for (const ent of entries) {
  const nameBuf = Buffer.from(ent.name, 'utf8')
  const raw = ent.dir ? Buffer.alloc(0) : fs.readFileSync(ent.full)
  const method = ent.dir ? 0 : 8
  const comp = ent.dir ? raw : zlib.deflateRawSync(raw, { level: 6 })
  const crc = ent.dir ? 0 : crc32(raw)
  const local = Buffer.alloc(30)
  local.writeUInt32LE(0x04034b50, 0)
  local.writeUInt16LE(20, 4)              // version needed
  local.writeUInt16LE(0x0800, 6)          // flag: UTF-8 文件名（中文名必须）
  local.writeUInt16LE(method, 8)
  local.writeUInt16LE(dTime, 10)
  local.writeUInt16LE(dDate, 12)
  local.writeUInt32LE(crc, 14)
  local.writeUInt32LE(comp.length, 18)
  local.writeUInt32LE(raw.length, 22)
  local.writeUInt16LE(nameBuf.length, 26)
  local.writeUInt16LE(0, 28)              // extra len
  writeBuf(local)
  writeBuf(nameBuf)
  if (comp.length) writeBuf(comp)

  const cen = Buffer.alloc(46)
  cen.writeUInt32LE(0x02014b50, 0)
  cen.writeUInt16LE(20, 4)                // version made by
  cen.writeUInt16LE(20, 6)                // version needed
  cen.writeUInt16LE(0x0800, 8)
  cen.writeUInt16LE(method, 10)
  cen.writeUInt16LE(dTime, 12)
  cen.writeUInt16LE(dDate, 14)
  cen.writeUInt32LE(crc, 16)
  cen.writeUInt32LE(comp.length, 20)
  cen.writeUInt32LE(raw.length, 24)
  cen.writeUInt16LE(nameBuf.length, 28)
  cen.writeUInt16LE(0, 30)                // extra
  cen.writeUInt16LE(0, 32)                // comment
  cen.writeUInt16LE(0, 34)                // disk
  cen.writeUInt16LE(0, 36)                // internal attrs
  cen.writeUInt32LE(ent.dir ? 0x10 : 0x20, 38)   // external attrs: 目录位
  cen.writeUInt32LE(offset, 42)           // local header offset
  central.push(Buffer.concat([cen, nameBuf]))
}
const cenStart = offset
for (const c of central) writeBuf(c)
const eocd = Buffer.alloc(22)
eocd.writeUInt32LE(0x06054b50, 0)
eocd.writeUInt16LE(0, 4)
eocd.writeUInt16LE(0, 6)
eocd.writeUInt16LE(entries.length, 8)
eocd.writeUInt16LE(entries.length, 10)
eocd.writeUInt32LE(offset - cenStart, 12)
eocd.writeUInt32LE(cenStart, 16)
eocd.writeUInt16LE(0, 20)
writeBuf(eocd)
fs.closeSync(out)
console.log(`  ${zipName}  ${(fs.statSync(zipPath).size / 1048576).toFixed(1)} MB`)

// ─────────────────────────── 4) 校验（R11 的硬底线）───────────────────────────
step('4) 校验发布包内容（rules 与 verify-zip.mjs 一致）')
const RULES = {
  'web/game.html': 1,
  'web/world.js': 1,
  'web/game/skills-official.js': 1,
  'web/assets/bgm/named/': 15,
  'web/assets/scenes/': 80,
  'web/assets/forms/art/': 11,
  'web/assets/items/': 30,
  'web/assets/skills/': 10,
  'web/assets/knights/': 14,
  'web/assets/monsters/': 100,
  'web/assets/anim/': 1000,
}
const res = checkZip(zipPath, RULES)
for (const c of res.checks) ok(c.ok, c.msg, c.extra)
ok(res.bytes > 0, '★ R11：发布包字节数 > 0', `${res.bytes} 字节`)

// game.html 的 <script src> 清单必须全部在包内（清单靠解析，不靠硬编码 —— R6）
const html = read('dist/web/game.html')
const srcs = [...html.matchAll(/<script[^>]+src="([^"]+)"/g)].map((m) => m[1])
const names = new Set(listZip(zipPath))
const missing = srcs.filter((s) => !names.has('web/' + s.replace(/^\.\//, '')))
ok(missing.length === 0, `game.html 引用的 ${srcs.length} 个脚本全部在包内`, missing.length ? '缺: ' + missing.join(', ') : '')

// ─────────────────────────── 5) 验收凭据 ───────────────────────────
step('5) 验收凭据（R11：三次实测的证据必须打出来）')
