{"content": "# 冒烟测试：启动打包好的 exe，验证
#   1) /__ping 能认出"这是我们自己"
#   2) /__save 能写入并在重启后读回（用户报的"存档重启又从头开始"就是这条）
#   3) 存档文件确实落在 exe 旁边
#   4) 第二个实例认出"已在运行"，不换端口、不双开
#
# 【第 46 轮修】原先所有失败都只在输出里写一行，**退出码恒为 0** ——
# 也就是"exe 根本没起来"和"全部通过"在自动化眼里长得一模一样。
# R11 要求"exe 实测启动"是发布验收的一环，所以这里改成：任何一条失败 → exit 1。
$ErrorActionPreference = 'Continue'
$failed = 0
function Note($msg, $isOk) {
  if ($isOk) { Write-Output "  [OK]   $msg" } else { Write-Output "  [FAIL] $msg"; $script:failed++ }
}

$exe = Join-Path (Get-Location) 'dist\多克多比.exe'
if (-not (Test-Path $exe)) { throw "找不到 $exe" }

$p = Start-Process -FilePath $exe -ArgumentList '--no-browser' -PassThru -WindowStyle Minimized
Start-Sleep -Seconds 4
try {
  $ping = Invoke-WebRequest -Uri 'http://127.0.0.1:8765/__ping' -UseBasicParsing -TimeoutSec 5
  Note "1) /__ping -> HTTP $($ping.StatusCode)  body=$($ping.Content)  标记头 X-DKDbb=$($ping.Headers['X-DKDbb'])" ($ping.StatusCode -eq 200)
} catch {
  Note "1) /__ping 失败: $_" $false
}

$payload = '{"level":9,"gold":777,"forms":["克罗 多比"],"items":{"291001":3}}'
try {
  $post = Invoke-WebRequest -Uri 'http://127.0.0.1:8765/__save' -Method POST -Body $payload -UseBasicParsing -TimeoutSec 5
  Note "2) POST /__save -> HTTP $($post.StatusCode)  body=$($post.Content)" ($post.StatusCode -eq 200)
} catch {
  Note "2) POST /__save 失败: $_" $false
}

$saveFile = Join-Path (Get-Location) 'dist\save.json'
Note "3) save.json 存在=$([bool](Test-Path $saveFile))" ([bool](Test-Path $saveFile))
if (Test-Path $saveFile) { Write-Output "       内容: $(Get-Content $saveFile -Raw)" }

try {
  $get = Invoke-WebRequest -Uri 'http://127.0.0.1:8765/__save' -UseBasicParsing -TimeoutSec 5
  Note "4) GET /__save -> $($get.Content)" ($get.StatusCode -eq 200)
} catch {
  Note "4) GET /__save 失败: $_" $false
}

# 再起一个实例：应该认出"已在运行"并把窗口指过去，而不是换端口
$p2 = Start-Process -FilePath $exe -ArgumentList '--no-browser' -PassThru -WindowStyle Minimized
Start-Sleep -Seconds 4
$alive = @(Get-Process -Name '多克多比' -ErrorAction SilentlyContinue)
Note "5) 同时运行的实例数: $($alive.Count)（期望 1 —— 第二个应该自己退出）" ($alive.Count -eq 1)

Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
if ($p2) { Stop-Process -Id $p2.Id -Force -ErrorAction SilentlyContinue }
Get-Process -Name '多克多比' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Remove-Item $saveFile -ErrorAction SilentlyContinue

if ($failed -gt 0) {
  Write-Output "smoke-exe: 失败 $failed 项"
  exit 1
}
Write-Output 'smoke-exe: 全部通过'
exit 0
", "file_path": "_build\smoke-exe.ps1"}

{"content": "// 事实采集：从**运行时数据文件**里读出真实条目数。
//
// 【为什么需要它】
// `_build/make-dist.mjs` 生成给玩家的 `dist/使用说明.txt`，里面曾经**写死**：
//     「多克多比 · 浮空群岛　v0.1 单机版 …… 11 个多比形态 …… 17 个原版技能 …… 34 种怪物」
// 而当时实际是 v0.6 / 52 只形态 / 136 个技能 / 36 种怪物 —— 一份**发给玩家的文件**在说谎，
// 而且没有任何机制会发现（写死的数字一定会过期；第 44 轮刚为"界面里写死 0.28 秒"踩过同一个坑）。
// 所以这里把"事实"做成一个函数：谁要写数字就调它，不许再手打。
//
// 数据源：`assets/forms.js`、`assets/items.js`（都是 `window.__X__ = {…}` 形式的 JSON）、
//         `game/skills-official.js`（带缩进的裸对象字面量）、目录计数。
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const P = (...p) => path.join(ROOT, ...p)

/** 扫出第一个平衡的 `{...}` 并 JSON.parse（两个数据文件都是严格 JSON）。 */
export function parseJsonAfter(file, marker) {
  const s = fs.readFileSync(P(file), 'utf8').replace(/^\uFEFF/, '')
  const at = marker ? s.indexOf(marker) : 0
  if (at < 0) throw new Error(`找不到标记 ${marker}（${file}）`)
  const start = s.indexOf('{', at)
  let d = 0, str = null
  for (let j = start; j < s.length; j++) {
    const c = s[j]
    if (str) { if (c === '\\') { j++; continue } if (c === str) str = null; continue }
    if (c === '"' || c === "'") { str = c; continue }
    if (c === '{') d++
    else if (c === '}') { d--; if (!d) return JSON.parse(s.slice(start, j + 1)) }
  }
  throw new Error(`括号未闭合（${file}）`)
}

/** 数 `game/skills-official.js` 里的顶层技能条目（形如 `  "重击": {`）。 */
export function countOfficialSkills() {
  const s = fs.readFileSync(P('game/skills-official.js'), 'utf8')
  return (s.match(/^ {2}"[^"]+":\s*\{/gm) || []).length
}

const countDir = (d) => (fs.existsSync(P(d)) ? fs.readdirSync(P(d)).filter((f) => !f.startsWith('.')).length : 0)

/** 一次拿全所有"会写进文档"的事实数字。 */
export function collectFacts() {
  const forms = parseJsonAfter('assets/forms.js', '__DKDbb_FORMS__')
  const data = parseJsonAfter('assets/gamedata.js', '__DKDbb_DATA__')
  const items = parseJsonAfter('assets/items.js', '__DKDbb_ITEMS__')
  const html = fs.readFileSync(P('game.html'), 'utf8')
  const state = fs.existsSync(P('STATE.md')) ? fs.readFileSync(P('STATE.md'), 'utf8').replace(/^\uFEFF/, '') : ''

  // 版本号与测试数**从 STATE.md 读**（它是单一事实源），不在这里另算一份
  const ver = (state.match(/\*\*当前版本\*\*：\s*v([\d.]+)/) || [])[1] || null

  return {
    version: ver,
    forms: (forms.forms || []).length,
    formsArtOnly: (forms.artOnly || []).length,
    formsArtFiles: countDir('assets/forms/art'),
    skills: countOfficialSkills(),
    skillsBase: (data.skills || []).length,
    monsters: (data.monsters || []).length,
    monsterFiles: countDir('assets/monsters'),
    items: (items.items || []).length,
    scenes: countDir('assets/scenes'),
    namedBgm: countDir('assets/bgm/named'),
    knights: countDir('assets/knights'),
    scripts: [...html.matchAll(/<script[^>]+src="([^"]+)"/g)].length,
  }
}

if (import.meta.url === `file://${process.argv[1].replace(/\\/g, '/')}` || process.argv[1]?.endsWith('release-facts.mjs')) {
  console.log(JSON.stringify(collectFacts(), null, 2))
}
", "file_path": "_tools\lib\release-facts.mjs"}

