{"file_path": "game\game.js", "new_string": "  const WALK = { x0: 0.06, x1: 0.94, y0: 0.46, y1: 0.86 }

  // ── NPC 排布的**唯一实现**（界面与测试共用，避免两边算法分叉）──
  // 第 46 轮抽出来，因为 check-scene-npc.mjs 要核对"每个人都在画面内"，
  // 如果测试自己再算一遍列数，就会出现本仓库反复记过的"同一逻辑两份实现 → 一定分叉"。
  const NPC_ROW_Y = [330, 430, 500]      // 画布高 560，500 是最后可用的行（再低就出画）
  const NPC_COSTUME_H = 70               // 立绘约 70px 高，用于"脚底不出画"的判定
  function npcLayout(n) {
    // 列数按人数选：≤6 → 3 列（两行 6 人）；7~8 → 4 列（两行 8 人）；>8 → 4 列三行
    const cols = n <= 6 ? Math.max(1, Math.min(n, 3)) : 4
    return { cols, rows: Math.ceil(Math.max(n, 1) / cols), rowY: NPC_ROW_Y.slice() }
  }
  function npcPositions(n) {
    const lay = npcLayout(n)
    const out = []
    for (let i = 0; i < n; i++) {
      const col = i % lay.cols, row = Math.floor(i / lay.cols)
      out.push({
        x: lay.cols === 1 ? W / 2 : 200 + col * (560 / (lay.cols - 1)),
        y: NPC_ROW_Y[Math.min(row, NPC_ROW_Y.length - 1)],
        row, col,
      })
    }
    return { ...lay, points: out, bottom: Math.max(...out.map((p) => p.y), 0) + NPC_COSTUME_H }
  }

  function walkBounds() {
    return {
      x0: W * WALK.x0, x1: W * WALK.x1,
      y0: H * WALK.y0, y1: H * WALK.y1,
    }
