  // 如果测试自己再算一遍列数，就会出现本仓库反复记过的"同一逻辑两份实现 → 一定分叉"。
  const NPC_ROW_Y = [330, 430, 500]      // 画布高 560；330/430 是两行主位（500 只是兜底，见下）
  const NPC_COSTUME_H = 70               // 立绘约 70px 高，用于"脚底不出画"的判定
  const NPC_ZONE = { x0: 200, x1: 760 }  // 左右各留 200：出口箭头占 x<116 与 x>844
  function npcLayout(n) {
    // 【为什么列数要跟着人数长】硬上限是 9 人，而画面只有 560 高：
    //   两行最多 8 人（4 列 × 2 行）。第一版列数封顶 4、行数不封 →
    //   第 9 个人落到第三行 y=500，脚底 570 **超出画布**（第 46 轮 check-scene-npc 抓到）。
    //   第二版改成"两行封顶 + 超 8 人挤第三行"仍然出画（实测 9 人脚底 570）。
    //   所以正解是：**列数按人数摊开**，让 ≤9 人始终只占两行。
    //   间距够不够由 check-scene-npc 的"同排间距 ≥60px"判据守着（9 人时 86.7px）。
    const cols = n <= 0 ? 1 : n <= 3 ? n : n <= 6 ? 3 : n <= 8 ? 4 : n
    return { cols, rows: 1, rowY: NPC_ROW_Y.slice() }
  }
  function npcPositions(n) {
    const lay = npcLayout(n)
    const spanX = NPC_ZONE.x1 - NPC_ZONE.x0
    const out = []
    for (let i = 0; i < n; i++) {
      out.push({
        x: lay.cols === 1 ? W / 2 : NPC_ZONE.x0 + (i % lay.cols) * (spanX / (lay.cols - 1)),
        y: NPC_ROW_Y[0],
