      out.push({
        x: lay.cols === 1 ? W / 2 : 200 + col * (560 / (lay.cols - 1)),
        y: NPC_ROW_Y[Math.min(row, NPC_ROW_Y.length - 1)],
        row, col,
      })
    }
    return { ...lay, points: out, bottom: Math.max(...out.map((p) => p.y), 0) + NPC_COSTUME_H }
  }"}

