{"file_path": "_tools\bot-lib.mjs", "new_string": "  // 哈里的金币（第 47 轮，官方攻略 7k7k/660617）：把箱子挪到"最快落下来的那枚金币"下面。
  // 注意箱子可以二维移动（官方技巧就是"按住四个方向键不松"），所以纵向也要跟。
  coinCatch(t, DBG, extra) {
    const g = DBG().coinCatchState()
    if (!g) return true
    if (g.over) return true
    const P = DBG().coinCatchParams()
    const a = DBG().coinCatchArena()
    for (const k of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) extra.ku(k)
    const live = g.coins.filter((c) => !c.got && !c.miss)
    if (!live.length) return true
    const boxY = g.y - (P.boxH || 34) / 2
    // 只挑"还来得及挪过去"的：按剩余下落时间排序，取最快到的那枚
    let best = null, bt = Infinity
    for (const c of live) {
      const dist = Math.abs(c.x - g.x)
      const eta = (boxY - c.y) / Math.max(1, P.fallSpeed || 130)
      if (eta < 0) continue
      const reach = eta * (P.moveSpeed || 420)
      if (dist <= reach + 6 && eta < bt) { bt = eta; best = c }
    }
    if (!best) best = live.sort((a2, b2) => b2.y - a2.y)[0]
    if (best.x > g.x + 4) extra.kd('ArrowRight')
    else if (best.x < g.x - 4) extra.kd('ArrowLeft')
    // 纵向：箱子该停在金币将要落到的那个高度（贴住底线时不用动）
    if (boxY > a.y1 && g.y > a.y1 - 4) extra.kd('ArrowUp')
    return true
  },
  // 魔镜世界（第 47 轮，官方攻略 7k7k/660928）：先去没开的箱子，再去出口找钥匙。
  // ★ 机器人必须**按镜像后的方向操作**（按右键实际往左走）—— 这正是这一关的玩法内核，
  //   不是为了迁就实现：官方攻略给玩家的建议就是"把键盘颠倒 180 度"。
  mirror(t, DBG, extra) {
    const g = DBG().mirrorState()
    if (!g) return true
    if (g.over) return true
    const P = DBG().mirrorParams()
    for (const k of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) extra.ku(k)
    // 目标：还没开的箱子；全开完了就没事可做（钥匙已到手时会自动过关）
    const left = g.crates.filter((c) => !c.opened)
    if (!left.length) return true
    // 躲怪优先：把怪物当成障碍，绕开它的巡逻线
    const danger = g.mons.some((m) => Math.hypot(m.x - g.px, m.y - g.py) < 90)
    let tgt = left.sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0]
    let dx = tgt.x - g.px, dy = tgt.y - g.py
    if (danger) {
      // 危险时垂直躲开最近那只怪
      const m = g.mons.slice().sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0]
      dy = (g.py < m.y ? -1 : 1) * 120
      dx = 0
    }
    // 镜像：想往 +x 走就得按左键
    const wantX = dx > 4 ? -1 : dx < -4 ? 1 : 0
    const wantY = dy > 4 ? -1 : dy < -4 ? 1 : 0
    if (P.mirrorX) { if (wantX < 0) extra.kd('ArrowRight'); else if (wantX > 0) extra.kd('ArrowLeft') }
    else { if (wantX < 0) extra.kd('ArrowLeft'); else if (wantX > 0) extra.kd('ArrowRight') }
    if (P.mirrorY) { if (wantY < 0) extra.kd('ArrowDown'); else if (wantY > 0) extra.kd('ArrowUp') }
    else { if (wantY < 0) extra.kd('ArrowUp'); else if (wantY > 0) extra.kd('ArrowDown') }
    return true
  },
  // 潜行（无所遁形）：一直往前挪
  stealth(t, DBG, extra) {
    extra.t.key(' ')
    return true
  },", "old_string": "  // 潜行（无所遁形）：一直往前挪
  stealth(t, DBG, extra) {
    extra.t.key(' ')
    return true
  },"}

