{"content": "// 诊断：魔镜世界为什么通关不了（一次性排查脚本，不进回归）
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'

const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
const extra = { t, frame: 0, ...makeInput(W) }

DBG().state.mode = 'explore'
console.log('开局:', DBG().startMinigame('mirrorWorld'))
console.log('phase:', DBG().dungeonState().phase)
const P = DBG().mirrorParams()
console.log('参数:', JSON.stringify(P))
const a = DBG().mirrorArena()
console.log('场地:', JSON.stringify(a))

let over = false
for (let i = 0; i < 3600 && !over; i++) {
  STAGE_BOTS.mirror(t, DBG, extra)
  extra.frame++
  DBG().mirrorTick(1 / 60)
  if (i % 300 === 0) {
    const g = DBG().mirrorState()
    const p = DBG().dungeonState()
    console.log(`t=${(i / 60).toFixed(1)}s  玩家(${g.px.toFixed(0)},${g.py.toFixed(0)})  开箱 ${g.opened}/${g.crates.length}  钥匙 ${g.hasKey}  出口 ${g.exit.open}  剩余时间 ${g.timeLeft.toFixed(0)}  phase=${p.phase}  miniDone=${!!p.miniDone}`)
    console.log('   怪物:', g.mons.map((m) => `(${m.x.toFixed(0)},${m.y.toFixed(0)})dir${m.dir}`).join(' '))
    console.log('   未开箱:', g.crates.filter((c) => !c.opened).map((c) => `(${c.x.toFixed(0)},${c.y.toFixed(0)})`).join(' ') || '（都开了）')
  }
  const g = DBG().mirrorState()
  if (g && g.over) over = true
}
const g = DBG().mirrorState()
const p = DBG().dungeonState()
console.log('\n结束状态:', JSON.stringify({ over: g.over, opened: g.opened, hasKey: g.hasKey, exitOpen: g.exit.open, fails: g.fails, timeLeft: Math.round(g.timeLeft) }))
console.log('phase:', p.phase, 'miniDone:', !!p.miniDone)
", "file_path": "_tools\diag-mirror.mjs"}

{"content": "// 诊断 2：手动按住方向键，看玩家到底动不动（排查 input.down 是否生效）
import { T } from './game-harness.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('mirrorWorld')
const kd = (k) => W.fire('keydown', { key: k, preventDefault() { } })
const ku = (k) => W.fire('keyup', { key: k })
const pos = () => { const g = DBG().mirrorState(); return `(${g.px.toFixed(0)},${g.py.toFixed(0)})` }

console.log('起始', pos())
// ① 按住"左"键（镜像后应当往右走）
kd('ArrowLeft')
for (let i = 0; i < 60; i++) DBG().mirrorTick(1 / 60)
console.log('按住 ArrowLeft 1 秒后', pos(), '（镜像 → 应当向右，x 变大）')
ku('ArrowLeft')
// ② 按住"上"键（镜像后应当往下走）
kd('ArrowUp')
for (let i = 0; i < 60; i++) DBG().mirrorTick(1 / 60)
console.log('按住 ArrowUp   1 秒后', pos(), '（镜像 → 应当向下，y 变大）')
ku('ArrowUp')
// ③ 直接看 input.down 怎么读
console.log('input.down 能不能读到按键：')
kd('ArrowRight')
const st = DBG().state
console.log('  按下 ArrowRight 后，mirrorTick 再跑 1 帧：')
const before = pos()
DBG().mirrorTick(1 / 60)
console.log('  ', before, '→', pos(), '（镜像 → 应当向左，x 变小）')
ku('ArrowRight')
// ④ 检查是否存在"每帧被清空"的输入集合
