{"file_path": "_tools\bot-lib.mjs", "new_string": "  // 魔镜世界（第 47 轮，官方攻略 7k7k/660928）：先去没开的箱子，出口开了就去出口。
  // ★ 方向映射的坑（第一版就栽在这里，值得写下来）：
  //   mirrorTick 会把按下的键**再镜像一次**，所以机器人必须"反着按键"：
  //   想往屏幕右边走就得按 ArrowLeft，想往上走就得按 ArrowDown。
  //   第一版按的是"屏幕方向"，结果一路朝反方向撞到边界卡死 —— 自动试玩体检直接报 0/6。
  //   这种错从代码上完全看不出来，只有跑起来才知道。
  // ★ 第二版又栽在"躲怪半径 90px"上：碰撞半径其实只有 18+20=38px，
  //   90px 就开始躲 → 目标方向被反复改写，机器人在场地中间来回抖，一局都赢不了。
  //   现在只在**真的很近（<52px）**时才让开，其余时候直着走向目标。
  mirror(t, DBG, extra) {
    const g = DBG().mirrorState()
    if (!g) return true
    if (g.over) return true
    const P = DBG().mirrorParams()
    for (const k of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) extra.ku(k)
    const left = g.crates.filter((c) => !c.opened)
    const goal = g.exit.open ? g.exit
      : (left.length ? left.slice().sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0] : null)
    if (!goal) return true
    let dx = goal.x - g.px, dy = goal.y - g.py
    // 只在快撞上时才让开（碰撞半径 38px，留一点余量）
    const near = g.mons.slice().sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0]
    if (near && Math.hypot(near.x - g.px, near.y - g.py) < 52) {
      dx = (g.px < near.x ? -1 : 1) * 90
      dy = (g.py < near.y ? -1 : 1) * 60
    }
    // 期望的屏幕方向
    const wantX = dx > 4 ? 1 : dx < -4 ? -1 : 0
    const wantY = dy > 4 ? 1 : dy < -4 ? -1 : 0
    // 镜像 → 反着按（这才是"把键盘颠倒 180 度"）
    if (wantX !== 0) extra.kd(P.mirrorX ? (wantX > 0 ? 'ArrowLeft' : 'ArrowRight') : (wantX > 0 ? 'ArrowRight' : 'ArrowLeft'))
    if (wantY !== 0) extra.kd(P.mirrorY ? (wantY > 0 ? 'ArrowUp' : 'ArrowDown') : (wantY > 0 ? 'ArrowDown' : 'ArrowUp'))
    return true
  },", "old_string": "  // 魔镜世界（第 47 轮，官方攻略 7k7k/660928）：先去没开的箱子，再去出口找钥匙。
  // ★ 机器人必须**按镜像后的方向操作**（按右键实际往左走）—— 这正是这一关的玩法内核，
  //   不是为了迁就实现：官方攻略给玩家的建议就是"把键盘颠倒 180 度"。
  mirror(t, DBG, extra) {
    const g = DBG().mirrorState()
    if (!g) return true
    if (g.over) return true
    const P = DBG().mirrorParams()
    for (const k of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) extra.ku(k)
    // 目标：出口开了就去出口；否则去还没开的箱子
    const left = g.crates.filter((c) => !c.opened)
    const goal = g.exit.open ? g.exit : (left.length ? left.sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0] : null)
    if (!goal) return true
    // 躲怪优先：把怪物当成障碍，绕开它的巡逻线
    const danger = g.mons.some((m) => Math.hypot(m.x - g.px, m.y - g.py) < 90)
    let dx = goal.x - g.px, dy = goal.y - g.py
    if (danger) {
      // 危险时垂直躲开最近那只怪
      const m = g.mons.slice().sort((a, b) => Math.hypot(a.x - g.px, a.y - g.py) - Math.hypot(b.x - g.px, b.y - g.py))[0]
      dy = (g.py < m.y ? -1 : 1) * 120
      dx = 0
    }
    // 镜像：想往 +x 走就得按左键
    // ⚠️ 这里最容易写错（第一版就是这么错的）：dx/dy 已经是**屏幕坐标**下的方向，
    //    而 mirrorTick 会把按下的键再镜像一次。所以"想往右"必须按**左**键，
    //    即 wantX<0（想左）→ 按右。第一版写成"wantX<0 → 按左"，
    //    结果机器人朝反方向一路走到边界卡死，自动试玩体检报 0/6 通关。
    //    这也说明体检脚本的价值：这种错**从代码上看不出来**，跑一局就露馅。
    const wantX = dx > 4 ? -1 : dx < -4 ? 1 : 0
    const wantY = dy > 4 ? -1 : dy < -4 ? 1 : 0
    if (P.mirrorX) { if (wantX < 0) extra.kd('ArrowRight'); else if (wantX > 0) extra.kd('ArrowLeft') }
    else { if (wantX < 0) extra.kd('ArrowLeft'); else if (wantX > 0) extra.kd('ArrowRight') }
    if (P.mirrorY) { if (wantY < 0) extra.kd('ArrowDown'); else if (wantY > 0) extra.kd('ArrowUp') }
    else { if (wantY < 0) extra.kd('ArrowUp'); else if (wantY > 0) extra.kd('ArrowDown') }
    return true
  },"}

