{"file_path": "_tools\bot-lib.mjs", "new_string": "  // 冲上云霄（第 48 轮，官方攻略 7k7k/551114）：一路踩泡泡往上跳，目标 50000 分。
  // 【为什么要挑"够得着的泡泡"】官方提示是「把光标放在想要跳的泡泡上面」——
  // 也就是**先站到泡泡上方再跳**，不是乱跳。机器人照这个来：找最近的、在上方且水平距离够近的泡泡。
  soar(t, DBG, extra) {
    const g = DBG().soarState()
    if (!g) return true
    if (g.over) return true
    extra.ku('ArrowLeft'); extra.ku('ArrowRight')
    const P = DBG().soarParams()
    const jumpH = (P.jump * P.jump) / (2 * P.gravity)     // 一次跳跃能上升多高
    // 候选：在玩家上方、且在一跳高度内的泡泡里，挑最高的那个（爬得最快）
    const cand = (g.bubbles || [])
      .filter((b) => b.y < g.y - 10 && g.y - b.y <= jumpH * 0.92)
      .sort((a, b) => a.y - b.y)
    const target = cand[0] || (g.bubbles || []).sort((a, b) => a.y - b.y)[0]
    if (!target) return true
    const dx = target.x - g.x
    // 先横向对准（对准了再跳 —— 这就是官方说的"把光标放在想跳的泡泡上面"）
    if (Math.abs(dx) > 10) {
      if (dx > 0) extra.kd('ArrowRight'); else extra.kd('ArrowLeft')
      return true
    }
    // 站住了就往上跳
    if (g.onBubble || g.y >= 440) extra.t.key(' ')
    return true
  },
  // 极限顶顶球（第 48 轮，归档截图规则 + 7k7k/660779）：把球顶进对方（右边）瓶子。
  // ★ 官方说"电脑比我们更快更高"，所以机器人不能靠拼速度，只能**提前站位抢落点**。
  ballpush(t, DBG, extra) {
    const g = DBG().ballPushState()
    if (!g) return true
    extra.ku('ArrowLeft'); extra.ku('ArrowRight')
    const P = DBG().ballPushParams()
    const x1 = P.fieldX1 || 810, gy = P.groundY || 470
    // 目标：站在球的**左侧**（这样一撞就往右推），并且靠近球要落下的地方
    const wantX = g.ball.x - 34
    const dx = wantX - g.me.x
    if (dx > 8) extra.kd('ArrowRight')
    else if (dx < -8) extra.kd('ArrowLeft')
    // 球在天上且快到落点 → 跳起来顶
    const eta = g.ball.vy > 0 ? (gy - g.ball.y) / Math.max(1, g.ball.vy) : 99
    if (g.me.onGround && Math.abs(g.ball.x - g.me.x) < 70 && g.ball.y < gy - 90 && eta < 0.9) extra.t.key('ArrowUp')
    return true
  },
  // 潜行（无所遁形）：一直往前挪
  stealth(t, DBG, extra) {
    extra.t.key(' ')
    return true
  },", "old_string": "  // 潜行（无所遁形）：一直往前挪
  stealth(t, DBG, extra) {
    extra.t.key(' ')
    return true
  },"}

{"content": "// 诊断（一次性，不进回归）：冲上云霄 / 极限顶顶球为什么机器人打不过
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'

const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
const extra = { t, frame: 0, ...makeInput(W) }

function run(id, kind, frames, label) {
  console.log(`\n${'='.repeat(70)}\n【${id}】`)
  DBG().state.mode = 'explore'
  console.log('开局:', DBG().startMinigame(id), 'phase=', DBG().dungeonState().phase)
  for (let i = 0; i < frames; i++) {
    const ok = STAGE_BOTS[kind] ? STAGE_BOTS[kind](t, DBG, extra) : false
    if (i === 0) console.log('  机器人帧0 返回', ok)
    extra.frame++
    if (kind === 'soar') DBG().soarTick(1 / 60)
    else DBG().ballPushTick(1 / 60)
    const st = DBG().dungeonState()
    if (i % 300 === 0 || i === frames - 1) {
      if (kind === 'soar') {
        const g = DBG().soarState()
        console.log(`  t=${(i / 60).toFixed(1)}s 位置(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 分=${g.score} 踩=${g.jumped} 站住=${g.onBubble} 掉=${g.fails} 时间=${g.timeLeft.toFixed(0)} phase=${st.phase}`)
      } else {
        const g = DBG().ballPushState()
        console.log(`  t=${(i / 60).toFixed(1)}s 我(${g.me.x.toFixed(0)},${g.me.y.toFixed(0)}) AI(${g.ai.x.toFixed(0)},${g.ai.y.toFixed(0)}) 球(${g.ball.x.toFixed(0)},${g.ball.y.toFixed(0)}) v=(${g.ball.vx.toFixed(0)},${g.ball.vy.toFixed(0)}) 比分 ${g.scoreMe}:${g.scoreAi} 时间=${g.timeLeft.toFixed(0)} phase=${st.phase}`)
      }
    }
    if (st.phase !== 'soar' && st.phase !== 'ballpush') { console.log('  阶段变为', st.phase); break }
  }
  console.log(`  ${label} 结束 phase=${DBG().dungeonState().phase} miniDone=${!!DBG().dungeonState().miniDone}`)
}

run('soarSky', 'soar', 1800, '冲上云霄')
run('ballDuel', 'ballpush', 1800, '极限顶顶球')
