{"file_path": "game\game.js", "new_string": "    // 重力
    g.vy += (C.gravity || 1500) * dt
    const prevY = g.y
    g.y += g.vy * dt
    // 大雁在动（官方"它会动"）
    for (const go of g.geese) {
      go.x += go.dir * (C.gooseSpeed || 90) * dt
      if (go.x < go.x0) { go.x = go.x0; go.dir = 1 }
      if (go.x > go.x1) { go.x = go.x1; go.dir = -1 }
    }
    // 落到泡泡上：脚底碰到泡泡顶 → 站住并计分（每个泡泡只算一次）
    // 【第 48 轮修：必须做**穿越检测**】第一版只看"这一帧脚底是否落在泡泡顶 ±16px 内"，
    // 而重力下落的单帧位移是 `vy*dt`（可达 15~25px）—— 于是脚底**经常整帧跨过**那个窗口，
    // 一次都判不到：实测机器人连跳 30 秒、分数恒为 0、一个泡泡都踩不上（游戏实际上无法通关）。
    // 正解：比较"上一帧脚底"与"这一帧脚底"，只要**跨过**泡泡顶就算落地（swept collision）。
    if (g.vy > 0) {
      let land = null
      for (const b of g.bubbles) {
        if (b.used) continue
        const top = b.y - b.r
        const crossed = prevY <= top + 4 && g.y >= top
        const near = Math.abs(g.x - b.x) <= b.r + 14
        if (crossed && near) { land = b; break }
      }
      if (land) {
        land.used = true
        g.onBubble = land
        g.y = land.y - land.r
        g.vy = 0
        g.jumped++
        g.score += (C.scorePerBubble || 1200)
        audio.sfx('assets/sfx/onMouseOver_03.mp3')
      }", "old_string": "    // 重力
