{"file_path": "game\game.js", "new_string": "  function bpBounceOff(paddle, C, ball) {
    // 用"人物撞球"来顶球：球获得一个**远离人物**的水平冲量 + 一点上抛。
    // 【第 48 轮修】冲量方向必须由"球在人物的哪一侧"决定，不能按"球往哪飞"决定 ——
    // 否则人物追着球跑的时候会把球一路顶向**自己**的瓶子（AI 第一版就这么把自己的球送进场了）。
    const b = ball || dungeonState().bp.ball
    const dir = b.x >= paddle.x ? 1 : -1
    b.vx = dir * 330
