const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const P = DBG().soarParams()
const st = DBG().dungeonState().sr
const groundY = 560 - 120
// 挑一个泡泡，把玩家放到它正下方地面上
const b = st.bubbles.filter((x) => !x.used).sort((a, c) => c.y - a.y)[0]
st.x = b.x
st.y = groundY
st.vy = 0
console.log(`泡泡: x=${b.x.toFixed(1)} y=${b.y.toFixed(1)} r=${b.r} 顶面=${(b.y - b.r).toFixed(1)}  used=${b.used}`)
console.log(`玩家: x=${st.x.toFixed(1)} y=${st.y.toFixed(1)}  水平差=${Math.abs(st.x - b.x).toFixed(1)}（判定窗 ${b.r + 22}）`)
console.log(`一跳高度=${((P.jump * P.jump) / (2 * P.gravity)).toFixed(1)}  需要上升=${(st.y - (b.y - b.r)).toFixed(1)}`)
// 跳，然后逐帧打印
W.fire('keydown', { key: ' ', preventDefault() { } })
let frames = 0
for (let i = 0; i < 90; i++) {
  const beforeY = st.y, beforeVy = st.vy
  DBG().soarTick(1 / 60)
  W.fire('keyup', { key: ' ' })
  const g = DBG().soarState()
  const top = b.y - b.r
  const crossed = beforeY <= top + 14 && g.y >= top
  if (i < 46) {
    console.log(`帧${i}: y ${beforeY.toFixed(1)}→${g.y.toFixed(1)} vy ${beforeVy.toFixed(0)}→${g.vy.toFixed(0)}` +
      `  | 顶面${top.toFixed(1)} 前帧<=${(top + 14).toFixed(1)}? ${beforeY <= top + 14}  后帧>=? ${g.y >= top}  crossed=${crossed}` +
      `  水平差=${Math.abs(st.x - b.x).toFixed(1)}  used=${b.used} 分=${g.score} 跳=${g.jumped}`)
  }
  if (g.score > 0) { console.log('★ 踩到'); frames = i; break }
}
if (!frames) console.log('✗ 90 帧内没踩到')
