{"file_path": "_tools\bot-lib.mjs", "new_string": "  soar(t, DBG, extra) {
    const g = DBG().soarState()
    if (!g) return true
    if (g.over) return true
    const P = DBG().soarParams()
    const jumpH = (P.jump * P.jump) / (2 * P.gravity)
    const grounded = g.onBubble || g.vy === 0     // 站在泡泡上，或站在地面（引擎会把 vy 归零）
    const bubbles = g.bubbles || []
    // 目标：一跳范围内、**综合距离（竖直 + 水平）最小**的那个泡泡。
    // 【第 6 次踩坑】只按竖直距离挑，会挑到横向几百像素外的泡泡 ——
    // 玩家一路走到场地边上顶着墙（实测卡在 x=627 不动 20 秒），永远够不着。
    // 横向距离必须一起算进代价。
    const reach = bubbles.filter((b) => b.y < g.y - 8 && g.y - b.y <= jumpH * 0.95)
    const target = reach.sort((a, b) =>
      (Math.abs(a.x - g.x) + (g.y - a.y) * 1.5) - (Math.abs(b.x - g.x) + (g.y - b.y) * 1.5))[0]
      || bubbles.slice().sort((a, b) => (Math.abs(a.x - g.x) + (g.y - a.y)) - (Math.abs(b.x - g.x) + (g.y - b.y)))[0]
    if (!target) return true
    const dx = target.x - g.x
    // 卡住检测：连续 12 帧都贴在同一边界上（说明这个泡泡在场地外/够不到）→ 记下来，换个目标
    if (extra._lastX !== undefined && Math.abs(g.x - extra._lastX) < 0.5 && grounded && Math.abs(dx) > 12) {
      extra._stuck = (extra._stuck || 0) + 1
      if (extra._stuck > 12) { extra._skip = target; extra._stuck = 0 }
    } else extra._stuck = 0
    extra._lastX = g.x
    let goal = target
    if (extra._skip && Math.abs(extra._skip.x - target.x) < 1 && Math.abs(extra._skip.y - target.y) < 1) {
      const alt = reach.filter((b) => !(Math.abs(b.x - target.x) < 1 && Math.abs(b.y - target.y) < 1))
        .sort((a, b) => (Math.abs(a.x - g.x) + (g.y - a.y)) - (Math.abs(b.x - g.x) + (g.y - b.y)))[0]
      if (alt) goal = alt
    }
    const gx = goal.x - g.x
    // 站在落脚点上 + 还没对准 → 横着走过去（不跳）
    if (grounded && Math.abs(gx) > 12) {
