    //   （第 5 次踩坑：实测玩家在泡泡上方 y 377~434 无限弹跳、一分不得）。
    //   `landedAt` 是游戏自己记的落地时刻，等它比当前时刻早 0.08 秒再跳。
    const sinceLand = (typeof g.landedAt === 'number') ? (g.t - g.landedAt) : 99
    if (grounded && sinceLand >= 0.08) {
      if (extra._jumpDown !== t.frame) { extra.t.key(' '); extra._jumpDown = t.frame }
    }
    return true
