import { T } from './game-harness.mjs'
import { makeInput } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
const st = DBG().dungeonState().sr
console.log('起点 x=', st.x.toFixed(1))
// ① 只按右键，不抬起
io.kd('ArrowRight')
for (let i = 0; i < 30; i++) DBG().soarTick(1 / 60)
console.log('按住右键 30 帧后 x=', st.x.toFixed(1), '（应 +100）')
// ② 每帧 ku+kd（模拟机器人每帧的写法）
for (let i = 0; i < 30; i++) { io.kd('ArrowRight'); DBG().soarTick(1 / 60); io.ku('ArrowRight') }
console.log('每帧 kd→tick→ku 30 帧后 x=', st.x.toFixed(1), '（若没动，说明 ku 在 tick 之前就吃掉了按键）')
// ③ 只 ku 不 kd（应停住）
io.ku('ArrowRight')
const x0 = st.x
for (let i = 0; i < 30; i++) DBG().soarTick(1 / 60)
console.log('抬起后 30 帧 x 变化=', (st.x - x0).toFixed(1), '（应 0）')
