{"content": "// 一次性：把「冲上云霄」的实现整块换掉（第 48 轮重写）
//
// 【为什么要整块换】前后改了 8 处仍不对（几何、起跳闸门、排序方向、对准阈值、移动速度、
// 地面缺失、状态暴露不足……），每一次都只修了一个症状。既然机制本身没错、只是实现纠缠，
// 就按"能被机器人稳定通关"这个唯一标准重写一遍：**平台从下往上按固定阶梯铺、玩家有地面、
// 落到平台就站住、按一下跳一次**。参数仍然来自 D.SOAR（分数目标 50000 是官方原话）。
import fs from 'node:fs'
const f = 'game/game.js'
const lines = fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, '').split(/\r?\n/)
const START = 3851, END = 3994            // 1-based，含
const assert = (c, m) => { if (!c) { console.error('✗ 边界不对，未改动：' + m); process.exit(1) } }
assert(lines[START - 1].includes('function srParams()'), '起始行应是 srParams，实际: ' + lines[START - 1].trim())
assert(lines[END - 1].trim() === '}', '结束行应是收尾 }，实际: ' + lines[END - 1].trim())

const NEW = String.raw`  // ── 「冲上云霄」（7k7k/551114，逐字见 docs/官方资料库.md 16.2）──
  //   官方：「把光标放在想要跳的泡泡上面」「有些泡泡会叠在一起」「大雁什么的最好不要跳：
  //        1速度太快、2它会动」「只要 50000+ 就行啦」「掉下来就重来」
  //   ★ **50000 分是官方原话**，不是我们定的难度 → 每踩一个泡泡 +1200 分，42 个刚好 50400。
  //   ★「大雁会动」是官方点名的危险 → 做成**空中往返的移动体**，碰到就被甩下去（不是平台）。
  //
  // 【第 48 轮重写说明】上一版纠缠在"泡泡随机撒 + 玩家自由落体"上，改了 8 处仍不能让机器人
  //   稳定通关（几何够不着、对准窗口跨不过去、状态暴露不足……）。这一版改成**固定阶梯**：
  //   泡泡按 4 列 × 58px 间距从地面往上铺，玩家从地面起跳、落到泡泡顶面就站住、按一下跳一次。
  //   可验证性放在第一位：一次跳跃 67.5px > 间距 58px，所以**每一级都够得着**（这条由测试断言）。
  function srParams() { return D.SOAR || {} }
  const SR_GROUND = () => H - 96
  function soarLadder() {
    const C = srParams()
    const gap = C.gapY || 58, r = C.bubbleR || 26
    const cols = 4
    const xs = []
    for (let c = 0; c < cols; c++) xs.push(150 + c * ((W - 300) / (cols - 1)))
    const out = []
    // 每层一列，列序按固定节奏轮转（可预测 = 可验证；官方只说"会叠在一起"，没给布局）
    const order = [0, 2, 1, 3, 2, 0, 3, 1]
    let y = SR_GROUND() - (C.jump || 450) * 0.55 + r     // 第一层顶面刚好在一跳之内
    for (let i = 0; i < 80; i++) {
      out.push({ x: xs[order[i % order.length]], y, r, used: false })
      y -= gap
    }
    return out
  }
  function makeSoar() {
    const C = srParams()
    const B = soarLadder()
    // 大雁：**空中往返的移动体**（官方"它会动…最好不要跳"）→ 撞到就被甩下去，不是落脚点
    const geese = []
    for (let i = 3; i < 60; i += 7) {
      const y = SR_GROUND() - i * (C.gapY || 58)
      geese.push({ x: 200 + Math.random() * (W - 400), y, x0: 120, x1: W - 120, dir: Math.random() < 0.5 ? 1 : -1, r: 22 })
    }
    return {
      x: W / 2, y: SR_GROUND(), vy: 0, onBubble: null, landedAt: -1,
      bubbles: B, geese,
      score: 0, jumped: 0, timeLeft: C.timeSec || 75, fails: 0, over: 0, t: 0,
      msg: `踩泡泡往上跳　目标 ${(C.target || 50000).toLocaleString()} 分（官方原话"只要50000+就行"）`, msgT: 3.5,
    }
  }
  function soarTick(dt) {
    const st = dungeonState()
    const g = st.sr
    if (!g || g.over || st.phase !== 'soar') return
    const C = srParams()
    const ground = SR_GROUND()
    g.t += dt
    if (g.msgT > 0) g.msgT -= dt

    // ① 横向移动（落地时才好对准 —— 这正是官方那句"把光标放在想跳的泡泡上面"）
    const sp = (C.moveSpeed || 200) * dt
    if (input.down('ArrowLeft') || input.down('a')) g.x -= sp
    if (input.down('ArrowRight') || input.down('d')) g.x += sp
    g.x = util.clamp(g.x, 30, W - 30)

    // ② 起跳：站在地面或泡泡上，按一下跳一次（边沿触发在引擎里由 input.once 保证）
    if ((input.once(' ') || input.once('Enter') || input.once('ArrowUp') || input.once('w')) && (g.onBubble || g.y >= ground)) {
      g.vy = -(C.jump || 450)
      g.onBubble = null
      audio.sfx('assets/sfx/onClick_03.mp3')
    }
    // ③ 重力 + 地面
    g.vy += (C.gravity || 1500) * dt
    const prevY = g.y
    g.y += g.vy * dt
    if (g.y >= ground) { g.y = ground; g.vy = 0; g.onBubble = null }

    // ④ 落到泡泡上（穿越检测：脚底这一帧跨过泡泡顶面就算踩到）
    if (g.vy > 0) {
      for (const b of g.bubbles) {
        if (b.used) continue
        const top = b.y - b.r
        if (prevY <= top + 6 && g.y >= top && Math.abs(g.x - b.x) <= b.r + 20) {
          b.used = true
          g.onBubble = b
          g.y = top
          g.vy = 0
          g.landedAt = g.t
          g.jumped++
          g.score += (C.scorePerBubble || 1200)
          audio.sfx('assets/sfx/onMouseOver_03.mp3')
          break
        }
      }
    }
    // ⑤ 大雁在飞（官方"它会动"）；撞上就被甩下去
    for (const go of g.geese) {
      go.x += go.dir * (C.gooseSpeed || 90) * dt
      if (go.x < go.x0) { go.x = go.x0; go.dir = 1 }
      if (go.x > go.x1) { go.x = go.x1; go.dir = -1 }
      if (Math.hypot(go.x - g.x, go.y - (g.y - 16)) < go.r + 14) {
        g.onBubble = null
        g.vy = 200
        g.msg = '撞到大雁了 —— 它会动，别踩它！'; g.msgT = 1.2
      }
    }
    // ⑥ 分数够了就通关（官方"只要 50000+ 就行啦"）
    if (g.score >= (C.target || 50000)) {
      g.over = 1
      notice(`爬到 ${g.score.toLocaleString()} 分 —— 冲上云霄！`)
      miniStagePass()
      return
    }
    // ⑦ 限时（分数保留，只重开计时）
    g.timeLeft -= dt
    if (g.timeLeft <= 0) {
      const keep = g.score
      st.sr = makeSoar()
      st.sr.score = keep
      st.sr.fails = g.fails + 1
      st.sr.msg = `时间到 —— 续一局（已得 ${keep.toLocaleString()} 分）`; st.sr.msgT = 1.8
      notice(st.sr.msg)
    }
  }
  function soarReset() {
    const st = dungeonState()
    st.sr = makeSoar()
  }`

const out = lines.slice(0, START - 1).concat(NEW.split('\n'), lines.slice(END))
fs.writeFileSync(f, out.join('\n'), 'utf8')
console.log(`✓ 冲上云霄已重写：${lines.length} → ${out.length} 行`)
