{"content": "// 一次性：把冲上云霄的阶梯改成"每一步都真的够得着"（第 48 轮最后一次修）
//
// 【为什么】之前的阶梯是"4 列固定轮转"，横向跨度 220px —— 玩家要横着走很久才能对准，
// 而玩家站在地面/泡泡上时一旦走到场地边界就卡死（实测 x=930 顶着墙到超时）。
// 这一版改成**链式生成**：每一层都在上一层的可达范围内（横向 ≤180、竖直正好 58），
// 于是"从下往上爬到 50000 分"在几何上一定做得到（这条由测试断言）。
import fs from 'node:fs'
const f = 'game/game.js'
let s = fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, '')
const OLD = `  function soarLadder() {
    const C = srParams()
    const gap = C.gapY || 58, r = C.bubbleR || 26
    const cols = 4
    const xs = []
    for (let c = 0; c < cols; c++) xs.push(150 + c * ((W - 300) / (cols - 1)))
    const out = []
    // 每层一列，列序按固定节奏轮转（可预测 = 可验证；官方只说"会叠在一起"，没给布局）
    const order = [0, 2, 1, 3, 2, 0, 3, 1]
    let y = SR_GROUND() - (C.jump || 450) * 0.55 + r     // 第一层顶面刚好在一跳之内
    for (let i = 0; i < 80; i++) {
      out.push({ x: xs[order[i % order.length]], y, r, used: false })
      y -= gap
    }
    return out
  }`
if (!s.includes(OLD)) { console.error('✗ 找不到旧的 soarLadder，未改动'); process.exit(1) }
const NEW = `  function soarLadder() {
    const C = srParams()
    const gap = C.gapY || 58, r = C.bubbleR || 26
    const jumpH = (C.jump || 450) * (C.jump || 450) / (2 * (C.gravity || 1500))
    const out = []
    const margin = 70                        // 离左右边界的余量（别把泡泡放在走不到的地方）
    let x = W / 2
    let y = SR_GROUND() - jumpH * 0.55 + r   // 第一层顶面刚好在一跳之内
    for (let i = 0; i < 80; i++) {
      out.push({ x, y, r, used: false })
      y -= gap
      // ★ **链式可达**：下一层横向最多挪 180px（走 0.9 秒）、竖直正好 58px（一跳 67.5px 够得着）。
      //   这样"一层层爬上去"在几何上一定成立 —— 玩家不会遇到"看得见、永远走不到"的泡泡。
      //   （旧版 4 列固定轮转、横向跨度 220px，玩家会走到场地边界顶着墙卡死。）
      const step = (Math.random() * 2 - 1) * 180
      x = Math.max(margin, Math.min(W - margin, x + step))
    }
    return out
  }`
s = s.replace(OLD, NEW)
fs.writeFileSync(f, s, 'utf8')
console.log('✓ soarLadder 已改成链式可达生成')
