{"content": "// 诊断：站在第一个泡泡上时，机器人到底把哪个泡泡当目标
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const inner = makeInput(W)
let log = []
const extra = { t, frame: 0, kd: (k) => { inner.kd(k); log.push('↓' + k.replace('Arrow', '')) }, ku: (k) => { inner.ku(k); log.push('↑' + k.replace('Arrow', '')) }, allUp: inner.allUp }
const P = DBG().soarParams()
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
for (let i = 0; i < 200; i++) {
  log = []
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  const g = DBG().soarState()
  const reach = (g.bubbles || []).filter((b) => b.y < g.y - 4 && g.y - b.y <= jumpH * 0.95 && Math.abs(b.x - g.x) <= 240)
  const cost = (b) => Math.abs(b.x - g.x) * 2 + (g.y - b.y)
  const inField = reach.filter((b) => b.x > 120 && b.x < 840)
  const tgt = (inField.length ? inField : reach).slice().sort((a, b) => cost(a) - cost(b))[0]
  if (i < 4 || (i > 28 && i < 50)) {
    console.log(`帧${i} 键[${log.join(' ')}] 我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 站=${g.onBubble ? 'Y' : 'N'}` +
      ` 目标=${tgt ? `(${tgt.x.toFixed(0)},${tgt.y.toFixed(0)}) 顶=${(tgt.y - tgt.r).toFixed(0)}` : '无'} 可达=${reach.length} 中段=${inField.length} 分=${g.score}`)
  }
  if (g.score >= 2400) { console.log(`★ 踩到第 2 个，分=${g.score}（帧 ${i}）`); break }
}
const g = DBG().soarState()
console.log('末态:', JSON.stringify({ x: Math.round(g.x), y: Math.round(g.y), score: g.score, jumped: g.jumped }))
", "file_path": "_tools\diag-soar8.mjs"}

