{"content": "// 诊断：第 49 轮——机器人在原地弹跳时，它锁定的目标到底是哪个泡泡
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
const extra = { t, frame: 0, ...io }
const P = DBG().soarParams()
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
for (let i = 0; i < 300; i++) {
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  const g = DBG().soarState()
  if (i % 20 === 0 || i < 4) {
    const bubbles = g.bubbles || []
    const reach = bubbles.filter((b) => b.y < g.y - 4 && g.y - b.y <= jumpH * 0.95 && Math.abs(b.x - g.x) <= 240)
    const inField = reach.filter((b) => b.x > 120 && b.x < 840)
    const pick = (arr) => arr.slice().sort((a, b) => (b.y - a.y) || (Math.abs(a.x - g.x) - Math.abs(b.x - g.x)))[0]
    const tgt = pick(inField.length ? inField : reach) || pick(bubbles.filter((b) => b.y < g.y - 4))
    console.log(`帧${i} 我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} grounded=${g.onBubble || g.vy === 0} locked=${!!extra._locked} lastJump=${extra._jumpAt}` +
      ` 可达=${reach.length} 中段=${inField.length} 目标=${tgt ? `(x=${tgt.x.toFixed(0)},y=${tgt.y.toFixed(0)}) dx=${(tgt.x - g.x).toFixed(0)}` : '无'} 分=${g.score} 跳=${g.jumped}`)
  }
}
const g = DBG().soarState()
console.log('末态:', JSON.stringify({ x: Math.round(g.x), y: Math.round(g.y), score: g.score, jumped: g.jumped }))
