    const out = []
    const margin = 70                        // 离左右边界的余量（别把泡泡放在走不到的地方）
    let x = W / 2
    let y = SR_GROUND() - jumpH * 0.55 + r   // 第一层顶面刚好在一跳之内
    for (let i = 0; i < 80; i++) {
      out.push({ x, y, r, used: false })
      y -= gap
      // ★ **链式可达**：下一层横向最多挪 110px、竖直正好 58px（一跳 67.5px 够得着）。
      //   110px 的依据：玩家起跳后仍可横向移动（200px/s），一次跳跃滞空约 0.6 秒 → 约 120px 的修正量。
