{"content": "// 诊断（第 50 轮）：重叠阶梯 + 空中不可控之后，机器人爬到哪一层
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
const extra = { t, frame: 0, ...io }
const P = DBG().soarParams()
const st = DBG().dungeonState().sr
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
console.log('参数:', JSON.stringify({ jump: P.jump, gravity: P.gravity, gapY: P.gapY, bubbleR: P.bubbleR, target: P.target }))
console.log('一跳高度:', jumpH.toFixed(1), ' 泡泡总数:', st.bubbles.length)
// 打印前 3 层的几何
for (let L = 0; L < 3; L++) {
  const row = st.bubbles.filter((b) => b.layer === L)
  console.log(`第 ${L} 层: y=${row[0].y.toFixed(0)} 顶面=${(row[0].y - row[0].r).toFixed(0)} x=[${row.map((b) => Math.round(b.x)).join(',')}]`)
}
for (let i = 0; i < 7200; i++) {
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  if (i % 600 === 0) {
    const g = DBG().soarState()
    console.log(`t=${(i / 60).toFixed(0)}s 我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 站=${g.onBubble ? 'Y' : 'N'} 分=${g.score} 踩=${g.jumped} 掉=${g.fails} 剩=${g.timeLeft.toFixed(0)}s`)
  }
  const d = DBG().dungeonState()
  if (d.phase !== 'soar') { console.log(`阶段结束 ${d.phase}（第 ${i} 帧）`); break }
}
const g = DBG().soarState()
console.log('末态:', JSON.stringify({ x: Math.round(g.x), y: Math.round(g.y), score: g.score, jumped: g.jumped, fails: g.fails }))
console.log('需要', Math.ceil((P.target || 50000) / (P.scorePerBubble || 1200)), '层')
