{"content": "// 诊断：卡住那一层的几何（第 50 轮）
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
const extra = { t, frame: 0, ...io }
const P = DBG().soarParams()
const st = DBG().dungeonState().sr
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
for (let i = 0; i < 1500; i++) {
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  const g = DBG().soarState()
  if (i === 1200) {
    console.log(`帧 1200：我(${g.x.toFixed(0)},${g.y.toFixed(0)}) 分=${g.score} 站=${g.onBubble ? 'Y' : 'N'} standTop=${g.standTop}`)
    const surf = g.standTop != null ? g.standTop : g.y
    const usedLayers = new Set(st.bubbles.filter((b) => b.used).map((b) => b.layer))
    console.log('已踩过的层号:', [...usedLayers].sort((a, b) => a - b).join(','))
    const maxUsed = Math.max(...usedLayers)
    for (let L = maxUsed; L <= maxUsed + 2 && L < 80; L++) {
      const row = st.bubbles.filter((b) => b.layer === L)
      if (!row.length) continue
      const rise = surf - (row[0].y - row[0].r)
      console.log(`第 ${L} 层: 顶面=${(row[0].y - row[0].r).toFixed(0)} x=[${row.map((b) => Math.round(b.x)).join(',')}] 落差=${rise.toFixed(0)}（一跳 ${jumpH.toFixed(0)}） 横向距=${row.map((b) => Math.round(Math.abs(b.x - g.x))).join(',')} used=${row.map((b) => b.used ? 1 : 0).join('')}`)
    }
    // 可达集合
    const bubbles = g.bubbles || []
    const reach = bubbles.filter((b) => { const rise = surf - (b.y - b.r); return rise > 4 && rise <= jumpH * 0.98 && Math.abs(b.x - g.x) <= 240 })
    console.log(`暴露泡泡 ${bubbles.length} 个，可达 ${reach.length} 个`)
