{"content": "// 诊断：卡住时逐帧看（第 50 轮）
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
const extra = { t, frame: 0, ...io }
const P = DBG().soarParams()
const st = DBG().dungeonState().sr
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
let lastScore = 0, stuckAt = -1
for (let i = 0; i < 2000; i++) {
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  const g = DBG().soarState()
  if (g.score !== lastScore) { lastScore = g.score; stuckAt = i }
  if (i - stuckAt > 500 && stuckAt > 0) {
    console.log(`★ 自第 ${stuckAt} 帧（分=${lastScore}）起 500 帧没有新进展`)
    console.log(`  我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 站=${g.onBubble ? 'Y' : 'N'} grounded=${g.onBubble || g.vy === 0} locked=${!!extra._locked} standTop=${g.standTop}`)
    const footY = g.y
    const bubbles = g.bubbles || []
    const reach = bubbles.filter((b) => { const rise = footY - (b.y - b.r); return rise > 4 && rise <= jumpH * 0.98 && Math.abs(b.x - g.x) <= 240 })
    const reachAny = bubbles.filter((b) => { const rise = footY - (b.y - b.r); return rise > 4 && rise <= jumpH * 0.98 })
    console.log(`  可达(含横向限制)=${reach.length}  可达(不限横向)=${reachAny.length}  暴露=${bubbles.length}`)
    if (reachAny.length) console.log('  不限横向的可达示例:', reachAny.slice(0, 4).map((b) => `(x=${Math.round(b.x)},顶=${Math.round(b.y - b.r)},横向=${Math.round(Math.abs(b.x - g.x))})`).join(' '))
    const usedLayers = new Set(st.bubbles.filter((b) => b.used).map((b) => b.layer))
    console.log('  已踩层:', [...usedLayers].sort((a, b) => a - b).join(','))
    // 逐帧打印最后 6 帧
    for (let k = 0; k < 6; k++) {
      const gg = DBG().soarState()
      console.log(`   帧 y=${gg.y.toFixed(0)} vy=${gg.vy.toFixed(0)} x=${gg.x.toFixed(0)} 分=${gg.score} 跳=${gg.jumped}`)
      STAGE_BOTS.soar(t, DBG, extra)
      extra.frame++
      DBG().soarTick(1 / 60)
    }
    break
  }
}
