await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
DBG().state.mode = 'explore'
DBG().startMinigame('soarSky')
const io = makeInput(W)
let log = []
const extra = { t, frame: 0, kd: (k) => { io.kd(k); log.push('↓' + k.replace('Arrow', '')) }, ku: (k) => { io.ku(k); log.push('↑' + k.replace('Arrow', '')) }, allUp: io.allUp }
const P = DBG().soarParams()
const st = DBG().dungeonState().sr
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
for (let i = 0; i < 1400; i++) {
  log = []
  STAGE_BOTS.soar(t, DBG, extra)
  extra.frame++
  DBG().soarTick(1 / 60)
  const g = DBG().soarState()
  if (i > 1150 && i % 25 === 0) {
    const bubbles = g.bubbles || []
    const footY = g.y
    const reach = bubbles.filter((b) => { const rise = footY - (b.y - b.r); return rise > 4 && rise <= jumpH * 0.98 && Math.abs(b.x - g.x) <= 240 })
    const pick = (arr) => arr.slice().sort((a, b) => (b.y - a.y) || (Math.abs(a.x - g.x) - Math.abs(b.x - g.x)))[0]
    const inField = reach.filter((b) => b.x > 120 && b.x < 840)
    const tgt = pick(inField.length ? inField : reach) || pick(bubbles.filter((b) => (footY - (b.y - b.r)) > 4))
    console.log(`帧${i} 键[${log.join(' ')}] 我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 站=${g.onBubble ? 'Y' : 'N'} bubbleX=${g.bubbleX == null ? '-' : Math.round(g.bubbleX)}` +
