{"content": "// 诊断：完全复刻 check-minigame-balance 的循环形状（bot → t.step(1)）
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const D = W.DKDbbData
const DBG = () => W.__DKDbb_DEBUG__
const S = () => DBG().state
const { kd, ku, allUp } = makeInput(W)
W.__SOAR_TRACE__ = true
allUp()
S().mode = 'explore'
console.log('开局:', DBG().startMinigame('soarSky'), ' phase=', DBG().dungeonState().phase)
const ctx = { t, kd, ku, frame: 0 }
const bot = STAGE_BOTS.soar
const cap = 90 * 60
let frames = 0
while (DBG().dungeonState().phase !== 'miniDone' && frames < cap) {
  ctx.frame = frames
  bot(t, DBG, ctx)
  t.step(1)
  frames++
  if (frames % 900 === 0) {
    const g = DBG().soarState()
    console.log(`帧${frames} (${(frames / 60).toFixed(0)}s) 分=${g ? g.score : '?'} 踩=${g ? g.jumped : '?'} y=${g ? g.y.toFixed(0) : '?'} phase=${DBG().dungeonState().phase}`)
  }
  if (S().mode === 'result') { t.key(' '); t.step(2) }
}
const st = DBG().dungeonState()
console.log(`结束：phase=${st.phase} 帧=${frames}（${(frames / 60).toFixed(1)}s） 通关=${st.phase === 'miniDone'}`)
const g = DBG().soarState()
if (g) console.log('末态分:', g.score, ' 踩:', g.jumped, ' 掉:', g.fails)
