{"content": "// 诊断：真实循环下逐帧看（bot → t.step(1)），找出为什么只爬到 3 层
import { T } from './game-harness.mjs'
import { makeInput, STAGE_BOTS } from './bot-lib.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
const S = () => DBG().state
const inner = makeInput(W)
let log = []
const kd = (k) => { inner.kd(k); log.push('D' + k.replace('Arrow', '')) }
const ku = (k) => { inner.ku(k); log.push('U' + k.replace('Arrow', '')) }
S().mode = 'explore'
DBG().startMinigame('soarSky')
const ctx = { t, kd, ku, allUp: inner.allUp, frame: 0 }
const P = DBG().soarParams()
const jumpH = (P.jump * P.jump) / (2 * P.gravity)
for (let i = 0; i < 900; i++) {
  log = []
  STAGE_BOTS.soar(t, DBG, ctx)
  t.step(1)
  ctx.frame++
  const g = DBG().soarState()
  if (i > 100 && i < 140) {
    const bubbles = g.bubbles || []
    const reach = bubbles.filter((b) => { const r = g.y - (b.y - b.r); return r > 4 && r <= jumpH * 0.98 && Math.abs(b.x - g.x) <= 240 })
    const pick = (arr) => arr.slice().sort((a, b) => (b.y - a.y) || (Math.abs(a.x - g.x) - Math.abs(b.x - g.x)))[0]
    const tgt = pick(reach.filter((b) => b.x > 120 && b.x < 840).length ? reach.filter((b) => b.x > 120 && b.x < 840) : reach)
      || pick(bubbles.filter((b) => (g.y - (b.y - b.r)) > 4))
    console.log(`帧${i} 键[${log.join(' ')}] 我(${g.x.toFixed(0)},${g.y.toFixed(0)}) vy=${g.vy.toFixed(0)} 站=${g.onBubble ? 'Y' : 'N'} grounded=${g.onBubble || g.vy === 0}` +
      ` 目标=${tgt ? `(x=${tgt.x.toFixed(0)},顶=${(tgt.y - tgt.r).toFixed(0)}) dx=${(tgt.x - g.x).toFixed(0)}` : '无'} 可达=${reach.length} 分=${g.score} 跳=${g.jumped}`)
  }
}
const g = DBG().soarState()
console.log('末态:', JSON.stringify({ x: Math.round(g.x), y: Math.round(g.y), score: g.score, jumped: g.jumped, fails: g.fails }))
