{"file_path": "game\game.js", "new_string": "  function drawBar(x, y, w, h, cur, max, color, label) {
    ctx.fillStyle = 'rgba(6,10,18,.85)'; ctx.fillRect(x - 2, y - 2, w + 4, h + 4)
    ctx.fillStyle = '#1b2334'; ctx.fillRect(x, y, w, h)
    ctx.fillStyle = color; ctx.fillRect(x, y, w * util.clamp(cur / max, 0, 1), h)
    ctx.strokeStyle = 'rgba(255,255,255,.25)'; ctx.lineWidth = 1; ctx.strokeRect(x + .5, y + .5, w - 1, h - 1)
    if (label) text.stroked(ctx, label, x + 2, y - 5, { size: 12, weight: 'normal', lw: 3 })
  }

  // ==================== 战斗名牌（照原版画，第 51 轮）====================
  //
  // 【为什么要单独一个函数】用户要求「战斗画风尽量还原页游」。
  // 原版（归档 `战斗截图.jpg`，962×546，与本作画布 960×540 几乎 1:1）实测：
  //   · 左上角一块**亮黄板 `#fff18b`**，上面压着**红字**名字 `#e33300`；
  //   · 黄板右边接一个**深蓝信息框**，里面是 **HP 条 `#7598c0`（蓝灰，不是红！）**
  //     与 **MP 条 `#2c95fe`（亮蓝）**，每条都带 `当前/上限` 数字；
  //   · 名牌整体位于 y 16~71（即画面上沿 3%~13%），玩家在左、敌方在右。
  // 【为什么不能沿用旧写法】旧代码用暗色块 + 红血条，玩家在战斗里**根本没有名牌**
  //   （名字只出现在探索界面的队伍卡里）—— 那是"我们的设计"，不是原版。
  // 所有尺寸按原版比例（乘以 W/962）缩放，所以换画布也不会走形。
  function drawBattleNameplate(o) {
    const k = W / 962                               // 原版 → 本画布的缩放比
    const plateW = o.big ? 168 * k : 138 * k        // 黄板宽（玩家板更大）
    const plateH = 52 * k
    const boxW = o.big ? 196 * k : 168 * k          // 深蓝信息框宽
    const x = o.align === 'right' ? o.x - (plateW + boxW) : o.x
    const y = o.y

    ctx.save()
    // ---- 黄色名牌（原版最大的视觉特征）----
    const g = ctx.createLinearGradient(0, y, 0, y + plateH)
    g.addColorStop(0, '#fff18b'); g.addColorStop(0.55, '#f7d94e'); g.addColorStop(1, '#e8b428')
    ctx.fillStyle = g
    ctx.fillRect(x, y, plateW, plateH)
    ctx.strokeStyle = '#8a5a10'; ctx.lineWidth = 2
    ctx.strokeRect(x + 1, y + 1, plateW - 2, plateH - 2)
    // 顶部一道亮高光（原版黄板有立体感）
    ctx.fillStyle = 'rgba(255,255,255,.45)'
    ctx.fillRect(x + 3, y + 3, plateW - 6, 3 * k)

    // ---- 深蓝信息框 ----
    const bx = x + plateW
    const bg = ctx.createLinearGradient(0, y, 0, y + plateH)
    bg.addColorStop(0, '#16295c'); bg.addColorStop(1, '#0b1a3e')
    ctx.fillStyle = bg
    ctx.fillRect(bx, y, boxW, plateH)
    ctx.strokeStyle = '#4a7fd4'; ctx.lineWidth = 2
    ctx.strokeRect(bx + 1, y + 1, boxW - 2, plateH - 2)

    // ---- 名字（红字压在黄板上 —— 原版就是这样）----
    const name = String(o.name || '')
    // 名字太长就按长度缩一点，别溢出黄板（这是"必须能画下"的硬要求）
    let nameSize = (o.big ? 20 : 17) * k
    if (name.length > 5) nameSize *= Math.max(0.62, 5 / name.length)
    text.stroked(ctx, name, x + plateW / 2, y + plateH * 0.64,
      { size: nameSize, align: 'center', color: '#e33300', lw: 3 })

    // ---- HP / MP 双条（原版：蓝灰 HP + 亮蓝 MP，各带数字）----
    const pad = 6 * k
    const barW = boxW - pad * 2
    const barH = 11 * k
    const barX = bx + pad
    const hpY = y + 9 * k
    const mpY = hpY + barH + 5 * k
    const miniBar = (by, cur, max, fill, edge) => {
      ctx.fillStyle = '#050c1e'; ctx.fillRect(barX - 1, by - 1, barW + 2, barH + 2)
      ctx.fillStyle = '#22304f'; ctx.fillRect(barX, by, barW, barH)
      const frac = util.clamp((cur || 0) / Math.max(1, max || 1), 0, 1)
      if (frac > 0) {
        const fg = ctx.createLinearGradient(0, by, 0, by + barH)
        fg.addColorStop(0, fill[0]); fg.addColorStop(1, fill[1])
        ctx.fillStyle = fg
        ctx.fillRect(barX, by, barW * frac, barH)
      }
      ctx.strokeStyle = edge; ctx.lineWidth = 1
      ctx.strokeRect(barX + .5, by + .5, barW - 1, barH - 1)
      // 数字压在条上（原版就是"1072/1124"这样贴在条上）
      text.stroked(ctx, `${Math.max(0, Math.round(cur || 0))}/${Math.round(max || 0)}`,
        barX + barW - 3, by + barH - 2 * k,
        { size: 10.5 * k, align: 'right', color: '#ffffff', lw: 3 })
    }
    miniBar(hpY, o.hp, o.maxHp, ['#a9c4e4', '#7598c0'], '#c8dcf5')
    miniBar(mpY, o.mp, o.maxMp, ['#63b8ff', '#2c95fe'], '#a8d8ff')
    ctx.restore()
  }
