{"file_path": "game\game.js", "new_string": "  function notice(msg, ms = 1600) {
    const b = S.battle
    if (!b) { toast(msg, ms); return }
    b.notice = { text: msg, until: performance.now() + ms }
    battleLog(msg)                       // 同时进战斗消息框（第 51 轮：原版左下角那个白底框）
    audio.sfx('assets/sfx/onClick_03.mp3')
  }

  // 战斗消息框的内容（原版左下角那条白底框写的就是战斗播报）。
  // 【为什么要单独存】原来战斗里的提示只有"画面正中一闪而过"的那种，玩家打完之后
  // 完全想不起来"刚才那一击打了多少"。原版的做法是**留一条常驻的消息框**，
  // 所以这里把每条播报都记下来，最多留 LOG_MAX 条。
  const LOG_MAX = 5
  function battleLog(msg) {
    const b = S.battle
    if (!b || !msg) return
    if (!b.log) b.log = []
    b.log.push({ text: String(msg), t: performance.now() })
    while (b.log.length > LOG_MAX) b.log.shift()
  }

  // ==================== 战斗左下角：消息框 + 三个橙色按钮（第 51 轮）====================
  // 【为什么要做】原版（归档 `战斗截图.jpg` 左下角实测）就长这样：
  //   一条**白底消息框** `#cdd3e1` 滚动战斗播报，右边三个**橙色方钮** `#f07a1b`。
  //   【关键决定：给真功能，不做装饰】早先那版这里有"两个小方块"，因为**没有任何功能**
  //   被我自己删掉了（见下方注释）。所以这次三个钮都必须真的有用：
  //     ← 返回：退出战斗（要确认，防误触）  ☰ 菜单：切换战斗速度  💬 说话：快捷发言进消息框
  function drawBattleMsgAndButtons(B, L) {
    const b = S.battle
    if (!b) return
    const mx = B.leftX, mw = B.leftW, mh = 30
    const my = B.y + BATTLE_BAR_H - mh - 14            // 贴底对齐（原版消息框在最下面）
    // 白底消息框（原版底色 #cdd3e1，文字是深蓝）
    drawOrigPanel(mx, my, mw, mh, { top: '#eef2f8', bot: '#cdd3e1', edge: '#afbfcf', r: 7 })
    const lines = (b.log || []).slice(-1)               // 框很窄，只显示最新一条
    const last = lines[lines.length - 1]
    text.stroked(ctx, last ? last.text : '（战斗播报）', mx + 8, my + mh * 0.68,
      { size: 12, align: 'left', color: '#1b2b52', lw: 0, weight: 'normal' })
    // 更早的几条用小字列在框上方（原版是滚动，这里用叠字近似，信息量一样）
    const older = (b.log || []).slice(0, -1).slice(-2)
    older.forEach((l, i) => {
      ctx.save()
      ctx.globalAlpha = 0.5 - i * 0.15
      text.stroked(ctx, l.text, mx + 8, my - 6 - i * 13,
        { size: 10.5, align: 'left', color: '#dfe8f5', lw: 3, weight: 'normal' })
      ctx.restore()
    })

    // 三个橙色方钮（原版尺寸约 22×22，摆在消息框右上角那一排）
    const s = 22, gap = 6
    const bx0 = mx + mw - (s * 3 + gap * 2)
    const by = my - s - 6
    L.battleBtns = [
      { id: 'back', x: bx0, y: by, w: s, h: s, glyph: '←', tip: '退出战斗' },
      { id: 'menu', x: bx0 + s + gap, y: by, w: s, h: s, glyph: '☰', tip: '战斗速度' },
      { id: 'talk', x: bx0 + (s + gap) * 2, y: by, w: s, h: s, glyph: '💬', tip: '快捷发言' },
    ]
    for (const btn of L.battleBtns) {
      const hot = S.hoverBattleBtn === btn.id
      drawOrigBtn(btn.x, btn.y, s, btn.glyph)
      if (hot) {
        ctx.save()
        ctx.strokeStyle = 'rgba(255,240,180,.9)'; ctx.lineWidth = 2
        roundBox(btn.x - 2, btn.y - 2, s + 4, s + 4, 6); ctx.stroke()
        ctx.restore()
        // 悬停时把功能名写出来（原版没有提示，但"按钮不写用途"是我早先删按钮的原因）
        const tw = btn.tip.length * 12 + 12
        ctx.save()
        ctx.fillStyle = 'rgba(8,14,26,.92)'
        roundBox(btn.x + s / 2 - tw / 2, btn.y - 24, tw, 18, 6); ctx.fill()
        text.stroked(ctx, btn.tip, btn.x + s / 2, btn.y - 11, { size: 11, align: 'center', color: '#ffe45e', lw: 3 })
        ctx.restore()
      }
    }
  }

  // 三个按钮的真功能（键鼠共用入口）
  const QUICK_TALK = ['加油！', '小心它的技能！', '先打小的', '谢谢～']
  function battleBtnAct(id) {
    const b = S.battle
    if (!b) return
    if (id === 'back') {
      if (b.phase !== 'command') { notice('等这一下打完再退'); return }
      // 确认一下再退（防误触；原版这个键也是"返回"）
      if (S.battleQuitAsk) { S.battleQuitAsk = false; fleeBattle(); return }
      S.battleQuitAsk = true
      notice('再点一次「←」就退出战斗')
      return
    }
    if (id === 'menu') {
      // 战斗速度：1× → 2× → 3× 循环（原版这个键开菜单，我们这里放最实用的那项）
      const order = [1, 2, 3]
      const cur = order.indexOf(S.battleSpeed || 1)
      S.battleSpeed = order[(cur + 1) % order.length]
      notice(`战斗速度 ${S.battleSpeed}×`)
      return
    }
    if (id === 'talk') {
      // 快捷发言：循环发一句（原版这个键是聊天输入，我们给一组预设）
      S.talkIdx = ((S.talkIdx || 0) + 1) % QUICK_TALK.length
      battleLog('我说：' + QUICK_TALK[S.talkIdx])
      notice('我说：' + QUICK_TALK[S.talkIdx])
    }
  }
