{"content": "// 「基础多克多比」高清效果图：把归档里的 4000×2333 官方立绘与游戏现在用的 311×640 并排对比。
//
// 【为什么做这个】用户要求「画一个基础多克多比高清版让我看看效果图」。
// 探针 `_tools/probe-form-art-hi.mjs` 查出归档里有 **92 张 >=600px 的透明官方立绘**，
// 其中 `克罗多比.png` 是 **4000×2333**；而游戏实际加载的是从归档里抽出并缩过的
// `assets/forms/art/克罗.png`（**311×640**）。所以"高清版"不是要重画，而是**把高清原图用起来**。
// 这张图就是给用户看的证据：左边=现在游戏里的清晰度，右边=归档高清原图的清晰度。
//
// 用法: node _tools/render-form-hd-preview.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng, makeFramebuffer, PixelCtx, parseColor } from './pixel-canvas.mjs'
import { loadGlyphAtlas, TextRenderer } from './text-render.mjs'

const ROOT = path.resolve('.')
const OUT = path.join(ROOT, 'docs', 'shots', 'form-hd-preview.png')
const HI = '多克多比专区资料素材/多比形态素材/克罗多比.png'
const LO = 'assets/forms/art/克罗.png'

// ---------- 读图 + 求"有效像素外框"（去掉四周透明留白）----------
function loadFont(p) {
  const img = decodePng(fs.readFileSync(path.join(ROOT, p)))
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) {
    for (let x = 0; x < img.w; x++) {
      const a = img.rgba[(y * img.w + x) * 4 + 3]
      if (a > 8) {
        if (x < x0) x0 = x; if (x > x1) x1 = x
        if (y < y0) y0 = y; if (y > y1) y1 = y
      }
    }
  }
  if (x1 < 0) return { img, box: { x0: 0, y0: 0, x1: img.w - 1, y1: img.h - 1 } }
  return { img, box: { x0, y0, x1, y1 } }
}

// ---------- 面积平均降采样（把 4000px 的图做成"目标高度"的干净缩略）----------
// 用面积平均而不是最近邻：缩小时最近邻会丢掉细节并产生锯齿。
function downscale(img, box, dstH) {
  const sw = box.x1 - box.x0 + 1, sh = box.y1 - box.y0 + 1
  const scale = dstH / sh
  const dw = Math.max(1, Math.round(sw * scale)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy0 = box.y0 + Math.floor(y / scale), sy1 = Math.max(sy0 + 1, box.y0 + Math.floor((y + 1) / scale))
    for (let x = 0; x < dw; x++) {
      const sx0 = box.x0 + Math.floor(x / scale), sx1 = Math.max(sx0 + 1, box.x0 + Math.floor((x + 1) / scale))
      let r = 0, g = 0, b = 0, a = 0, n = 0
      for (let sy = sy0; sy < sy1 && sy <= box.y1; sy++) {
        for (let sx = sx0; sx < sx1 && sx <= box.x1; sx++) {
          const i = (sy * img.w + sx) * 4
          const al = img.rgba[i + 3] / 255
          r += img.rgba[i] * al; g += img.rgba[i + 1] * al; b += img.rgba[i + 2] * al; a += img.rgba[i + 3]
          n++
        }
      }
      if (!n) continue
      const aa = a / n
      const wsum = a / 255 || 1
      const o = (y * dw + x) * 4
      out[o] = r / wsum; out[o + 1] = g / wsum; out[o + 2] = b / wsum; out[o + 3] = aa
    }
  }
  return { w: dw, h: dh, rgba: out }
}

// ---------- 双线性放大（把"游戏里的 311×640"放大到展示尺寸，模拟游戏内的糊）----------
function bilinear(src, dstH) {
  const scale = dstH / src.h
  const dw = Math.max(1, Math.round(src.w * scale)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy = (y + 0.5) / scale - 0.5
    const y0 = Math.max(0, Math.floor(sy)), y1 = Math.min(src.h - 1, y0 + 1), fy = Math.max(0, sy - y0)
    for (let x = 0; x < dw; x++) {
      const sx = (x + 0.5) / scale - 0.5
      const x0 = Math.max(0, Math.floor(sx)), x1 = Math.min(src.w - 1, x0 + 1), fx = Math.max(0, sx - x0)
      const o = (y * dw + x) * 4
      for (let c = 0; c < 4; c++) {
        const p00 = src.rgba[(y0 * src.w + x0) * 4 + c], p10 = src.rgba[(y0 * src.w + x1) * 4 + c]
        const p01 = src.rgba[(y1 * src.w + x0) * 4 + c], p11 = src.rgba[(y1 * src.w + x1) * 4 + c]
        out[o + c] = (p00 * (1 - fx) + p10 * fx) * (1 - fy) + (p01 * (1 - fx) + p11 * fx) * fy
      }
    }
  }
  return { w: dw, h: dh, rgba: out }
}

// ---------- 把一张 RGBA 画到 framebuffer（带 alpha 混合）----------
function blit(fb, img, dx, dy) {
  for (let y = 0; y < img.h; y++) {
    const ty = dy + y
    if (ty < 0 || ty >= fb.h) continue
    for (let x = 0; x < img.w; x++) {
      const tx = dx + x
      if (tx < 0 || tx >= fb.w) continue
      const s = (y * img.w + x) * 4
      const a = img.rgba[s + 3] / 255
      if (a <= 0.004) continue
      const d = (ty * fb.w + tx) * 4
      fb.rgba[d] = img.rgba[s] * a + fb.rgba[d] * (1 - a)
      fb.rgba[d + 1] = img.rgba[s + 1] * a + fb.rgba[d + 1] * (1 - a)
      fb.rgba[d + 2] = img.rgba[s + 2] * a + fb.rgba[d + 2] * (1 - a)
      fb.rgba[d + 3] = 255
    }
  }
}

// ---------- 画布 ----------
const CW = 1440, CH = 900
const fb = makeFramebuffer(CW, CH)
const ctx = new PixelCtx(fb)
const atlas = loadGlyphAtlas()
const text = new TextRenderer(ctx, atlas)

// 背景：深蓝渐变（跟战斗界面同一个调子）
const bg = ctx.createLinearGradient(0, 0, 0, CH)
bg.addColorStop(0, '#0a1430'); bg.addColorStop(1, '#04070f')
ctx.fillStyle = bg; ctx.fillRect(0, 0, CW, CH)

console.log('读取归档高清立绘…')
const hi = loadFont(HI)
console.log(`  高清: ${hi.img.w}×${hi.img.h}，有效内容 ${hi.box.x1 - hi.box.x0 + 1}×${hi.box.y1 - hi.box.y0 + 1}`)
const lo = loadFont(LO)
console.log(`  游戏内: ${lo.img.w}×${lo.img.h}，有效内容 ${lo.box.x1 - lo.box.x0 + 1}×${lo.box.y1 - lo.box.y0 + 1}`)

const showH = 620                       // 展示高度
// 右：高清原图降采样到展示高度（= 屏幕上"高清版"的样子）
const hiShown = downscale(hi.img, hi.box, showH)
// 左：把游戏内的图放大到展示高度（= 现在屏幕上的样子，含糊）
const loUp = bilinear({ w: lo.box.x1 - lo.box.x0 + 1, h: lo.box.y1 - lo.box.y0 + 1, rgba: (() => {
  const w = lo.box.x1 - lo.box.x0 + 1, h = lo.box.y1 - lo.box.y0 + 1
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((lo.box.y0 + y) * lo.img.w + (lo.box.x0 + x)) * 4
    const d = (y * w + x) * 4
    out[d] = lo.img.rgba[s]; out[d + 1] = lo.img.rgba[s + 1]; out[d + 2] = lo.img.rgba[s + 2]; out[d + 3] = lo.img.rgba[s + 3]
  }
  return out
})() }, showH)

// 两块面板
const padT = 96, panelW = 620
const leftX = 60, rightX = CW - 60 - panelW
const py = padT, ph = showH + 90
ctx.fillStyle = 'rgba(16,28,56,.85)'
ctx.fillRect(leftX - 24, py - 18, panelW + 48, ph)
ctx.fillRect(rightX - 24, py - 18, panelW + 48, ph)
ctx.strokeStyle = '#3aa0e8'; ctx.lineWidth = 2
ctx.strokeRect(leftX - 24, py - 18, panelW + 48, ph)
ctx.strokeStyle = '#ffd23f'
ctx.strokeRect(rightX - 24, py - 18, panelW + 48, ph)

// 标题
text.draw(ctx, '多克多比 · 高清立绘对比', CW / 2, 52, { size: 34, align: 'center', color: '#ffe45e' })
text.draw(ctx, '同一个官方素材：左＝现在游戏加载的缩略图（放大后糊）；右＝归档里的高清原图',
  CW / 2, 78, { size: 16, align: 'center', color: '#9fb0cc' })

// 缩放显示
const fit = (src, boxW, boxH) => {
  const s = Math.min(boxW / src.w, boxH / src.h)
  return { src, w: Math.round(src.w * s), h: Math.round(src.h * s) }
}
const L = fit(loUp, panelW - 40, showH)
const R = fit(hiShown, panelW - 40, showH)
blit(fb, L.src, leftX - 24 + (panelW + 48 - L.w) / 2, py + 30 + (showH - L.h) / 2)
blit(fb, R.src, rightX - 24 + (panelW + 48 - R.w) / 2, py + 30 + (showH - R.h) / 2)

// 面板下方说明
text.draw(ctx, `现在：assets/forms/art/克罗.png  ${lo.img.w}×${lo.img.h}`, leftX + panelW / 2, py + ph - 34,
  { size: 17, align: 'center', color: '#ff9a8a' })
text.draw(ctx, '', leftX + panelW / 2, py + ph - 14, { size: 13, align: 'center', color: '#9fb0cc' })
text.draw(ctx, `归档：多比形态素材/克罗多比.png  ${hi.img.w}×${hi.img.h}`, rightX + panelW / 2, py + ph - 34,
  { size: 17, align: 'center', color: '#8affa8' })

// 底部结论
text.draw(ctx, `放大倍数差 ${Math.round(hi.img.w / lo.img.w)} 倍 —— 换成高清原图后，人物边缘不再发虚`, CW / 2, CH - 46,
  { size: 18, align: 'center', color: '#ffe45e' })

fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(CW, CH, fb.rgba))
console.log('已写出', path.relative(ROOT, OUT), `${CW}×${CH}`)
", "file_path": "_tools\render-form-hd-preview.mjs"}

