    if (img.data[i] > maxA) maxA = img.data[i]
  }
  const mid = ((img.h >> 1) * img.w + (img.w >> 1)) * 4
  console.log(`${path.basename(p)}: ${img.w}×${img.h}  不透明像素 ${opaque} (${(opaque / (img.w * img.h) * 100).toFixed(1)}%)  最大 alpha ${maxA}`)
  console.log(`   中心像素 rgba = ${img.data[mid]},${img.data[mid + 1]},${img.data[mid + 2]},${img.data[mid + 3]}`)
  // 找第一个不透明像素
  let fx = -1, fy = -1
  outer: for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 8) { fx = x; fy = y; break outer }
