{"file_path": "_tools\render-form-hd-preview.mjs", "new_string": "// ---------- 把一张 RGBA 画到 framebuffer（带 alpha 混合）----------
// ⚠️ 尺寸必须**显式传进来**：`makeFramebuffer` 返回的是**裸 Uint8Array**（不是 {w,h,data}），
//    所以 `fb.w`/`fb.h` 是 undefined —— 第一版就是这么写的，比较 `ty >= undefined` 恒为 true，
//    整个循环每帧都被跳过，一个人像素都没画上去（而我加的"自检"把它抓了出来）。
function blit(fb, fw, fh, img, dx, dy) {
  for (let y = 0; y < img.h; y++) {
    const ty = dy + y
    if (ty < 0 || ty >= fh) continue
    for (let x = 0; x < img.w; x++) {
      const tx = dx + x
      if (tx < 0 || tx >= fw) continue
      const s = (y * img.w + x) * 4
      const a = img.data[s + 3] / 255
      if (a <= 0.004) continue
      const d = (ty * fw + tx) * 4
      fb[d] = img.data[s] * a + fb[d] * (1 - a)
      fb[d + 1] = img.data[s + 1] * a + fb[d + 1] * (1 - a)
      fb[d + 2] = img.data[s + 2] * a + fb[d + 2] * (1 - a)
      fb[d + 3] = 255
    }
  }
}", "old_string": "// ---------- 把一张 RGBA 画到 framebuffer（带 alpha 混合）----------
