{"content": "// 从输出图里采样，确认左右两块的**真实颜色**（不许只靠肉眼判断）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'
const ROOT = path.resolve('.')
const img = decodePng(fs.readFileSync(path.join(ROOT, 'docs/shots/form-hd-preview.png')))
console.log(`输出图 ${img.w}×${img.h}`)
const at = (x, y) => { const i = (y * img.w + x) * 4; return [img.data[i], img.data[i + 1], img.data[i + 2], img.data[i + 3]] }
const hex = (c) => '#' + c.slice(0, 3).map((v) => v.toString(16).padStart(2, '0')).join('')

// 找左右两块面板里的"最饱和"像素（人物主体），并统计色相
function scan(name, x0, x1, y0, y1) {
  const hue = { 橙黄: 0, 青蓝: 0, 其他: 0 }
  let best = null, bestSat = -1
  for (let y = y0; y < y1; y += 2) for (let x = x0; x < x1; x += 2) {
    const [r, g, b] = at(x, y)
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b)
    const sat = mx - mn
    if (sat > bestSat) { bestSat = sat; best = [r, g, b, x, y] }
    if (sat < 40) continue
    if (r >= g && g > b) hue.橙黄++
    else if (b >= g && g > r) hue.青蓝++
    else hue.其他++
  }
  console.log(`${name}: 最饱和像素 ${best ? hex(best) + ` @(${best[3]},${best[4]})` : '无'}`)
  console.log(`   色相分布  橙黄 ${hue.橙黄}  青蓝 ${hue.青蓝}  其他 ${hue.其他}`)
}
scan('左面板(游戏内素材)', 30, 690, 100, 780)
scan('右面板(归档高清)  ', 750, 1410, 100, 780)
", "file_path": "_tools\diag-hd-colors.mjs"}

{"content": "// 插桩：找出颜色在哪一步变掉的
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'
const ROOT = path.resolve('.')
const img = decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/克罗.png')))
const at = (d, w, x, y) => { const i = (y * w + x) * 4; return [d[i], d[i + 1], d[i + 2], d[i + 3]] }
console.log('原图 colorType 已确认 6；中心像素:', at(img.data, img.w, 155, 320))

// 复刻 render-form-hd-preview 的 crop → bilinear
function crop(f, box) {
  const w = box.x1 - box.x0 + 1, h = box.y1 - box.y0 + 1
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((box.y0 + y) * f.img.w + (box.x0 + x)) * 4
    const d = (y * w + x) * 4
    out[d] = f.img.data[s]; out[d + 1] = f.img.data[s + 1]
    out[d + 2] = f.img.data[s + 2]; out[d + 3] = f.img.data[s + 3]
  }
  return { w, h, data: out }
}
const box = { x0: 0, y0: 0, x1: img.w - 1, y1: img.h - 1 }
const c = crop({ img }, box)
console.log('crop 后中心:', at(c.data, c.w, 155, 320))

function bilinear(src, dstH) {
  const scale = dstH / src.h
  const dw = Math.max(1, Math.round(src.w * scale)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy = (y + 0.5) / scale - 0.5
    const y0 = Math.max(0, Math.floor(sy)), y1 = Math.min(src.h - 1, y0 + 1), fy = Math.max(0, sy - y0)
    for (let x = 0; x < dw; x++) {
      const sx = (x + 0.5) / scale - 0.5
      const x0 = Math.max(0, Math.floor(sx)), x1 = Math.min(src.w - 1, x0 + 1), fx = Math.max(0, sx - x0)
      const o = (y * dw + x) * 4
      for (let c2 = 0; c2 < 4; c2++) {
        const p00 = src.data[(y0 * src.w + x0) * 4 + c2], p10 = src.data[(y0 * src.w + x1) * 4 + c2]
        const p01 = src.data[(y1 * src.w + x0) * 4 + c2], p11 = src.data[(y1 * src.w + x1) * 4 + c2]
        out[o + c2] = (p00 * (1 - fx) + p10 * fx) * (1 - fy) + (p01 * (1 - fx) + p11 * fx) * fy
      }
    }
  }
  return { w: dw, h: dh, data: out }
}
const up = bilinear(c, 620)
const mid = at(up.data, up.w, Math.round(up.w / 2), Math.round(up.h / 2))
console.log(`bilinear 到 620 后中心 (${up.w}×${up.h}):`, mid)

function downscaleSrc(src, dstH) {
  const scale = dstH / src.h
  const dw = Math.max(1, Math.round(src.w * scale)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy0 = Math.floor(y / scale), sy1 = Math.max(sy0 + 1, Math.floor((y + 1) / scale))
    for (let x = 0; x < dw; x++) {
      const sx0 = Math.floor(x / scale), sx1 = Math.max(sx0 + 1, Math.floor((x + 1) / scale))
      let r = 0, g = 0, b = 0, a = 0, n = 0
      for (let sy = sy0; sy < sy1 && sy < src.h; sy++) for (let sx = sx0; sx < sx1 && sx < src.w; sx++) {
        const i = (sy * src.w + sx) * 4
        const al = src.data[i + 3] / 255
        r += src.data[i] * al; g += src.data[i + 1] * al; b += src.data[i + 2] * al
        a += src.data[i + 3]; n++
      }
      if (!n) continue
      const wsum = a / 255 || 1
      const o = (y * dw + x) * 4
      out[o] = r / wsum; out[o + 1] = g / wsum; out[o + 2] = b / wsum; out[o + 3] = a / n
    }
  }
  return { w: dw, h: dh, data: out }
}
const dn = downscaleSrc(up, 620)
console.log(`downscaleSrc 到 620 后中心 (${dn.w}×${dn.h}):`, at(dn.data, dn.w, Math.round(dn.w / 2), Math.round(dn.h / 2)))
", "file_path": "_tools\diag-hd-steps.mjs"}

