  const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
  const s = Math.max(r, g, b) - Math.min(r, g, b)
  if (s > bs) { bs = s; best = [r, g, b, x, y] }
  if (s > 40) { if (r >= g && g > b) warm++; else if (b >= g && g > r) cyan++ }
}
