{"content": "// 盘点：每个形态的立绘**有效像素高度** vs 目标 640px（= 屏幕最大显示 320px 的 2 倍）
//
// 目的：找出"小图拉大的"形态 —— 那才是看起来糊的原因（尺寸够但源像素不够）。
// 用法: node _tools/audit-form-art-2x.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'assets', 'forms', 'art')
const TARGET_H = 640          // = 屏幕最大显示 320px × 2

const rows = []
for (const f of fs.readdirSync(DIR).filter((n) => n.endsWith('.png') && !n.includes('_icon')).sort()) {
  const img = decodePng(fs.readFileSync(path.join(DIR, f)))
  // 有效内容外框（去掉透明留白）
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) {
    for (let x = 0; x < img.w; x++) {
      if (img.data[(y * img.w + x) * 4 + 3] > 8) {
        if (x < x0) x0 = x; if (x > x1) x1 = x
        if (y < y0) y0 = y; if (y > y1) y1 = y
      }
    }
  }
  if (x1 < 0) { rows.push({ name: f.replace('.png', ''), w: img.w, h: img.h, cw: 0, ch: 0, kb: 0, verdict: '空图' }); continue }
  const cw = x1 - x0 + 1, ch = y1 - y0 + 1
  const kb = Math.round(fs.statSync(path.join(DIR, f)).size / 1024)
  // 有效内容高度 / 目标：<1 说明源像素不足（会被放大 → 糊）
  const ratio = ch / TARGET_H
  const verdict = ratio >= 1 ? '够' : ratio >= 0.75 ? '偏小' : '不足'
  rows.push({ name: f.replace('.png', ''), w: img.w, h: img.h, cw, ch, kb, ratio, verdict })
}

rows.sort((a, b) => (a.ratio || 0) - (b.ratio || 0))
console.log(`目标有效高度 ${TARGET_H}px（= 屏幕最大显示 320px 的 2 倍）\n`)
console.log('  形态            画布      有效内容    有效高/目标  体积   判定')
for (const r of rows) {
  if (r.verdict === '空图') { console.log(`  ${r.name.padEnd(14)} ${r.w}×${r.h}  —  空图`); continue }
  console.log(`  ${r.name.padEnd(14)} ${String(r.w + '×' + r.h).padEnd(9)} ${String(r.cw + '×' + r.ch).padEnd(11)} ` +
    `${r.ratio.toFixed(2).padStart(6)}      ${String(r.kb + 'KB').padStart(6)}  ${r.verdict}`)
}
const short = rows.filter((r) => r.verdict === '不足')
const near = rows.filter((r) => r.verdict === '偏小')
console.log(`\n合计 ${rows.length} 张：够 ${rows.length - short.length - near.length} / 偏小 ${near.length} / 不足 ${short.length}`)
console.log(`需要重新同步的（不足 + 偏小）：${[...short, ...near].map((r) => r.name).join('、') || '无'}`)
", "file_path": "_tools\audit-form-art-2x.mjs"}

{"content": "// 给"源像素不足"的形态在归档里找**高清原图**（>=640px 有效高度）
// 用法: node _tools/find-form-art-hi.mjs
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
// 需要补高清的形态（来自 audit-form-art-2x.mjs 的结论）
const NEED = ['哈瑞肯多比', '凤凰多比', '正义多比', '费勒姆炎多比', '人鱼多比', '兔多比', '艾斯林',
  '龙多比', '斯莱特刃多比', '毒多比', '曼陀罗多比', '土蝎多比', '夜影冽多比', '夜影空多比',
  '厄斯垒', '夜影博伊斯多比', '冰多比', '夜影凌多比', '夜影厄斯多比', '夜影正义多比']
// 每个形态的"检索关键词"（文件名里可能不带"多比"二字，得按官方名找）
const KEYS = {
  哈瑞肯多比: ['哈瑞肯', '哈瑞'],
  凤凰多比: ['凤凰'],
  正义多比: ['正义'],
  费勒姆炎多比: ['费勒姆', '炎多比'],
  人鱼多比: ['人鱼'],
  兔多比: ['瑞比特', '兔多比'],
  艾斯林: ['艾斯·林', '艾斯林', '艾斯'],
  龙多比: ['龙多比', '德拉科'],
  斯莱特刃多比: ['斯莱特'],
  毒多比: ['毒多比', '普伊斯', '蛛多比'],
  曼陀罗多比: ['曼陀罗'],
  土蝎多比: ['土蝎'],
  夜影冽多比: ['夜影冽', '冽'],
  夜影空多比: ['夜影空'],
  厄斯垒: ['厄斯'],
  夜影博伊斯多比: ['博伊斯'],
  冰多比: ['冰多比', '弗瑞斯'],
  夜影凌多比: ['夜影凌'],
  夜影厄斯多比: ['夜影厄斯'],
  夜影正义多比: ['夜影正义'],
}

function pngInfo(p) {
  const fd = fs.openSync(p, 'r')
  try {
    const b = Buffer.alloc(34)
    fs.readSync(fd, b, 0, 34, 0)
    if (b.readUInt32BE(0) !== 0x89504e47) return null
    return { w: b.readUInt32BE(16), h: b.readUInt32BE(20), colorType: b[25] }
  } finally { fs.closeSync(fd) }
}

// 扫归档里所有 >=600px 的透明 PNG
const ROOTS = ['多克多比专区资料素材']
const all = []
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name)
    if (e.isDirectory()) { walk(p); continue }
    if (!/\.(png|PNG)$/.test(e.name)) continue
    const info = pngInfo(p)
    if (!info || info.w < 600) continue
    if (info.colorType !== 6 && info.colorType !== 4) continue
    all.push({ p, ...info, size: fs.statSync(p).size })
  }
}
for (const r of ROOTS) walk(path.join(ROOT, r))
console.log(`归档里 >=600px 的透明 PNG：${all.length} 张\n`)

for (const name of NEED) {
  const keys = KEYS[name] || [name]
  const hits = all.filter((f) => keys.some((k) => path.basename(f.p).includes(k)))
  hits.sort((a, b) => (b.w * b.h) - (a.w * a.h))
  console.log(`【${name}】关键词 ${keys.join('/')} → 命中 ${hits.length}`)
  for (const h of hits.slice(0, 3)) {
    console.log(`    ${h.w}×${h.h}  ${Math.round(h.size / 1024)}KB  ${path.relative(ROOT, h.p).replace(/\\/g, '/')}`)
  }
  if (!hits.length) console.log('    （归档里没有 >=600px 的透明图 → 只能用现有素材放大，或确认原版就没画）')
}
", "file_path": "_tools\find-form-art-hi.mjs"}

{"content": "// 扩大搜索：给"源像素不足"的 20 个形态在归档里找**一切可用的大图源**
// 不只看透明 PNG，也看 JPG / 编号图；命中按"有效像素高度"排序（不是画布大小）。
// 用法: node _tools/find-form-art-hi2.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const NEED = ['哈瑞肯多比', '凤凰多比', '正义多比', '费勒姆炎多比', '人鱼多比', '兔多比', '艾斯林',
  '龙多比', '斯莱特刃多比', '毒多比', '曼陀罗多比', '土蝎多比', '夜影冽多比', '夜影空多比',
  '厄斯垒', '夜影博伊斯多比', '冰多比', '夜影凌多比', '夜影厄斯多比', '夜影正义多比']
const KEYS = {
  哈瑞肯多比: ['哈瑞肯', '哈瑞'], 凤凰多比: ['凤凰'], 正义多比: ['正义'],
  费勒姆炎多比: ['费勒姆', '炎多比', '费勒姆炎'], 人鱼多比: ['人鱼'], 兔多比: ['瑞比特', '兔多比'],
  艾斯林: ['艾斯·林', '艾斯林', '艾斯', '艾斯林'], 龙多比: ['龙多比', '德拉科'],
  斯莱特刃多比: ['斯莱特'], 毒多比: ['毒多比', '普伊斯', '蛛多比'], 曼陀罗多比: ['曼陀罗'],
  土蝎多比: ['土蝎'], 夜影冽多比: ['夜影冽', '冽多比'], 夜影空多比: ['夜影空'],
  厄斯垒: ['厄斯'], 夜影博伊斯多比: ['博伊斯'], 冰多比: ['冰多比', '弗瑞斯'],
  夜影凌多比: ['夜影凌'], 夜影厄斯多比: ['夜影厄斯'], 夜影正义多比: ['夜影正义'],
}

function pngInfo(p) {
  const fd = fs.openSync(p, 'r')
  try {
    const b = Buffer.alloc(34)
    fs.readSync(fd, b, 0, 34, 0)
    if (b.readUInt32BE(0) !== 0x89504e47) return null
    return { w: b.readUInt32BE(16), h: b.readUInt32BE(20), ct: b[25] }
  } finally { fs.closeSync(fd) }
}

// 先收集：文件名命中任一关键词的所有图片（png/jpg）
const names = []
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name)
    if (e.isDirectory()) { walk(p); continue }
    if (!/\.(png|PNG|jpg|JPG|jpeg)$/.test(e.name)) continue
    names.push(p)
  }
}
walk(path.join(ROOT, '多克多比专区资料素材'))
console.log(`归档图片总数：${names.length}`)

for (const form of NEED) {
  const keys = KEYS[form] || [form]
  const cand = names.filter((p) => keys.some((k) => path.basename(p).includes(k)))
  // 逐个求"有效像素高度"（透明图算 alpha 外框；JPG 算非白外框），只留够大的
  const scored = []
  for (const p of cand.slice(0, 400)) {
    const isPng = /\.png$/i.test(p)
    let w = 0, h = 0, eff = 0
    if (isPng) {
      const info = pngInfo(p)
      if (!info) continue
      w = info.w; h = info.h
      // 太大的先按画布估（不逐个解码 4000px 的图，太慢）；>=700 就够
      eff = Math.min(h, info.w) >= 700 ? h : 0
    } else {
      try {
        const fd = fs.openSync(p, 'r'); const b = Buffer.alloc(4); fs.readSync(fd, b, 0, 4, 0); fs.closeSync(fd)
        if (b[0] !== 0xFF || b[1] !== 0xD8) continue
      } catch { continue }
      // JPEG 尺寸要扫 SOF 段
      const buf = fs.readFileSync(p)
      for (let i = 2; i + 9 < buf.length;) {
        if (buf[i] !== 0xFF) { i++; continue }
        const m = buf[i + 1]
        if (m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) {
          h = buf.readUInt16BE(i + 5); w = buf.readUInt16BE(i + 7); break
        }
        i += 2 + buf.readUInt16BE(i + 2)
      }
      if (!h) continue
      eff = Math.min(h, w) >= 700 ? h : 0
    }
    if (eff > 0) scored.push({ p, w, h, eff })
  }
  scored.sort((a, b) => b.eff - a.eff)
  const uniq = []
  const seen = new Set()
  for (const s of scored) { const d = path.dirname(s.p); if (seen.has(d)) continue; seen.add(d); uniq.push(s) }
  console.log(`\n【${form}】命中大图 ${uniq.length} 处`)
  for (const s of uniq.slice(0, 3)) {
    console.log(`    ${s.w}×${s.h}  ${path.relative(ROOT, s.p).replace(/\\/g, '/')}`)
  }
  if (!uniq.length) console.log('    ✗ 归档里没有 >=700px 的图 → 原版大概率就没画高清版（或只在活动素材里）')
}
", "file_path": "_tools\find-form-art-hi2.mjs"}

