async function loadImage(rel) {
  const abs = path.join(ROOT, rel)
  if (/\.png$/i.test(rel)) return decodePng(fs.readFileSync(abs))
  if (/\.jpe?g$/i.test(rel)) {
    const mod = await import('./lib/jpeg.mjs').catch(() => null)
    if (!mod || typeof mod.decodeJpeg !== 'function') {
