{"content": "// 下载 Real-ESRGAN ncnn-vulkan（Windows）到 _tools/ai/（不进发布包）
// 用法: node _tools/get-realesrgan.mjs
import https from 'node:https'
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, '_tools', 'ai')
const ZIP = path.join(DIR, 'realesrgan-windows.zip')
const URL = 'https://github.com/xinntao/Real-ESRGAN/releases/download/v0.2.5.0/realesrgan-ncnn-vulkan-20220424-windows.zip'

fs.mkdirSync(DIR, { recursive: true })
if (fs.existsSync(ZIP) && fs.statSync(ZIP).size > 40 * 1048576) {
  console.log(`已存在 ${path.relative(ROOT, ZIP)}（${(fs.statSync(ZIP).size / 1048576).toFixed(1)} MB），跳过下载`)
  process.exit(0)
}

function download(url, dst, depth = 0) {
  return new Promise((resolve, reject) => {
    if (depth > 5) return reject(new Error('跳转过多'))
    https.get(url, { timeout: 60000, headers: { 'User-Agent': 'node' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume()
        return resolve(download(new URL(res.headers.location, url).href, dst, depth + 1))
      }
      if (res.statusCode !== 200) return reject(new Error('HTTP ' + res.statusCode))
      const total = Number(res.headers['content-length'] || 0)
      let got = 0, lastPct = -1
      const out = fs.createWriteStream(dst)
      res.on('data', (c) => {
        got += c.length
        if (total) {
          const pct = Math.floor(got / total * 100)
          if (pct >= lastPct + 10) { lastPct = pct; console.log(`  ${pct}%  ${(got / 1048576).toFixed(1)}/${(total / 1048576).toFixed(1)} MB`) }
        }
      })
      res.pipe(out)
      out.on('finish', () => out.close(() => resolve({ bytes: got })))
      out.on('error', reject)
    }).on('error', reject)
  })
}

console.log('下载 Real-ESRGAN ncnn-vulkan（Windows 版）…')
try {
  const r = await download(URL, ZIP)
  console.log(`✓ 下载完成：${(r.bytes / 1048576).toFixed(1)} MB → ${path.relative(ROOT, ZIP)}`)
} catch (e) {
  console.log('✗ 下载失败：' + e.message)
  process.exit(1)
}
