{"content": "// 多连接并行下载 Real-ESRGAN（Windows）。单连接只有 ~11 KB/s，43 MB 要一小时 —— 所以分段并发。
//
// 做法：先 HEAD/GET 拿最终 URL 与 Content-Length，然后开 N 个 Range 连接各下一段，
//   合并成一个 zip。任何一段失败就重试该段（最多 5 次）。
// ⚠️ 段文件写在 `_tools/ai/parts/`，全部到齐才合并 —— 中途断掉可以重跑续传。
//
// 用法: node _tools/get-realesrgan2.mjs
import https from 'node:https'
import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, '_tools', 'ai')
const PARTS = path.join(DIR, 'parts')
const ZIP = path.join(DIR, 'realesrgan-windows.zip')
const SRC = 'https://github.com/xinntao/Real-ESRGAN/releases/download/v0.2.5.0/realesrgan-ncnn-vulkan-20220424-windows.zip'
const CONN = 6

fs.mkdirSync(PARTS, { recursive: true })
const agent = new https.Agent({ keepAlive: true, maxSockets: CONN + 2 })

function req(url, headers = {}, depth = 0) {
  return new Promise((resolve, reject) => {
    if (depth > 5) return reject(new Error('跳转过多'))
    const lib = url.startsWith('http:') ? http : https
    const r = lib.get(url, { headers: { 'User-Agent': 'node', ...headers }, agent, timeout: 120000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume()
        return resolve(req(new global.URL(res.headers.location, url).href, headers, depth + 1))
      }
      resolve(res)
    })
    r.on('timeout', () => r.destroy(new Error('超时')))
    r.on('error', reject)
  })
}

console.log('探测文件大小…')
const head = await req(SRC, { Range: 'bytes=0-0' })
const cr = head.headers['content-range'] || ''
const total = cr ? Number(cr.split('/')[1]) : Number(head.headers['content-length'])
head.resume()
if (!total) { console.log('✗ 拿不到文件大小'); process.exit(1) }
console.log(`总大小 ${(total / 1048576).toFixed(1)} MB，用 ${CONN} 个连接分段下载`)

const seg = Math.ceil(total / CONN)
let doneBytes = 0

async function fetchSeg(i) {
  const from = i * seg, to = Math.min(total - 1, (i + 1) * seg - 1)
  const dst = path.join(PARTS, `p${i}.bin`)
  if (fs.existsSync(dst) && fs.statSync(dst).size === to - from + 1) {
    doneBytes += fs.statSync(dst).size
    console.log(`  段 ${i}：已存在，跳过（${((to - from + 1) / 1048576).toFixed(1)} MB）`)
    return
  }
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const res = await req(SRC, { Range: `bytes=${from}-${to}` })
      if (res.statusCode !== 206 && res.statusCode !== 200) throw new Error('HTTP ' + res.statusCode)
      const chunks = []
      await new Promise((resolve, reject) => {
        res.on('data', (c) => chunks.push(c))
        res.on('end', resolve)
        res.on('error', reject)
      })
      const buf = Buffer.concat(chunks)
      if (buf.length !== to - from + 1) throw new Error(`长度不对 ${buf.length} != ${to - from + 1}`)
      fs.writeFileSync(dst, buf)
      doneBytes += buf.length
      console.log(`  段 ${i}：完成 ${(buf.length / 1048576).toFixed(1)} MB（累计 ${(doneBytes / 1048576).toFixed(1)}/${(total / 1048576).toFixed(1)}）`)
      return
    } catch (e) {
      console.log(`  段 ${i}：第 ${attempt} 次失败（${e.message}）`)
      if (attempt === 5) throw e
      await new Promise((r) => setTimeout(r, 1500 * attempt))
    }
  }
}

const t0 = Date.now()
try {
  await Promise.all(Array.from({ length: CONN }, (_, i) => fetchSeg(i)))
} catch (e) {
  console.log('✗ 下载失败：' + e.message + '（重跑本脚本可续传）')
  process.exit(1)
}
// 合并
const out = fs.createWriteStream(ZIP)
for (let i = 0; i < CONN; i++) {
  const buf = fs.readFileSync(path.join(PARTS, `p${i}.bin`))
  await new Promise((r) => out.write(buf, r))
}
await new Promise((r) => out.end(r))
const size = fs.statSync(ZIP).size
console.log(`✓ 合并完成 ${path.relative(ROOT, ZIP)}  ${(size / 1048576).toFixed(1)} MB  用时 ${((Date.now() - t0) / 1000).toFixed(0)}s`)
fs.rmSync(PARTS, { recursive: true, force: true })
", "file_path": "_tools\get-realesrgan2.mjs"}

