{"file_path": "_tools\sr-form-art.mjs", "new_string": "// 灰影清理：AI 超分会把源 JPG 里的**脚底灰色投影**一起放大并保留下来，
// 而官方生成器 `build-form-art.mjs` 有一道泛洪抠背景专门吃掉它。
// 【为什么不能直接复用他的 removeBackground】那函数从**四边**泛洪（源是白底图）；
//   而 AI 输出已经是**透明底**，"从透明像素继续扩散"的路径在这里不成立 ——
//   实测 `正义多比` 会留下 52% 灰影，被 `test-form-art.mjs` 的残留检查抓住。
// 所以这里改成**对着灰影本身的特征判**：低饱和 + 偏亮 + 落在下半部。
// 两趟：① 从边缘/透明处泛洪，任意亮度都吃（连通到外面的灰影）；
//      ② 下半部再按严格中性灰（R≈G≈B 且 ≥120）直接吃（不连通但明显是投影的）。
function cleanGrayShadow(img) {
  const { w, h, data } = img
  const isGreyish = (i) => {
    const r = data[i], g = data[i + 1], b = data[i + 2]
    return Math.max(r, g, b) - Math.min(r, g, b) <= 14 && (r + g + b) / 3 >= 110
  }
  const isNearNeutral = (i) => {
    const r = data[i], g = data[i + 1], b = data[i + 2]
    return Math.max(r, g, b) - Math.min(r, g, b) <= 12 && (r + g + b) / 3 >= 120
  }
  const dead = new Uint8Array(w * h)
  const q = []
  const push = (p) => { if (!dead[p] && data[p * 4 + 3] > 0) { dead[p] = 1; q.push(p) } }
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x) }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1) }
  for (let p = 0; p < w * h; p++) if (data[p * 4 + 3] < 8) dead[p] = 1      // 已有的透明像素
  // ① 连通扩散：只吃"灰"像素
  while (q.length) {
    const p = q.pop()
    const x = p % w, y = (p / w) | 0
    const nb = []
    if (x > 0) nb.push(p - 1)
    if (x < w - 1) nb.push(p + 1)
    if (y > 0) nb.push(p - w)
    if (y < h - 1) nb.push(p + w)
    for (const n2 of nb) if (!dead[n2] && isGreyish(n2 * 4)) push(n2)
  }
  // ② 下半部的严格中性灰（不连通也吃）
  for (let y = Math.floor(h * 0.62); y < h; y++) {
    for (let x = 0; x < w; x++) {
      const p = y * w + x
      if (!dead[p] && isNearNeutral(p * 4)) dead[p] = 1
    }
  }
  let n = 0
  for (let p = 0; p < w * h; p++) if (dead[p] && data[p * 4 + 3] > 0) { data[p * 4 + 3] = 0; n++ }
  return n
}

