{"content": "// 搭一个便携 Python（embeddable）+ Pillow，用于跑 `gen-form-walk.mjs`（它内嵌 Python 且要用 PIL）
//
// 【为什么需要】走路帧生成器 `_tools/gen-form-walk.mjs` 是**内嵌 Python** 的脚本，
//   而本机 `python` 是 Windows 应用商店的占位（`python --version` 无输出）、没有 PIL。
//   官方 Python 安装包动辄 25 MB+ 且要走安装器；**embeddable zip 只有约 11 MB**，
//   解压即用、不写注册表 —— 正合适放进 `_tools/py/`（不进发布包，见 make-dist 白名单）。
//
// ⚠️ embeddable 版**默认不带 pip、也不读 site-packages**，所以：
//   ① 先解开 `python3XX._pth`（注释掉 `import site` 那行的注释）；
//   ② 下 get-pip.py 装上 pip；③ `pip install pillow`。
//
// 用法: node _tools/setup-python-pil.mjs
import fs from 'node:fs'
import path from 'node:path'
import https from 'node:https'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const PYDIR = path.join(ROOT, '_tools', 'py')
const ZIP = path.join(ROOT, '_tools', 'py-embed.zip')
const PYVER = '3.11.9'
const MIRRORS = [
  (u) => 'https://gh-proxy.com/' + u,
  (u) => u,
]
const PY_URL = `https://github.com/indygreg/python-build-standalone/releases/download/20240415/cpython-${PYVER}+20240415-x86_64-pc-windows-msvc-shared-install_only.tar.gz`

function fetch(url, dst, depth = 0) {
  return new Promise((resolve, reject) => {
    if (depth > 4) return reject(new Error('跳转过多'))
    https.get(url, { headers: { 'User-Agent': 'node' }, timeout: 120000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume()
        return resolve(fetch(new global.URL(res.headers.location, url).href, dst, depth + 1))
      }
      if (res.statusCode !== 200) return reject(new Error('HTTP ' + res.statusCode))
      const out = fs.createWriteStream(dst)
      res.pipe(out)
      out.on('finish', () => out.close(() => resolve(fs.statSync(dst).size)))
      out.on('error', reject)
    }).on('error', reject)
  })
}

