{"content": "// 诊断：HD 之后到底哪一步改了配色 —— 分步量"主体平均色"
// 用法: node _tools/diag-hd-colors.mjs 正义多比
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const form = process.argv[2] || '正义多比'
const BEF = path.join(ROOT, '_tmp_test_out', 'art-before-sr', form + '.png')   // 官方源直出
const NOW = path.join(ROOT, 'assets', 'forms', 'art', form + '.png')           // 现在在用的
const TMP = path.join(ROOT, '_tmp_test_out', 'sr')
const EXE = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'realesrgan-ncnn-vulkan.exe')
const MODELS = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'models')

// 主体平均色：只统计**完全不透明**的像素（>250），并按亮度分档，这样能看出"白有没有变黑"
function stats(p, label) {
  const img = decodePng(fs.readFileSync(p))
  let n = 0, r = 0, g = 0, b = 0
  const buckets = { 白: 0, 亮: 0, 中: 0, 暗: 0, 黑: 0 }
  for (let i = 0; i < img.w * img.h; i++) {
    if (img.data[i * 4 + 3] < 250) continue
    const R = img.data[i * 4], G = img.data[i * 4 + 1], B = img.data[i * 4 + 2]
    r += R; g += G; b += B; n++
    const lum = (R + G + B) / 3
    if (lum >= 230) buckets.白++
    else if (lum >= 180) buckets.亮++
    else if (lum >= 110) buckets.中++
    else if (lum >= 50) buckets.暗++
    else buckets.黑++
  }
  const pct = (v) => (n ? (v / n * 100).toFixed(1) + '%' : '-')
  console.log(`${label.padEnd(22)} ${img.w}×${img.h}  平均色 rgb(${Math.round(r / n)},${Math.round(g / n)},${Math.round(b / n)})`)
  console.log(`${' '.repeat(22)} 亮度分布  白${pct(buckets.白)} 亮${pct(buckets.亮)} 中${pct(buckets.中)} 暗${pct(buckets.暗)} 黑${pct(buckets.黑)}`)
  return { img, buckets, n }
}

console.log(`=== ${form} 的分步配色对比 ===\n`)
stats(BEF, '① 官方源直出（改前）')
const up = path.join(TMP, form + '_4x.png')
if (!fs.existsSync(up)) {
  execFileSync(EXE, ['-i', BEF, '-o', up, '-s', '4', '-n', 'realesrgan-x4plus-anime', '-m', MODELS], { stdio: 'ignore' })
}
stats(up, '② AI 4× 超分（未后处理）')
stats(NOW, '③ 最终（含去灰影+缩放）')
console.log('\n判读：如果 ② 的白/亮占比就掉了一大截 → 是 AI 改的色；如果 ② 正常、③ 掉了 → 是我的去灰影/缩放改的')
