{"content": "// 公平的"放大质量"对比：同一张立绘（官方源直出）用两种方式放到同一显示尺寸
//   左 = 双线性/面积平均放大（= 以前游戏里看到的效果）
//   右 = Real-ESRGAN 超分后降采样（= 现在 HD 的效果）
// 两边**同尺寸、同背景**，只差"放大算法"这一个变量 —— 这样看到的差别才是算法造成的。
//
// 用法: node _tools/make-upscale-compare.mjs 正义多比 [输出.png]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const form = process.argv[2] || '正义多比'
const OUT = path.join(ROOT, 'docs', 'shots',
  (process.argv[3] && process.argv[3].endsWith('.png')) ? process.argv[3] : 'upscale-compare.png')
const SRC = path.join(ROOT, '_tmp_test_out', 'art-before-sr', form + '.png')  // 官方源直出
const TMP = path.join(ROOT, '_tmp_test_out', 'sr')
const EXE = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'realesrgan-ncnn-vulkan.exe')
const MODELS = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'models')
const SHOW = 620

if (!fs.existsSync(SRC)) { console.log('找不到官方源直出版本：' + SRC); process.exit(1) }

const bbox = (img) => {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 8) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  return x1 < 0 ? { x0: 0, y0: 0, x1: img.w - 1, y1: img.h - 1 } : { x0, y0, x1, y1 }
}
const crop = (img, b) => {
  const w = b.x1 - b.x0 + 1, h = b.y1 - b.y0 + 1
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((b.y0 + y) * img.w + (b.x0 + x)) * 4, d = (y * w + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w, h, data: out }
}
const fit = (img, dstH) => {
  const sc = dstH / img.h, dw = Math.max(1, Math.round(img.w * sc)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy0 = Math.floor(y / sc), sy1 = Math.max(sy0 + 1, Math.floor((y + 1) / sc))
    for (let x = 0; x < dw; x++) {
      const sx0 = Math.floor(x / sc), sx1 = Math.max(sx0 + 1, Math.floor((x + 1) / sc))
      let r = 0, g = 0, b = 0, a = 0, n = 0
      for (let sy = sy0; sy < sy1 && sy < img.h; sy++) for (let sx = sx0; sx < sx1 && sx < img.w; sx++) {
        const i = (sy * img.w + sx) * 4, al = img.data[i + 3] / 255
        r += img.data[i] * al; g += img.data[i + 1] * al; b += img.data[i + 2] * al
        a += img.data[i + 3]; n++
      }
      if (!n) continue
      const ws = a / 255 || 1, o = (y * dw + x) * 4
      out[o] = r / ws; out[o + 1] = g / ws; out[o + 2] = b / ws; out[o + 3] = a / n
    }
  }
  return { w: dw, h: dh, data: out }
}
const sharp = (img) => {
  const L = (i) => 0.299 * img.data[i] + 0.587 * img.data[i + 1] + 0.114 * img.data[i + 2]
  let s = 0, s2 = 0, n = 0
  for (let y = 1; y < img.h - 1; y++) for (let x = 1; x < img.w - 1; x++) {
    const i = (y * img.w + x) * 4
    if (img.data[i + 3] < 200) continue
    const v = 4 * L(i) - L(i - 4) - L(i + 4) - L(i - img.w * 4) - L(i + img.w * 4)
    s += v; s2 += v * v; n++
  }
  return n ? s2 / n - (s / n) ** 2 : 0
}

const plainImg = decodePng(fs.readFileSync(SRC))
const plain = fit(crop(plainImg, bbox(plainImg)), SHOW)

const up = path.join(TMP, form + '_4x.png')
if (!fs.existsSync(up)) {
  execFileSync(EXE, ['-i', SRC, '-o', up, '-s', '4', '-n', 'realesrgan-x4plus-anime', '-m', MODELS], { stdio: 'ignore' })
}
const upImg = decodePng(fs.readFileSync(up))
const hd = fit(crop(upImg, bbox(upImg)), SHOW)

console.log(`${form}：源 ${plainImg.w}×${plainImg.h} → 两边都放到高 ${SHOW}`)
console.log(`  左（面积平均放大） 锐度 ${sharp(plain).toFixed(0)}`)
console.log(`  右（AI 超分后缩放）锐度 ${sharp(hd).toFixed(0)}（×${(sharp(hd) / sharp(plain)).toFixed(2)}）`)

const GAP = 24, PAD = 20
const W = PAD * 2 + plain.w + GAP + hd.w
const H = PAD * 2 + SHOW
const fb = new Uint8ClampedArray(W * H * 4)
for (let i = 0; i < W * H; i++) { fb[i * 4] = 12; fb[i * 4 + 1] = 18; fb[i * 4 + 2] = 38; fb[i * 4 + 3] = 255 }
const place = (im, ox) => {
  for (let y = 0; y < im.h; y++) for (let x = 0; x < im.w; x++) {
    const s = (y * im.w + x) * 4, al = im.data[s + 3] / 255
    if (al <= 0) continue
    const d = ((PAD + y) * W + ox + x) * 4
    fb[d] = im.data[s] * al + fb[d] * (1 - al)
    fb[d + 1] = im.data[s + 1] * al + fb[d + 1] * (1 - al)
    fb[d + 2] = im.data[s + 2] * al + fb[d + 2] * (1 - al)
    fb[d + 3] = 255
  }
}
place(plain, PAD)
place(hd, PAD + plain.w + GAP)
fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(W, H, fb))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${W}×${H}`)
", "file_path": "_tools\make-upscale-compare.mjs"}

{"content": "// 模型对比：哪个超分模型**最不改配色**（颜色保真优先）
//
// 用户口径：「变高清之后配色变化了」→ 那"保色"就是硬指标。
// 判据（都对同一显示尺寸算）：
//   · 平均色差（vs 官方源直出的放大版）—— 越小越保色
//   · 平均饱和度差 —— 正数=AI 更艳
//   · 平均亮度差 —— 正数=AI 更亮
//   · 锐度增益 —— 越大越清晰
//
// 用法: node _tools/cmp-sr-models.mjs 正义多比
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const form = process.argv[2] || '正义多比'
const SRC = path.join(ROOT, '_tmp_test_out', 'art-before-sr', form + '.png')
const TMP = path.join(ROOT, '_tmp_test_out', 'sr')
const EXE = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'realesrgan-ncnn-vulkan.exe')
const MODELS = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'models')
const SHOW = 256          // 比较用的统一高度

const bbox = (img) => {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 8) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  return { x0, y0, x1, y1 }
}
const norm = (img, dstH) => {
  const b = bbox(img)
  const sw = b.x1 - b.x0 + 1, sh = b.y1 - b.y0 + 1
  const sc = dstH / sh, dw = Math.max(1, Math.round(sw * sc)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) {
    const sy0 = b.y0 + Math.floor(y / sc), sy1 = Math.max(sy0 + 1, b.y0 + Math.floor((y + 1) / sc))
    for (let x = 0; x < dw; x++) {
      const sx0 = b.x0 + Math.floor(x / sc), sx1 = Math.max(sx0 + 1, b.x0 + Math.floor((x + 1) / sc))
      let r = 0, g = 0, b2 = 0, a = 0, n = 0
      for (let sy = sy0; sy < sy1 && sy <= b.y1; sy++) for (let sx = sx0; sx < sx1 && sx <= b.x1; sx++) {
        const i = (sy * img.w + sx) * 4, al = img.data[i + 3] / 255
        r += img.data[i] * al; g += img.data[i + 1] * al; b2 += img.data[i + 2] * al
        a += img.data[i + 3]; n++
      }
      if (!n) continue
      const ws = a / 255 || 1, o = (y * dw + x) * 4
      out[o] = r / ws; out[o + 1] = g / ws; out[o + 2] = b2 / ws; out[o + 3] = a / n
    }
  }
  return { w: dw, h: dh, data: out }
}
// 只统计两边都不透明的像素，才算"同一块区域"
function compare(A, B) {
  const w = Math.min(A.w, B.w), h = Math.min(A.h, B.h)
  let n = 0, dSum = 0, satA = 0, satB = 0, lumA = 0, lumB = 0
  let s = 0, s2 = 0
  const L = (d, i) => 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = (y * w + x) * 4
    if (A.data[i + 3] < 200 || B.data[i + 3] < 200) continue
    n++
    dSum += Math.hypot(A.data[i] - B.data[i], A.data[i + 1] - B.data[i + 1], A.data[i + 2] - B.data[i + 2])
    const sa = Math.max(A.data[i], A.data[i + 1], A.data[i + 2]) - Math.min(A.data[i], A.data[i + 1], A.data[i + 2])
    const sb = Math.max(B.data[i], B.data[i + 1], B.data[i + 2]) - Math.min(B.data[i], B.data[i + 1], B.data[i + 2])
    satA += sa; satB += sb
    lumA += L(A.data, i); lumB += L(B.data, i)
    const v = 4 * L(B.data, i) - L(B.data, i - 4) - L(B.data, i + 4) - L(B.data, i - w * 4) - L(B.data, i + w * 4)
    s += v; s2 += v * v
  }
  return {
    n,
    colorDist: dSum / n,
    satDelta: (satB - satA) / n,
    lumDelta: (lumB - lumA) / n,
    sharp: s2 / n - (s / n) ** 2,
  }
}

const base = norm(decodePng(fs.readFileSync(SRC)), SHOW)
console.log(`${form}：源 ${bbox(decodePng(fs.readFileSync(SRC))).x1 + 1}px 宽 → 统一放大到高 ${SHOW}\n`)
console.log('  模型                        色差↓   饱和差↓   亮度差↓   锐度↑')
console.log(`  面积平均放大（基准）         —        —         —        ${compare(base, base).sharp.toFixed(0)}`)
for (const model of ['realesrgan-x4plus-anime', 'realesrgan-x4plus']) {
  const up = path.join(TMP, `${form}_${model}.png`)
  if (!fs.existsSync(up)) {
    execFileSync(EXE, ['-i', SRC, '-o', up, '-s', '4', '-n', model, '-m', MODELS], { stdio: 'ignore' })
  }
  const r = compare(base, norm(decodePng(fs.readFileSync(up)), SHOW))
  console.log(`  ${model.padEnd(26)} ${r.colorDist.toFixed(1).padStart(6)}  ${r.satDelta.toFixed(1).padStart(7)}  ${r.lumDelta.toFixed(1).padStart(7)}  ${r.sharp.toFixed(0).padStart(7)}`)
}
", "file_path": "_tools\cmp-sr-models.mjs"}

{"file_path": "_tools\sr-form-art.mjs", "new_string": "function cleanGrayShadow(img) {
  const { w, h, data } = img
  // ⚠️⚠️ **这段踩过两个坑，改动前务必读完** ⚠️⚠️
  //   坑 1（太宽）：判据写成「色差 ≤12 且亮度 ≥120」，结果把**白色铠甲/翅膀**也删了
  //     —— 白色本身就是无彩色（R≈G≈B）！正义多比的铠甲、哈瑞肯的翅膀被挖成黑块。
  //   坑 2（太窄）：为救白铠甲把"灰"限制成"中等灰 110~190"，结果**又吃不掉投影**
  //     —— `test-form-art.mjs` 报「正义多比 脚底灰影残留 48%」。
  //   **正解：不要靠颜色阈值去分"白"和"灰"（它们本质同色），靠"连通性"分。**
  //     投影永远**连着画面边缘**（它在人物外面、铺到图边）；
  //     而白铠甲是**被人身包住的内部区域**，从边缘泛洪根本走不到它那里。
  //     所以：只做**一趟从边缘/透明处的连通扩散**，判据放宽到「低饱和且不太暗」即可，
  //     内部的白/灰一律安全。
  const isGreyish = (i) => {
    const r = data[i], g = data[i + 1], b = data[i + 2]
    const d = Math.max(r, g, b) - Math.min(r, g, b)
    const lum = (r + g + b) / 3
    return d <= 16 && lum >= 105          // 低饱和 + 不是黑描边/暗部
  }
  const dead = new Uint8Array(w * h)
  const q = []
  const push = (p) => { if (!dead[p] && data[p * 4 + 3] > 0) { dead[p] = 1; q.push(p) } }
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x) }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1) }
  for (let p = 0; p < w * h; p++) if (data[p * 4 + 3] < 8) dead[p] = 1      // 已有的透明像素也算外围
  while (q.length) {
    const p = q.pop()
    const x = p % w, y = (p / w) | 0
    const nb = []
    if (x > 0) nb.push(p - 1)
    if (x < w - 1) nb.push(p + 1)
    if (y > 0) nb.push(p - w)
    if (y < h - 1) nb.push(p + w)
    for (const n2 of nb) if (!dead[n2] && isGreyish(n2 * 4)) push(n2)
  }
  let n = 0
  for (let p = 0; p < w * h; p++) if (dead[p] && data[p * 4 + 3] > 0) { data[p * 4 + 3] = 0; n++ }
  return n
}", "old_string": "function cleanGrayShadow(img) {
  const { w, h, data } = img
  const isGreyish = (i) => {
    const r = data[i], g = data[i + 1], b = data[i + 2]
    return Math.max(r, g, b) - Math.min(r, g, b) <= 14 && (r + g + b) / 3 >= 110
  }
  // ⚠️⚠️ **这条判据踩过大坑，改动前先读完** ⚠️⚠️
  // 第一版写成「色差 ≤12 且亮度 ≥120」—— 结果把**白色铠甲/翅膀**也当灰影删了
  //   （白色本身就是无彩色 R≈G≈B！），正义多比的铠甲、哈瑞肯的翅膀、人鱼的下身
  //   全被挖成黑色大块。截图一看就露馅，`test-form-art` 的灰影检查也拦不住（它只看下半部）。
  // 正解：把"白"和"灰"分开
  //   · **白**（护甲高光/翅膀）色差 ≤5（几乎纯中性）→ 允许吃，但**亮度上限 205**，
  //     超过 205 的一律保留（那是纯白，不是灰影）；
  //   · **灰影**是"中等灰"：亮度落在 110~190，色差 ≤10 —— 这才是脚底投影的特征。
  // 亮度上限是关键：投影永远不会比 205 还亮。
  const isShadowGrey = (i) => {
    const r = data[i], g = data[i + 1], b = data[i + 2]
    const d = Math.max(r, g, b) - Math.min(r, g, b)
    const lum = (r + g + b) / 3
    if (lum > 205) return false                 // 纯白护甲：保留
    return d <= 6 ? lum >= 100 : (d <= 10 && lum >= 110 && lum <= 190)
  }
  const dead = new Uint8Array(w * h)
  const q = []
  const push = (p) => { if (!dead[p] && data[p * 4 + 3] > 0) { dead[p] = 1; q.push(p) } }
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x) }
  for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1) }
  for (let p = 0; p < w * h; p++) if (data[p * 4 + 3] < 8) dead[p] = 1      // 已有的透明像素
  // ① 连通扩散：只吃"灰"像素
  while (q.length) {
    const p = q.pop()
    const x = p % w, y = (p / w) | 0
    const nb = []
    if (x > 0) nb.push(p - 1)
    if (x < w - 1) nb.push(p + 1)
    if (y > 0) nb.push(p - w)
    if (y < h - 1) nb.push(p + w)
    for (const n2 of nb) if (!dead[n2] && isGreyish(n2 * 4)) push(n2)
  }
  // ② 下半部：按"白/灰分开"的判据吃投影（不连通也吃）
  for (let y = Math.floor(h * 0.62); y < h; y++) {
    for (let x = 0; x < w; x++) {
      const p = y * w + x
      if (!dead[p] && isShadowGrey(p * 4)) dead[p] = 1
    }
  }
  let n = 0
  for (let p = 0; p < w * h; p++) if (dead[p] && data[p * 4 + 3] > 0) { data[p * 4 + 3] = 0; n++ }
  return n
}"}

