{"content": "// 量"脚底灰影"的真实颜色区间（用它来定判据，而不是猜）
// 用法: node _tools/probe-shadow-color.mjs 正义多比
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const form = process.argv[2] || '正义多比'
const SRC = path.join(ROOT, '_tmp_test_out', 'art-before-sr', form + '.png')
const TMP = path.join(ROOT, '_tmp_test_out', 'sr')
const EXE = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'realesrgan-ncnn-vulkan.exe')
const MODELS = path.join(ROOT, '_tools', 'ai', 'realesrgan', 'models')

// 用 AI 超分后的图（灰影最清楚）
const up = path.join(TMP, form + '_4x.png')
if (!fs.existsSync(up)) {
  execFileSync(EXE, ['-i', SRC, '-o', up, '-s', '4', '-n', 'realesrgan-x4plus-anime', '-m', MODELS], { stdio: 'ignore' })
}
const img = decodePng(fs.readFileSync(up))
let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
  if (img.data[(y * img.w + x) * 4 + 3] > 8) {
    if (x < x0) x0 = x; if (x > x1) x1 = x
    if (y < y0) y0 = y; if (y > y1) y1 = y
  }
}
console.log(`${form}（AI 超分图 ${img.w}×${img.h}，有效框 ${x0},${y0} ~ ${x1},${y1}）\n`)

// 按"离底边的距离"分带统计：低饱和像素的亮度分布
const bottom = y1
for (const band of [0.08, 0.16, 0.26, 0.40]) {
  const from = Math.max(y0, Math.round(bottom - (bottom - y0) * band))
  const hist = {}
  let total = 0, grey = 0
  for (let y = from; y <= bottom; y++) for (let x = x0; x <= x1; x++) {
    const i = (y * img.w + x) * 4
    if (img.data[i + 3] < 40) continue
    total++
    const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
    const d = Math.max(r, g, b) - Math.min(r, g, b)
    const lum = Math.round((r + g + b) / 3)
    if (d <= 16) {
      grey++
      const k = Math.floor(lum / 32) * 32
      hist[k] = (hist[k] || 0) + 1
    }
  }
  const top = Object.entries(hist).sort((a, b) => b[1] - a[1]).slice(0, 5)
  console.log(`底边上方 ${(band * 100).toFixed(0)}% 带：不透明 ${total}，其中低饱和(色差≤16) ${grey}（${(grey / total * 100).toFixed(1)}%）`)
  console.log(`   低饱和像素的亮度分布（前 5 档）：${top.map(([k, v]) => `${k}-${+k + 31}:${v}`).join('  ')}`)
}
", "file_path": "_tools\probe-shadow-color.mjs"}

