{"content": "// 自证：碎片掉落 + 在线礼包真的能拿到（第 54 轮）
import { T } from './game-harness.mjs'
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const D = W.DKDbbData
const DBG = W.__DKDbb_DEBUG__
const save = W.DKDbb.save

console.log('掉落表:', JSON.stringify(D.SHARD_DROP))

// 1) 普通野怪会不会掉：统计 rollShardDrop 的实际命中率
const before = save.data.shards || 0
let hits = 0
const N = 2000
for (let i = 0; i < N; i++) if (DBG().rollShardDrop({})) hits++
const got = (save.data.shards || 0) - before
console.log(`普通怪抽样 ${N} 次：命中 ${hits} 次（${(hits / N * 100).toFixed(1)}%），碎片实际 +${got}`)
console.log(hits === got ? '  ✓ 命中次数与碎片增量一致' : '  ✗ 命中次数与增量不符')

// 2) 副本 BOSS 必掉
