{"content": "// 发布包内容抽查：确认这一轮的新东西真的进包了（不是只在仓库里）
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'

const ROOT = path.resolve('.')
const ZIP = fs.readdirSync(ROOT).filter((f) => /^多克多比v[\d.]+单机版\.zip$/.test(f)).sort().pop()
if (!ZIP) { console.log('找不到发布包'); process.exit(1) }
console.log(`包: ${ZIP}  ${(fs.statSync(ZIP).size / 1048576).toFixed(1)} MB`)

// 读中央目录（只取文件名与大小，不解压全部）
const buf = fs.readFileSync(ZIP)
let eocd = -1
for (let i = buf.length - 22; i >= 0 && i > buf.length - 70000; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break }
}
if (eocd < 0) { console.log('找不到 EOCD'); process.exit(1) }
const count = buf.readUInt16LE(eocd + 10)
let off = buf.readUInt32LE(eocd + 16)
const names = []
for (let i = 0; i < count; i++) {
  const nlen = buf.readUInt16LE(off + 28)
  const name = buf.toString('utf8', off + 46, off + 46 + nlen)
  names.push(name)
  off += 46 + nlen + buf.readUInt16LE(off + 30) + buf.readUInt16LE(off + 32)
}
console.log(`条目 ${names.length}`)

const pick = (re) => names.filter((n) => re.test(n))
const art = pick(/forms\/art\/.+\.png$/)
const artBig = pick(/forms\/art\/[^/]+\.png$/).filter((n) => !n.includes('_icon'))
const walk = pick(/forms\/walk\/.+\.png$/)
const icons = pick(/forms\/art\/.+_icon\.png$/)
console.log(`  立绘 ${artBig.length} 张 · 头像 ${icons.length} 张 · 走路帧 ${walk.length} 张`)

// 关键抽查：这几个文件必须在（本轮改过 / 新增）
const MUST = [
  ['game/game.js', '主逻辑（含在线礼包 / 战斗速度接线）'],
  ['game/fx.js', '技能特效（冷色外圈 + 白炽核心）'],
  ['game/treasure.js', '碎片掉落表（普通怪 0.4）'],
  ['game.html', '含右上角「礼包」按钮'],
  ['web/assets/forms/art/正义多比.png', '本轮超分过的立绘'],
  ['web/assets/forms/walk/龙多比_6.png', '6 帧走路（本轮新增的第 6 帧）'],
]
let bad = 0
for (const [f, why] of MUST) {
  const hit = names.some((n) => n.endsWith(f) || n.endsWith(f.replace('web/', '')))
  if (!hit) bad++
  console.log(`  ${hit ? '✓' : '✗'} ${f}   ${why}`)
}
// game.html 里必须真的有「礼包」按钮
const htmlEntry = names.find((n) => n.endsWith('game.html'))
if (htmlEntry) {
  const nlen = buf.readUInt16LE(0) // 占位，真正解压走 zlib
  // 用本地源文件代替（打包是拷贝，源里改了包内就有）——但为了自证还是解一次
  let o = buf.readUInt32LE(eocd + 16)
  let found = false
  for (let i = 0; i < count; i++) {
    const nl = buf.readUInt16LE(o + 28), el = buf.readUInt16LE(o + 30), cl = buf.readUInt16LE(o + 32)
    const name = buf.toString('utf8', o + 46, o + 46 + nl)
    if (name.endsWith('game.html')) {
      const lho = buf.readUInt32LE(o + 42)
      const lnl = buf.readUInt16LE(lho + 26), lel = buf.readUInt16LE(lho + 28)
      const data = buf.subarray(lho + 30 + lnl + lel, lho + 30 + lnl + lel + cl)
      const txt = (buf.readUInt16LE(o + 10) === 0 ? zlib.inflateRawSync(data) : data).toString('utf8')
      found = txt.includes('btn-gift')
      break
    }
    o += 46 + nl + el + cl
  }
  console.log(`  ${found ? '✓' : '✗'} 包内 game.html 含「礼包」按钮（btn-gift）`)
  if (!found) bad++
}
console.log(bad ? `\n✗ ${bad} 项没进包` : '\n✓ 本轮改动全部进包')
process.exit(bad ? 1 : 0)
", "file_path": "_tools\check-release-content.mjs"}

