        // 存储（未压缩）：长度以中央目录为准，为 0 时找到下一个 PK 签名
        let end = cl ? start + cl : buf.indexOf(Buffer.from([0x50, 0x4b, 0x03, 0x04]), start)
        if (end < 0) end = buf.length
        txt = buf.toString('utf8', start, end)
        how = 'stored'
      } else {
        // 压缩：给到下一个 PK 签名（或文件尾），inflateRaw 自己会在流末停
        let end = buf.indexOf(Buffer.from([0x50, 0x4b, 0x03, 0x04]), start)
        if (end < 0) end = buf.length
        try {
          txt = zlib.inflateRawSync(buf.subarray(start, end)).toString('utf8')
          how = 'deflate'
        } catch (e) {
          txt = ''
          how = 'inflate 失败: ' + e.message
        }
      }
      found = txt.includes('btn-gift')
      break
    }
    o += 46 + nl + el + cl
  }
  console.log(`  ${found ? '✓' : '✗'} 包内 game.html 含「礼包」按钮（btn-gift）　[${how}]`)
  if (!found) bad++
