{"content": "// 核实：形态立绘到底"朝左"的多还是"朝右"的多
//
// 【为什么需要】`game.js` 里写死 `const ART_FACES_LEFT = true`，注释说
//   "官方立绘是朝左的 3/4 侧脸"。但用户指出战斗里朝向不对 ——
//   如果立绘**不是全都朝左**，用同一个常数翻所有立绘就必然有一半是反的。
//
// 判据（对**眼睛/脸**做，不是整张图的包围盒 —— 角色可能歪头）：
//   取立绘上半部（头），计算**左右两半"白色亮部"的重心**；
//   脸/眼睛所在的那一侧通常更亮（眼白 + 高光）。
//   这个判据只能给"多数倾向"，所以输出的是**统计结论 + 逐只明细**，最终仍以人眼抽查为准。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const DIR = path.resolve('assets', 'forms', 'art')
const files = fs.readdirSync(DIR).filter((f) => f.endsWith('.png') && !f.includes('_icon')).sort()

const rows = []
for (const f of files) {
  const img = decodePng(fs.readFileSync(path.join(DIR, f)))
  // 定位主体包围盒
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  if (x1 < 0) continue
  // 头部区域 = 上 45%
  const hy1 = y0 + Math.round((y1 - y0) * 0.45)
  const mid = Math.round((x0 + x1) / 2)
  let lw = 0, rw = 0          // 左/右半边的"亮像素"加权重心
  let lsum = 0, rsum = 0, ln = 0, rn = 0
  for (let y = y0; y <= hy1; y++) for (let x = x0; x <= x1; x++) {
    const i = (y * img.w + x) * 4
    if (img.data[i + 3] < 40) continue
    const lum = (img.data[i] + img.data[i + 1] + img.data[i + 2]) / 3
    if (lum < 205) continue                 // 只看接近白的高光/眼白
    if (x < mid) { lw += lum; lsum++; ln++ } else { rw += lum; rsum++; rn++ }
  }
  // 亮部像素数差（脸那一侧通常眼白更多）
  const diff = ln - rn
  rows.push({ name: f.replace('.png', ''), ln, rn, diff, bias: diff > 0 ? '左' : '右' })
}

const left = rows.filter((r) => r.bias === '左').length
const right = rows.filter((r) => r.bias === '右').length
console.log(`形态立绘 ${rows.length} 张（按"头部亮部重心"判，仅供参考）`)
console.log(`  偏左 ${left} 张 / 偏右 ${right} 张`)
console.log('\n明细（按差异绝对值排序，差异大的更可信）：')
rows.sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff))
for (const r of rows.slice(0, 16)) {
  console.log(`  ${r.name.padEnd(14)} 左亮 ${String(r.ln).padStart(5)}  右亮 ${String(r.rn).padStart(5)}  → 偏${r.bias}`)
}
console.log('\n⚠️ 这只是统计参考：立绘可能歪头、戴头盔、有异色虹膜，都会干扰。')
console.log('   要判断某一只的朝向，**必须看图**。')
", "file_path": "_tools\probe-art-facing.mjs"}

{"content": "// 量朝向：把游戏画出来的一帧读回像素，量"眼睛（白色亮块）"落在头的左半还是右半。
//
// 【为什么要量而不是看】用户报「朝向有问题」时，肉眼在 960×560 上很难判；
//   而"立绘原始朝向"和"游戏里朝向"是两件事（中间有 artFlip / drawMonster 两道处理）。
//   所以直接对比**同一只**在"原始立绘"和"战斗画面"里的眼位，翻转与否一目了然。
//
// 判据：眼睛 = 头区域内**接近纯白且被深色描边包住**的像素；
//   取这些像素的横向重心，与头区域的水平中线比较 → 偏左 / 偏右。
// 用法: node _tools/probe-facing-in-game.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'
import { T } from './game-harness.mjs'

const ROOT = path.resolve('.')

// 在一张图上量"头部亮部重心偏向"
function eyeBias(img, box) {
  const { w, h, data } = img
  const [bx0, by0, bx1, by1] = box
  const x0 = Math.round(bx0 * w), x1 = Math.round(bx1 * w)
  const y0 = Math.round(by0 * h), y1 = Math.round(by1 * h)
  let sx = 0, n = 0
  let minX = 1e9, maxX = -1
  for (let y = Math.max(0, y0); y < Math.min(h, y1); y++) {
    for (let x = Math.max(0, x0); x < Math.min(w, x1); x++) {
      const i = (y * w + x) * 4
      const a = data[i + 3]
      if (a < 200) continue
      const r = data[i], g = data[i + 1], b = data[i + 2]
      const lum = (r + g + b) / 3
      const sat = Math.max(r, g, b) - Math.min(r, g, b)
      if (lum < 200 || sat > 45) continue          // 近白且低饱和 = 眼白/高光
      sx += x; n++
      if (x < minX) minX = x
      if (x > maxX) maxX = x
    }
  }
  if (!n) return null
  const cx = (x0 + x1) / 2
  return { n, cx: sx / n, mid: cx, bias: (sx / n) < cx ? '左' : '右', minX, maxX }
}

// ---------- 1) 原始立绘 ----------
const ART = path.join(ROOT, 'assets', 'forms', 'art')
const artRes = {}
for (const name of ['龙多比', '凤凰多比', '冰多比']) {
  const p = path.join(ART, name + '.png')
  if (!fs.existsSync(p)) continue
  const img = decodePng(fs.readFileSync(p))
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  // 头部 = 上 40%
  const hy = y0 + (y1 - y0) * 0.4
  const b = eyeBias(img, [x0 / img.w, y0 / img.h, x1 / img.w, hy / img.h])
  artRes[name] = b
  console.log(`原始立绘 ${name.padEnd(8)} 眼白 ${String(b ? b.n : 0).padStart(5)} px　重心 ${b ? b.cx.toFixed(1) : '-'} / 中线 ${b ? b.mid.toFixed(1) : '-'} → **偏${b ? b.bias : '?'}**`)
}

// ---------- 2) 游戏里画一帧 ----------
console.log('\n（下面把游戏画出来的一帧读回像素来量）')
const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
const S = () => DBG().state
S().mode = 'explore'
const sp = DBG().spawns
const m = sp && sp.monsters && sp.monsters[0]
if (!m) { console.log('找不到怪物'); process.exit(1) }
S().form = W.DKDbbData.FORMS.find((f) => f.name === '龙多比') || W.DKDbbData.FORMS[0]
console.log(`  出战形态: ${S().form.name}   敌人: ${m.mon.name}`)
DBG().startBattle({ mon: m.mon, level: m.level, stats: m.stats })
for (let i = 0; i < 120 && S().battle && (S().battle.phase !== 'command' || S().battle.intro > 0); i++) t.step(1)

const shot = path.join(ROOT, '_tmp_test_out', 'probe-facing.png')
DBG().screenshot ? DBG().screenshot(shot) : null
if (!fs.existsSync(shot)) {
  // 没有截图接口就用探针里已有的画布导出约定
  console.log('  （调试接口没有 screenshot，改用 _tools/shoot.mjs 出图后再量）')
  process.exit(2)
}
const img = decodePng(fs.readFileSync(shot))
console.log(`  画面 ${img.w}×${img.h}`)
", "file_path": "_tools\probe-facing-in-game.mjs"}

{"content": "// 朝向对照图：把"原始立绘"和"战斗画面里那一帧"并排，人眼一看就知道谁反了
//
// 【为什么需要】用户报「多比朝向有问题，应该全部朝向敌人」。
//   眼睛位置这类自动判据在"整张脸都是白的"（如龙多比）立绘上会失效，
//   所以最终必须**并排给人看**。这张图就是那个证据。
// 用法: node _tools/make-facing-compare.mjs <战斗截图.png>
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SHOT = path.join(ROOT, process.argv[2] || '_tmp_test_out/shots-icon/10-battle-command.png')
const OUT = path.join(ROOT, 'docs', 'shots', 'facing-compare.png')

const shot = decodePng(fs.readFileSync(SHOT))
const W = shot.w, H = shot.h

// 从截图里裁一块（按比例），并放大到指定高度（最近邻，保持像素锐利）
function cut(img, box, dstH) {
  const x0 = Math.round(box[0] * img.w), y0 = Math.round(box[1] * img.h)
  const x1 = Math.round(box[2] * img.w), y1 = Math.round(box[3] * img.h)
  const sw = x1 - x0, sh = y1 - y0
  const sc = dstH / sh, dw = Math.round(sw * sc), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) for (let x = 0; x < dw; x++) {
    const sx = x0 + Math.min(sw - 1, Math.floor(x / sc)), sy = y0 + Math.min(sh - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dh, data: out }
}
// 立绘：按内容裁紧再等比放到 dstH
function fitArt(img, dstH) {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  const sw = x1 - x0 + 1, sh = y1 - y0 + 1
  const sc = dstH / sh, dw = Math.max(1, Math.round(sw * sc)), dh = dstH
  const out = new Uint8ClampedArray(dw * dh * 4)
  for (let y = 0; y < dh; y++) for (let x = 0; x < dw; x++) {
    const sx = x0 + Math.min(sw - 1, Math.floor(x / sc)), sy = y0 + Math.min(sh - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dh, data: out }
}
const mirror = (img) => {
  const out = { w: img.w, h: img.h, data: new Uint8ClampedArray(img.w * img.h * 4) }
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    const s = (y * img.w + x) * 4, d = (y * img.w + (img.w - 1 - x)) * 4
    out.data[d] = img.data[s]; out.data[d + 1] = img.data[s + 1]; out.data[d + 2] = img.data[s + 2]; out.data[d + 3] = img.data[s + 3]
  }
  return out
}

const H2 = 300
const playerArt = fitArt(decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/龙多比.png'))), H2)
const enemyArt = fitArt(decodePng(fs.readFileSync(path.join(ROOT, 'assets/monsters/labeled/mon_10020.png'))), H2)
const playerShot = cut(shot, [0.19, 0.5, 0.32, 0.79], H2)     // 玩家在画面里
const enemyShot = cut(shot, [0.60, 0.17, 0.78, 0.53], H2)     // 敌人在画面里

const cells = [
  { img: playerArt, label: '① 龙多比 原始立绘' },
  { img: playerShot, label: '② 龙多比 游戏里（现在）' },
  { img: mirror(playerShot), label: '③ 龙多比 镜像后（方案A）' },
  { img: enemyArt, label: '④ 大蘑菇 原始立绘' },
  { img: enemyShot, label: '⑤ 大蘑菇 游戏里（现在）' },
]
const PAD = 14, LABEL = 26
const colW = Math.max(...cells.map((c) => c.img.w))
const totW = PAD * 2 + cells.length * colW + (cells.length - 1) * PAD
const totH = PAD * 2 + LABEL + H2
const fb = new Uint8ClampedArray(totW * totH * 4)
for (let i = 0; i < totW * totH; i++) { fb[i * 4] = 14; fb[i * 4 + 1] = 18; fb[i * 4 + 2] = 34; fb[i * 4 + 3] = 255 }
const place = (im, ox, oy) => {
  for (let y = 0; y < im.h; y++) for (let x = 0; x < im.w; x++) {
    const s = (y * im.w + x) * 4, al = im.data[s + 3] / 255
    if (al <= 0) continue
    const tx = ox + x, ty = oy + y
    if (tx < 0 || ty < 0 || tx >= totW || ty >= totH) continue
    const d = (ty * totW + tx) * 4
    fb[d] = im.data[s] * al + fb[d] * (1 - al)
    fb[d + 1] = im.data[s + 1] * al + fb[d + 1] * (1 - al)
    fb[d + 2] = im.data[s + 2] * al + fb[d + 2] * (1 - al)
    fb[d + 3] = 255
  }
}
cells.forEach((c, i) => place(c.img, PAD + i * (colW + PAD) + ((colW - c.img.w) >> 1), PAD + LABEL))
fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(totW, totH, fb))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log('列顺序：' + cells.map((c) => c.label).join(' | '))
", "file_path": "_tools\make-facing-compare.mjs"}

{"content": "// 判定"游戏里到底翻转了没有"：把原始立绘与游戏截图里那只做像素比对
//   · 原图 vs 截图 差异小 → 没翻转
//   · 镜像 vs 截图 差异小 → 翻转了
// 两边都先按内容裁紧、缩到同一高度（最近邻），再比"非透明像素的平均色差"。
// 用法: node _tools/probe-flip-state.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SHOT = path.join(ROOT, '_tmp_test_out/shots-icon/10-battle-command.png')
const shot = decodePng(fs.readFileSync(SHOT))

function cropTight(img, box) {
  const x0 = Math.max(0, Math.round(box[0] * img.w)), y0 = Math.max(0, Math.round(box[1] * img.h))
  const x1 = Math.min(img.w, Math.round(box[2] * img.w)), y1 = Math.min(img.h, Math.round(box[3] * img.h))
  let bx0 = x1, by0 = y1, bx1 = -1, by1 = -1
  for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 200) {
      if (x < bx0) bx0 = x; if (x > bx1) bx1 = x
      if (y < by0) by0 = y; if (y > by1) by1 = y
    }
  }
  if (bx1 < 0) return null
  const w = bx1 - bx0 + 1, h = by1 - by0 + 1
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((by0 + y) * img.w + (bx0 + x)) * 4, d = (y * w + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w, h, data: out }
}
function norm(img, dstH) {
  const sc = dstH / img.h, dw = Math.max(1, Math.round(img.w * sc))
  const out = new Uint8ClampedArray(dw * dstH * 4)
  for (let y = 0; y < dstH; y++) for (let x = 0; x < dw; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x / sc)), sy = Math.min(img.h - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dstH, data: out }
}
const mirror = (img) => {
  const out = { w: img.w, h: img.h, data: new Uint8ClampedArray(img.w * img.h * 4) }
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    const s = (y * img.w + x) * 4, d = (y * img.w + (img.w - 1 - x)) * 4
    out.data[d] = img.data[s]; out.data[d + 1] = img.data[s + 1]; out.data[d + 2] = img.data[s + 2]; out.data[d + 3] = img.data[s + 3]
  }
  return out
}
// 平均色差（只算两边都不透明的像素）
function diff(a, b) {
  const w = Math.min(a.w, b.w), h = Math.min(a.h, b.h)
  let s = 0, n = 0
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = (y * w + x) * 4
    if (a.data[i + 3] < 128 || b.data[i + 3] < 128) continue
    s += Math.hypot(a.data[i] - b.data[i], a.data[i + 1] - b.data[i + 1], a.data[i + 2] - b.data[i + 2])
    n++
  }
  return n ? s / n : 999
}

const H = 160
const cases = [
  ['玩家 龙多比', 'assets/forms/art/龙多比.png', [0.19, 0.50, 0.32, 0.79]],
  ['敌人 大蘑菇', 'assets/monsters/labeled/mon_10020.png', [0.60, 0.17, 0.78, 0.53]],
]
for (const [label, artRel, box] of cases) {
  const art = cropTight(decodePng(fs.readFileSync(path.join(ROOT, artRel))), [0, 0, 1, 1])
  const cut = cropTight(shot, box)
  if (!art || !cut) { console.log(`${label}: 裁剪失败`); continue }
  const A = norm(art, H), C = norm(cut, H), M = mirror(A)
  const dOrig = diff(A, C), dMir = diff(M, C)
  const flipped = dMir < dOrig
  console.log(`${label}`)
  console.log(`   原始立绘 vs 游戏里 : 色差 ${dOrig.toFixed(1)}`)
  console.log(`   镜像立绘 vs 游戏里 : 色差 ${dMir.toFixed(1)}`)
  console.log(`   → 游戏里${flipped ? '**翻转了**' : '**没有翻转**'}（差 ${Math.abs(dOrig - dMir).toFixed(1)}，越大越可信）`)
}
