const json = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1))
const all = (json.detail || []).map((d) => ({ name: d.name, element: d.element, note: d.note || '', sprite: d.sprite }))
const standin = all.filter((d) => /replace|fallback/.test(d.note))

// 归档根目录（素材包）
const ARCH = path.join(ROOT, '多克多比专区资料素材')
const imgExt = new Set(['.png', '.jpg', '.jpeg', '.bmp', '.gif'])

// 建索引：归档里所有含"怪物/怪/图鉴"路径的图片，按文件名建表
const files = []
function walk(dir, depth) {
  if (depth > 6) return
  let ents
  try { ents = fs.readdirSync(dir, { withFileTypes: true }) } catch { return }
  for (const e of ents) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) walk(p, depth + 1)
    else if (imgExt.has(path.extname(e.name).toLowerCase())) files.push(p)
  }
}
walk(ARCH, 0)
console.log(`归档图片总数 ${files.length}\n`)

const norm = (s) => String(s).replace(/[\s·・_\-()（）]/g, '')
console.log('=== 22 只替身怪：归档里有没有同名/近名的真图 ===')
