{"content": "// 定论：怪物"名称↔模型"到底有多少对不上，以及归档里有没有真图可用
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const raw = fs.readFileSync(path.join(ROOT, 'assets/monsters/map.js'), 'utf8')
const j = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1))
const det = j.detail || []

// 按 source 归类（source 是自由文本，取开头的关键词）
const cls = (s) => {
  const t = String(s || '')
  if (t.startsWith('atlas')) return 'atlas 图鉴编号已核对'
  if (t.startsWith('replace')) return 'replace 近似替换'
  if (t.startsWith('fallback')) return 'fallback 回退旧素材'
  return 'other: ' + t.slice(0, 20)
}
const buckets = {}
for (const d of det) {
  const k = cls(d.source)
  ;(buckets[k] = buckets[k] || []).push(d)
}
console.log(`怪物表共 ${det.length} 只`)
for (const [k, v] of Object.entries(buckets).sort((a, b) => b[1].length - a[1].length)) {
  console.log(`  ${String(v.length).padStart(3)} 只  ${k}`)
}
const bad = det.filter((d) => !cls(d.source).startsWith('atlas'))
console.log(`\n→ **对不上的共 ${bad.length} / ${det.length} 只（${Math.round(bad.length / det.length * 100)}%）**`)

// 归档里有没有"怪物"系列的单体图（可能能替得更好）
const ARCH = path.join(ROOT, '多克多比专区资料素材')
const imgExt = new Set(['.png', '.jpg', '.jpeg', '.bmp', '.gif'])
const files = []
;(function walk(dir, depth) {
  if (depth > 7) return
  let ents
  try { ents = fs.readdirSync(dir, { withFileTypes: true }) } catch { return }
  for (const e of ents) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) walk(p, depth + 1)
    else if (imgExt.has(path.extname(e.name).toLowerCase())) files.push(p)
  }
})(ARCH, 0)

console.log('\n=== 归档里与"怪物"有关的图片目录 ===')
const byDir = {}
for (const f of files) {
  const rel = f.replace(ARCH + path.sep, '')
  if (!/怪物|怪兽|怪/.test(rel)) continue
  const top = rel.split(path.sep).slice(0, 2).join('/')
  byDir[top] = (byDir[top] || 0) + 1
}
for (const [k, v] of Object.entries(byDir).sort((a, b) => b[1] - a[1])) console.log(`  ${String(v).padStart(4)} 张  ${k}`)

console.log('\n=== 24 只替身怪：归档里能否按名找到（含模糊）===')
const norm = (s) => String(s).replace(/[\s·・_\-()（）]/g, '')
let hit = 0
for (const d of bad) {
  const key = norm(d.name)
  const exact = files.filter((f) => norm(path.basename(f)).includes(key))
  // 模糊：去掉最后一个字再找一次（"雷暴鲁巴"→"雷暴鲁"）
  const fuzzy = key.length > 2 ? files.filter((f) => norm(path.basename(f)).includes(key.slice(0, -1))) : []
  if (exact.length || fuzzy.length) {
    hit++
    console.log(`  ✓ ${d.name}  精确 ${exact.length} / 模糊 ${fuzzy.length}`)
    for (const h of (exact.length ? exact : fuzzy).slice(0, 2)) console.log(`       ${h.replace(ARCH + path.sep, '')}`)
  }
}
console.log(`  → ${hit}/${bad.length} 只能找到（哪怕模糊匹配）`)
