// 用法: node _tools/probe-monster-atlas.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ARCH = path.join(ROOT, '多克多比专区资料素材')
const cands = [
  ['怪物/怪物大全.png', '怪物大全'],
  ['npc大全/怪物图鉴.png', '怪物图鉴'],
]
for (const [rel, label] of cands) {
  const p = path.join(ARCH, rel)
  if (!fs.existsSync(p)) { console.log(`缺 ${rel}`); continue }
  const img = decodePng(fs.readFileSync(p))
  console.log(`\n=== ${label}  ${img.w}×${img.h} ===`)
  // "有内容"= 不是接近白底
  const isInk = (x, y) => {
    const i = (y * img.w + x) * 4
    const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
    const a = img.data[i + 3]
    if (a < 40) return false
    return !(r > 238 && g > 238 && b > 238)
  }
  // 列/行的墨迹投影
  const colInk = new Int32Array(img.w), rowInk = new Int32Array(img.h)
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (isInk(x, y)) { colInk[x]++; rowInk[y]++ }
  }
  // 找"全空"的列/行作为分隔（阈值 1%）
  const thC = Math.max(2, img.h * 0.01), thR = Math.max(2, img.w * 0.01)
  const spans = (arr, th) => {
    const out = []
    let s = -1
    for (let i = 0; i < arr.length; i++) {
      const empty = arr[i] < th
      if (!empty && s < 0) s = i
      if (empty && s >= 0) { out.push([s, i - 1]); s = -1 }
    }
    if (s >= 0) out.push([s, arr.length - 1])
    return out
  }
  const colBands = spans(colInk, thC)
  const rowBands = spans(rowInk, thR)
  console.log(`  列向内容带 ${colBands.length} 段，行向 ${rowBands.length} 段`)
  console.log(`  → 推测网格 ${colBands.length} 列 × ${rowBands.length} 行 = 约 ${colBands.length * rowBands.length} 格`)
  console.log(`  列带宽度: ${colBands.slice(0, 12).map(([a, b]) => b - a + 1).join(' ')}${colBands.length > 12 ? ' …' : ''}`)
  console.log(`  行带高度: ${rowBands.slice(0, 10).map(([a, b]) => b - a + 1).join(' ')}${rowBands.length > 10 ? ' …' : ''}`)
  // 统计"含墨迹的格"（有真内容的格）
  let nonEmpty = 0
  for (const [ry0, ry1] of rowBands) {
    for (const [cx0, cx1] of colBands) {
      let ink = 0
      for (let y = ry0; y <= ry1; y += 2) for (let x = cx0; x <= cx1; x += 2) if (isInk(x, y)) ink++
      if (ink > 50) nonEmpty++
    }
  }
  console.log(`  实际有内容的格: ${nonEmpty} / ${colBands.length * rowBands.length}`)
}
", "file_path": "_tools\probe-monster-atlas.mjs"}

