{"content": "// 量化"名称↔模型"重复：哪些怪拿到了同一张图（同图 = 必然有怪的名字对不上）
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'

const ROOT = path.resolve('.')
const raw = fs.readFileSync(path.join(ROOT, 'assets/monsters/map.js'), 'utf8')
const j = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1))
const det = j.detail || []

const byHash = new Map()
for (const d of det) {
  const p = path.join(ROOT, d.sprite)
  if (!fs.existsSync(p)) continue
  const buf = fs.readFileSync(p)
  const h = crypto.createHash('sha256').update(buf).digest('hex').slice(0, 12)
  if (!byHash.has(h)) byHash.set(h, [])
  byHash.get(h).push({ name: d.name, source: String(d.source || '').slice(0, 8), bytes: buf.length })
}
const dups = [...byHash.entries()].filter(([, v]) => v.length > 1)
console.log(`怪表 ${det.length} 只，用到 ${byHash.size} 张不同的图`)
console.log(`**重复组 ${dups.length} 组**（每组里至多只有 1 只的名字是对的）:\n`)
let dupCount = 0
for (const [h, v] of dups) {
  dupCount += v.length - 1
  console.log(`  [${h}] ${v.map((x) => `${x.name}(${x.source})`).join('  =  ')}   ${v[0].bytes}B`)
}
console.log(`\n→ 受影响的怪：${dupCount} 只`)

// 同时看 gamedata 里怪物总数，确认表本身
const gd = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/gamedata.json'), 'utf8'))
const mons = (gd.monsters || gd.MONSTERS || [])
if (mons.length) console.log(`gamedata 里的怪物 ${mons.length} 只`)
