{"content": "// 朝向对照（确定性版）：把同一只怪按 faceLeft=false / true 各画一遍，旁边放原始立绘
//
// 【为什么要写成探针】"朝哪边"用肉眼在小图上判很容易错（我已经错过一次：
//   把 36 张互不相同的怪图误判成"有 5 组重复"）。所以这里把三个版本放在同一张图上，
//   并附**阴影重心偏移**这个客观量：接地影总在角色"面朝方向"的略后方，
//   所以阴影重心相对身体重心的偏移方向 = 朝向的反方向。
//
// 用法: node _tools/_probe-facing-render.mjs 哈拉兽
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'
import { T } from './game-harness.mjs'

const ROOT = path.resolve('.')
const wanted = process.argv[2] || null

const t = T
t.load('game/game.js')
await T.settle()
const W = t.get('window')
const DBG = () => W.__DKDbb_DEBUG__
const D = W.DKDbbData

// 找到要看的怪（默认取刷怪池第一只）
const sp = DBG().spawns
const list = (sp && sp.monsters) || []
const m = wanted ? list.find((x) => x.mon.name === wanted) || { mon: D.MONSTERS.find((x) => x.name === wanted), level: 7 } : list[0]
if (!m || !m.mon) { console.log('找不到怪物', wanted || '(刷怪池空)'); process.exit(1) }
console.log(`怪: ${m.mon.name}   立绘: ${m.mon.sprite}`)

// canvas 尺寸
const CV = W.document.getElementById('game') || W.document.querySelector('canvas')
console.log(`canvas: ${CV.width}x${CV.height}`)

const shot = (opts) => {
  const c = CV.getContext('2d')
  c.setTransform(1, 0, 0, 1, 0, 0)
  c.clearRect(0, 0, CV.width, CV.height)
  c.fillStyle = '#101828'; c.fillRect(0, 0, CV.width, CV.height)
  DBG().drawMonsterForProbe(m.mon, 240, 300, 200, opts)
  return c.getImageData(0, 0, CV.width, CV.height)
}

let hasProbe = typeof DBG().drawMonsterForProbe === 'function'
if (!hasProbe) {
  console.log('调试接口没有 drawMonsterForProbe — 改用整帧战斗截图（见 _tools/shoot.mjs）')
  process.exit(2)
}

const a = shot({ t: 0, faceLeft: false })
const b = shot({ t: 0, faceLeft: true })

// 把 ImageData 转成可分析的格式
const toImg = (d) => ({ w: d.width, h: d.height, data: d.data })
const A = toImg(a), B = toImg(b)

// 客观量：不透明像素的横向重心（身体朝向会让重心偏向面对的一侧）
function com(img, x0, x1) {
  let sx = 0, n = 0
  for (let y = 0; y < img.h; y++) for (let x = x0; x < x1; x++) {
    const i = (y * img.w + x) * 4
    if (img.data[i + 3] > 40 && img.data[i] + img.data[i + 1] + img.data[i + 2] > 90) { sx += x; n++ }
  }
  return n ? sx / n : 0
}
// 找主体包围盒
function bbox(img) {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  return { x0, y0, x1, y1 }
}
const bA = bbox(A), bB = bbox(B)
console.log(`\nfaceLeft=false: 包围盒 x ${bA.x0}..${bA.x1}  亮部重心 ${com(A, bA.x0, bA.x1).toFixed(1)}（盒中心 ${((bA.x0 + bA.x1) / 2).toFixed(1)}）`)
console.log(`faceLeft=true : 包围盒 x ${bB.x0}..${bB.x1}  亮部重心 ${com(B, bB.x0, bB.x1).toFixed(1)}（盒中心 ${((bB.x0 + bB.x1) / 2).toFixed(1)}）`)
console.log('（两个包围盒宽度应相同 —— 只镜像、不位移。宽度不同说明翻转实现有问题）')

// 拼图：原图 | faceLeft=false | faceLeft=true
const H2 = 260, PAD = 12, LAB = 22
let art = null
const artPath = m.mon.sprite
if (artPath && fs.existsSync(artPath)) art = decodePng(fs.readFileSync(artPath))
function cropScale(img, box, dstH) {
  const sw = box.x1 - box.x0 + 1, sh = box.y1 - box.y0 + 1
  const sc = dstH / sh, dw = Math.max(1, Math.round(sw * sc))
  const out = new Uint8ClampedArray(dw * dstH * 4)
  for (let y = 0; y < dstH; y++) for (let x = 0; x < dw; x++) {
    const sx = box.x0 + Math.min(sw - 1, Math.floor(x / sc)), sy = box.y0 + Math.min(sh - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dstH, data: out }
}
const cells = []
if (art) cells.push({ img: cropScale(art, bbox(art), H2), label: '① 原始立绘' })
cells.push({ img: cropScale(A, bA, H2), label: '② faceLeft=false' })
cells.push({ img: cropScale(B, bB, H2), label: '③ faceLeft=true' })
const colW = Math.max(...cells.map((c) => c.img.w))
const totW = PAD * 2 + cells.length * colW + (cells.length - 1) * PAD
const totH = PAD * 2 + LAB + H2
const fb = new Uint8ClampedArray(totW * totH * 4)
for (let i = 0; i < totW * totH; i++) { fb[i * 4] = 16; fb[i * 4 + 1] = 22; fb[i * 4 + 2] = 38; fb[i * 4 + 3] = 255 }
cells.forEach((c, i) => {
  const ox = PAD + i * (colW + PAD) + ((colW - c.img.w) >> 1)
  for (let y = 0; y < c.img.h; y++) for (let x = 0; x < c.img.w; x++) {
    const s = (y * c.img.w + x) * 4, al = c.img.data[s + 3] / 255
    if (al <= 0) continue
    const d = ((PAD + LAB + y) * totW + ox + x) * 4
    fb[d] = c.img.data[s] * al + fb[d] * (1 - al)
    fb[d + 1] = c.img.data[s + 1] * al + fb[d + 1] * (1 - al)
    fb[d + 2] = c.img.data[s + 2] * al + fb[d + 2] * (1 - al)
    fb[d + 3] = 255
  }
})
const OUT = path.join(ROOT, '_tmp_test_out', 'facing-render.png')
fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(totW, totH, fb))
console.log(`\n已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log('列：' + cells.map((c) => c.label).join(' | '))
", "file_path": "_tools\_probe-facing-render.mjs"}

