{"content": "// 确定性判朝向：把立绘按"原样 / 镜像"各画一次，用同一套光栅化，得到两张可比的图；
// 再把"用户截图里的那只怪"裁出来，跟这两张比色差 —— 差小的那个就是**游戏里真实的样子**。
//
// 【为什么要这么绕】前面两次都栽在"用肉眼在小图上判朝向"：
//   ① 把 36 张互不相同的怪图误判成有 5 组重复；
//   ② 截图里哈拉兽朝哪边，肉眼一次说右一次说不准。
//   所以这里不猜：**光栅化两份候选 + 与真实截图比对**，用数字说话。
//
// 用法: node _tools/_probe-facing-truth.mjs <截图.png> <立绘相对路径> <裁框 x0,y0,x1,y1（0..1 比例）>
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const args = process.argv.slice(2)
const SHOT = path.join(ROOT, args[0] || '')
const ART = path.join(ROOT, args[1] || '')
const box = (args[2] || '0,0,1,1').split(',').map(Number)
if (!fs.existsSync(SHOT) || !fs.existsSync(ART)) { console.log('用法: node _tools/_probe-facing-truth.mjs <截图> <立绘> x0,y0,x1,y1'); process.exit(1) }

function cut(img, b) {
  const x0 = Math.max(0, Math.round(b[0] * img.w)), y0 = Math.max(0, Math.round(b[1] * img.h))
  const x1 = Math.min(img.w, Math.round(b[2] * img.w)), y1 = Math.min(img.h, Math.round(b[3] * img.h))
  const w = x1 - x0, h = y1 - y0
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((y0 + y) * img.w + (x0 + x)) * 4, d = (y * w + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w, h, data: out }
}
// 按内容裁紧（只认完全不透明的像素，避开背景）
function tight(img) {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 240) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  if (x1 < 0) return null
  return cut(img, [x0 / img.w, y0 / img.h, (x1 + 1) / img.w, (y1 + 1) / img.h])
}
const norm = (img, dstH) => {
  const sc = dstH / img.h, dw = Math.max(1, Math.round(img.w * sc))
  const out = new Uint8ClampedArray(dw * dstH * 4)
  for (let y = 0; y < dstH; y++) for (let x = 0; x < dw; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x / sc)), sy = Math.min(img.h - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dstH, data: out }
}
const mirror = (img) => {
  const out = { w: img.w, h: img.h, data: new Uint8ClampedArray(img.w * img.h * 4) }
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    const s = (y * img.w + x) * 4, d = (y * img.w + (img.w - 1 - x)) * 4
    out.data[d] = img.data[s]; out.data[d + 1] = img.data[s + 1]; out.data[d + 2] = img.data[s + 2]; out.data[d + 3] = img.data[s + 3]
  }
  return out
}
// 比"形状"而不是"颜色"：都转成二值剪影，算 IoU（交并比）。IoU 越大 = 朝向越像。
function silhouette(img) {
  const m = new Uint8Array(img.w * img.h)
  for (let i = 0; i < img.w * img.h; i++) m[i] = img.data[i * 4 + 3] > 128 ? 1 : 0
  return m
}
function iou(a, b) {
  const w = Math.min(a.w, b.w), h = Math.min(a.h, b.h)
  const ma = silhouette(a), mb = silhouette(b)
  let inter = 0, uni = 0
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const va = ma[y * a.w + x], vb = mb[y * b.w + x]
    if (va && vb) inter++
    if (va || vb) uni++
  }
  return uni ? inter / uni : 0
}

const H = 200
const shot = decodePng(fs.readFileSync(SHOT))
const artImg = decodePng(fs.readFileSync(ART))
const A = norm(tight(artImg), H)
const M = mirror(A)
const S = tight(cut(shot, box))
if (!S) { console.log('截图裁剪区里没有完全不透明的像素 —— 放宽裁框或改用 alpha>40 判据'); process.exit(1) }
const Sn = norm(S, H)

const iA = iou(A, Sn), iM = iou(M, Sn)
console.log(`与截图比对（剪影 IoU，越大越像）`)
console.log(`  立绘**原样** vs 截图 : ${iA.toFixed(4)}`)
console.log(`  立绘**镜像** vs 截图 : ${iM.toFixed(4)}`)
const verdict = iM > iA ? '镜像（= 游戏里翻转了）' : '原样（= 游戏里没翻转）'
console.log(`  → 截图里那只怪是 **${verdict}**   （差 ${Math.abs(iA - iM).toFixed(4)}）`)
", "file_path": "_tools\_probe-facing-truth.mjs"}

