{"content": "// 判定一张立绘在游戏里"该不该翻"：用**内容不对称特征**算朝向，并与截图比对。
//
// 【为什么又写一个探针】"朝哪边"这件事我已经错过两次（看小图看错重复组、截图里朝哪说不准）。
//   这次不靠肉眼也不靠"亮部重心"（那对整张脸都白的立绘会失效），改用**两条独立特征**：
//     ① **包围盒重心** —— 角色常把身体/尾巴压向"背后"，重心偏的那侧多半是背面；
//     ② **接地影重心** —— 投影椭圆通常画在角色**下方略偏一侧**，偏的那侧是"面朝方向"。
//   两条都算出来，并**同时给出与用户截图比对的剪影 IoU**，三个数一起看。
//
// 用法: node _tools/_probe-facing-decide.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SHOT = path.join(ROOT, '_tmp_test_out', 'user-shot2.png')
const ART = path.join(ROOT, 'assets/monsters/labeled/mon_10003.png')   // 绿毒粘液兽
// 用户截图里那只怪的裁框（比例，按 2026×1185 目测的右半区）
const BOX = [0.60, 0.22, 0.90, 0.68]

const cut = (img, b) => {
  const x0 = Math.max(0, Math.round(b[0] * img.w)), y0 = Math.max(0, Math.round(b[1] * img.h))
  const x1 = Math.min(img.w, Math.round(b[2] * img.w)), y1 = Math.min(img.h, Math.round(b[3] * img.h))
  const w = x1 - x0, h = y1 - y0
  const out = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const s = ((y0 + y) * img.w + (x0 + x)) * 4, d = (y * w + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w, h, data: out }
}
const bbox = (img) => {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  return { x0, y0, x1, y1 }
}
const tight = (img) => { const b = bbox(img); return cut(img, [b.x0 / img.w, b.y0 / img.h, (b.x1 + 1) / img.w, (b.y1 + 1) / img.h]) }
const norm = (img, dstH) => {
  const sc = dstH / img.h, dw = Math.max(1, Math.round(img.w * sc))
  const out = new Uint8ClampedArray(dw * dstH * 4)
  for (let y = 0; y < dstH; y++) for (let x = 0; x < dw; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x / sc)), sy = Math.min(img.h - 1, Math.floor(y / sc))
    const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
    out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
  }
  return { w: dw, h: dstH, data: out }
}
const mirror = (img) => {
  const out = { w: img.w, h: img.h, data: new Uint8ClampedArray(img.w * img.h * 4) }
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    const s = (y * img.w + x) * 4, d = (y * img.w + (img.w - 1 - x)) * 4
    out.data[d] = img.data[s]; out.data[d + 1] = img.data[s + 1]; out.data[d + 2] = img.data[s + 2]; out.data[d + 3] = img.data[s + 3]
  }
  return out
}
const iou = (a, b) => {
  const w = Math.min(a.w, b.w), h = Math.min(a.h, b.h)
  let inter = 0, uni = 0
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const va = a.data[(y * a.w + x) * 4 + 3] > 128, vb = b.data[(y * b.w + x) * 4 + 3] > 128
    if (va && vb) inter++
    if (va || vb) uni++
  }
  return uni ? inter / uni : 0
}

// 特征①：不透明主体重心 vs 包围盒中心
function bodyBias(img) {
  const b = bbox(img)
  let sx = 0, n = 0
  for (let y = b.y0; y <= b.y1; y++) for (let x = b.x0; x <= b.x1; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 120) { sx += x; n++ }
  }
  const mid = (b.x0 + b.x1) / 2
  return { bias: sx / n - mid, dir: sx / n < mid ? '左' : '右', bbox: b }
}
// 特征②：接地影（下半部的灰色低饱和块）重心
function shadowBias(img) {
  const b = bbox(img)
  const y0 = b.y0 + Math.round((b.y1 - b.y0) * 0.72)
  let sx = 0, n = 0
  for (let y = y0; y <= b.y1; y++) for (let x = b.x0; x <= b.x1; x++) {
    const i = (y * img.w + x) * 4
    if (img.data[i + 3] < 60) continue
    const r = img.data[i], g = img.data[i + 1], bl = img.data[i + 2]
