    if (sat < 26 && lum > 90 && lum < 215) { sx += x; n++ }
  }
  if (!n) return null
  const mid = (b.x0 + b.x1) / 2
  return { bias: sx / n - mid, dir: sx / n < mid ? '左' : '右', n }
}

