{"content": "// 自证：按 game.js 的规则算一遍，36 只怪在战斗里是否**全部朝左**（面对玩家）
//
// 规则（与 game.js 一致）：
//   · 怪在右侧 → 目标朝向 = 朝左
//   · `MONSTER_ART_FACES_RIGHT`（素材天然朝右的 9 只）→ 翻转 → `faceRight: false`
//   · 其余 27 只素材朝左 → 不翻 → `faceRight: true`
//   · 翻一次 = 转 180°（左↔右）
import fs from 'node:fs'

const t = JSON.parse(fs.readFileSync('assets/monsters/facing-right.json', 'utf8'))
const RIGHT = new Set(t.needFlipInBattle)
let bad = 0
for (const m of t.all) {
  const artFacesRight = RIGHT.has(m.id)
  const faceRight = !artFacesRight              // 传给 drawMonster 的值
  const willFlip = !faceRight                   // faceRight=false 时 drawMonster 会翻
  const idx = m.dir === '左' ? 0 : 1            // 0=左 1=右
  const finalDir = (idx + (willFlip ? 1 : 0)) % 2 === 0 ? '左' : '右'
  if (finalDir !== '左') {
    bad++
    console.log(`  ✗ ${m.name}  素材朝${m.dir}  faceRight=${faceRight} 翻=${willFlip}  → 最终朝${finalDir}`)
  }
}
console.log(`  ${t.all.length} 只算完：最终不朝左的 **${bad}** 只`)
console.log(bad === 0 ? '  ✓ 战斗里 36 只怪全部朝左（面对玩家）' : '  ✗ 仍有怪朝向错误')
process.exit(bad ? 1 : 0)
