  //   · 出手频率：速度取主人的 85%，所以排在主人之后、多数回合都能轮到
  const SOYA_ATK_SCALE = 0.45
  const SOYA_SPD_SCALE = 0.85

  // 把宠物包成一个"能进伤害公式"的单位。
  // ⚠️ 必须是**每次现取**（主人的攻防会随装备/形态/增益变化），不能在开战时算一次存着。
