    return {
      atk: sc(st.atk), matk: sc(st.matk != null ? st.matk : st.atk),
      def: sc(st.def), mdef: sc(st.mdef != null ? st.mdef : st.def),
      spd: Math.max(1, Math.round((st.spd || 100) * SOYA_SPD_SCALE)),
      hit: st.hit || 40, eva: st.eva || 35, crit: 3,
