{"content": "// 诊断发布包：ZIP64 结构是否完整（真实解压器能不能读）
import fs from 'node:fs'
const f = '多克多比v0.7单机版.zip'
const buf = fs.readFileSync(f)
console.log(`文件 ${(buf.length / 1048576).toFixed(2)} MB`)

// 找 EOCD (0x06054b50)
let eocd = -1
for (let i = buf.length - 22; i >= 0 && i > buf.length - 70000; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break }
}
console.log('EOCD 偏移 =', eocd, eocd < 0 ? '✗ 找不到' : '')
if (eocd < 0) process.exit(1)
const disk = buf.readUInt16LE(eocd + 4)
const cdDisk = buf.readUInt16LE(eocd + 6)
const nThis = buf.readUInt16LE(eocd + 8)
const nTotal = buf.readUInt16LE(eocd + 10)
const cdSize = buf.readUInt32LE(eocd + 12)
const cdOff = buf.readUInt32LE(eocd + 16)
console.log(`  EOCD: 条目 ${nTotal}（本盘 ${nThis}） 中央目录 size=${cdSize} off=${cdOff} 磁盘 ${disk}/${cdDisk}`)
console.log(`  条目数 0xFFFF? ${nTotal === 0xffff ? '是 → 需要 ZIP64 EOCD' : '否'}`)
console.log(`  cdOff 0xFFFFFFFF? ${cdOff === 0xffffffff ? '是 → 需要 ZIP64 定位' : '否'}`)

// 找 ZIP64 EOCD locator (0x07064b50)，必须紧邻 EOCD 之前 20 字节
const locOff = eocd - 20
const locSig = buf.readUInt32LE(locOff)
console.log(`\nZIP64 locator @${locOff}: 签名 0x${locSig.toString(16)} ${locSig === 0x07064b50 ? '✓' : '✗ 缺失'}`)
if (locSig === 0x07064b50) {
  const z64Off = Number(buf.readBigUInt64LE(locOff + 8))
  console.log(`  → ZIP64 EOCD 偏移 = ${z64Off}`)
  const sig = buf.readUInt32LE(z64Off)
  console.log(`  ZIP64 EOCD 签名 0x${sig.toString(16)} ${sig === 0x06064b50 ? '✓' : '✗ 位置不对'}`)
  if (sig === 0x06064b50) {
    const size = Number(buf.readBigUInt64LE(z64Off + 4))
    const nTot = Number(buf.readBigUInt64LE(z64Off + 32))
    const cdS = Number(buf.readBigUInt64LE(z64Off + 40))
    const cdO = Number(buf.readBigUInt64LE(z64Off + 48))
    console.log(`    记录长 ${size}  条目 ${nTot}  中央目录 size=${cdS} off=${cdO}`)
    console.log(`    中央目录是否落在文件内: ${cdO + cdS <= buf.length ? '✓' : '✗ 越界!'}`)
    console.log(`    尾部剩余字节: ${buf.length - (cdO + cdS)}（应为 EOCD64+locator+EOCD ≈ ${size + 20 + 22}）`)
    // 中央目录必须以 0x02014b50 开头
    console.log(`    中央目录首签名 0x${buf.readUInt32LE(cdO).toString(16)} ${buf.readUInt32LE(cdO) === 0x02014b50 ? '✓' : '✗'}`)
  }
} else {
  console.log('  ⚠️ 没有 ZIP64 locator — 若条目数或偏移溢出，标准解压器会报损坏')
}
