}
$zip.Dispose()
Write-Output ""
Write-Output ("逐条目解压结果：正常 {0} / 异常 {1}" -f $ok, $bad)
if ($badList.Count) { Write-Output "前几个异常："; $badList | ForEach-Object { Write-Output ("  ✗ " + $_) } }
