{"content": "// 最小复现：复刻 make-release.mjs 的 zip 写入逻辑，打 3 个小文件，再用 .NET 验
// 目的：把"包坏了"缩到可看字节的规模，定位是哪个字段写错。
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'
import { spawnSync } from 'node:child_process'

const TMP = path.resolve('_tmp_test_out', 'ziptest')
fs.rmSync(TMP, { recursive: true, force: true })
fs.mkdirSync(TMP, { recursive: true })
// 三个大小递减的文件（模拟"串位"现象：若长度写错，大的会被解成小的）
fs.writeFileSync(path.join(TMP, 'a.bin'), Buffer.alloc(20000, 0x41))   // 20000 A
fs.writeFileSync(path.join(TMP, 'b.bin'), Buffer.alloc(9000, 0x42))    //  9000 B
fs.writeFileSync(path.join(TMP, 'c.bin'), Buffer.alloc(3000, 0x43))    //  3000 C
const zipPath = path.join(TMP, 'test.zip')

// ---- 与 make-release.mjs 完全相同的写法 ----
const CRC_TABLE = (() => {
  const t = new Int32Array(256)
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c }
  return t
})()
const crc32 = (buf) => { let c = -1; for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8); return (c ^ -1) >>> 0 }
const dTime = 0, dDate = 0

const entries = fs.readdirSync(TMP).filter((f) => f.endsWith('.bin')).map((f) => ({ name: f, full: path.join(TMP, f) }))
const out = fs.openSync(zipPath, 'w')
const central = []
let offset = 0
const writeBuf = (b) => { fs.writeSync(out, b); offset += b.length }

for (const ent of entries) {
  const nameBuf = Buffer.from(ent.name, 'utf8')
  const raw = fs.readFileSync(ent.full)
  const method = 8
  const comp = zlib.deflateRawSync(raw, { level: 6 })
  const crc = crc32(raw)
  const local = Buffer.alloc(30)
  local.writeUInt32LE(0x04034b50, 0)
  local.writeUInt16LE(20, 4)
  local.writeUInt16LE(0x0800, 6)
  local.writeUInt16LE(method, 8)
  local.writeUInt16LE(dTime, 10)
  local.writeUInt16LE(dDate, 12)
  local.writeUInt32LE(crc, 14)
  local.writeUInt32LE(comp.length, 18)
  local.writeUInt32LE(raw.length, 22)
  local.writeUInt16LE(nameBuf.length, 26)
  local.writeUInt16LE(0, 28)
  writeBuf(local); writeBuf(nameBuf); writeBuf(comp)

  const cen = Buffer.alloc(46)
  cen.writeUInt32LE(0x02014b50, 0)
  cen.writeUInt16LE(20, 4)
  cen.writeUInt16LE(20, 6)
  cen.writeUInt16LE(0x0800, 8)
  cen.writeUInt16LE(method, 10)
  cen.writeUInt16LE(dTime, 12)
  cen.writeUInt16LE(dDate, 14)
  cen.writeUInt32LE(crc, 16)
  cen.writeUInt32LE(comp.length, 20)
  cen.writeUInt32LE(raw.length, 24)
  cen.writeUInt16LE(nameBuf.length, 28)
  cen.writeUInt16LE(0, 30)
  cen.writeUInt16LE(0, 32)
  cen.writeUInt16LE(0, 34)
  cen.writeUInt16LE(0, 36)
  cen.writeUInt32LE(0x20, 38)
  cen.writeUInt32LE(offset, 42)
  central.push(Buffer.concat([cen, nameBuf]))
}
const cenStart = offset
for (const c of central) writeBuf(c)
const eocd = Buffer.alloc(22)
eocd.writeUInt32LE(0x06054b50, 0)
eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6)
eocd.writeUInt16LE(entries.length, 8); eocd.writeUInt16LE(entries.length, 10)
eocd.writeUInt32LE(offset - cenStart, 12)
eocd.writeUInt32LE(cenStart, 16)
eocd.writeUInt16LE(0, 20)
writeBuf(eocd)
fs.closeSync(out)

console.log(`写出 ${path.relative(process.cwd(), zipPath)}  ${fs.statSync(zipPath).size} 字节`)
console.log(`条目: ${entries.map((e) => e.name).join(', ')}`)

// ---- .NET 验证 ----
const ps = `
Add-Type -AssemblyName System.IO.Compression.FileSystem
$z=[System.IO.Compression.ZipFile]::OpenRead('${zipPath.replace(/'/g, "''")}')
foreach($e in $z.Entries){
  try{
    $s=$e.Open(); $ms=New-Object System.IO.MemoryStream; $s.CopyTo($ms); $s.Close()
    Write-Output ($e.FullName+' 期望'+$e.Length+' 实得'+$ms.Length)
    $ms.Dispose()
  } catch { Write-Output ($e.FullName+' 异常: '+$_.Exception.Message) }
}
$z.Dispose()
`
const r = spawnSync('powershell.exe', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', ps], { encoding: 'utf8' })
console.log('\n.NET 逐条目解压：')
console.log((r.stdout || r.stderr || '(无输出)').trim())

// ---- 与 PowerShell 自带 Compress-Archive 的产物对比 ----
const refZip = path.join(TMP, 'ref.zip')
const r2 = spawnSync('powershell.exe', ['-NoProfile', '-Command',
  `Compress-Archive -Path '${path.join(TMP, 'a.bin')}','${path.join(TMP, 'b.bin')}','${path.join(TMP, 'c.bin')}' -DestinationPath '${refZip}' -Force`],
  { encoding: 'utf8' })
if (fs.existsSync(refZip)) {
  const a = fs.readFileSync(zipPath), b = fs.readFileSync(refZip)
  console.log(`\n对照 Compress-Archive 产物：${b.length} 字节（我的 ${a.length} 字节）`)
  // 打印两者前 32 字节，看本地头有没有差异
  const hex = (buf, n) => buf.subarray(0, n).toString('hex').replace(/(.{8})/g, '$1 ')
  console.log('  我的本地头 :', hex(a, 30))
  console.log('  参考本地头 :', hex(b, 30))
}
