const buf = fs.readFileSync(zipPath)
console.log(`包 ${buf.length} 字节\n`)

// 逐个本地头走一遍，打印每个字段
let p = 0, n = 0
while (p + 30 <= buf.length && buf.readUInt32LE(p) === 0x04034b50 && n < 10) {
  const ver = buf.readUInt16LE(p + 4)
  const flag = buf.readUInt16LE(p + 6)
  const method = buf.readUInt16LE(p + 8)
  const crc = buf.readUInt32LE(p + 14)
  const csize = buf.readUInt32LE(p + 18)
  const usize = buf.readUInt32LE(p + 22)
  const nlen = buf.readUInt16LE(p + 26)
  const elen = buf.readUInt16LE(p + 28)
  const name = buf.toString('utf8', p + 30, p + 30 + nlen)
  const dataStart = p + 30 + nlen + elen
  console.log(`本地头 #${n + 1} @${p}`)
  console.log(`  名称 "${name}"  版本 ${ver}  标志 0x${flag.toString(16)}  方法 ${method}`)
  console.log(`  crc 0x${crc.toString(16)}  csize ${csize}  usize ${usize}  nlen ${nlen}  elen ${elen}`)
  console.log(`  数据起点 ${dataStart}`)
  // 试着只喂 csize 字节给 inflateRaw
  try {
    const raw = zlib.inflateRawSync(buf.subarray(dataStart, dataStart + csize))
    console.log(`  按 csize 解出 ${raw.length} 字节 ${raw.length === usize ? '✓' : '✗ 与 usize 不符'}`)
    // 前 8 字节是不是连续填充？
    console.log(`  前 4 字节 ${[...raw.subarray(0, 4)].map((x) => x.toString(16)).join(' ')}`)
  } catch (e) {
    console.log(`  按 csize 解压失败: ${e.message}`)
  }
  // 本地头后面紧邻的是不是下一个本地头？
  const next = dataStart + csize
  const sig = buf.readUInt32LE(next)
  console.log(`  数据后紧邻 @${next}: 签名 0x${sig.toString(16)} ${sig === 0x04034b50 ? '✓ 是下一个本地头' : '✗ 不是本地头（说明 csize 不对，这里还残留数据）'}`)
  p = next
  n++
}
console.log(`\n走完 ${n} 个本地头，停在 ${p}`)
// 中央目录
while (p + 46 <= buf.length && buf.readUInt32LE(p) === 0x02014b50) {
  const csize = buf.readUInt32LE(p + 20)
  const usize = buf.readUInt32LE(p + 24)
  const nlen = buf.readUInt16LE(p + 28)
  const lho = buf.readUInt32LE(p + 42)
  console.log(`中央 #${p}  "${buf.toString('utf8', p + 46, p + 46 + nlen)}"  csize ${csize}  usize ${usize}  本地偏移 ${lho}`)
  p += 46 + nlen + buf.readUInt16LE(p + 30) + buf.readUInt16LE(p + 32)
}
