{"content": "// 量貂蝉多比的脸：两个"眼形"区域里到底有没有眼睛内容
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
for (const rel of ['assets/forms/art/貂蝉多比.png', '多克多比专区资料素材/多比形态素材/行者孙吕布等/吕布&貂蝉/貂蝉多比2.png']) {
  const p = path.join(ROOT, rel)
  if (!fs.existsSync(p)) { console.log(`缺 ${rel}`); continue }
  const img = decodePng(fs.readFileSync(p))
  console.log(`\n=== ${rel}  ${img.w}×${img.h} ===`)
  // 找"接近纯白/极浅"的连通块（眼形区域是白色填充）
  const isWhite = (i) => {
    const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
    return img.data[i + 3] > 200 && r > 225 && g > 225 && b > 228 && (Math.max(r, g, b) - Math.min(r, g, b)) < 22
  }
  // 脸部大概在画面上部 1/3；只扫这块，避免扫到衣服的白色
  const yTop = Math.round(img.h * 0.18), yBot = Math.round(img.h * 0.52)
  const seen = new Uint8Array(img.w * img.h)
  const blobs = []
  for (let y = yTop; y < yBot; y++) for (let x = 0; x < img.w; x++) {
    const p0 = y * img.w + x
    if (seen[p0] || !isWhite(p0 * 4)) continue
    // 洪水
    const q = [p0]; seen[p0] = 1
    let n = 0, bx0 = x, bx1 = x, by0 = y, by1 = y, sx = 0, sy = 0
    while (q.length) {
      const c = q.pop(), cx = c % img.w, cy = (c / img.w) | 0
      if (!isWhite(c * 4)) continue
      n++; sx += cx; sy += cy
      if (cx < bx0) bx0 = cx; if (cx > bx1) bx1 = cx
      if (cy < by0) by0 = cy; if (cy > by1) by1 = cy
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || nx >= img.w || ny < yTop || ny >= yBot) continue
        const np = ny * img.w + nx
        if (!seen[np]) { seen[np] = 1; q.push(np) }
      }
    }
    if (n > 300) blobs.push({ n, bx0, bx1, by0, by1, cx: sx / n, cy: sy / n })
  }
  blobs.sort((a, b) => b.n - a.n)
  console.log(`  脸部白色块 ${blobs.length} 个（>300px）：`)
  for (const b of blobs.slice(0, 6)) {
    console.log(`    面积 ${b.n}  x ${b.bx0}..${b.bx1}  y ${b.by0}..${b.by1}  重心 (${b.cx.toFixed(0)},${b.cy.toFixed(0)})`)
  }
  // 在这两块里统计"非白"像素（= 眼睛内容：瞳孔/描边）
  for (const [k, b] of blobs.slice(0, 2).entries()) {
    let nonWhite = 0, tot = 0, dark = 0
    for (let y = b.by0; y <= b.by1; y++) for (let x = b.bx0; x <= b.bx1; x++) {
      const i = (y * img.w + x) * 4
