{"content": "// 搜归档里所有"貂蝉"相关图片，逐张量"眼形区域里有没有深色内容"
// 判据：脸部的两个眼形空白里若存在**深色像素簇**（瞳孔），就是有眼睛。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ARCH = path.join(ROOT, '多克多比专区资料素材')
const imgExt = new Set(['.png', '.jpg', '.jpeg', '.bmp'])
const hits = []
;(function walk(d, dep) {
  if (dep > 7) return
  let es
  try { es = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
  for (const e of es) {
    const p = path.join(d, e.name)
    if (e.isDirectory()) walk(p, dep + 1)
    else if (/貂蝉/.test(e.name) && imgExt.has(path.extname(e.name).toLowerCase())) hits.push(p)
  }
})(ARCH, 0)
console.log(`归档里"貂蝉"相关图片 ${hits.length} 张\n`)

for (const p of hits) {
  const rel = p.replace(ARCH + path.sep, '')
  let img
  try { img = decodePng(fs.readFileSync(p)) } catch (e) { console.log(`  ${rel}  读不了: ${e.message}`); continue }
  // 找"接近纯白"的大块（眼形空白）
  const isWhite = (i) => {
    const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
    return img.data[i + 3] > 200 && r > 222 && g > 222 && b > 226 && (Math.max(r, g, b) - Math.min(r, g, b)) < 26
  }
  const yTop = Math.round(img.h * 0.15), yBot = Math.round(img.h * 0.55)
  const seen = new Uint8Array(img.w * img.h)
  const blobs = []
  for (let y = yTop; y < yBot; y += 2) for (let x = 0; x < img.w; x += 2) {
    const p0 = y * img.w + x
    if (seen[p0] || !isWhite(p0 * 4)) continue
    const q = [p0]; seen[p0] = 1
    let n = 0, bx0 = x, bx1 = x, by0 = y, by1 = y
    while (q.length) {
      const c = q.pop(), cx = c % img.w, cy = (c / img.w) | 0
      if (!isWhite(c * 4)) continue
      n++
      if (cx < bx0) bx0 = cx; if (cx > bx1) bx1 = cx
      if (cy < by0) by0 = cy; if (cy > by1) by1 = cy
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || nx >= img.w || ny < yTop || ny >= yBot) continue
        const np = ny * img.w + nx
        if (!seen[np]) { seen[np] = 1; q.push(np) }
      }
    }
    if (n > 200) blobs.push({ n, bx0, bx1, by0, by1 })
  }
  blobs.sort((a, b) => b.n - a.n)
  // 在每个白块内部数"深色"像素（瞳孔特征）
  let darkTotal = 0, area = 0
  for (const b of blobs.slice(0, 3)) {
    for (let y = b.by0; y <= b.by1; y++) for (let x = b.bx0; x <= b.bx1; x++) {
      const i = (y * img.w + x) * 4
      if (img.data[i + 3] < 100) continue
      area++
      const lum = (img.data[i] + img.data[i + 1] + img.data[i + 2]) / 3
      if (lum < 140) darkTotal++
    }
  }
  const pct = area ? (darkTotal / area * 100) : 0
  console.log(`  ${rel}`)
  console.log(`     ${img.w}×${img.h}  脸部白块 ${blobs.length} 个  白块内深色像素 ${darkTotal} / ${area} = ${pct.toFixed(1)}%`)
  console.log(`     → ${pct > 1.5 ? '**可能有眼睛（有深色内容）**' : '眼形区域是空的（无瞳孔）'}`)
}
