{"content": "// 判定貂蝉多比右脸那块"黑色眼形"是头发还是眼睛：看它与棕色头发的连通性 + 边界色
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const img = decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/貂蝉多比.png')))
const at = (x, y) => { const i = (y * img.w + x) * 4; return [img.data[i], img.data[i + 1], img.data[i + 2], img.data[i + 3]] }
const isBlack = (x, y) => { const c = at(x, y); return c[3] > 200 && c[0] < 30 && c[1] < 30 && c[2] < 30 }
const isBrown = (x, y) => { const c = at(x, y); return c[3] > 200 && c[0] > 50 && c[0] < 130 && c[1] > 20 && c[1] < 90 && c[2] < 60 }

console.log('脸部区域横向采样（y=250 / 270 / 290，每 6px）：')
for (const y of [250, 270, 290]) {
  const row = []
  for (let x = 90; x <= 240; x += 6) {
    const c = at(x, y)
    const tag = isBlack(x, y) ? '黑' : isBrown(x, y) ? '棕' : (c[0] > 240 && c[1] > 240 && c[2] > 240) ? '白' : '淡'
    row.push(`${x}:${tag}`)
  }
  console.log(`  y=${y}  ${row.join(' ')}`)
}

// 黑色区域与棕色头发是否相连（洪水：黑块能不能走到棕色）
const seen = new Uint8Array(img.w * img.h)
// 找一个黑色种子（右脸中心附近）
let seed = null
for (let y = 230; y < 320 && !seed; y++) for (let x = 150; x < 240; x++) if (isBlack(x, y)) { seed = [x, y]; break }
if (!seed) { console.log('\n没找到黑色种子'); process.exit(0) }
console.log(`\n黑色种子 @${seed}`)
let n = 0, touchesBrown = false, x0 = 1e9, x1 = -1, y0 = 1e9, y1 = -1
const q = [seed[1] * img.w + seed[0]]; seen[q[0]] = 1
while (q.length) {
  const c = q.pop(), cx = c % img.w, cy = (c / img.w) | 0
  n++
  if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
  if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nx = cx + dx, ny = cy + dy
    if (nx < 0 || nx >= img.w || ny < 0 || ny >= img.h) continue
    if (isBrown(nx, ny)) { touchesBrown = true; continue }
    const np = ny * img.w + nx
    if (!seen[np] && isBlack(nx, ny)) { seen[np] = 1; q.push(np) }
  }
}
console.log(`  黑色连通块：面积 ${n}，包围盒 x ${x0}..${x1}  y ${y0}..${y1}`)
console.log(`  是否紧邻棕色头发: ${touchesBrown ? '是 → **很可能是头发**（黑发在脸的投影/刘海）' : '否 → 更像一块独立的黑色填充（可能是眼睛）'}`)
// 看它的形状宽高比
console.log(`  形状 ${x1 - x0 + 1}×${y1 - y0 + 1}，宽高比 ${((x1 - x0 + 1) / (y1 - y0 + 1)).toFixed(2)}`)
