for (let y = yTop; y < yBot; y += 2) for (let x = 0; x < img.w; x += 2) {
  const p0 = y * img.w + x
  if (seen[p0] || !isRed(x, y)) continue
  const q = [p0]; seen[p0] = 1
  let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
  while (q.length) {
    const c = q.pop(), cx = c % img.w, cy = (c / img.w) | 0
    n++
    if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
    if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = cx + dx, ny = cy + dy
      if (nx < 0 || nx >= img.w || ny < 0 || ny >= img.h || ny >= yBot) continue
      const np = ny * img.w + nx
      if (!seen[np] && isRed(nx, ny)) { seen[np] = 1; q.push(np) }
    }
