{"content": "// 给貂蝉多比补眼睛（按吕布多比的画风：深色描边 + 红填充 + 白高光）
//
// 【依据】
//   · 用户：「而且图鉴里有貂蝉多克多比缺一个眼」→ 核实：官方 4 张立绘**全都没有眼睛**，
//     脸是纯白、只有**两个眼形轮廓**（左眼可见、右眼被头发遮住）。
//   · 用户选定的方案：「按吕布的画风补上双眼」—— 吕布多比是同一批素材
//     （`吕布&貂蝉/` 目录），实测其眼睛配色 = 黑/深红描边 + 鲜红填充 + 右上角白高光。
//   · 这是**推测性补画**（官方素材本身没有），所以：
//       ① 单独成脚本、可一键还原；② 结果登记进 deviations；③ 出对比图给用户确认。
//
// 用法: node _tools/draw-diaochan-eyes.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, 'assets/forms/art/貂蝉多比.png')
const BAK = path.join(ROOT, '_tmp_test_out/art-before-eyes.png')
const DRY = process.argv.includes('--dry')

const img = decodePng(fs.readFileSync(SRC))
const { w: W, h: H, data } = img
const at = (x, y) => { const i = (y * W + x) * 4; return [data[i], data[i + 1], data[i + 2], data[i + 3]] }

// ---------- 1) 自动找出两个"眼形空白"（纯白块） ----------
const isEyeWhite = (x, y) => {
  const c = at(x, y)
  return c[3] > 200 && c[0] > 246 && c[1] > 246 && c[2] > 246
}
const seen = new Uint8Array(W * H)
const blanks = []
// 只在脸部范围找（避免扫到衣服的白色）：脸部已量过在 x 80..300 / y 200..320
for (let y = 200; y < 330; y++) for (let x = 80; x < 320; x++) {
  const p0 = y * W + x
  if (seen[p0] || !isEyeWhite(x, y)) continue
  const q = [p0]; seen[p0] = 1
  let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
  while (q.length) {
    const c = q.pop(), cx = c % W, cy = (c / W) | 0
    n++
    if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
    if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = cx + dx, ny = cy + dy
      if (nx < 80 || nx >= 320 || ny < 200 || ny >= 330) continue
      const np = ny * W + nx
      if (!seen[np] && isEyeWhite(nx, ny)) { seen[np] = 1; q.push(np) }
    }
  }
  if (n > 150) blanks.push({ n, x0, x1, y0, y1 })
}
blanks.sort((a, b) => b.n - a.n)
console.log(`找到 ${blanks.length} 个眼形空白块：`)
for (const b of blanks) console.log(`  面积 ${b.n}  x ${b.x0}..${b.x1}  y ${b.y0}..${b.y1}  ${b.x1 - b.x0 + 1}×${b.y1 - b.y0 + 1}`)
if (!blanks.length) { console.log('没找到眼形空白，退出'); process.exit(1) }

// ---------- 2) 按吕布配色画一只眼 ----------
// 配色取自吕布多比实测：描边深色(0,0,0) → 外圈暗红(120,0,20) → 主体鲜红(224,0,32) → 高光白
const COL = {
  outline: [22, 8, 14],
  outer: [122, 12, 34],
  main: [226, 30, 58],
  main2: [186, 14, 40],
  gloss: [255, 240, 244],
}
function put(x, y, rgb, a = 1) {
  if (x < 0 || y < 0 || x >= W || y >= H) return
  const i = (y * W + x) * 4
  if (data[i + 3] < 40) return              // 不动透明区
  data[i] = Math.round(rgb[0] * a + data[i] * (1 - a))
  data[i + 1] = Math.round(rgb[1] * a + data[i + 1] * (1 - a))
  data[i + 2] = Math.round(rgb[2] * a + data[i + 2] * (1 - a))
}
// 眼形是"上尖下圆"的叶形，且右侧被头发遮住 —— 用逐行椭圆宽度铺出来
function drawEye(b, { cxFrac = 0.52, wFrac = 0.86, hFrac = 0.92 } = {}) {
  const bw = b.x1 - b.x0 + 1, bh = b.y1 - b.y0 + 1
  const cx = b.x0 + bw * cxFrac, cy = b.y0 + bh * 0.5
  const rx = bw * wFrac * 0.5, ry = bh * hFrac * 0.5
  let painted = 0
  for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
    const t = (y - cy) / ry
    if (Math.abs(t) > 1) continue
    // 叶形：上半更窄（尖），下半更宽（圆）
    const k = t < 0 ? 0.72 + 0.28 * (1 + t) : 1
    const half = rx * Math.sqrt(Math.max(0, 1 - t * t)) * k
    if (half < 0.5) continue
    for (let x = Math.floor(cx - half); x <= Math.ceil(cx + half); x++) {
      // 只画在"原本是白"或"原本是脸"的像素上（不覆盖头发/描边）
      const c = at(x, y)
      const isFace = c[3] > 200 && c[0] > 180 && c[1] > 180 && c[2] > 180
