      const u = (x - cx) / half            // -1..1
      const edge = Math.abs(u) > 0.86 || Math.abs(t) > 0.88
      const nearEdge = Math.abs(u) > 0.74 || Math.abs(t) > 0.78
      if (edge) put(x, y, COL.outline)
      else if (nearEdge) put(x, y, COL.outer)
      else {
        // 主体：上浅下深，做出立体感
        const v = (t + 1) / 2
        put(x, y, v < 0.5 ? COL.main : COL.main2)
      }
      painted++
    }
  }
  // 高光：右上角一小片（吕布的高光在眼框右上）
  const gx = cx + rx * 0.30, gy = cy - ry * 0.34
  for (let y = Math.floor(gy - ry * 0.2); y <= Math.ceil(gy + ry * 0.2); y++) {
    for (let x = Math.floor(gx - rx * 0.2); x <= Math.ceil(gx + rx * 0.2); x++) {
      const c = at(x, y)
      if (c[3] < 200 || c[0] < 150) continue
      put(x, y, COL.gloss, 0.95)
    }
  }
  return painted
}

if (!DRY && !fs.existsSync(BAK)) { fs.mkdirSync(path.dirname(BAK), { recursive: true }); fs.copyFileSync(SRC, BAK); console.log(`\n已备份原图 → ${path.relative(ROOT, BAK)}`) }
console.log('\n补眼：')
// 只画**可见的那只**（最大的白块 = 左眼）。右眼被头发整片遮住，不画（画了会浮在头发上）。
const target = blanks[0]
const n = drawEye(target)
console.log(`  在 x ${target.x0}..${target.x1} / y ${target.y0}..${target.y1} 画了 ${n} 像素`)
