{"content": "// 给貂蝉多比补眼睛（第 2 版：让原有头发自然遮挡）
//
// 【依据与授权】
//   · 用户：「图鉴里有貂蝉多克多比缺一个眼」→ 核实：官方 4 张立绘**全无眼睛**，
//     脸是纯白、只有**两个眼形轮廓**（右眼被头发整片遮住）。
//   · 用户选定：「按吕布的画风补上双眼」—— 吕布多比（同目录素材）实测眼睛配色 =
//     深色描边 + 鲜红填充 + 右上白高光。
//   · 这是**推测性补画**（官方素材本身没有眼睛），故：可一键还原、结果登记 deviations、出对比图。
//
// 【第 1 版为什么失败】把"包围盒中心"当瞳孔位置 → 瞳孔落到了**头发上**（红块浮在发丝上），
//   而且高光画成了方块。第 2 版改两件事：
//     ① **让头发遮挡**：只在"原本不是头发"的像素上落笔（用原图的褐色/深色描边做遮罩）；
//     ② **按眼形实际重心放瞳孔**（白色区域的质心），而不是包围盒中心；
//     ③ 高光改圆形、描边用超采样求平滑。
//
// 用法: node _tools/draw-diaochan-eyes.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, 'assets/forms/art/貂蝉多比.png')
const BAK = path.join(ROOT, '_tmp_test_out/art-before-eyes.png')
const DRY = process.argv.includes('--dry')

const img = decodePng(fs.readFileSync(SRC))
const { w: W, h: H, data } = img
const at = (x, y) => { const i = (y * W + x) * 4; return [data[i], data[i + 1], data[i + 2], data[i + 3]] }

// ---------- 1) 眼部区域：找"纯白块"（眼形轮廓）并求其质心 ----------
const isEyeWhite = (x, y) => {
  const c = at(x, y)
  return c[3] > 200 && c[0] > 246 && c[1] > 246 && c[2] > 246
}
const seen = new Uint8Array(W * H)
const blanks = []
for (let y = 200; y < 330; y++) for (let x = 80; x < 320; x++) {
  const p0 = y * W + x
  if (seen[p0] || !isEyeWhite(x, y)) continue
  const q = [p0]; seen[p0] = 1
  let n = 0, x0 = x, x1 = x, y0 = y, y1 = y, sx = 0, sy = 0
  while (q.length) {
    const c = q.pop(), cx = c % W, cy = (c / W) | 0
    n++; sx += cx; sy += cy
    if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
    if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = cx + dx, ny = cy + dy
      if (nx < 80 || nx >= 320 || ny < 200 || ny >= 330) continue
      const np = ny * W + nx
      if (!seen[np] && isEyeWhite(nx, ny)) { seen[np] = 1; q.push(np) }
    }
  }
  if (n > 150) blanks.push({ n, x0, x1, y0, y1, cx: sx / n, cy: sy / n })
}
blanks.sort((a, b) => b.n - a.n)
console.log(`眼形白块 ${blanks.length} 个：`)
for (const b of blanks) {
  console.log(`  面积 ${b.n}  框 x ${b.x0}..${b.x1} y ${b.y0}..${b.y1}  质心 (${b.cx.toFixed(0)}, ${b.cy.toFixed(0)})`)
}
if (!blanks.length) { console.log('没有眼形白块，退出'); process.exit(1) }

// ---------- 2) 遮罩：头发与描边不许被覆盖 ----------
// 头发 = 褐色系（R 明显大于 B、且不是脸那种很亮的粉紫）；描边 = 很深
function isHairOrLine(x, y) {
  const c = at(x, y)
  if (c[3] < 60) return true
  const [r, g, b] = c
  const lum = (r + g + b) / 3
  if (lum < 120) return true                       // 深色描边
  if (r > b + 30 && r < 200 && g < 150) return true // 褐色头发
  return false
}

// ---------- 3) 画一只眼 ----------
const COL = { line: [26, 10, 16], outer: [120, 10, 32], iris: [224, 28, 56], iris2: [176, 12, 36], gloss: [255, 244, 248] }
function put(x, y, rgb, a = 1) {
  const i = (y * W + x) * 4
  if (x < 0 || y < 0 || x >= W || y >= H) return false
  if (data[i + 3] < 40) return false
  if (isHairOrLine(x, y)) return false             // 头发压在上面
  data[i] = Math.round(rgb[0] * a + data[i] * (1 - a))
  data[i + 1] = Math.round(rgb[1] * a + data[i + 1] * (1 - a))
  data[i + 2] = Math.round(rgb[2] * a + data[i + 2] * (1 - a))
  return true
}

// 超采样求平滑边缘：对每个像素在 3×3 子点上判内外，得到覆盖率
function drawEye(b) {
  const bw = b.x1 - b.x0 + 1, bh = b.y1 - b.y0 + 1
  const cx = b.cx, cy = b.cy
  const rx = bw * 0.44, ry = bh * 0.44           // 虹膜比眼形略小，留出眼白
  let painted = 0
  const x0 = Math.floor(cx - rx * 1.3), x1 = Math.ceil(cx + rx * 1.3)
  const y0 = Math.floor(cy - ry * 1.3), y1 = Math.ceil(cy + ry * 1.3)
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      // 子点采样：算"在虹膜内"的覆盖率
      let inside = 0, sub = 0
      for (const dx of [-0.33, 0, 0.33]) for (const dy of [-0.33, 0, 0.33]) {
        sub++
        const u = (x + dx - cx) / rx, v = (y + dy - cy) / ry
        if (u * u + v * v <= 1) inside++
      }
      if (!inside) continue
      const cov = inside / sub
      const u = (x - cx) / rx, v = (y - cy) / ry
      const d = Math.sqrt(u * u + v * v)
      let col
      if (d > 0.86) col = COL.line                    // 外描边
      else if (d > 0.72) col = COL.outer              // 暗红过渡
      else col = (v < -0.1 ? COL.iris : COL.iris2)    // 主体：上浅下深
      if (put(x, y, col, cov)) painted++
    }
  }
  // 高光：右上角**圆形**（第 1 版画成方块）
  const gx = cx + rx * 0.34, gy = cy - ry * 0.36, gr = Math.max(1.6, rx * 0.24)
  for (let y = Math.floor(gy - gr - 1); y <= Math.ceil(gy + gr + 1); y++) {
    for (let x = Math.floor(gx - gr - 1); x <= Math.ceil(gx + gr + 1); x++) {
      const d = Math.hypot(x - gx, y - gy)
      if (d > gr) continue
      const a = d > gr - 1 ? (gr - d) : 1
      if (put(x, y, COL.gloss, Math.min(1, a))) painted++
    }
  }
  return painted
}

if (!DRY && !fs.existsSync(BAK)) { fs.mkdirSync(path.dirname(BAK), { recursive: true }); fs.copyFileSync(SRC, BAK); console.log(`已备份 → ${path.relative(ROOT, BAK)}`) }
const target = blanks[0]
const n = drawEye(target)
console.log(`\n在质心 (${target.cx.toFixed(0)}, ${target.cy.toFixed(0)}) 画了 ${n} 像素（被头发挡住的不会画上）`)
if (!DRY) { fs.writeFileSync(SRC, encodePng(W, H, data)); console.log(`已写回 ${path.relative(ROOT, SRC)}`) }
else console.log('（--dry，未写盘）')
