  const cx = b.cx, cy = b.cy
  const rx = bw * 0.44, ry = bh * 0.44           // 虹膜比眼形略小，留出眼白
  let painted = 0
  const x0 = Math.floor(cx - rx * 1.3), x1 = Math.ceil(cx + rx * 1.3)
  const y0 = Math.floor(cy - ry * 1.3), y1 = Math.ceil(cy + ry * 1.3)
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      // 子点采样：算"在虹膜内"的覆盖率
      let inside = 0, sub = 0
      for (const dx of [-0.33, 0, 0.33]) for (const dy of [-0.33, 0, 0.33]) {
        sub++
        const u = (x + dx - cx) / rx, v = (y + dy - cy) / ry
        if (u * u + v * v <= 1) inside++
      }
      if (!inside) continue
      const cov = inside / sub
      const u = (x - cx) / rx, v = (y - cy) / ry
      const d = Math.sqrt(u * u + v * v)
      let col
      if (d > 0.86) col = COL.line                    // 外描边
      else if (d > 0.72) col = COL.outer              // 暗红过渡
      else col = (v < -0.1 ? COL.iris : COL.iris2)    // 主体：上浅下深
      if (put(x, y, col, cov)) painted++
    }
  }
  // 高光：右上角**圆形**（第 1 版画成方块）
  const gx = cx + rx * 0.34, gy = cy - ry * 0.36, gr = Math.max(1.6, rx * 0.24)
  for (let y = Math.floor(gy - gr - 1); y <= Math.ceil(gy + gr + 1); y++) {
    for (let x = Math.floor(gx - gr - 1); x <= Math.ceil(gx + gr + 1); x++) {
      const d = Math.hypot(x - gx, y - gy)
      if (d > gr) continue
      const a = d > gr - 1 ? (gr - d) : 1
      if (put(x, y, COL.gloss, Math.min(1, a))) painted++
    }
  }
  return painted
}"}

{"content": "// 量清貂蝉多比脸上"两个空的地方"各自是什么颜色（不要靠感觉改）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const img = decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/貂蝉多比.png')))
const { w: W, h: H, data } = img
const at = (x, y) => { const i = (y * W + x) * 4; return [data[i], data[i + 1], data[i + 2], data[i + 3]] }

// 粗糙但够用的颜色分类
function cls(c) {
  const [r, g, b, a] = c
  if (a < 40) return '透明'
  const lum = (r + g + b) / 3
  const sat = Math.max(r, g, b) - Math.min(r, g, b)
  if (lum < 60) return '黑'
  if (lum < 120) return '深'
  if (r > 240 && g > 240 && b > 240) return '纯白'
  if (lum > 215 && sat < 40) return '浅脸'
  if (r > b + 25 && r > 90) return '棕发'
  if (r > 150 && g < 110 && b < 130) return '红'
  return `${r},${g},${b}`
}

// 脸部整块扫描：每 6px 一个点，输出颜色分类矩阵
const X0 = 88, X1 = 320, Y0 = 210, Y1 = 330
console.log(`脸部扫描 x ${X0}..${X1}  y ${Y0}..${Y1}（每 6px）`)
console.log('图例：白=纯白(空白)  脸=浅脸(皮肤)  发=棕发  黑=深色/描边  红=红')
const legend = { '纯白': '白', '浅脸': '脸', '棕发': '发', '黑': '黑', '深': '黑', '红': '红', '透明': '　' }
let header = '     '
for (let x = X0; x <= X1; x += 6) header += (Math.floor(x / 10) % 10)
console.log(header)
for (let y = Y0; y <= Y1; y += 6) {
  let row = String(y).padStart(4) + ' '
  for (let x = X0; x <= X1; x += 6) {
    const t = cls(at(x, y))
    row += legend[t] || '?'
  }
  console.log(row)
}

// 另外：把"纯白"和"浅脸"的所有大块列出来
console.log('\n各颜色像素占比（脸部区域）：')
const cnt = {}
for (let y = Y0; y <= Y1; y++) for (let x = X0; x <= X1; x++) { const t = cls(at(x, y)); cnt[t] = (cnt[t] || 0) + 1 }
for (const [k, v] of Object.entries(cnt).sort((a, b) => b[1] - a[1]).slice(0, 8)) {
  console.log(`  ${k}  ${v}  (${(v / ((X1 - X0) * (Y1 - Y0)) * 100).toFixed(1)}%)`)
}
