{"content": "// 精确定位貂蝉多比"右侧那块空的地方"：看它的实际颜色值与边界，判断该填成什么
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const img = decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/貂蝉多比.png')))
const { w: W, h: H, data } = img
const at = (x, y) => { const i = (y * W + x) * 4; return [data[i], data[i + 1], data[i + 2], data[i + 3]] }

// 从脸部中心往右采样一条线，看颜色怎么变
console.log('横向采样 y=270（脸中心高度），x 从 140 到 280：')
let line = ''
for (let x = 140; x <= 280; x += 4) {
  const c = at(x, y0 = 270)
  line += `${x}:[${c[0]},${c[1]},${c[2]}] `
}
console.log('  ' + line)

console.log('\n横向采样 y=250：')
line = ''
for (let x = 140; x <= 280; x += 4) {
  const c = at(x, 250)
  line += `${x}:[${c[0]},${c[1]},${c[2]}] `
}
console.log('  ' + line)

// 找"深色内域"连通块（luminance < 90 且不透明），列出最大的几个
const isDark = (x, y) => { const c = at(x, y); return c[3] > 150 && (c[0] + c[1] + c[2]) / 3 < 90 }
const seen = new Uint8Array(W * H)
const blobs = []
for (let y = 180; y < 360; y++) for (let x = 80; x < 340; x++) {
  const p0 = y * W + x
  if (seen[p0] || !isDark(x, y)) continue
  const q = [p0]; seen[p0] = 1
  let n = 0, x0 = x, x1 = x, y1 = y, y0b = y, sx = 0, sy = 0
  while (q.length) {
    const c = q.pop(), cx = c % W, cy = (c / W) | 0
    n++; sx += cx; sy += cy
    if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
    if (cy < y0b) y0b = cy; if (cy > y1) y1 = cy
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = cx + dx, ny = cy + dy
      if (nx < 80 || nx >= 340 || ny < 180 || ny >= 360) continue
      const np = ny * W + nx
      if (!seen[np] && isDark(nx, ny)) { seen[np] = 1; q.push(np) }
    }
  }
  if (n > 400) blobs.push({ n, x0, x1, y0: y0b, y1, cx: sx / n, cy: sy / n })
}
blobs.sort((a, b) => b.n - a.n)
console.log('\n深色连通块（>400px）：')
for (const b of blobs) {
  const c = at(Math.round(b.cx), Math.round(b.cy))
  console.log(`  面积 ${b.n}  x ${b.x0}..${b.x1}  y ${b.y0}..${b.y1}  质心 (${b.cx.toFixed(0)},${b.cy.toFixed(0)})  质心颜色 [${c[0]},${c[1]},${c[2]}]  不透明 ${c[3]}`)
}
