{"content": "// 对照判定：吕布多比脸上有没有"同位置的大块纯黑内域"？
//   有 → 那是这套画风的**头发内域**（不是眼窝），不该填白；
//   没有 → 貂蝉那块更像眼窝/空洞，可以按用户要求填成脸白。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, '多克多比专区资料素材/多比形态素材/行者孙吕布等/吕布&貂蝉')
const files = ['吕布多比.png', '貂蝉多比2.png', '貂蝉多比4.png', '貂蝉多比5.png']

for (const f of files) {
  const p = path.join(DIR, f)
  if (!fs.existsSync(p)) { console.log(`缺 ${f}`); continue }
  const img = decodePng(fs.readFileSync(p))
  const { w: W, h: H, data } = img
  const isPureBlack = (x, y) => {
    const i = (y * W + x) * 4
    return data[i + 3] > 200 && data[i] < 12 && data[i + 1] < 12 && data[i + 2] < 12
  }
  const seen = new Uint8Array(W * H)
  const blobs = []
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const p0 = y * W + x
    if (seen[p0] || !isPureBlack(x, y)) continue
    const q = [p0]; seen[p0] = 1
    let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
    while (q.length) {
      const c = q.pop(), cx = c % W, cy = (c / W) | 0
      n++
      if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
      if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue
        const np = ny * W + nx
        if (!seen[np] && isPureBlack(nx, ny)) { seen[np] = 1; q.push(np) }
      }
    }
    if (n > 300) blobs.push({ n, x0, x1, y0, y1 })
  }
  blobs.sort((a, b) => b.n - a.n)
  const total = blobs.reduce((s, b) => s + b.n, 0)
  console.log(`\n${f}  ${W}×${H}`)
  console.log(`  纯黑(0,0,0)连通块 ${blobs.length} 个，合计 ${total} 像素（占画面 ${(total / (W * H) * 100).toFixed(2)}%）`)
  for (const b of blobs.slice(0, 3)) {
    const bw = b.x1 - b.x0 + 1, bh = b.y1 - b.y0 + 1
    console.log(`    面积 ${String(b.n).padStart(6)}  x ${b.x0}..${b.x1} y ${b.y0}..${b.y1}  ${bw}×${bh}  占宽 ${(bw / W * 100).toFixed(0)}%`)
  }
}
