{"content": "// 占位形象预览：并排渲染"真实立绘"与几种占位设计，用于比对风格是否统一
//
// 【为什么要这个工具】占位形象要和游戏里其它多比"看起来是一套的"：
//   官方立绘的共同特征（实测）：**粗深色描边**（≈3~4px @640 高）、
//   分色块填充 + 一层暗部 + 一点高光、脚下有接地影。
//   第一版占位画得太平（半透明填充 + 细描边），和官方立绘放一起像两个游戏。
//
// 用法: node _tools/_preview-form-placeholder.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const OUT = path.join(ROOT, '_tmp_test_out', 'placeholder-preview.png')
const H = 360, PAD = 16, LAB = 26

// ---------- 画布 ----------
function makeCtx(w, h, bg) {
  const d = new Uint8ClampedArray(w * h * 4)
  for (let i = 0; i < w * h; i++) { d[i * 4] = bg[0]; d[i * 4 + 1] = bg[1]; d[i * 4 + 2] = bg[2]; d[i * 4 + 3] = 255 }
  return {
    w, h, d,
    px(x, y, rgb, a = 1) {
      x = Math.round(x); y = Math.round(y)
      if (x < 0 || y < 0 || x >= w || y >= h) return
      const i = (y * w + x) * 4
      d[i] = Math.round(rgb[0] * a + d[i] * (1 - a))
      d[i + 1] = Math.round(rgb[1] * a + d[i + 1] * (1 - a))
      d[i + 2] = Math.round(rgb[2] * a + d[i + 2] * (1 - a))
      d[i + 3] = 255
    },
    // 椭圆填充（带覆盖率抗锯齿）
    ellipse(cx, cy, rx, ry, rgb, a = 1) {
      for (let y = Math.floor(cy - ry - 1); y <= Math.ceil(cy + ry + 1); y++) {
        for (let x = Math.floor(cx - rx - 1); x <= Math.ceil(cx + rx + 1); x++) {
          let ins = 0, sub = 0
          for (const dx of [-0.33, 0, 0.33]) for (const dy of [-0.33, 0, 0.33]) {
            sub++
            const u = (x + dx - cx) / rx, v = (y + dy - cy) / ry
            if (u * u + v * v <= 1) ins++
          }
          if (ins) this.px(x, y, rgb, a * ins / sub)
        }
      }
    },
    // 椭圆描边（在内缩的一圈上画，模拟粗描边）
    ring(cx, cy, rx, ry, lw, rgb) {
      this.ellipse(cx, cy, rx + lw * 0.5, ry + lw * 0.5, rgb)
      // 用"擦除再画内部"的手法做不出真描边，这里改成：外层画色，内层再画填充
    },
  }
}
const shade = (c, k) => [Math.max(0, Math.min(255, c[0] * k)), Math.max(0, Math.min(255, c[1] * k)), Math.max(0, Math.min(255, c[2] * k))].map(Math.round)

// ---------- 设计 A：当前的"扁平占位"（第一版）----------
function drawA(c, cx, by, h, col, name) {
  const bodyW = h * 0.52, bodyH = h * 0.46, headR = h * 0.21
  c.ellipse(cx, by - h * 0.01, bodyW * 0.52, bodyW * 0.14, [13, 28, 48], 0.28)
  c.ellipse(cx, by - bodyH * 0.62, bodyW * 0.5, bodyH * 0.5, [210, 220, 240], 0.30)
  c.ellipse(cx, by - bodyH * 1.06 - headR * 0.35, headR, headR, [210, 220, 240], 0.30)
  for (const s of [-1, 1]) c.ellipse(cx + s * bodyW * 0.22, by - h * 0.03, bodyW * 0.17, h * 0.035, [210, 220, 240], 0.30)
}

// ---------- 设计 B：官方风格（粗描边 + 分色 + 高光 + 接地影）----------
function drawB(c, cx, by, h, col, name, variant = 0) {
  const lw = Math.max(3, h * 0.026)                    // 粗描边（官方立绘约 3~4px @640）
  const dark = shade(col, 0.42)
  const light = shade(col, 1.25)
  const bodyW = h * 0.56, bodyH = h * 0.44, headR = h * 0.215
  const headY = by - bodyH * 1.02 - headR * 0.42
  const bodyY = by - bodyH * 0.60
  // 接地影
  c.ellipse(cx, by + h * 0.005, bodyW * 0.46, h * 0.032, [16, 20, 30], 0.35)
  // 描边层：先画"放大一圈的深色形状"
  c.ellipse(cx, bodyY, bodyW * 0.5 + lw, bodyH * 0.5 + lw, dark)
  c.ellipse(cx, headY, headR + lw, headR + lw, dark)
  for (const s of [-1, 1]) c.ellipse(cx + s * bodyW * 0.21, by - h * 0.028, bodyW * 0.16 + lw, h * 0.036 + lw * 0.6, dark)
  // 填充层
  c.ellipse(cx, bodyY, bodyW * 0.5, bodyH * 0.5, col)
  c.ellipse(cx, headY, headR, headR, col)
  for (const s of [-1, 1]) c.ellipse(cx + s * bodyW * 0.21, by - h * 0.028, bodyW * 0.16, h * 0.036, col)
  // 暗部（身体右下）
  c.ellipse(cx + bodyW * 0.14, bodyY + bodyH * 0.12, bodyW * 0.30, bodyH * 0.30, dark, 0.55)
  c.ellipse(cx + headR * 0.22, headY + headR * 0.22, headR * 0.62, headR * 0.62, dark, 0.42)
  // 高光（左上）
  c.ellipse(cx - bodyW * 0.14, bodyY - bodyH * 0.16, bodyW * 0.16, bodyH * 0.13, light, 0.75)
  c.ellipse(cx - headR * 0.32, headY - headR * 0.34, headR * 0.34, headR * 0.26, [255, 255, 255], 0.80)
  if (variant === 0) {
    // 问号（表明形象未收录）
    drawQuestion(c, cx, bodyY, h, [255, 255, 255])
  } else {
    // 元素水晶（替代问号，更像"角色"而不是"缺图"）
    c.ellipse(cx, bodyY, bodyW * 0.16, bodyH * 0.20, light, 0.95)
    c.ellipse(cx, bodyY, bodyW * 0.16, bodyH * 0.20, [255, 255, 255], 0.35)
  }
}
// 用一个简单的"?"字形（圆点 + 弧）
function drawQuestion(c, cx, cy, h, rgb) {
  const r = h * 0.075
  c.ellipse(cx, cy - r * 0.5, r * 0.52, r * 0.52, rgb, 0.95)
  c.ellipse(cx, cy + r * 0.95, r * 0.20, r * 0.20, rgb, 0.95)
}

// ---------- 参考：一张真实官方立绘 ----------
function blitScaled(c, img, cx, by, h) {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  const sw = x1 - x0 + 1, sh = y1 - y0 + 1
  const sc = h / sh
  for (let y = 0; y < Math.round(sh * sc); y++) {
    for (let x = 0; x < Math.round(sw * sc); x++) {
      const sx = x0 + Math.min(sw - 1, Math.floor(x / sc)), sy = y0 + Math.min(sh - 1, Math.floor(y / sc))
      const i = (sy * img.w + sx) * 4
      if (img.data[i + 3] < 30) continue
      c.px(cx - (sw * sc) / 2 + x, by - sh * sc + y, [img.data[i], img.data[i + 1], img.data[i + 2]], img.data[i + 3] / 255)
    }
  }
}

// ---------- 拼接 ----------
const COLORS = { 火: [255, 107, 53], 水: [63, 182, 255], 风: [94, 230, 168], 土: [216, 163, 74], 光: [255, 228, 94], 暗: [168, 107, 255], 毒: [158, 224, 74], 无: [207, 214, 228] }
const panels = [
  { lab: '① 官方立绘（参考）', draw: (c, cx, by) => { const p = path.join(ROOT, 'assets/forms/art/龙多比.png'); blitScaled(c, decodePng(fs.readFileSync(p)), cx, by, H) } },
  { lab: '② 现版占位（太扁）', draw: (c, cx, by) => drawA(c, cx, by, H, COLORS.无, '德拉科·龙') },
  { lab: '③ 官方风·问号', draw: (c, cx, by) => drawB(c, cx, by, H, COLORS.无, '德拉科·龙', 0) },
  { lab: '④ 官方风·元素水晶', draw: (c, cx, by) => drawB(c, cx, by, H, COLORS.水, '德拉科·龙', 1) },
  { lab: '⑤ 官方风·暗元素', draw: (c, cx, by) => drawB(c, cx, by, H, COLORS.暗, '修罗·岚', 1) },
  { lab: '⑥ 官方立绘（另一只）', draw: (c, cx, by) => { const p = path.join(ROOT, 'assets/forms/art/冰多比.png'); blitScaled(c, decodePng(fs.readFileSync(p)), cx, by, H) } },
]
const colW = H
const totW = PAD * 2 + panels.length * colW + (panels.length - 1) * PAD
const totH = PAD * 2 + LAB + H
const out = makeCtx(totW, totH, [16, 20, 34])
panels.forEach((p, i) => {
  const cx = PAD + i * (colW + PAD) + colW / 2
  p.draw(out, cx, PAD + LAB + H)
})
fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(totW, totH, out.d))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log('列：' + panels.map((p) => p.lab).join(' | '))
", "file_path": "_tools\_preview-form-placeholder.mjs"}

{"content": "// 占位形象预览 v2：一体化剪影（头身相连），与官方立绘并排比对风格
//
// 【v1 的问题】三个椭圆各画各的 → 头是头、身是身，中间"掐"出一段，看着像雪人。
//   官方立绘的共同点（实测）：**一个连续的外轮廓**（粗深描边）+ 内部色块/暗部/高光。
//   所以这里改成：先在"剪影掩码"上做形态学膨胀得到描边，再填色 —— 轮廓必然连续。
//
// 用法: node _tools/_preview-form-placeholder2.mjs
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const OUT = path.join(ROOT, '_tmp_test_out', 'placeholder-preview2.png')
const H = 380, PAD = 16, LAB = 26

const shade = (c, k) => c.map((v) => Math.max(0, Math.min(255, Math.round(v * k))))

// ---- 剪影 + 描边（掩码膨胀法，保证外轮廓连续）----
function silhouette(w, h, cx, by, hh) {
  const m = new Uint8Array(w * h)
  const set = (x, y) => { x = Math.round(x); y = Math.round(y); if (x >= 0 && y >= 0 && x < w && y < h) m[y * w + x] = 1 }
  const ell = (ex, ey, rx, ry) => {
    for (let y = Math.floor(ey - ry - 1); y <= Math.ceil(ey + ry + 1); y++) {
      for (let x = Math.floor(ex - rx - 1); x <= Math.ceil(ex + rx + 1); x++) {
        const u = (x - ex) / rx, v = (y - ey) / ry
        if (u * u + v * v <= 1) set(x, y)
      }
    }
  }
  // 多比身形：头（大圆）+ 身（下半圆）+ 两脚，且**头身重叠**保证连成一体
  const headR = hh * 0.225
  const headY = by - hh * 0.70
  const bodyRx = hh * 0.27, bodyRy = hh * 0.26
  const bodyY = by - hh * 0.30
  ell(cx, headY, headR, headR * 0.96)
  ell(cx, bodyY, bodyRx, bodyRy)
  ell(cx, by - hh * 0.12, bodyRx * 0.92, hh * 0.14)          // 连接头身的中段
  ell(cx - hh * 0.115, by - hh * 0.028, hh * 0.085, hh * 0.032)
  ell(cx + hh * 0.115, by - hh * 0.028, hh * 0.085, hh * 0.032)
  return m
}
function dilate(m, w, h, r) {
  const out = new Uint8Array(w * h)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (!m[y * w + x]) continue
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      if (dx * dx + dy * dy > r * r + r) continue
      const nx = x + dx, ny = y + dy
      if (nx >= 0 && ny >= 0 && nx < w && ny < h) out[ny * w + nx] = 1
    }
  }
  return out
}
// 描边 = 膨胀(剪影) - 剪影
function outlineOf(m, w, h, r) {
  const d = dilate(m, w, h, r)
  const o = new Uint8Array(w * h)
  for (let i = 0; i < w * h; i++) o[i] = d[i] && !m[i] ? 1 : 0
  return o
}

function makeCanvas(w, h, bg) {
  const d = new Uint8ClampedArray(w * h * 4)
  for (let i = 0; i < w * h; i++) { d[i * 4] = bg[0]; d[i * 4 + 1] = bg[1]; d[i * 4 + 2] = bg[2]; d[i * 4 + 3] = 255 }
  return {
    w, h, d,
    blitMask(mask, rgb, a = 1) {
      for (let i = 0; i < w * h; i++) if (mask[i]) {
        const j = i * 4
        d[j] = Math.round(rgb[0] * a + d[j] * (1 - a))
        d[j + 1] = Math.round(rgb[1] * a + d[j + 1] * (1 - a))
        d[j + 2] = Math.round(rgb[2] * a + d[j + 2] * (1 - a))
      }
    },
    ellipse(cx, cy, rx, ry, rgb, a = 1) {
      if (rx <= 0 || ry <= 0) return
      for (let y = Math.floor(cy - ry - 1); y <= Math.ceil(cy + ry + 1); y++) {
        for (let x = Math.floor(cx - rx - 1); x <= Math.ceil(cx + rx + 1); x++) {
          let ins = 0, sub = 0
          for (const dx of [-0.33, 0, 0.33]) for (const dy of [-0.33, 0, 0.33]) {
            sub++
            const u = (x + dx - cx) / rx, v = (y + dy - cy) / ry
            if (u * u + v * v <= 1) ins++
          }
          if (!ins) continue
          const xx = Math.round(x), yy = Math.round(y)
          if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue
          const j = (yy * w + xx) * 4, aa = a * ins / sub
          d[j] = Math.round(rgb[0] * aa + d[j] * (1 - aa))
          d[j + 1] = Math.round(rgb[1] * aa + d[j + 1] * (1 - aa))
          d[j + 2] = Math.round(rgb[2] * aa + d[j + 2] * (1 - aa))
        }
      }
    },
  }
}

// ---- 占位（一体化）----
function placeholder(canvas, cx, by, hh, col, name, mark) {
  const w = canvas.w, h = canvas.h
  const m = silhouette(w, h, cx, by, hh)
  const lineR = Math.max(3, Math.round(hh * 0.024))
  const line = outlineOf(m, w, h, lineR)
  const dark = shade(col, 0.45), light = shade(col, 1.28)
  // 接地影
  canvas.ellipse(cx, by + hh * 0.004, hh * 0.30, hh * 0.030, [16, 20, 30], 0.38)
  canvas.blitMask(line, [26, 16, 24])            // 粗描边（比深色填充更深，像官方那样）
  canvas.blitMask(m, col)                        // 主体色
  // 暗部（右下）：只画在剪影内部
  const inner = (mask) => { for (let i = 0; i < w * h; i++) if (!m[i]) mask[i] = 0; return mask }
  const shMask = new Uint8Array(w * h)
  ;(function () {
    const ex = cx + hh * 0.16, ey = by - hh * 0.30, rx = hh * 0.24, ry = hh * 0.30
    for (let y = Math.floor(ey - ry); y <= Math.ceil(ey + ry); y++) for (let x = Math.floor(ex - rx); x <= Math.ceil(ex + rx); x++) {
      if (x < 0 || y < 0 || x >= w || y >= h) continue
      const u = (x - ex) / rx, v = (y - ey) / ry
      if (u * u + v * v <= 1) shMask[y * w + x] = 1
    }
  })()
  canvas.blitMask(inner(shMask), dark, 0.62)
  // 高光（左上）
  const hlMask = new Uint8Array(w * h)
  ;(function () {
    const ex = cx - hh * 0.13, ey = by - hh * 0.78, rx = hh * 0.085, ry = hh * 0.065
    for (let y = Math.floor(ey - ry); y <= Math.ceil(ey + ry); y++) for (let x = Math.floor(ex - rx); x <= Math.ceil(ex + rx); x++) {
      if (x < 0 || y < 0 || x >= w || y >= h) continue
      const u = (x - ex) / rx, v = (y - ey) / ry
      if (u * u + v * v <= 1) hlMask[y * w + x] = 1
    }
  })()
  canvas.blitMask(inner(hlMask), [255, 255, 255], 0.85)
  // 标记：'?'、水晶、或什么都不加
  if (mark === '?') {
    canvas.ellipse(cx, by - hh * 0.46, hh * 0.055, hh * 0.055, [255, 255, 255], 0.9)
    canvas.ellipse(cx, by - hh * 0.26, hh * 0.022, hh * 0.022, [255, 255, 255], 0.9)
  } else if (mark === 'gem') {
    canvas.ellipse(cx, by - hh * 0.34, hh * 0.075, hh * 0.10, light, 0.95)
    canvas.ellipse(cx - hh * 0.02, by - hh * 0.36, hh * 0.032, hh * 0.042, [255, 255, 255], 0.9)
  } else if (mark === 'eye') {
    // 两只"多比式"大眼（官方多比多为纯色大眼）
    for (const s of [-1, 1]) {
      canvas.ellipse(cx + s * hh * 0.085, by - hh * 0.74, hh * 0.055, hh * 0.075, [255, 255, 255], 0.95)
      canvas.ellipse(cx + s * hh * 0.085, by - hh * 0.73, hh * 0.026, hh * 0.038, [30, 20, 30], 0.9)
    }
  }
}

function blitScaled(c, img, cx, by, hh) {
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
    if (img.data[(y * img.w + x) * 4 + 3] > 40) {
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  const sw = x1 - x0 + 1, sh = y1 - y0 + 1, sc = hh / sh
  const dw = Math.round(sw * sc), dh = Math.round(sh * sc)
  for (let y = 0; y < dh; y++) for (let x = 0; x < dw; x++) {
    const sx = x0 + Math.min(sw - 1, Math.floor(x / sc)), sy = y0 + Math.min(sh - 1, Math.floor(y / sc))
    const i = (sy * img.w + sx) * 4
    if (img.data[i + 3] < 30) continue
    const xx = Math.round(cx - dw / 2 + x), yy = Math.round(by - dh + y)
    if (xx < 0 || yy < 0 || xx >= c.w || yy >= c.h) continue
    const j = (yy * c.w + xx) * 4, a = img.data[i + 3] / 255
    c.d[j] = Math.round(img.data[i] * a + c.d[j] * (1 - a))
    c.d[j + 1] = Math.round(img.data[i + 1] * a + c.d[j + 1] * (1 - a))
    c.d[j + 2] = Math.round(img.data[i + 2] * a + c.d[j + 2] * (1 - a))
  }
}

const COLORS = { 火: [255, 107, 53], 水: [63, 182, 255], 风: [94, 230, 168], 土: [216, 163, 74], 光: [255, 228, 94], 暗: [168, 107, 255], 毒: [158, 224, 74], 无: [170, 186, 214] }
const panels = [
  { lab: '① 官方立绘', draw: (c, cx, by) => blitScaled(c, decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/龙多比.png'))), cx, by, H) },
  { lab: '② 占位·无标记', draw: (c, cx, by) => placeholder(c, cx, by, H, COLORS.无, '', '') },
  { lab: '③ 占位·大眼', draw: (c, cx, by) => placeholder(c, cx, by, H, COLORS.无, '', 'eye') },
  { lab: '④ 占位·水晶', draw: (c, cx, by) => placeholder(c, cx, by, H, COLORS.水, '', 'gem') },
  { lab: '⑤ 占位·大眼(暗)', draw: (c, cx, by) => placeholder(c, cx, by, H, COLORS.暗, '', 'eye') },
  { lab: '⑥ 官方立绘', draw: (c, cx, by) => blitScaled(c, decodePng(fs.readFileSync(path.join(ROOT, 'assets/forms/art/冰多比.png'))), cx, by, H) },
]
const colW = H
const totW = PAD * 2 + panels.length * colW + (panels.length - 1) * PAD
const totH = PAD * 2 + LAB + H
const out = makeCanvas(totW, totH, [16, 20, 34])
panels.forEach((p, i) => p.draw(out, PAD + i * (colW + PAD) + colW / 2, PAD + LAB + H))
fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, encodePng(totW, totH, out.d))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log('列：' + panels.map((p) => p.lab).join(' | '))
", "file_path": "_tools\_preview-form-placeholder2.mjs"}

{"file_path": "game\game.js", "new_string": "  // 无立绘形态的占位形象（第 55 轮）
  //
  // 【为什么要有它】用户报「好多多比是没有绘图的就完全空白」。查因：52 只里 **25 只没有立绘**，
  //   `drawFigure` 走到兜底就 `return false` → 画布上什么都不画。归档里也确实没有它们的图
  //   （按名搜 4933 张，命中的全是"大禹治水壁纸""草料房"这类同名误命中）。
  //
  // 【造型依据：对齐官方立绘的画风】实测官方立绘的共同特征：
  //   **粗深色描边**（≈3~4px @640 高）、主体色 + 一块暗部 + 一点白高光、脚下有接地影。
  //   第一版占位画成了"半透明灰圆堆"，和官方立绘放一起像两个游戏（对比图见
  //   `_tools/_preview-form-placeholder2.mjs` 的产物），所以这一版重做：
  //     · **一体化剪影**：头/身/脚用互相重叠的圆拼出来，外轮廓连续（不是几个分开的圆）；
  //     · 描边用**掩码膨胀**求出（`outline = dilate(silhouette) - silhouette`），所以任何尺寸下都匀；
  //     · 元素色主体 + 右下暗部 + 左上高光 + **多比式大眼**。
  //   ⚠️ 画的是**通用占位**，不是编造某只多比的样子 —— 官方图不存在，编就是造假。
  //   25 只里 element 大多为'无'（原表就没给），这时用中性灰蓝而不是乱猜属性色。
  function drawFormPlaceholder(cx, bottomY, height, form, t) {
    const col = (D.ELEMENT_COLOR && D.ELEMENT_COLOR[form.element]) || '#aabadd'
    const h = height
    const bob = Math.sin((t || 0) * 2.6) * h * 0.010           // 轻微呼吸，别像死图
    const headR = h * 0.225, headY = -h * 0.70
    const bodyRx = h * 0.27, bodyRy = h * 0.26, bodyY = -h * 0.30
    const hex = (c) => c
    const shade = (c, k) => {
      // 支持 '#rgb' / '#rrggbb'
      const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(c)
      if (!m) return c
      let s = m[1]
      if (s.length === 3) s = s.split('').map((x) => x + x).join('')
      const r = parseInt(s.slice(0, 2), 16), g = parseInt(s.slice(2, 4), 16), b = parseInt(s.slice(4, 6), 16)
      const f = (v) => Math.max(0, Math.min(255, Math.round(v * k)))
      return `rgb(${f(r)},${f(g)},${f(b)})`
    }
    ctx.save()
    // 接地影（与 drawGroundShadow 一致的风格）
    ctx.globalAlpha = 0.32
    ctx.fillStyle = '#0d1c30'
    ctx.beginPath()
    ctx.ellipse(cx, bottomY + h * 0.004, h * 0.30, h * 0.030, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.globalAlpha = 1
    ctx.translate(cx, bottomY + bob)
    // ① 剪影路径：头 + 身 + 连接段 + 两脚（互相重叠 → 外轮廓连续）
    const silhouette = () => {
      ctx.beginPath()
      ctx.ellipse(0, headY, headR, headR * 0.96, 0, 0, Math.PI * 2)
      ctx.ellipse(0, bodyY, bodyRx, bodyRy, 0, 0, Math.PI * 2)
      ctx.ellipse(0, -h * 0.12, bodyRx * 0.92, h * 0.14, 0, 0, Math.PI * 2)
      ctx.ellipse(-h * 0.115, -h * 0.028, h * 0.085, h * 0.032, 0, 0, Math.PI * 2)
      ctx.ellipse(h * 0.115, -h * 0.028, h * 0.085, h * 0.032, 0, 0, Math.PI * 2)
    }
    // ② 粗描边：先把剪影整体描一圈粗线，再在**上面**填色 → 得到"色块外面一圈深线"
    ctx.lineJoin = 'round'
    ctx.strokeStyle = '#2a1a24'
    ctx.lineWidth = Math.max(3, h * 0.030)
    silhouette(); ctx.stroke()
    // ③ 主体色
    ctx.fillStyle = col
    silhouette(); ctx.fill()
    // ④ 暗部（右下）：裁剪在剪影内，避免糊到描边外
    ctx.save()
    silhouette(); ctx.clip()
    ctx.fillStyle = shade(col, 0.62)
    ctx.beginPath()
    ctx.ellipse(h * 0.16, bodyY + h * 0.04, bodyRx * 0.95, bodyRy * 1.15, 0, 0, Math.PI * 2)
    ctx.fill()
    // ⑤ 高光（左上）
    ctx.fillStyle = 'rgba(255,255,255,.85)'
    ctx.beginPath()
    ctx.ellipse(-h * 0.085, headY - h * 0.055, h * 0.050, h * 0.035, -0.5, 0, Math.PI * 2)
    ctx.fill()
    ctx.restore()
    // ⑥ 多比式大眼（白底 + 深瞳），让占位一眼看着"是个多比"
    for (const s of [-1, 1]) {
      ctx.fillStyle = '#ffffff'
      ctx.beginPath()
      ctx.ellipse(s * h * 0.085, headY + h * 0.005, h * 0.055, h * 0.075, 0, 0, Math.PI * 2)
      ctx.fill()
      ctx.fillStyle = '#1e1420'
      ctx.beginPath()
      ctx.ellipse(s * h * 0.085, headY + h * 0.015, h * 0.026, h * 0.038, 0, 0, Math.PI * 2)
      ctx.fill()
    }
    // ⑦ 名字（脚下方，让玩家知道这是哪只）
    text.stroked(ctx, form.name, 0, h * 0.085,
      { size: Math.max(9, h * 0.070), align: 'center', color: '#e6ecf6', lw: Math.max(2, h * 0.014) })
    ctx.restore()
  }", "old_string": "  // 无立绘形态的占位形象（第 55 轮）
  // 造型：一个"多比剪影"（圆头 + 圆身 + 两只脚）+ 元素色描边 + 名字。
  // 全部用矢量画，所以任何显示尺寸下都清晰，不需要额外素材。
  function drawFormPlaceholder(cx, bottomY, height, form, t) {
    const col = (D.ELEMENT_COLOR && D.ELEMENT_COLOR[form.element]) || '#cfd6e4'
    const h = height
    const bodyW = h * 0.52
    const bob = Math.sin((t || 0) * 2.6) * h * 0.008          // 轻微呼吸，别像死图
    ctx.save()
    // 接地影
    ctx.globalAlpha = 0.28
    ctx.fillStyle = '#0d1c30'
    ctx.beginPath()
    ctx.ellipse(cx, bottomY - h * 0.01, bodyW * 0.52, bodyW * 0.14, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.globalAlpha = 1
    ctx.translate(cx, bottomY + bob)
    // 身体（椭圆）
    const bodyH = h * 0.46, headR = h * 0.21
    ctx.fillStyle = 'rgba(210,220,240,.30)'
    ctx.strokeStyle = col
    ctx.lineWidth = Math.max(2, h * 0.018)
    ctx.beginPath()
    ctx.ellipse(0, -bodyH * 0.62, bodyW * 0.5, bodyH * 0.5, 0, 0, Math.PI * 2)
    ctx.fill(); ctx.stroke()
    // 头（圆）
    ctx.beginPath()
    ctx.arc(0, -bodyH * 1.06 - headR * 0.35, headR, 0, Math.PI * 2)
    ctx.fill(); ctx.stroke()
    // 两只小脚
    for (const s of [-1, 1]) {
      ctx.beginPath()
      ctx.ellipse(s * bodyW * 0.22, -h * 0.03, bodyW * 0.17, h * 0.035, 0, 0, Math.PI * 2)
      ctx.fill(); ctx.stroke()
    }
    // 问号：表明"形象未收录"，比空白或编造都诚实
    text.stroked(ctx, '?', 0, -bodyH * 0.62 + h * 0.02,
      { size: Math.max(12, h * 0.16), align: 'center', color: col, lw: Math.max(2, h * 0.02) })
    // 名字（脚下方）
    text.stroked(ctx, form.name, 0, h * 0.075,
      { size: Math.max(9, h * 0.072), align: 'center', color: '#dfe6f2', lw: Math.max(2, h * 0.014) })
    ctx.restore()
  }"}

