{"content": "// 给头像加一版深蓝底（平台用透明底常显示成白/黑，不如自带底色）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'docs/avatar')
// 底色取项目 UI 的深蓝（底部操作栏渐变起点 #1d2f6e 与面板底 #0c3635 之间的观感）
const BG = [26, 38, 78]

for (const size of [512, 256, 96]) {
  const src = path.join(DIR, `吕布多比_${size}.png`)
  if (!fs.existsSync(src)) continue
  const img = decodePng(fs.readFileSync(src))
  const out = new Uint8ClampedArray(img.w * img.h * 4)
  for (let i = 0; i < img.w * img.h; i++) {
    const a = img.data[i * 4 + 3] / 255
    out[i * 4] = img.data[i * 4] * a + BG[0] * (1 - a)
    out[i * 4 + 1] = img.data[i * 4 + 1] * a + BG[1] * (1 - a)
    out[i * 4 + 2] = img.data[i * 4 + 2] * a + BG[2] * (1 - a)
    out[i * 4 + 3] = 255
  }
  const dst = path.join(DIR, `吕布多比_${size}_深蓝底.png`)
  fs.writeFileSync(dst, encodePng(img.w, img.h, out))
  console.log(`  ${size}×${size}  ${path.relative(ROOT, dst)}`)
}
