{"content": "// 用"已有的 17 个已知名字的图标"当锚点，在新素材里找出同一个图标 → 建立映射
//
// 【思路】项目里 `assets/skills/skill_icon_*.png` 有 17 张，其中 7 张**有名字**
//   （火球/火雨/嗜血/多重火球/地之咆哮/坚韧/大地之怒 —— 见 assets/skills/index.json）。
//   它们和新素材**同源**（都来自官方「图鉴3.1技能ICON」），所以同一张图在新素材里
//   应该能找到**近似相同**的像素块。找到之后，就说明"新素材的编号 ↔ 技能名"能对上，
//   可以照同样的排布推出其余图标的名字。
//
// 判据：缩到 32×32 后比平均色差；差值最小且明显小于次小值才算锚定成功（避免硬凑）。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const KNOWN_DIR = path.join(ROOT, 'assets/skills')
const NEW_DIR = path.join(ROOT, '_tmp_test_out/skill-icons-sliced')

const idx = JSON.parse(fs.readFileSync(path.join(NEW_DIR, 'index.json'), 'utf8'))
const newIcons = []
for (const s of idx.sheets) for (const ic of s.icons) {
  const p = path.join(NEW_DIR, ic.name)
  if (fs.existsSync(p)) newIcons.push({ el: s.element, ...ic, img: decodePng(fs.readFileSync(p)) })
}
console.log(`新素材图标 ${newIcons.length} 个`)

const norm = (img, S = 32) => {
  const sc = img.w / S, sy = img.h / S
  const out = new Float32Array(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x * sc)), syy = Math.min(img.h - 1, Math.floor(y * sy))
    const i = (syy * img.w + sx) * 4, o = (y * S + x) * 4
    out[o] = img.data[i]; out[o + 1] = img.data[i + 1]; out[o + 2] = img.data[i + 2]; out[o + 3] = img.data[i + 3]
  }
  return out
}
const dist = (a, b) => {
  let s = 0, n = 0
  for (let i = 0; i < a.length; i += 4) {
    if (a[i + 3] < 128 && b[i + 3] < 128) continue
    s += Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2])
    n++
  }
  return n ? s / n / 3 : 999
}

// 已知名字的图标
const known = []
const meta = JSON.parse(fs.readFileSync(path.join(KNOWN_DIR, 'index.json'), 'utf8'))
for (const it of meta.icons) {
  if (!it.name) continue
  const p = path.join(ROOT, it.file)
  if (!fs.existsSync(p)) continue
  known.push({ id: it.id, name: it.name, img: decodePng(fs.readFileSync(p)) })
}
console.log(`已知名字的图标 ${known.length} 个：${known.map((k) => k.name).join('、')}\n`)

console.log('锚定结果（新素材里的哪一张 = 已知技能）：')
const anchors = []
for (const k of known) {
  const A = norm(k.img)
  const scored = newIcons.map((n) => ({ n, d: dist(A, norm(n.img)) })).sort((x, y) => x.d - y.d)
  const best = scored[0], second = scored[1]
  const confident = best.d < 12 && (second.d - best.d) > 2
  anchors.push({ name: k.name, hit: best, second, confident })
  console.log(`  ${k.name.padEnd(6)} → ${confident ? '✓' : '?'} ${best.n.el}_${String(best.n.idx).padStart(2, '0')}  色差 ${best.d.toFixed(2)}（次近 ${second.d.toFixed(2)} ${second.n.el}_${String(second.n.idx).padStart(2, '0')}）`)
}

const good = anchors.filter((a) => a.confident)
console.log(`\n可信锚点 ${good.length} / ${known.length}`)
if (good.length) {
  console.log('\n可信的对应关系（可用于推广到其余图标）：')
  for (const a of good) console.log(`  ${a.hit.n.el} 第 ${a.hit.n.idx} 个  =  「${a.name}」`)
}
", "file_path": "_tools\match-skill-icons.mjs"}

{"content": "// 对照：每个元素组的"图标数"与"技能数"，判断能否一一对应
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const cat = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-catalog.json'), 'utf8'))
const sliced = JSON.parse(fs.readFileSync(path.join(ROOT, '_tmp_test_out/skill-icons-sliced/index.json'), 'utf8'))

const iconCount = {}
for (const s of sliced.sheets) iconCount[s.element] = s.count
const skillCount = {}
for (const [el, list] of Object.entries(cat.byElement)) skillCount[el] = list.length

// 映射表：素材名 → 技能分类名
const MAP = {
  火系: '火', 水系: '水', 土系: '土', 风系: '风', 光系: '光', 暗系: '暗', 毒系: '毒',
  无属性系: '无', 宠物技能: '（宠物，无对应技能分类）',
}
console.log('素材名        图标数   对应技能数   差   结论')
let totalIcon = 0, totalSkill = 0
for (const [sheet, el] of Object.entries(MAP)) {
  const ic = iconCount[sheet]
  if (ic === undefined) continue
  totalIcon += ic
  const sk = skillCount[el] || 0
  if (sk) totalSkill += sk
  const d = ic - sk
  const verdict = el.startsWith('（') ? '独立分类'
    : d === 0 ? '**完全相等 → 可按顺序一一对应**'
      : d > 0 ? `图标多 ${d} 个（素材里有清单外的技能）`
        : `技能多 ${-d} 个（缺图标）`
  console.log(`${sheet.padEnd(12)} ${String(ic).padStart(4)}   ${String(sk).padStart(8)}   ${String(d).padStart(4)}   ${verdict}`)
}
console.log(`\n合计：图标 ${totalIcon} / 有对应关系的技能 ${totalSkill}`)
console.log('\n各系技能名单（按用户文本顺序）：')
for (const [el, list] of Object.entries(cat.byElement)) {
  console.log(`  ${el}(${list.length})：${list.join('、')}`)
}
