{"content": "// 校准：用"已有名字的 7 张图标"确定各元素表的**行结构**，并算出锚点在表内的行/列
//
// 【为什么要行结构】现有 7 张有名字的图标来自同一张官方图鉴，`index.json` 记了来源
//   （如「图鉴 y=517 第0列」）。同一元素在同一 y 上的图标属于**同一行**。
//   而用户提供的 8 张表是按元素切开的 —— 如果两者的行序一致，
//   就能用锚点把"表内行 → 图鉴 y"对应起来，进而给整行图标定名。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const KNOWN = path.join(ROOT, 'assets/skills')
const NEW = path.join(ROOT, '_tmp_test_out/skill-icons-sliced')

const meta = JSON.parse(fs.readFileSync(path.join(KNOWN, 'index.json'), 'utf8'))
const sliced = JSON.parse(fs.readFileSync(path.join(NEW, 'index.json'), 'utf8'))

// 新素材：按元素 + 行序整理
const newByEl = {}
for (const s of sliced.sheets) {
  newByEl[s.element] = s
}
console.log('新素材各表的行结构（y 中心聚类）：')
for (const [el, s] of Object.entries(newByEl)) {
  // 用 y 中心重新分行
  const items = s.icons.slice().sort((a, b) => a.y - b.y || a.x - b.x)
  const rows = []
  for (const it of items) {
    const cy = it.y + it.h / 2
    let r = rows.find((rr) => Math.abs(rr.cy - cy) < Math.max(20, it.h * 0.5))
    if (!r) { r = { cy, n: 0 }; rows.push(r) }
    r.n++
  }
  rows.sort((a, b) => a.cy - b.cy)
  console.log(`  ${el.padEnd(5)} 共 ${s.count} 个，分 ${rows.length} 行：[${rows.map((r) => r.n).join(', ')}]`)
}

// 锚点：现有已知名字的图标 vs 新素材（同元素内找最像的）
const norm = (img, S = 48) => {
  const out = new Float32Array(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x * img.w / S)), sy = Math.min(img.h - 1, Math.floor(y * img.h / S))
    const i = (sy * img.w + sx) * 4, o = (y * S + x) * 4
    out[o] = img.data[i]; out[o + 1] = img.data[i + 1]; out[o + 2] = img.data[i + 2]; out[o + 3] = img.data[i + 3]
  }
  return out
}
const dist = (a, b) => {
  let s = 0, n = 0
  for (let i = 0; i < a.length; i += 4) {
    if (a[i + 3] < 128 && b[i + 3] < 128) continue
    s += Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2])
    n++
  }
  return n ? s / n / 3 : 999
}
// 元素 → 素材表名
const EL2SHEET = { 火: '火系', 水: '水系', 土: '土系', 风: '风系', 光: '光系', 暗: '暗系', 毒: '毒系', 无: '无属性系' }

console.log('\n锚点定位（已知技能 → 新素材里的位置）：')
for (const it of meta.icons) {
  if (!it.name) continue
  const el = /火球|嗜血/.test(it.name) ? '火' : /地之咆哮|坚韧|大地之怒/.test(it.name) ? '土' : null
  if (!el) { console.log(`  ${it.name}: 未归类，跳过`); continue }
  const sheet = newByEl[EL2SHEET[el]]
  if (!sheet) continue
  const p = path.join(ROOT, it.file)
  if (!fs.existsSync(p)) continue
  const A = norm(decodePng(fs.readFileSync(p)))
  const scored = sheet.icons.map((ic) => {
    const f = path.join(NEW, ic.name)
    return { ic, d: dist(A, norm(decodePng(fs.readFileSync(f)))) }
  }).sort((x, y) => x.d - y.d)
  const b = scored[0]
  console.log(`  ${it.name.padEnd(6)} (${it.from || '原图鉴'})  →  ${b.ic.name}  色差 ${b.d.toFixed(1)}  [行内 y=${b.ic.y}]`)
}
", "file_path": "_tools\calibrate-skill-icons.mjs"}

