{"content": "// 探测 Ruffle（Flash 模拟器）的下载源可达性与速度
// Ruffle 能把 SWF 渲染成 PNG 帧，正好用来吃归档里的纯矢量素材
import https from 'node:https'

const URLS = [
  ['github release', 'https://github.com/ruffle-rs/ruffle/releases/latest'],
  ['ruffle nightly (windows x64)', 'https://github.com/ruffle-rs/ruffle/releases/download/nightly-2024-01-01/ruffle-nightly-2024_01_01-windows-x86_64.zip'],
  ['gh-proxy 镜像测试', 'https://gh-proxy.com/https://github.com/ruffle-rs/ruffle/releases'],
]

function probe(url, label, depth = 0) {
  return new Promise((resolve) => {
    const t0 = Date.now()
    const req = https.get(url, { headers: { 'User-Agent': 'node', Range: 'bytes=0-262143' }, timeout: 20000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth < 5) {
        res.resume()
        return resolve(probe(new global.URL(res.headers.location, url).href, label, depth + 1))
      }
      let got = 0
      res.on('data', (c) => { got += c.length })
      res.on('end', () => resolve({ label, status: res.statusCode, got, ms: Date.now() - t0, final: url }))
    })
    req.on('error', (e) => resolve({ label, err: e.message }))
    req.on('timeout', () => { req.destroy(); resolve({ label, err: '超时' }) })
  })
}

for (const [label, u] of URLS) {
  const r = await probe(u, label)
  if (r.err) { console.log(`✗ ${label}: ${r.err}`); continue }
  const kbs = r.ms ? (r.got / 1024 / (r.ms / 1000)) : 0
  console.log(`${r.status < 400 ? '✓' : '✗'} ${label}: HTTP ${r.status}  ${(r.got / 1024).toFixed(0)}KB / ${(r.ms / 1000).toFixed(1)}s → ${kbs.toFixed(0)} KB/s`)
}
", "file_path": "_tools\_probe-ruffle.mjs"}

{"content": "// 从 GitHub API 查 Ruffle 最新 nightly 的 Windows 资产名（拼接资产 URL 需要精确文件名）
import https from 'node:https'

function get(url, depth = 0) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'node', Accept: 'application/vnd.github+json' }, timeout: 30000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth < 5) {
        res.resume()
        return resolve(get(new global.URL(res.headers.location, url).href, depth + 1))
      }
      let b = ''
      res.on('data', (c) => { b += c })
      res.on('end', () => resolve({ status: res.statusCode, body: b }))
    }).on('error', reject).on('timeout', function () { this.destroy(new Error('超时')) })
  })
}

const r = await get('https://api.github.com/repos/ruffle-rs/ruffle/releases?per_page=3')
console.log(`API HTTP ${r.status}`)
if (r.status !== 200) { console.log(r.body.slice(0, 300)); process.exit(1) }
const rels = JSON.parse(r.body)
for (const rel of rels) {
  console.log(`\n=== ${rel.tag_name}  (${rel.published_at}) ===`)
  const win = (rel.assets || []).filter((a) => /windows/i.test(a.name))
  for (const a of win) console.log(`  ${a.name}  ${(a.size / 1048576).toFixed(1)}MB\n     ${a.browser_download_url}`)
  if (!win.length) console.log('  （没有 windows 资产）')
}
