{"content": "// SWF 标签盘点：判断"自己写渲染器"是否现实
//   · 形状(DefineShape) / 精灵(DefineSprite) / 位图(DefineBits*) 各多少个
//   · 帧数、是否有 morph/字体/脚本
// 标签号参考 SWF 规范（部分常用）：
//   0 End 1 ShowFrame 2 DefineShape 22 DefineShape2 32 DefineShape3 83 DefineShape4
//   4 PlaceObject 26 PlaceObject2 70 PlaceObject3
//   39 DefineSprite 43 FrameLabel
//   6 DefineBits 21 DefineBitsJPEG2 35 DefineBitsJPEG3 20 DefineBitsLossless 36 DefineBitsLossless2
//   34 DefineButton2 7 DefineButton
//   46 DefineMorphShape 84 DefineMorphShape2
//   48 DefineFont2 75 DefineFont3 10 DefineFont
//   12 DoAction 59 DoInitAction 76 ExportAssets 56 ExportAssets(ExportAssets=56)
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'

const DIR = path.resolve('多克多比专区资料素材/动画视频/多比战斗动画')
const NAMES = {
  0: 'End', 1: 'ShowFrame', 2: 'DefineShape', 22: 'DefineShape2', 32: 'DefineShape3', 83: 'DefineShape4',
  4: 'PlaceObject', 26: 'PlaceObject2', 70: 'PlaceObject3', 5: 'RemoveObject', 28: 'RemoveObject2',
  39: 'DefineSprite', 43: 'FrameLabel', 9: 'SetBackgroundColor',
  6: 'DefineBits', 21: 'DefineBitsJPEG2', 35: 'DefineBitsJPEG3', 20: 'DefineBitsLossless', 36: 'DefineBitsLossless2',
  7: 'DefineButton', 34: 'DefineButton2', 46: 'DefineMorphShape', 84: 'DefineMorphShape2',
  10: 'DefineFont', 48: 'DefineFont2', 75: 'DefineFont3', 11: 'DefineText', 33: 'DefineText2',
  12: 'DoAction', 59: 'DoInitAction', 56: 'ExportAssets', 76: 'SymbolClass', 82: 'DoABC',
  37: 'DefineEditText', 60: 'DefineVideoStream', 24: 'Protect',
}

function body(buf) {
  const sig = buf.toString('ascii', 0, 3)
  if (sig === 'FWS') return buf.subarray(8)
  if (sig === 'CWS') return zlib.inflateSync(buf.subarray(8))
  return buf
}
// 解析矩形（SWF 的 RECT 是变长位域）
function readRect(b, p) {
  const nbits = b[p] >> 3
  const total = 5 + nbits * 4
  const bytes = Math.ceil(total / 8)
  let bits = ''
  for (let i = 0; i < bytes; i++) bits += b[p + i].toString(2).padStart(8, '0')
  const rd = (o) => parseInt(bits.slice(o, o + nbits), 2)
  const xmin = rd(5), xmax = rd(5 + nbits), ymin = rd(5 + nbits * 2), ymax = rd(5 + nbits * 3)
  return { xmin, xmax, ymin, ymax, next: p + bytes, nbits }
}

for (const f of fs.readdirSync(DIR).filter((x) => /\.swf$/i.test(x))) {
  const buf = fs.readFileSync(path.join(DIR, f))
  const b = body(buf)
  const ver = b[3]
  const r = readRect(b, 8)
  // 跳过 frameRate(2) + frameCount(2)
  let p = r.next + 4
  const counts = {}
  let shapeDetail = 0
  let spriteFrames = 0
  while (p + 2 <= b.length) {
    const tagLen = b.readUInt16LE(p); p += 2
    const code = tagLen >> 6
    let len = tagLen & 0x3f
    if (len === 0x3f) { len = b.readUInt32LE(p); p += 4 }
    if (code === 0) break
    const nm = NAMES[code] || ('tag' + code)
    counts[nm] = (counts[nm] || 0) + 1
    if (code === 1) spriteFrames++
    p += len
    if (p > b.length) break
  }
  const w = (r.xmax - r.xmin) / 20, h = (r.ymax - r.ymin) / 20
  const shapes = (counts.DefineShape || 0) + (counts.DefineShape2 || 0) + (counts.DefineShape3 || 0) + (counts.DefineShape4 || 0)
  const sprites = counts.DefineSprite || 0
  const bits = (counts.DefineBits || 0) + (counts.DefineBitsJPEG2 || 0) + (counts.DefineBitsJPEG3 || 0) + (counts.DefineBitsLossless || 0) + (counts.DefineBitsLossless2 || 0)
  const morph = (counts.DefineMorphShape || 0) + (counts.DefineMorphShape2 || 0)
  console.log(`\n=== ${f}  SWF v${ver}  ${w.toFixed(0)}×${h.toFixed(0)}px  主时间轴 ${b.readUInt16LE(r.next + 2)} 帧 ===`)
  console.log(`  形状 ${shapes} · 精灵 ${sprites} · 位图 ${bits} · 变形 ${morph} · 按钮 ${(counts.DefineButton || 0) + (counts.DefineButton2 || 0)}`)
  console.log(`  脚本 DoAction ${counts.DoAction || 0} · DoABC ${counts.DoABC || 0} · 字体 ${(counts.DefineFont || 0) + (counts.DefineFont2 || 0) + (counts.DefineFont3 || 0)}`)
  const top = Object.entries(counts).sort((a, c) => c[1] - a[1]).slice(0, 8)
  console.log(`  标签 top: ${top.map(([k, v]) => `${k}×${v}`).join('  ')}`)
  console.log(`  → 自写渲染器可行性：${shapes > 0 && morph === 0 ? '**可行**（只有基本形状）' : morph > 0 ? '困难（含变形形状）' : bits > 0 ? '可行（位图为主）' : '未知'}`)
}
