{"content": "// 从 SWF 抽出的动作帧里挑"站姿"帧（用于当形态立绘）
//
// 【背景】`extract-swf-frames.mjs` 从 `多比战斗动画/*.swf` 抽出 437 张动作帧
//   （水多比 104 / 火多比 184 / 超级多比 126 / 普通多比 14 / 新版 6 / 新手区 3）。
//   这些帧**带透明通道**（DefineBitsJPEG3 的 alpha），但很多帧带技能光效（尖刺、闪电），
//   当立绘用不合适 —— 所以要挑"干净站姿"帧。
//
// 判据（客观、可复核）：
//   · **不含大面积特效**：特效是灰白/黄色的半透明尖刺，特征是"低饱和+高亮"像素占比高；
//     站姿帧这类像素少。
//   · **主体居中、脚底接近画布底**：站姿帧通常是整套动作里的"普通姿态"。
//   · 主体宽度占比适中（特效会让包围盒撑满画布）。
//
// 产出：每组挑出的候选帧复制到 `_tmp_test_out/form-art-candidates/<形态>/`，并出对比图
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRCDIR = path.join(ROOT, '_tmp_test_out/swf-frames')
const OUTROOT = path.join(ROOT, '_tmp_test_out/form-art-candidates')

// JPEG 解码：项目没有 jpeg 解码器，这里用 python(Pillow) 转成 PNG 再分析
// —— 走"python 写文件"的老路子（沙箱禁止管道抓输出）
import { execFileSync } from 'node:child_process'
const PY = path.join(ROOT, '_tools', 'py', 'python.exe')

const GROUPS = [
  { tag: '水多比', form: '水多比' },
  { tag: '火多比', form: '火多比' },
  { tag: '超级多比', form: '超级多比' },
  { tag: '普通多比战斗', form: '（通用，暂不接入）' },
]

fs.mkdirSync(OUTROOT, { recursive: true })
const script = path.join(ROOT, '_tmp_test_out', '_pick_idle.py')
const outJson = path.join(ROOT, '_tmp_test_out', 'idle-pick.json')
const py = `
import os, json, glob
from PIL import Image
import numpy as np

SRC = r"${SRCDIR.replace(/\\/g, '/')}"
OUT = r"${OUTROOT.replace(/\\/g, '/')}"
groups = ${JSON.stringify(GROUPS.map((g) => g.tag))}
report = {}
for tag in groups:
    files = sorted(glob.glob(os.path.join(SRC, tag + "*.jpg")))
    rows = []
    for f in files:
        try:
            im = Image.open(f).convert("RGBA")
        except Exception:
            continue
        a = np.asarray(im).astype(np.float32)
        alpha = a[:, :, 3]
        ys, xs = np.where(alpha > 40)
        if len(ys) < 500:
            continue
        h, w = alpha.shape
        bw = xs.max() - xs.min() + 1
        bh = ys.max() - ys.min() + 1
        # "特效"判据：低饱和且高亮（灰白尖刺/黄闪电）的像素占比
        rgb = a[:, :, :3]
        lum = rgb.mean(axis=2)
        sat = rgb.max(axis=2) - rgb.min(axis=2)
        opaque = alpha > 40
        fx = ((sat < 50) & (lum > 170) & opaque).sum() / max(1, opaque.sum())
        rows.append(dict(file=os.path.basename(f), w=w, h=h, bw=int(bw), bh=int(bh),
                         fx=float(fx), cover=float(opaque.sum()) / (w * h),
                         foot=float(ys.max()) / h))
    rows.sort(key=lambda r: (r["fx"], -r["cover"]))
    report[tag] = rows
    print("%s: %d 帧，fx 最小的 5 帧：" % (tag, len(rows)))
    for r in rows[:5]:
        print("   %s  %dx%d  主体 %dx%d  fx=%.3f  cover=%.2f  脚底=%.2f" %
              (r["file"], r["w"], r["h"], r["bw"], r["bh"], r["fx"], r["cover"], r["foot"]))
with open(r"${outJson.replace(/\\/g, '/')}", "w", encoding="utf-8") as fp:
    json.dump(report, fp, ensure_ascii=False)
print("done")
`
fs.writeFileSync(script, py, 'utf8')
const env = { ...process.env, TMP: path.join(ROOT, '_tmp_test_out'), TEMP: path.join(ROOT, '_tmp_test_out') }
execFileSync(PY, [script], { stdio: 'inherit', cwd: ROOT, env })
console.log(`\n分析结果已写出 ${path.relative(ROOT, outJson)}`)
", "file_path": "_tools\pick-idle-frames.mjs"}

{"content": "// 从 SWF 抽"带 alpha 的完整动作帧"（DefineBitsJPEG3 = JPEG + zlib(alpha)）
//
// 【为什么之前抽的不能用】`extract-swf-frames.mjs` 只拿了 JPEG 部分，
//   而 `DefineBitsJPEG3` 的**透明度存在 JPEG 之后的一段 zlib 数据里** ——
//   丢掉它 → 背景变纯黑，当立绘用不了（实测 alpha 全 255）。
//
// 做法：JPEG 写出临时文件 → 用 Pillow 解码 → 把解出的 alpha 合成上去 → 存 PNG。
//   （项目里没有 JPEG 解码器，Pillow 是最省事的路；走"python 写文件"的老套路）
//
// 用法: node _tools/extract-swf-frames-alpha.mjs <swf|目录> <输出目录> [最小尺寸]
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const SRC = process.argv[2]
const OUT = path.join(ROOT, process.argv[3] || '_tmp_test_out/swf-frames-alpha')
const MIN = Number(process.argv[4] || 64)
if (!SRC) { console.log('用法: node _tools/extract-swf-frames-alpha.mjs <swf|目录> <输出目录> [最小尺寸]'); process.exit(1) }

const PY = path.join(ROOT, '_tools', 'py', 'python.exe')
const TMP = path.join(ROOT, '_tmp_test_out', '_swfalpha')
fs.mkdirSync(TMP, { recursive: true })
fs.mkdirSync(OUT, { recursive: true })

function body(buf) {
  const sig = buf.toString('ascii', 0, 3)
  if (sig === 'FWS') return buf.subarray(8)
  if (sig === 'CWS') return zlib.inflateSync(buf.subarray(8))
  throw new Error('未知签名 ' + sig)
}
function readRect(b, p) {
  const nbits = b[p] >> 3
  const bytes = Math.ceil((5 + nbits * 4) / 8)
  let bits = ''
  for (let i = 0; i < bytes; i++) bits += b[p + i].toString(2).padStart(8, '0')
  const rd = (o) => parseInt(bits.slice(o, o + nbits), 2)
  return { next: p + bytes }
}
function jpegSize(buf) {
  let i = 2
  while (i < buf.length - 9) {
    if (buf[i] !== 0xFF) { i++; continue }
    const m = buf[i + 1]
    if (m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) return { h: buf.readUInt16BE(i + 5), w: buf.readUInt16BE(i + 7) }
    i += 2 + buf.readUInt16BE(i + 2)
  }
  return null
}

const files = []
const st = fs.statSync(SRC)
if (st.isDirectory()) {
  for (const e of fs.readdirSync(SRC, { withFileTypes: true })) {
    if (e.isFile() && /\.swf$/i.test(e.name)) files.push(path.join(SRC, e.name))
  }
} else files.push(SRC)

// 先把所有帧的 JPEG 与 alpha 落盘，再交给 python 批量合成
const jobs = []
for (const file of files) {
  const base = path.basename(file, path.extname(file))
  let b
  try { b = body(fs.readFileSync(file)) } catch (e) { console.log(`✗ ${base}: ${e.message}`); continue }
  let p = readRect(b, 8).next + 4
  let n = 0
  while (p + 2 <= b.length) {
    const tagLen = b.readUInt16LE(p); p += 2
    const code = tagLen >> 6
    let len = tagLen & 0x3f
    if (len === 0x3f) { len = b.readUInt32LE(p); p += 4 }
    if (code === 0) break
    if (code === 35 && len > 8) {
      const payload = b.subarray(p, p + len)
      const alphaOff = payload.readUInt32LE(2)
      const jpeg = payload.subarray(6, 6 + alphaOff)
      const alphaZ = payload.subarray(6 + alphaOff)
      const sz = jpeg[0] === 0xFF && jpeg[1] === 0xD8 ? jpegSize(jpeg) : null
      if (sz && sz.w >= MIN && sz.h >= MIN) {
        n++
        const stem = `${base}_${String(n).padStart(3, '0')}`
        fs.writeFileSync(path.join(TMP, stem + '.jpg'), jpeg)
        if (alphaZ.length > 8) fs.writeFileSync(path.join(TMP, stem + '.z'), alphaZ)
        jobs.push({ stem, w: sz.w, h: sz.h, hasAlpha: alphaZ.length > 8 })
      }
    }
    p += len
    if (p > b.length) break
  }
  console.log(`${base}: 待合成 ${n} 帧`)
}
console.log(`\n合计 ${jobs.length} 帧 → 交给 Pillow 合成 alpha`)

const manifest = path.join(TMP, 'manifest.json')
fs.writeFileSync(manifest, JSON.stringify({ tmp: TMP.replace(/\\/g, '/'), out: OUT.replace(/\\/g, '/'), jobs }, null, 1))
const pyPath = path.join(TMP, 'compose.py')
fs.writeFileSync(pyPath, `
import json, os, zlib, struct
from PIL import Image
import numpy as np

m = json.load(open(r"${manifest.replace(/\\\\/g, '/')}", encoding="utf-8"))
ok = 0
for j in m["jobs"]:
    stem = j["stem"]
    jp = os.path.join(m["tmp"], stem + ".jpg")
    zp = os.path.join(m["tmp"], stem + ".z")
    try:
        im = Image.open(jp).convert("RGBA")
    except Exception:
        continue
    if os.path.exists(zp) and j["hasAlpha"]:
        try:
            raw = zlib.decompress(open(zp, "rb").read())
            # SWF 的 alpha 位图：zlib 解出后是 PGM 风格（格式字节 + w + h + 数据），
            # 但 DefineBitsJPEG3 的 alpha 是**裸 zlib 压缩的 w*h 字节**
            if len(raw) == j["w"] * j["h"]:
                al = np.frombuffer(raw, dtype=np.uint8).reshape(j["h"], j["w"])
                arr = np.asarray(im).copy()
                arr[:, :, 3] = al
                im = Image.fromarray(arr, "RGBA")
            else:
                # 有些是 5 字节头（fmt + w + h）
                if len(raw) >= 5:
                    w2 = struct.unpack(">H", raw[1:3])[0]
                    h2 = struct.unpack(">H", raw[3:5])[0]
                    dat = raw[5:]
                    if w2 * h2 <= len(dat):
                        al = np.frombuffer(dat[: w2 * h2], dtype=np.uint8).reshape(h2, w2)
                        if (w2, h2) != (j["w"], j["h"]):
                            al = np.asarray(Image.fromarray(al, "L").resize((j["w"], j["h"])))
                        arr = np.asarray(im).copy()
                        arr[:, :, 3] = al
                        im = Image.fromarray(arr, "RGBA")
        except Exception as e:
            pass
    out = os.path.join(m["out"], stem + ".png")
    im.save(out)
    ok += 1
print("合成 %d / %d" % (ok, len(m["jobs"])))
`, 'utf8')

const env = { ...process.env, TMP, TEMP: TMP }
execFileSync(PY, [pyPath], { stdio: 'inherit', cwd: ROOT, env })
console.log(`\n输出目录 ${path.relative(ROOT, OUT)}`)
", "file_path": "_tools\extract-swf-frames-alpha.mjs"}

{"content": "// 从带 alpha 的动作帧里挑"干净站姿"帧 → 做成形态立绘并接入游戏
//
// 【判据】特效（灰色尖刺 / 黄色闪电）的特征是**低饱和 + 中高亮度**的大块区域。
//   站姿帧这类像素很少。同时要求：主体够大、脚底接近画布底（站姿是踩地的）。
//
// 产出：assets/forms/art/<形态名>.png（写回前先备份）
// 用法: node _tools/install-swf-form-art.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRCDIR = path.join(ROOT, '_tmp_test_out/swf-frames-alpha')
const ARTDIR = path.join(ROOT, 'assets/forms/art')
const BAK = path.join(ROOT, '_tmp_test_out/art-before-swf')
const DRY = process.argv.includes('--dry')
const PY = path.join(ROOT, '_tools', 'py', 'python.exe')
const TMP = path.join(ROOT, '_tmp_test_out')

// 待接入：SWF 前缀 → 形态名
const GROUPS = [
  { tag: '水多比-战斗', form: '水多比' },
  { tag: '火多比-战斗', form: '火多比' },
  { tag: '超级多比-战斗', form: '超级克罗 多比' },
]

fs.mkdirSync(TMP, { recursive: true })
fs.mkdirSync(BAK, { recursive: true })

const outJson = path.join(TMP, 'idle-candidates.json')
const pyPath = path.join(TMP, '_pick_idle2.py')
const py = `
import os, json, glob
from PIL import Image
import numpy as np

SRC = r"${SRCDIR.replace(/\\/g, '/')}"
groups = ${JSON.stringify(GROUPS)}
report = {}
for g in groups:
    files = sorted(glob.glob(os.path.join(SRC, g["tag"] + "*.png")))
    rows = []
    for f in files:
        try:
            im = Image.open(f).convert("RGBA")
        except Exception:
            continue
        a = np.asarray(im).astype(np.float32)
        al = a[:, :, 3]
        ys, xs = np.where(al > 40)
        if len(ys) < 800:
            continue
        rgb = a[:, :, :3]
        lum = rgb.mean(axis=2)
        sat = rgb.max(axis=2) - rgb.min(axis=2)
        # 特效：低饱和 + 中高亮（灰尖刺 ~ (150,150,150)，黄闪电 sat 高但 lum 很高）
        fx = (((sat < 45) & (lum > 140)) | ((lum > 215) & (sat < 120)))
        fxRatio = float((fx & (al > 40)).sum()) / float((al > 40).sum())
        bw = int(xs.max() - xs.min() + 1)
        bh = int(ys.max() - ys.min() + 1)
        # 主体占画布比例：特效会把包围盒撑满，站姿不会
        fill = float((al > 40).sum()) / float(bw * bh)
        rows.append(dict(file=os.path.basename(f), w=im.size[0], h=im.size[1],
                         bw=bw, bh=bh, fx=fxRatio, fill=fill,
                         foot=float(ys.max()) / im.size[1]))
    rows.sort(key=lambda r: (r["fx"], -r["fill"]))
    report[g["form"]] = rows
    print("%s: %d 帧" % (g["form"], len(rows)))
    for r in rows[:4]:
        print("   %-28s %dx%d 主体%dx%d fx=%.3f fill=%.2f 脚底=%.2f" %
              (r["file"], r["w"], r["h"], r["bw"], r["bh"], r["fx"], r["fill"], r["foot"]))
json.dump(report, open(r"${outJson.replace(/\\/g, '/')}", "w", encoding="utf-8"), ensure_ascii=False)
`
fs.writeFileSync(pyPath, py, 'utf8')
const env = { ...process.env, TMP, TEMP: TMP }
execFileSync(PY, [pyPath], { stdio: 'inherit', cwd: ROOT, env })

const rep = JSON.parse(fs.readFileSync(outJson, 'utf8'))
console.log('\n=== 安装为形态立绘 ===')
for (const g of GROUPS) {
  const rows = rep[g.form] || []
  if (!rows.length) { console.log(`  ✗ ${g.form}: 没有可用帧`); continue }
  const pick = rows[0]
  const src = path.join(SRCDIR, pick.file)
  const dst = path.join(ARTDIR, g.form + '.png')
  const bak = path.join(BAK, g.form + '.png')
  if (fs.existsSync(dst) && !fs.existsSync(bak)) fs.copyFileSync(dst, bak)
  if (!DRY) {
    // 转成项目统一格式（PNG），并放大到 640 高（与其它立绘一致的有效高目标）
    const img = decodePng(fs.readFileSync(src))
    const sc = 640 / pick.bh
    const dw = Math.max(1, Math.round(pick.bw * sc))
    const out = new Uint8ClampedArray(dw * 640 * 4)
    for (let y = 0; y < 640; y++) {
      for (let x = 0; x < dw; x++) {
        const sx = Math.min(img.w - 1, Math.round((x + 0.5) / sc)), sy = Math.min(img.h - 1, Math.round((y + 0.5) / sc))
        const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
        out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
      }
    }
    fs.writeFileSync(dst, encodePng(dw, 640, out))
  }
  console.log(`  ${DRY ? '(dry) ' : ''}${g.form}  ←  ${pick.file}  fx=${pick.fx.toFixed(3)}  →  ${path.relative(ROOT, dst)}`)
}
console.log(`\n原图备份目录 ${path.relative(ROOT, BAK)}`)
", "file_path": "_tools\install-swf-form-art.mjs"}

{"content": "// 从带 alpha 的动作帧里挑"干净站姿"帧 → 做成形态立绘并接入游戏（第 2 版判据）
//
// 【第 1 版为什么挑错】用 `alpha>40` 当"有内容"，结果挑中了**模糊特效帧**（渐变雾）——
//   那种帧的 alpha 广泛分布在 40~150，几乎没有实心像素。
// 【第 2 版判据（都实测过）】
//   · **实心占比**（alpha>200 的像素 / 画布）：角色帧 0.24~0.28，雾帧≈0 → 必须够大
//   · **边缘强度**（alpha 梯度和）：角色帧 5~9（有清晰轮廓），雾帧低
//   · **饱和度**（实心像素的平均色差）：角色帧 98~165（有颜色），雾帧低
//   · 站姿还要**脚底靠下**（踩地），排除腾空帧
//
// 用法: node _tools/install-swf-form-art.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRCDIR = path.join(ROOT, '_tmp_test_out/swf-frames-alpha')
const ARTDIR = path.join(ROOT, 'assets/forms/art')
const BAK = path.join(ROOT, '_tmp_test_out/art-before-swf')
const DRY = process.argv.includes('--dry')
const PY = path.join(ROOT, '_tools', 'py', 'python.exe')
const TMP = path.join(ROOT, '_tmp_test_out')

const GROUPS = [
  { tag: '水多比-战斗', form: '水多比' },
  { tag: '火多比-战斗', form: '火多比' },
  { tag: '超级多比-战斗', form: '超级克罗 多比' },
]

fs.mkdirSync(TMP, { recursive: true })
fs.mkdirSync(BAK, { recursive: true })

const outJson = path.join(TMP, 'idle-candidates2.json')
const pyPath = path.join(TMP, '_pick_idle3.py')
const py = `
import os, json, glob
from PIL import Image
import numpy as np

SRC = r"${SRCDIR.replace(/\\/g, '/')}"
groups = ${JSON.stringify(GROUPS)}
report = {}
for g in groups:
    rows = []
    for f in sorted(glob.glob(os.path.join(SRC, g["tag"] + "*.png"))):
        try:
            im = Image.open(f).convert("RGBA")
        except Exception:
            continue
        a = np.asarray(im).astype(np.float32)
        al = a[:, :, 3]
        solid = al > 200
        n = int(solid.sum())
        if n < 2000:
            continue
        rgb = a[:, :, :3]
        sat = rgb.max(axis=2) - rgb.min(axis=2)
        ys, xs = np.where(solid)
        bw = int(xs.max() - xs.min() + 1)
        bh = int(ys.max() - ys.min() + 1)
        grad = float(np.abs(np.diff(al, axis=1)).mean() + np.abs(np.diff(al, axis=0)).mean())
        rows.append(dict(
            file=os.path.basename(f), w=im.size[0], h=im.size[1],
            solid=float(n) / (im.size[0] * im.size[1]),
            sat=float(sat[solid].mean()), grad=grad,
            bw=bw, bh=bh, ar=float(bh) / bw, foot=float(ys.max()) / im.size[1],
        ))
    # 站姿打分：实心多 + 边缘强 + 饱和高 + 脚底靠下 + 竖向站立（ar>1）
    for r in rows:
        r["score"] = (r["solid"] * 3.0 + min(r["grad"], 12) / 12 * 2.0
                      + min(r["sat"], 180) / 180 * 2.0
                      + (1.0 if r["foot"] > 0.85 else 0.0)
                      + (0.8 if r["ar"] > 1.05 else 0.0))
    rows.sort(key=lambda r: -r["score"])
    report[g["form"]] = rows
    print("%s: %d 帧候选" % (g["form"], len(rows)))
    for r in rows[:4]:
        print("   %-26s %dx%d solid=%.2f sat=%.0f grad=%.2f ar=%.2f foot=%.2f score=%.2f" %
              (r["file"], r["w"], r["h"], r["solid"], r["sat"], r["grad"], r["ar"], r["foot"], r["score"]))
json.dump(report, open(r"${outJson.replace(/\\/g, '/')}", "w", encoding="utf-8"), ensure_ascii=False)
`
fs.writeFileSync(pyPath, py, 'utf8')
execFileSync(PY, [pyPath], { stdio: 'inherit', cwd: ROOT, env: { ...process.env, TMP, TEMP: TMP } })

const rep = JSON.parse(fs.readFileSync(outJson, 'utf8'))
console.log('\n=== 安装为形态立绘（放大到有效高 640）===')
for (const g of GROUPS) {
  const rows = rep[g.form] || []
  if (!rows.length) { console.log(`  ✗ ${g.form}: 没有可用帧`); continue }
  const pick = rows[0]
  const src = path.join(SRCDIR, pick.file)
  const dst = path.join(ARTDIR, g.form + '.png')
  const bak = path.join(BAK, g.form + '.png')
  if (fs.existsSync(dst) && !fs.existsSync(bak)) fs.copyFileSync(dst, bak)
  if (!DRY) {
    const img = decodePng(fs.readFileSync(src))
    // 只取主体包围盒，再按有效高 640 放大（与其它立绘同规格）
    let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
    for (let y = 0; y < img.h; y++) for (let x = 0; x < img.w; x++) {
      if (img.data[(y * img.w + x) * 4 + 3] > 30) {
        if (x < x0) x0 = x; if (x > x1) x1 = x
        if (y < y0) y0 = y; if (y > y1) y1 = y
      }
    }
    const sw = x1 - x0 + 1, sh = y1 - y0 + 1
    const sc = 640 / sh
    const dw = Math.max(1, Math.round(sw * sc))
    const out = new Uint8ClampedArray(dw * 640 * 4)
    for (let y = 0; y < 640; y++) for (let x = 0; x < dw; x++) {
      const sx = x0 + Math.min(sw - 1, Math.floor((x + 0.5) / sc)), sy = y0 + Math.min(sh - 1, Math.floor((y + 0.5) / sc))
      const s = (sy * img.w + sx) * 4, d = (y * dw + x) * 4
      out[d] = img.data[s]; out[d + 1] = img.data[s + 1]; out[d + 2] = img.data[s + 2]; out[d + 3] = img.data[s + 3]
    }
    fs.writeFileSync(dst, encodePng(dw, 640, out))
  }
  console.log(`  ${DRY ? '(dry) ' : ''}${g.form}  ←  ${pick.file}  (solid=${pick.solid.toFixed(2)} sat=${pick.sat.toFixed(0)} score=${pick.score.toFixed(2)})  →  ${path.relative(ROOT, dst)}`)
}
console.log(`\n原图备份 ${path.relative(ROOT, BAK)}`)
", "file_path": "_tools\install-swf-form-art.mjs"}

