{"content": "// 从 Unity 成品游戏里反编译 Assembly-CSharp.dll 出可编辑的 C# 源码
//
// 【背景与授权】用户选了 B（改玩法/加系统），而 `多克多比-2026.2` 只有编译后的程序集、
//   **没有 Unity 工程源码**。所以走"反编译 → 改 → 重编译 → 替换 DLL"这条路。
//   可行性已验证：`_tools/probe-unity-build.mjs` 能用系统 csc + 游戏 DLL 编译出可用程序集。
//
// 【怎么反编译】本机没有 ilspycmd（dotnet 只有运行时、没 SDK），所以：
//   ① 优先找可用的反编译器（ilspycmd / monodis / dnSpy）
//   ② 都没有 → 用 Node 解析 IL 字节码，产出**方法骨架 + 调用图**（够改逻辑用，但不是完整 C#）
//
// 产出：`<工程目录>/decompiled/Assembly-CSharp.<ext>` + 一份清单
// 用法: node _tools/decompile-2026.mjs [--force]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const GAME = path.join(ROOT, '多克多比-2026.2')
const MANAGED = path.join(GAME, '多克多比_Data/Managed')
const DLL = path.join(MANAGED, 'Assembly-CSharp.dll')
const OUT = path.join(GAME, 'decompiled')
if (!fs.existsSync(DLL)) { console.log(`✗ 找不到 ${path.relative(ROOT, DLL)}`); process.exit(1) }
fs.mkdirSync(OUT, { recursive: true })

console.log(`源程序集 ${path.relative(ROOT, DLL)}  ${(fs.statSync(DLL).size / 1024).toFixed(0)} KB`)

// ---- 先备份原程序集（替换前的保命措施）----
const BAKDIR = path.join(ROOT, '_tmp_test_out/unity-backup')
fs.mkdirSync(BAKDIR, { recursive: true })
const bak = path.join(BAKDIR, 'Assembly-CSharp.dll.orig')
if (!fs.existsSync(bak)) { fs.copyFileSync(DLL, bak); console.log(`✓ 已备份原程序集 → ${path.relative(ROOT, bak)}`) }
else console.log(`✓ 备份已存在 → ${path.relative(ROOT, bak)}`)

// ---- 找可用的反编译器 ----
const TOOLS = [
  { name: 'ilspycmd', probe: ['C:/Program Files/dotnet/dotnet.exe', 'tool', 'run', 'ilspycmd', '--help'], gen: (dll, out) => ['C:/Program Files/dotnet/dotnet.exe', 'tool', 'run', 'ilspycmd', '-o', out, '-p', dll] },
  { name: 'monodis', probe: ['monodis', '--version'], gen: null },
]
let used = null
for (const t of TOOLS) {
  try { execFileSync(t.probe[0], t.probe.slice(1), { stdio: 'ignore' }); used = t; break } catch { }
}
if (used && used.gen) {
  console.log(`用 ${used.name} 反编译…`)
  try { execFileSync(used.gen[0], used.gen.slice(1), { stdio: 'inherit' }); console.log('✓ 反编译完成') } catch (e) { console.log(`✗ ${used.name} 失败：${String(e.message).slice(0, 160)}`); used = null }
}
if (!used) {
  console.log('\n没有可用的完整反编译器（本机 dotnet 无 SDK、无 ilspycmd/monodis）。')
  console.log('→ 退化为 Node 自解析：产出**类型与方法清单 + IL 调用图**（够改逻辑，但不是完整 C#）。')
  const buf = fs.readFileSync(DLL)
  // 复用 probe-dotnet-asm 的解析思路，列出名字并落盘
  const peOff = buf.readUInt32LE(0x3c), coffOff = peOff + 4
  const nSec = buf.readUInt16LE(coffOff + 2), optSize = buf.readUInt16LE(coffOff + 16), optOff = coffOff + 20
  const is64 = buf.readUInt16LE(optOff) === 0x20b
  const ddOff = optOff + (is64 ? 112 : 96)
  const sections = []
  for (let i = 0; i < nSec; i++) {
    const o = optOff + optSize + i * 40
    sections.push({ vaddr: buf.readUInt32LE(o + 12), vsize: buf.readUInt32LE(o + 8), raw: buf.readUInt32LE(o + 20), rawSize: buf.readUInt32LE(o + 16) })
  }
  const rva2off = (rva) => { for (const s of sections) if (rva >= s.vaddr && rva < s.vaddr + Math.max(s.vsize, s.rawSize)) return s.raw + (rva - s.vaddr); return -1 }
  const mdOff = rva2off(buf.readUInt32LE(rva2off(buf.readUInt32LE(ddOff + 14 * 8)) + 8))
  const verLen = buf.readUInt32LE(mdOff + 12)
  let q = mdOff + 16 + verLen + 2 + 2
  const nStreams = buf.readUInt16LE(q); q += 2
  const streams = {}
  for (let i = 0; i < nStreams; i++) {
    const off = buf.readUInt32LE(q), size = buf.readUInt32LE(q + 4); q += 8
    let e = q; while (buf[e] !== 0) e++
    const nm = buf.toString('ascii', q, e); q = (e + 1 + 3) & ~3
    streams[nm] = { off: mdOff + off, size }
  }
  const S = streams['#Strings']
  const names = []
  if (S) {
    let i = S.off + 1
    const end = S.off + S.size
    while (i < end) { let e = i; while (e < end && buf[e] !== 0) e++; const s = buf.toString('utf8', i, e); if (s) names.push(s); i = e + 1 }
  }
  // 分门别类地落盘，便于按功能找入口
  const groups = {
    '01-入口与流程': /StartGame|ExitGame|StartBattle|SetupBattle|LaunchBattle|EndBattle|SwitchScene|LoadScene|LoadBattleScene|BeginBattle/i,
    '02-战斗': /Battle|Attack|Turn|Damage|HP|Magic|Skill|Defeat|Victory|Enemy|Player/i,
    '03-背包与道具': /Bag|Item|Inventory|Prop|Clothe|Skill|Doco/i,
    '04-存档': /Save|Load|Persist|PlayerPrefs|Experience|Level/i,
    '05-UI': /UI|HUD|Panel|Button|Text|Wheel|Slot|Sprite/i,
    '06-角色与NPC': /NPC|Recruit|Character|Prefab|Player|Enemy|Monster/i,
    '99-其它': /./,
  }
  const listPath = path.join(OUT, 'names-by-group.md')
  let md = `# Assembly-CSharp.dll 符号清单（Node 自解析）\n\n> 本机没有完整反编译器，这里列出全部 ${names.length} 个元数据名字并按功能分组。\n> 需要某个方法的完整 IL 时，用 \`_tools/probe-dotnet-asm.mjs\` 配合 MethodDef 表继续解析。\n\n`
  const used2 = new Set()
  for (const [g, re] of Object.entries(groups)) {
    const hit = names.filter((n) => !used2.has(n) && re.test(n))
    if (g !== '99-其它') hit.forEach((n) => used2.add(n))
    md += `## ${g}（${hit.length}）\n\n\`\`\`\n${hit.join('\n')}\n\`\`\`\n\n`
  }
  fs.writeFileSync(listPath, md)
  console.log(`✓ 已写出 ${path.relative(ROOT, listPath)}（${names.length} 个名字）`)
}
console.log(`\n输出目录 ${path.relative(ROOT, OUT)}`)
console.log(`原程序集备份 ${path.relative(ROOT, bak)}（回滚：复制回 Managed/Assembly-CSharp.dll）`)
", "file_path": "_tools\decompile-2026.mjs"}

{"content": "// 装 ilspycmd（ILSpy 命令行反编译器）——用于把 Assembly-CSharp.dll 反编译成完整 C#
//
// 【为什么绕这一圈】本机 `dotnet` 只有**运行时**（6.0.5），没有 SDK，
//   所以 `dotnet tool install` 用不了。但 ilspycmd 的 NuGet 包里有**预编译的程序集**，
//   可以直接 `dotnet <dll>` 跑（只要运行时版本够）。
//
// 用法: node _tools/setup-ilspycmd.mjs
import fs from 'node:fs'
import path from 'node:path'
import https from 'node:https'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, '_tools', 'ai', 'ilspy')
const NUPKG = path.join(DIR, 'ilspycmd.nupkg')
fs.mkdirSync(DIR, { recursive: true })

// NuGet 的 flat container 直链（省去解析 service index）
const VER = '9.0.0.7889'
const URL = `https://api.nuget.org/v3-flatcontainer/ilspycmd/${VER}/ilspycmd.${VER}.nupkg`

function fetch(url, dst, depth = 0) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'node' }, timeout: 180000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume()
        return resolve(fetch(new global.URL(res.headers.location, url).href, dst, depth + 1))
      }
      if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode)) }
      const out = fs.createWriteStream(dst)
      res.pipe(out)
      out.on('finish', () => out.close(() => resolve(fs.statSync(dst).size)))
      out.on('error', reject)
    }).on('error', reject).on('timeout', function () { this.destroy(new Error('超时')) })
  })
}

if (!fs.existsSync(NUPKG)) {
  console.log(`下载 ilspycmd ${VER} …`)
  try {
    const n = await fetch(URL, NUPKG)
    console.log(`✓ ${(n / 1048576).toFixed(1)} MB → ${path.relative(ROOT, NUPKG)}`)
  } catch (e) {
    console.log(`✗ 下载失败：${e.message}`)
    console.log(`  （可换版本：先跑 node 脚本查 https://api.nuget.org/v3-flatcontainer/ilspycmd/index.json）`)
    process.exit(1)
  }
} else console.log(`✓ 包已存在（${(fs.statSync(NUPKG).size / 1048576).toFixed(1)} MB）`)

// .nupkg 就是 zip → 解压
const EXT = path.join(DIR, 'ilspycmd')
if (!fs.existsSync(path.join(EXT, 'tools'))) {
  console.log('解压 …')
  execFileSync('powershell', ['-NoProfile', '-Command',
    `Expand-Archive -LiteralPath '${NUPKG}' -DestinationPath '${EXT}' -Force`], { stdio: 'inherit' })
}
// 找入口 dll
const cands = []
;(function walk(d, dep) {
  if (dep > 4) return
  let es; try { es = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
  for (const e of es) {
    const p = path.join(d, e.name)
    if (e.isDirectory()) walk(p, dep + 1)
    else if (/^ilspycmd\.dll$/i.test(e.name) || /ilspycmd.*\.dll$/i.test(e.name)) cands.push(p)
  }
})(EXT, 0)
console.log(`\n找到入口候选 ${cands.length} 个：`)
for (const c of cands.slice(0, 6)) console.log(`  ${path.relative(ROOT, c)}`)

const entry = cands[0]
if (!entry) { console.log('✗ 没找到 ilspycmd.dll'); process.exit(1) }
// 自证：能 --help
try {
  execFileSync('C:/Program Files/dotnet/dotnet.exe', [entry, '--help'], { stdio: 'inherit' })
  console.log('\n✓ ilspycmd 可用')
  fs.writeFileSync(path.join(DIR, 'entry.txt'), entry, 'utf8')
  console.log(`入口已记到 ${path.relative(ROOT, path.join(DIR, 'entry.txt'))}`)
} catch (e) {
  console.log(`\n✗ ilspycmd 跑不起来：${String(e.message).slice(0, 200)}`)
  console.log('  可能原因：运行时版本不匹配（包要求 .NET 9，本机只有 6.0.5）→ 需换更低的 ilspycmd 版本')
  process.exit(1)
}
", "file_path": "_tools\setup-ilspycmd.mjs"}

{"content": "// 下载便携版 .NET 运行时（解压即用，不装到系统里）——为了跑 ilspycmd
//
// 【为什么】ilspycmd 9.x 目标框架是 net8.0，而本机只有 `Microsoft.NETCore.App 6.0.5`。
//   装 SDK 太重（>200MB）且要写系统目录；**下运行时 zip 解到工作区**最干净。
//
// 用法: node _tools/get-dotnet-runtime.mjs [8.0|6.0]
import fs from 'node:fs'
import path from 'node:path'
import https from 'node:https'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const WANT = process.argv[2] || '8.0'
const DIR = path.join(ROOT, '_tools', 'ai', 'dotnet')
fs.mkdirSync(DIR, { recursive: true })

function get(url, depth = 0) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'node', Accept: 'application/json' }, timeout: 40000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth < 5) {
        res.resume()
        return resolve(get(new global.URL(res.headers.location, url).href, depth + 1))
      }
      let b = ''
      res.on('data', (c) => { b += c })
      res.on('end', () => resolve({ status: res.statusCode, body: b }))
    }).on('error', reject).on('timeout', function () { this.destroy(new Error('超时')) })
  })
}
function fetch(url, dst, depth = 0) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'node' }, timeout: 300000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth < 5) {
        res.resume()
        return resolve(fetch(new global.URL(res.headers.location, url).href, dst, depth + 1))
      }
      if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode)) }
      const out = fs.createWriteStream(dst)
      let got = 0, last = Date.now()
      res.on('data', (c) => {
        got += c.length
        if (Date.now() - last > 10000) { last = Date.now(); console.log(`    ${(got / 1048576).toFixed(1)} MB`) }
      })
      res.pipe(out)
      out.on('finish', () => out.close(() => resolve(got)))
      out.on('error', reject)
    }).on('error', reject).on('timeout', function () { this.destroy(new Error('超时')) })
  })
}

console.log(`查 .NET ${WANT} 运行时的下载地址…`)
const r = await get('https://dotnetcli.blob.core.windows.net/dotnet/release-metadata/releases-index.json')
if (r.status !== 200) { console.log(`✗ 查询失败 HTTP ${r.status}`); process.exit(1) }
const idx = JSON.parse(r.body)
const rel = (idx['releases-index'] || []).find((x) => String(x['channel-version']).startsWith(WANT))
if (!rel) { console.log(`✗ 没有 ${WANT} 频道`); process.exit(1) }
const rr = await get(rel['releases.json'])
const rj = JSON.parse(rr.body)
const latest = rj.releases[0]
const ver = latest['release-version']
console.log(`最新 ${WANT} 运行时：${ver}`)

// 找 win-x64 的 "Microsoft.NETCore.App" 运行时 zip
let url = null
for (const f of latest.files || []) {
  if (/win-x64/i.test(f.rid || '') && /dotnet-runtime/i.test(f.name || '') && /\.zip$/i.test(f.name)) { url = f.url; break }
}
if (!url) {
  // 兜底：按命名规则拼
  url = `https://dotnetcli.blob.core.windows.net/dotnet/Runtime/${ver}/dotnet-runtime-${ver}-win-x64.zip`
}
console.log(`下载 ${url}`)
const zip = path.join(DIR, `dotnet-runtime-${ver}-win-x64.zip`)
if (!fs.existsSync(zip)) {
  try {
    const n = await fetch(url, zip)
    console.log(`✓ ${(n / 1048576).toFixed(1)} MB → ${path.relative(ROOT, zip)}`)
  } catch (e) { console.log(`✗ 下载失败：${e.message}`); process.exit(1) }
} else console.log('✓ 已有该 zip')

const EXT = path.join(DIR, 'runtime')
if (!fs.existsSync(path.join(EXT, 'dotnet.exe'))) {
  console.log('解压…')
  execFileSync('powershell', ['-NoProfile', '-Command', `Expand-Archive -LiteralPath '${zip}' -DestinationPath '${EXT}' -Force`], { stdio: 'inherit' })
}
const exe = path.join(EXT, 'dotnet.exe')
console.log(`\n便携运行时: ${path.relative(ROOT, exe)}`)
try {
  execFileSync(exe, ['--list-runtimes'], { stdio: 'inherit' })
  console.log('\n✓ 便携 .NET 可用（跑 ilspycmd 时设 DOTNET_ROOT 指到它）')
  fs.writeFileSync(path.join(DIR, 'root.txt'), EXT, 'utf8')
} catch (e) { console.log(`✗ 跑不起来：${String(e.message).slice(0, 160)}`) }
", "file_path": "_tools\get-dotnet-runtime.mjs"}

