{"content": "// 把反编译出来的源码**重新编译**成 Assembly-CSharp.dll（改代码 → 装回游戏的关键一步）
//
// 【为什么这一步是成败关键】反编译只是"看得见"，能不能改取决于**能不能编译回去**。
//   本机 `dotnet` 有运行时 8.0.31（便携版），所以用 `dotnet build` + 一个最小 csproj。
//   Unity 的代码编译需要引用游戏的 131 个 DLL —— csproj 里用通配引用。
//
// ⚠️ 安全：**默认输出到临时目录**，不动游戏里的原文件；加 `--install` 才替换（并自动备份）。
//
// 用法: node _tools/build-2026.mjs [--install]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, '多克多比-2026.2/decompiled/src/Assembly-CSharp.decompiled.cs')
const MANAGED = path.join(ROOT, '多克多比-2026.2/多克多比_Data/Managed')
const PROJ = path.join(ROOT, '多克多比-2026.2/decompiled/build')
const DN = path.join(ROOT, '_tools/ai/dotnet/runtime/dotnet.exe')
const BUILD_OUT = path.join(PROJ, 'out')
const INSTALL = process.argv.includes('--install')

if (!fs.existsSync(SRC)) { console.log(`✗ 没有源码（先跑 node _tools/decompile-2026.mjs）`); process.exit(1) }
if (!fs.existsSync(DN)) { console.log(`✗ 没有便携 dotnet（先跑 node _tools/get-dotnet-runtime.mjs）`); process.exit(1) }
fs.mkdirSync(PROJ, { recursive: true })

// 编译时引用的程序集：除 Assembly-CSharp.dll 自身以外的全部游戏 DLL
const refs = fs.readdirSync(MANAGED).filter((f) => /\.dll$/i.test(f) && !/^Assembly-CSharp/i.test(f))
console.log(`引用 ${refs.length} 个游戏 DLL`)

// 最小 csproj：netstandard2.1（Unity 的目标面）+ 通配引用
const csproj = `<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>netstandard2.1</TargetFramework>
    <AssemblyName>Assembly-CSharp</AssemblyName>
    <RootNamespace></RootNamespace>
    <LangVersion>9.0</LangVersion>
    <Nullable>disable</Nullable>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
    <GenerateAssemblyInfo>false</GenerateAssemblyInfo>
    <AppendTargetFrameworkToOutputPath>false</AppendTargetFrameworkToOutputPath>
    <NoWarn>CS0169;CS0414;CS0649;CS0108;CS0114;CS0162;CS0219;CS1591;CS0067</NoWarn>
    <OutputPath>${BUILD_OUT.replace(/\\/g, '/')}</OutputPath>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
    <ProduceReferenceAssembly>false</ProduceReferenceAssembly>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="${SRC.replace(/\\/g, '/')}" />
  </ItemGroup>
  <ItemGroup>
${refs.map((r) => `    <Reference Include="${path.basename(r, '.dll')}"><HintPath>${path.join(MANAGED, r).replace(/\\/g, '/')}</HintPath><Private>false</Private></Reference>`).join('\n')}
  </ItemGroup>
</Project>
`
fs.writeFileSync(path.join(PROJ, 'Assembly-CSharp.csproj'), csproj, 'utf8')
console.log(`csproj → ${path.relative(ROOT, path.join(PROJ, 'Assembly-CSharp.csproj'))}`)

// 关掉 NuGet 还原的网络访问（本机无 SDK 的 NuGet 配置，避免卡住）
const nuget = path.join(PROJ, 'nuget.config')
fs.writeFileSync(nuget, `<?xml version="1.0" encoding="utf-8"?>
<configuration>
  <packageSources><clear /></packageSources>
</configuration>
`, 'utf8')

console.log('\n编译中…')
try {
  execFileSync(DN, ['build', path.join(PROJ, 'Assembly-CSharp.csproj'), '-c', 'Release', '-v', 'minimal', '--nologo'], {
    stdio: 'inherit', cwd: PROJ,
    env: { ...process.env, DOTNET_ROOT: path.dirname(DN), DOTNET_CLI_TELEMETRY_OPTOUT: '1', DOTNET_NOLOGO: '1', TMP: path.join(ROOT, '_tmp_test_out'), TEMP: path.join(ROOT, '_tmp_test_out') },
  })
} catch (e) {
  console.log(`\n✗ 编译失败：${String(e.message).slice(0, 300)}`)
  process.exit(1)
}

const built = path.join(BUILD_OUT, 'Assembly-CSharp.dll')
if (!fs.existsSync(built)) { console.log(`\n✗ 没产出 ${path.relative(ROOT, built)}`); process.exit(1) }
const origSize = fs.statSync(path.join(MANAGED, 'Assembly-CSharp.dll')).size
const newSize = fs.statSync(built).size
console.log(`\n✓ 编译成功！`)
console.log(`  原程序集 ${(origSize / 1024).toFixed(0)} KB`)
console.log(`  新程序集 ${(newSize / 1024).toFixed(0)} KB  → ${path.relative(ROOT, built)}`)

if (INSTALL) {
  const BAK = path.join(ROOT, '_tmp_test_out/unity-backup/Assembly-CSharp.dll.orig')
  fs.mkdirSync(path.dirname(BAK), { recursive: true })
  if (!fs.existsSync(BAK)) fs.copyFileSync(path.join(MANAGED, 'Assembly-CSharp.dll'), BAK)
  fs.copyFileSync(built, path.join(MANAGED, 'Assembly-CSharp.dll'))
  console.log(`\n✓ 已装回游戏（原程序集备份在 ${path.relative(ROOT, BAK)}）`)
} else {
  console.log(`\n（未替换原文件。确认无误后加 --install 装回，或手动复制）`)
}
