{"content": "// 用系统 csc.exe 编译反编译出的源码 → Assembly-CSharp.dll
//
// 【为什么不用 dotnet build】本机 `dotnet` 只有**运行时**（便携包也只含运行时），
//   报 `No .NET SDKs were found`。而 `probe-unity-build.mjs` 已验证：
//   **系统 csc.exe + 游戏的 netstandard/UnityEngine 引用**能编译出可用程序集。
//   → 就用 csc，不折腾 SDK 下载（省 200MB+）。
//
// ⚠️ 安全：默认只输出到临时目录；加 `--install` 才替换游戏里的原文件（自动备份）。
//
// 用法: node _tools/build-2026-csc.mjs [--install]
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, '多克多比-2026.2/decompiled/src/Assembly-CSharp.decompiled.cs')
const MANAGED = path.join(ROOT, '多克多比-2026.2/多克多比_Data/Managed')
const OUTDIR = path.join(ROOT, '多克多比-2026.2/decompiled/build-out')
const INSTALL = process.argv.includes('--install')
const CSC = 'C:/Windows/Microsoft.NET/Framework64/v4.0.30319/csc.exe'

if (!fs.existsSync(SRC)) { console.log('✗ 没有源码（先跑 decompile-2026.mjs）'); process.exit(1) }
if (!fs.existsSync(CSC)) { console.log('✗ 找不到 csc.exe'); process.exit(1) }
fs.mkdirSync(OUTDIR, { recursive: true })

// 引用：除自身以外的全部游戏 DLL。
// ⚠️ 不能引用游戏的 mscorlib.dll / System.Runtime 面重复项 —— 会报 CS1703。
//    实测：引用 netstandard.dll 是**必须**的（UnityEngine.CoreModule 是 netstandard2.1 面）。
const all = fs.readdirSync(MANAGED).filter((f) => /\.dll$/i.test(f))
const skip = /^(Assembly-CSharp|mscorlib|System\.Runtime\.dll|System\.Private\.|System\.ValueTuple)/i
const refs = all.filter((f) => !skip.test(f))
console.log(`引用 ${refs.length} 个 DLL（跳过自身与 mscorlib 面）`)

const outDll = path.join(OUTDIR, 'Assembly-CSharp.dll')
const args = [
  '/nologo', '/target:library', '/platform:anycpu', '/langversion:9.0',
  '/optimize+', '/deterministic-',
  // 反编译代码必然有大量"未使用字段/隐藏成员"之类警告 —— 关掉，否则日志淹没真错误
  '/nowarn:0169,0414,0649,0108,0114,0162,0219,0067,0169,1701,1702',
  '/out:' + outDll,
  SRC,
  ...refs.map((r) => '/reference:' + path.join(MANAGED, r)),
]
console.log(`\n编译 ${path.basename(SRC)} …（引用多、耗时长）`)
try {
  execFileSync(CSC, args, { stdio: 'inherit', cwd: ROOT, maxBuffer: 64 * 1024 * 1024 })
} catch (e) {
  console.log(`\n✗ 编译失败（退出码 ${e.status}）`)
  process.exit(1)
}
if (!fs.existsSync(outDll)) { console.log('✗ 没有产出'); process.exit(1) }

const o = fs.statSync(path.join(MANAGED, 'Assembly-CSharp.dll')).size
const n = fs.statSync(outDll).size
console.log(`\n✓ 编译成功`)
console.log(`  原 ${(o / 1024).toFixed(0)} KB  →  新 ${(n / 1024).toFixed(0)} KB`)
console.log(`  产物 ${path.relative(ROOT, outDll)}`)

if (INSTALL) {
  const BAK = path.join(ROOT, '_tmp_test_out/unity-backup/Assembly-CSharp.dll.orig')
  fs.mkdirSync(path.dirname(BAK), { recursive: true })
  if (!fs.existsSync(BAK)) { fs.copyFileSync(path.join(MANAGED, 'Assembly-CSharp.dll'), BAK); console.log(`✓ 已备份原程序集`) }
  fs.copyFileSync(outDll, path.join(MANAGED, 'Assembly-CSharp.dll'))
  console.log(`✓ 已装回游戏（回滚：复制 ${path.relative(ROOT, BAK)} 回去）`)
} else {
  console.log('（未替换原文件；确认无误后加 --install）')
}
