{"content": "// 探针：找出"能让 UnityEngine + BCL 泛型集合同时编译通过"的引用组合
//
// 【问题】用 Roslyn csc 编译反编译的 Unity 代码时，
//   源码里 `Queue<Vector2>`（本意是 System.Collections.Generic.Queue<T>）解析失败：
//   `CS1069: 类型已转发到程序集 mscorlib` —— 因为用的是 .NET Framework 的 mscorlib，
//   而游戏 Managed 里的 `netstandard.dll` 是为 **Unity 自己的 mscorlib** 准备的。
// 本脚本用一段最小代码逐组合试，找出能过的引用集（不猜，用结果说话）。
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve('.')
const MANAGED = path.join(ROOT, '多克多比-2026.2/多克多比_Data/Managed')
const TMP = path.join(ROOT, '_tmp_test_out/refprobe')
const CSC = path.join(ROOT, '_tools/ai/roslyn/toolset/tasks/net472/csc.exe')
fs.mkdirSync(TMP, { recursive: true })

const src = path.join(TMP, 'Probe.cs')
fs.writeFileSync(src, `using UnityEngine;
using UnityEngine.UI;
public class RefProbe : MonoBehaviour {
    private System.Collections.Generic.Queue<Vector2> q = new System.Collections.Generic.Queue<Vector2>();
    private System.Collections.Generic.List<int> l = new System.Collections.Generic.List<int>();
    public Text label;
    void Start() { q.Enqueue(transform.position); l.Add(1); if (label != null) label.text = "ok"; }
}
`, 'utf8')

const M = (f) => path.join(MANAGED, f)
const combos = [
  { name: 'A: Unity 面 + 系统 mscorlib（当前做法）', refs: ['UnityEngine.dll', 'UnityEngine.CoreModule.dll', 'UnityEngine.UI.dll', 'netstandard.dll', 'System.Runtime.dll'] },
  { name: 'B: 去掉 netstandard/System.Runtime', refs: ['UnityEngine.dll', 'UnityEngine.CoreModule.dll', 'UnityEngine.UI.dll'] },
  { name: 'C: 直接引用游戏的 mscorlib', refs: ['mscorlib.dll', 'UnityEngine.dll', 'UnityEngine.CoreModule.dll', 'UnityEngine.UI.dll', 'netstandard.dll', 'System.Runtime.dll'] },
  { name: 'D: 游戏 mscorlib + 不引 netstandard', refs: ['mscorlib.dll', 'UnityEngine.dll', 'UnityEngine.CoreModule.dll', 'UnityEngine.UI.dll'] },
  { name: 'E: 游戏 mscorlib + System.Runtime 全套', refs: ['mscorlib.dll', 'System.Runtime.dll', 'System.Collections.dll', 'UnityEngine.dll', 'UnityEngine.CoreModule.dll', 'UnityEngine.UI.dll', 'netstandard.dll'] },
]

for (const c of combos) {
  const out = path.join(TMP, 'out.dll')
  fs.rmSync(out, { force: true })
  const args = ['/nologo', '/target:library', '/langversion:9.0', '/nostdlib+', '/out:' + out, src,
    ...c.refs.map((r) => '/reference:' + M(r)).filter((_, i) => fs.existsSync(M(c.refs[i])))]
  let ok = false, err = ''
  try {
    execFileSync(CSC, args, { stdio: 'inherit', cwd: TMP })
    ok = fs.existsSync(out)
  } catch (e) { err = `退出码 ${e.status}` }
  console.log(`${ok ? '✓' : '✗'} ${c.name}${ok ? '' : '  ' + err}`)
}
