            pm.evasionRateLevels = PairF(f.evasion / 100f);
            pm.speedLevels = Pair(f.speed);
            pm.maxHPLevels = Pair(f.hp);
            pm.maxMagicLevels = Pair(f.mp);
            pm.elementType = f.element;
            pm.CalculateStatsBasedOnLevel();
            return true;
        }

        private static int[] Pair(int v) { return new int[] { v, v }; }
        private static float[] PairF(float v) { return new float[] { v, v }; }

        /// <summary>供 UI/日志用：一共注入了几只形态。</summary>
        public static int Count { get { return All.Length; } }
    }
