{"content": "// 一次性修：把生成器模板字面量内部的反引号换成全角引号（否则 JS 语法错）
import fs from 'node:fs'
const F = '_tools/gen-dkdbb-forms-cs.mjs'
const t = fs.readFileSync(F, 'utf8')
const BT = String.fromCharCode(96)          // `
const start = t.indexOf('let cs = ' + BT)
const endMark = BT + '\n'
const end = t.lastIndexOf(endMark)
if (start < 0 || end <= start) { console.log(`定位失败 start=${start} end=${end}`); process.exit(1) }
const before = t.slice(0, start)
const body = t.slice(start, end)
const after = t.slice(end)
let n = 0
const fixed = body.split(BT).join('｀').replace(/｀｀｀｀/g, '')   // 多余的四连也清掉
for (const ch of body) if (ch === BT) n++
fs.writeFileSync(F, before + fixed + after, 'utf8')
console.log(`模板块内替换了 ${n} 个反引号`)
", "file_path": "_tools\_fix-backticks.mjs"}

