const before = t.slice(0, start)
const body = t.slice(start, end)
const after = t.slice(end)
let n = 0
const fixed = body.split(BT).join('｀').replace(/｀｀｀｀/g, '')   // 多余的四连也清掉
for (const ch of body) if (ch === BT) n++
fs.writeFileSync(F, before + fixed + after, 'utf8')
console.log(`模板块内替换了 ${n} 个反引号`)"}

