{"content": "// 用"已知名字的图标"作锚点，在 124 个切图里建立"技能 ID → 图标"的对应
//
// 【第 3 版关键修正】前两版失败的原因：
//   · 第 1 版：把图标缩到 32×32 —— 图标本身只 64px，缩一半细节全丢
//   · 第 2 版：原尺寸直接比 —— 但两组图**尺寸规则不同**：
//       已知图标 64×64（内容裁到边）  vs  新切图标 109×110（**四周带白边**）
//     尺寸不一致导致逐像素比必然错位。
//   实测证据：平均色完全一致（坚韧/土系_01 都是 rgb(225,167,57)；
//   大地之怒/土系_02 都是 rgb(215,132,59)）→ 确认是**同一批图**，只是切法不同。
// 【第 3 版做法】新图标先**去掉白边**（按不透明且非白的外接框裁紧），再缩到 64×64，然后比。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const KNOWN = path.join(ROOT, 'assets/skills')
const NEW = path.join(ROOT, '_tmp_test_out/skill-icons-sliced')

const meta = JSON.parse(fs.readFileSync(path.join(KNOWN, 'index.json'), 'utf8'))
const sliced = JSON.parse(fs.readFileSync(path.join(NEW, 'index.json'), 'utf8'))

// 归一化：裁掉"不透明但仍接近白色"的边（这就是新切图的白边），再缩到 S×S
const S = 64
function normalize(img) {
  // 找内容框：alpha>40 且不是纯白
  let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1
  for (let y = 0; y < img.h; y++) {
    for (let x = 0; x < img.w; x++) {
      const i = (y * img.w + x) * 4
      const a = img.data[i + 3]
      if (a < 40) continue
      const r = img.data[i], g = img.data[i + 1], b = img.data[i + 2]
      const white = r > 246 && g > 246 && b > 246
      if (white) continue
      if (x < x0) x0 = x; if (x > x1) x1 = x
      if (y < y0) y0 = y; if (y > y1) y1 = y
    }
  }
  if (x1 < 0) return null
  const cw = x1 - x0 + 1, ch = y1 - y0 + 1
  const out = new Float32Array(S * S * 4)
  for (let y = 0; y < S; y++) {
    for (let x = 0; x < S; x++) {
      const sx = x0 + Math.min(cw - 1, Math.floor(x * cw / S))
      const sy = y0 + Math.min(ch - 1, Math.floor(y * ch / S))
      const si = (sy * img.w + sx) * 4, di = (y * S + x) * 4
      out[di] = img.data[si]; out[di + 1] = img.data[si + 1]
      out[di + 2] = img.data[si + 2]; out[di + 3] = img.data[si + 3]
    }
  }
  return { w: S, h: S, data: out }
}

const dist = (a, b) => {
  let s = 0, n = 0
  for (let i = 0; i < S * S; i++) {
    const o = i * 4
    if (a.data[o + 3] < 40 && b.data[o + 3] < 40) continue
    s += Math.abs(a.data[o] - b.data[o]) + Math.abs(a.data[o + 1] - b.data[o + 1]) + Math.abs(a.data[o + 2] - b.data[o + 2])
    n++
  }
  return n ? s / n / 3 : 999
}

const newIcons = []
for (const s of sliced.sheets) {
  for (const ic of s.icons) {
    const p = path.join(NEW, ic.name)
    if (!fs.existsSync(p)) continue
    const nrm = normalize(decodePng(fs.readFileSync(p)))
    if (nrm) newIcons.push({ el: s.element, ic, img: nrm })
  }
}
const known = []
for (const it of meta.icons) {
  if (!it.name) continue
  const p = path.join(ROOT, it.file)
  if (!fs.existsSync(p)) continue
  const nrm = normalize(decodePng(fs.readFileSync(p)))
  if (nrm) known.push({ id: it.id, name: it.name, from: it.from || '', img: nrm })
}
console.log(`新素材 ${newIcons.length} 个 · 已知 ${known.length} 个（都已裁白边+归一化到 ${S}×${S}）\n`)

console.log('锚定结果：')
const anchors = []
for (const k of known) {
  const scored = newIcons.map((n) => ({ n, d: dist(k.img, n.img) })).sort((x, y) => x.d - y.d)
  const best = scored[0], second = scored[1]
  const conf = best.d < 6 && (second.d - best.d) > 2 ? 'high'
    : best.d < 12 && (second.d - best.d) > 1 ? 'mid' : 'low'
  anchors.push({ name: k.name, hit: best, second, conf })
  const mark = conf === 'high' ? '✓' : conf === 'mid' ? '~' : '?'
  console.log(`  ${mark} ${k.name.padEnd(6)} [${k.from || '?'}]  →  ${best.n.el}_${String(best.n.ic.idx).padStart(2, '0')}  色差 ${best.d.toFixed(2)}（次近 ${second.d.toFixed(2)} ${second.n.el}_${String(second.n.ic.idx).padStart(2, '0')}）`)
}

const hi = anchors.filter((a) => a.conf === 'high')
const mid = anchors.filter((a) => a.conf === 'mid')
console.log(`\n可信度：high ${hi.length} · mid ${mid.length} · low ${anchors.length - hi.length - mid.length}`)
if (hi.length + mid.length) {
  console.log('\n=== 可用锚点（技能 ↔ 素材表位置）===')
  for (const a of [...hi, ...mid]) console.log(`  ${a.hit.n.el} 第 ${a.hit.n.ic.idx} 个 = 「${a.name}」  [${a.conf}] 色差 ${a.hit.d.toFixed(2)}`)
}
fs.writeFileSync(path.join(ROOT, '_tmp_test_out/icon-anchors.json'), JSON.stringify({
  generated: new Date().toISOString(),
  method: '第 3 版：裁白边 + 归一化到 64×64（前两版因尺寸规则不同而失败）',
  anchors: anchors.map((a) => ({
    skill: a.name, conf: a.conf, sheet: a.hit.n.el, idx: a.hit.n.ic.idx,
    d: Number(a.hit.d.toFixed(2)),
    second: { sheet: a.second.n.el, idx: a.second.n.ic.idx, d: Number(a.second.d.toFixed(2)) },
  })),
}, null, 1))
console.log('\n→ _tmp_test_out/icon-anchors.json')
", "file_path": "_tools\match-skill-icons-v3.mjs"}

{"content": "// 盘点技能图标源图 `技能ICON.png` 的结构（行 × 列 + 每行平均色）
// 与官方技能表的 ID 段对照 → 建立"技能 ID → 图标"的完整映射
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, '多克多比专区资料素材/多比形态素材/技能及说明/技能ICON.png')
const img = decodePng(fs.readFileSync(SRC))
console.log(`源图 ${path.basename(SRC)}  ${img.w}×${img.h}`)

// 连通域找图标格子
const W = img.w, H = img.h, data = img.data
const isInk = (x, y) => {
  const i = (y * W + x) * 4
  if (data[i + 3] < 40) return false
  return !(data[i] > 242 && data[i + 1] > 242 && data[i + 2] > 242)
}
const seen = new Uint8Array(W * H)
const boxes = []
const stack = []
for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    const p0 = y * W + x
    if (seen[p0] || !isInk(x, y)) continue
    seen[p0] = 1
    stack.length = 0; stack.push(p0)
    let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
    while (stack.length) {
      const c = stack.pop(), cx = c % W, cy = (c / W) | 0
      n++
      if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
      if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue
        const np = ny * W + nx
        if (!seen[np] && isInk(nx, ny)) { seen[np] = 1; stack.push(np) }
      }
    }
    const bw = x1 - x0 + 1, bh = y1 - y0 + 1
    if (n > 600 && bw > 30 && bh > 30 && bw / bh > 0.6 && bw / bh < 1.7) boxes.push({ x0, y0, x1, y1, n, bw, bh })
  }
}
console.log(`连通域图标 ${boxes.length} 个`)

// 按行聚类
boxes.sort((a, b) => a.y0 - b.y0 || a.x0 - b.x0)
const rows = []
for (const b of boxes) {
  const cy = (b.y0 + b.y1) / 2
  let r = rows.find((rr) => Math.abs(rr.cy - cy) < Math.max(24, b.bh * 0.6))
  if (!r) { r = { cy, items: [] }; rows.push(r) }
  r.items.push(b)
}
rows.sort((a, b) => a.cy - b.cy)
console.log(`分成 ${rows.length} 行\n`)

// 官方技能表的 ID 段（从 assets/skills-official.json）
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))
const seg = {}
for (const s of off.skills) {
  const k = Math.floor(s.id / 1000)
  seg[k] = (seg[k] || []).push(s)
}

console.log('行结构（每行：y范围 · 列数 · 平均色 · 尺寸）')
for (const r of rows) {
  r.items.sort((a, b) => a.x0 - b.x0)
  let sr = 0, sg = 0, sb = 0, n = 0
  for (const b of r.items) {
    for (let y = b.y0; y <= b.y1; y += 2) for (let x = b.x0; x <= b.x1; x += 2) {
      const i = (y * W + x) * 4
      if (data[i + 3] > 40) { sr += data[i]; sg += data[i + 1]; sb += data[i + 2]; n++ }
    }
  }
  const yMid = Math.round(r.cy)
  const w0 = r.items[0].bw, h0 = r.items[0].bh
  console.log(`  y≈${String(yMid).padStart(4)}  ${String(r.items.length).padStart(2)} 列  rgb(${(sr / n) | 0},${(sg / n) | 0},${(sb / n) | 0})  ${w0}×${h0}  x: ${r.items.map((b) => Math.round(b.x0)).join(',')}`)
}

console.log('\n官方技能表 ID 段：')
for (const [k, list] of Object.entries(seg).sort()) {
  console.log(`  ${k}xxx  ${String(list.length).padStart(3)} 个  ${list[0].name.slice(0, 10)} … ${list[list.length - 1].name.slice(0, 10)}`)
}
