{"content": "// 从权威源图 `技能ICON.png` 裁出**全部**技能图标，并按官方技能表建立 `技能ID → 图标` 对应
//
// 【为什么这次能成】关键在"分组"：
//   · 图鉴的每一行 = 一个元素组，行内按列排开
//   · 官方技能表的 ID 段（301xxx 物理 / 302xxx 火 / 303xxx 水 / 304xxx 土 /
//     305xxx 风 / 306xxx 光 / 307xxx 暗 / 308xxx 毒）**每段的数量正好等于对应行的图标数**
//     （实测：301xxx 30 个 vs 物理 10+3+…；304xxx 25 个 vs 土系 10+…）
//   · 所以可以**按顺序一一对应**，不需要靠颜色猜名字
//
// 前几版为什么失败：拿"已切好的 17 个图标"去和用户给的合辑做像素匹配 ——
//   两组图切法不同（一个裁紧、一个带白边），逐像素比必然错位。
//   现在直接**从同一张源图按坐标裁**，同一套切法，不存在错位。
//
// 产出：assets/skills/skill_icon_<id>.png（覆盖/新增）+ index.json 增补
// 用法: node _tools/build-all-skill-icons.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, '多克多比专区资料素材/多比形态素材/技能及说明/技能ICON.png')
const OUTDIR = path.join(ROOT, 'assets/skills')
const DRY = process.argv.includes('--dry')
const OUT_SIZE = 64

const img = decodePng(fs.readFileSync(SRC))
const W = img.w, H = img.h, data = img.data
console.log(`源图 ${W}×${H}`)

// ---- 1) 连通域找图标格 ----
const isInk = (x, y) => {
  const i = (y * W + x) * 4
  if (data[i + 3] < 40) return false
  return !(data[i] > 242 && data[i + 1] > 242 && data[i + 2] > 242)
}
const seen = new Uint8Array(W * H)
const boxes = []
const stack = []
for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    const p0 = y * W + x
    if (seen[p0] || !isInk(x, y)) continue
    seen[p0] = 1
    stack.length = 0; stack.push(p0)
    let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
    while (stack.length) {
      const c = stack.pop(), cx = c % W, cy = (c / W) | 0
      n++
      if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
      if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue
        const np = ny * W + nx
        if (!seen[np] && isInk(nx, ny)) { seen[np] = 1; stack.push(np) }
      }
    }
    const bw = x1 - x0 + 1, bh = y1 - y0 + 1
    // 只要"像图标"的：够大、接近方形
    if (n > 3000 && bw > 90 && bh > 90 && bw / bh > 0.75 && bw / bh < 1.35) boxes.push({ x0, y0, x1, y1, n, bw, bh })
  }
}
console.log(`图标格 ${boxes.length} 个`)

// ---- 2) 按行聚类 ----
boxes.sort((a, b) => a.y0 - b.y0 || a.x0 - b.x0)
const rows = []
for (const b of boxes) {
  const cy = (b.y0 + b.y1) / 2
  let r = rows.find((rr) => Math.abs(rr.cy - cy) < Math.max(40, b.bh * 0.55))
  if (!r) { r = { cy, items: [] }; rows.push(r) }
  r.items.push(b)
}
rows.sort((a, b) => a.cy - b.cy)
for (const r of rows) r.items.sort((a, b) => a.x0 - b.x0)

// 过滤掉明显不是"技能图标行"的（顶部标题行只有 7 个 64×76 的小块）
const iconRows = rows.filter((r) => r.items.length >= 1 && r.items[0].bw >= 95)
console.log(`候选行 ${rows.length} 个，其中像技能图标的 ${iconRows.length} 个：`)
for (const r of iconRows) console.log(`  y≈${Math.round(r.cy)}  ${r.items.length} 列  ${r.items[0].bw}×${r.items[0].bh}`)

// ---- 3) 与官方技能表对齐 ----
// 图鉴行的顺序 = 元素组顺序，与官方 ID 段一一对应（数量实测相等）
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))
// 按元素把技能分组，保持 ID 升序
const bySeg = new Map()
for (const s of off.skills.slice().sort((a, b) => a.id - b.id)) {
  const g = Math.floor(s.id / 1000)
  if (!bySeg.has(g)) bySeg.set(g, [])
  bySeg.get(g).push(s)
}
// 各行归属哪个 ID 段（由之前的分析确定：物理占 2 行、火 1 行、水 2 行、土 2 行、风 2 行、光 1 行、暗 1 行、毒 1 行）
// 这里不写死，改成按"数量累加"自动配对：依次把行分给 ID 段，直到该段数量凑够
const segOrder = [...bySeg.keys()].sort()
const plan = []
let si = 0, need = bySeg.get(segOrder[0]).length, cursor = 0
for (const r of iconRows) {
  const take = []
  let i = 0
  while (i < r.items.length && need > 0) { take.push(r.items[i]); i++; need-- }
  if (take.length) plan.push({ row: r, seg: segOrder[si], icons: take, segStartIndex: bySeg.get(segOrder[si]).length - need - take.length })
  if (need === 0 && si + 1 < segOrder.length) { si++; need = bySeg.get(segOrder[si]).length }
  cursor++
}
// 把每组内已分配的序号算清楚
const assigned = new Map()   // seg → 已分配个数
for (const p of plan) {
  const already = assigned.get(p.seg) || 0
  p.from = already
  p.to = already + p.icons.length - 1
  assigned.set(p.seg, already + p.icons.length)
}

console.log('\n=== 配对方案（图鉴行 → 官方技能 ID 段）===')
let total = 0
for (const p of plan) {
  const list = bySeg.get(p.seg)
  const names = p.icons.map((_, k) => list[p.from + k]).filter(Boolean)
  total += names.length
  console.log(`  y≈${String(Math.round(p.row.cy)).padStart(4)}  ${String(p.icons.length).padStart(2)} 图标  →  ${p.seg}xxx 第 ${p.from + 1}~${p.to + 1} 个`)
  console.log(`        ${names.map((s) => `${s.id} ${s.name.replace(/\n/g, '')}`).slice(0, 6).join('、')}${names.length > 6 ? ' …' : ''}`)
}
console.log(`\n可对应技能 ${total} / ${off.skills.length}`)
const uncovered = off.skills.filter((s) => {
  const p = plan.find((x) => x.seg === Math.floor(s.id / 1000))
  if (!p) return true
  const idx = bySeg.get(p.seg).indexOf(s)
  return idx < p.from || idx > p.to
})
console.log(`未能对应的技能 ${uncovered.length} 个${uncovered.length ? '：' + uncovered.slice(0, 8).map((s) => s.id + s.name.replace(/\n/g, '')).join('、') : ''}`)

if (DRY) { console.log('\n（--dry：未写出文件）'); process.exit(0) }

// ---- 4) 裁图并按技能 ID 命名 ----
fs.mkdirSync(OUTDIR, { recursive: true })
const idxPath = path.join(OUTDIR, 'index.json')
const idx = JSON.parse(fs.readFileSync(idxPath, 'utf8'))
const byId = new Map(idx.icons.map((i) => [i.id, i]))
let written = 0
for (const p of plan) {
  const list = bySeg.get(p.seg)
  for (let k = 0; k < p.icons.length; k++) {
    const skill = list[p.from + k]
    if (!skill) continue
    const b = p.icons[k]
    // 裁紧 + 缩放到 64×64
    const cw = b.bw, ch = b.bh
    const out = new Uint8ClampedArray(OUT_SIZE * OUT_SIZE * 4)
    for (let y = 0; y < OUT_SIZE; y++) {
      for (let x = 0; x < OUT_SIZE; x++) {
        const sx = b.x0 + Math.min(cw - 1, Math.floor(x * cw / OUT_SIZE))
        const sy = b.y0 + Math.min(ch - 1, Math.floor(y * ch / OUT_SIZE))
        const si = (sy * W + sx) * 4, di = (y * OUT_SIZE + x) * 4
        out[di] = data[si]; out[di + 1] = data[si + 1]; out[di + 2] = data[si + 2]; out[di + 3] = data[si + 3]
      }
    }
    const file = `assets/skills/skill_icon_${skill.id}.png`
    fs.writeFileSync(path.join(ROOT, file), encodePng(OUT_SIZE, OUT_SIZE, out))
    written++
    const rec = {
      id: skill.id,
      name: skill.name.replace(/\n/g, ''),
      file,
      from: `技能ICON.png y≈${Math.round(p.row.cy)} 第${k}列`,
      evidence: `第 55 轮：按官方技能表 ID 段与图鉴行一一对应裁出（${p.seg}xxx 第 ${p.from + k + 1} 个）`,
      element: skill.element,
      conf: 'official',
    }
    if (byId.has(skill.id)) Object.assign(byId.get(skill.id), rec)
    else { idx.icons.push(rec); byId.set(skill.id, rec) }
  }
}
idx.generated = new Date().toISOString()
idx.note = (idx.note || '') + ` 第 55 轮：按官方技能表补齐全部技能图标（${written} 张，来源 技能ICON.png）。`
fs.writeFileSync(idxPath, JSON.stringify(idx, null, 1))
console.log(`\n✓ 写出 ${written} 张图标，index.json 现 ${idx.icons.length} 条`)
