{"content": "// 第一步：从权威源图按行裁出全部技能图标，输出"行/列 + 平均色 + 建议元素"
// 不猜技能名 —— 先把图标踏实裁出来，配对留给下一步（有据可查）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const SRC = path.join(ROOT, '多克多比专区资料素材/多比形态素材/技能及说明/技能ICON.png')
const OUT = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
fs.mkdirSync(OUT, { recursive: true })

const img = decodePng(fs.readFileSync(SRC))
const W = img.w, H = img.h, data = img.data
console.log(`源图 ${W}×${H}`)

const isInk = (x, y) => {
  const i = (y * W + x) * 4
  if (data[i + 3] < 40) return false
  return !(data[i] > 242 && data[i + 1] > 242 && data[i + 2] > 242)
}
const seen = new Uint8Array(W * H)
const boxes = []
const stack = []
for (let y = 0; y < H; y++) {
  for (let x = 0; x < W; x++) {
    const p0 = y * W + x
    if (seen[p0] || !isInk(x, y)) continue
    seen[p0] = 1
    stack.length = 0; stack.push(p0)
    let n = 0, x0 = x, x1 = x, y0 = y, y1 = y
    while (stack.length) {
      const c = stack.pop(), cx = c % W, cy = (c / W) | 0
      n++
      if (cx < x0) x0 = cx; if (cx > x1) x1 = cx
      if (cy < y0) y0 = cy; if (cy > y1) y1 = cy
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        const nx = cx + dx, ny = cy + dy
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue
        const np = ny * W + nx
        if (!seen[np] && isInk(nx, ny)) { seen[np] = 1; stack.push(np) }
      }
    }
    const bw = x1 - x0 + 1, bh = y1 - y0 + 1
    if (n > 800 && bw > 45 && bh > 45 && bw / bh > 0.7 && bw / bh < 1.45) boxes.push({ x0, y0, x1, y1, n, bw, bh })
  }
}
console.log(`图标格 ${boxes.length} 个`)

// 行聚类（阈值放宽，让同一行尽量聚在一起）
boxes.sort((a, b) => a.y0 - b.y0 || a.x0 - b.x0)
const rows = []
for (const b of boxes) {
  const cy = (b.y0 + b.y1) / 2
  let r = rows.find((rr) => Math.abs(rr.cy - cy) < Math.max(50, b.bh * 0.7))
  if (!r) { r = { cy, items: [] }; rows.push(r) }
  r.items.push(b)
}
rows.sort((a, b) => a.cy - b.cy)
for (const r of rows) r.items.sort((a, b) => a.x0 - b.x0)

// 元素参考色（按官方元素组的图标主色）
const EL_COLORS = {
  物理: [190, 120, 70], 火: [249, 181, 38], 水: [110, 180, 238], 土: [208, 128, 38],
  风: [140, 148, 217], 光: [159, 78, 153], 暗: [213, 157, 74], 毒: [136, 174, 179],
}
const nearestEl = (r, g, b) => {
  let best = null, bd = 1e9
  for (const [el, c] of Object.entries(EL_COLORS)) {
    const d = (r - c[0]) ** 2 + (g - c[1]) ** 2 + (b - c[2]) ** 2
    if (d < bd) { bd = d; best = el }
  }
  return { el: best, d: Math.sqrt(bd) | 0 }
}

const SIZE = 64
const report = []
let idx = 0
console.log('\n行 / 列 / 颜色 / 建议元素')
const manifest = []
for (let ri = 0; ri < rows.length; ri++) {
  const r = rows[ri]
  // 只要"多数是大块"的行
  const big = r.items.filter((b) => b.bw >= 95)
  if (big.length < r.items.length * 0.5) continue
  r.items = big
  let sr = 0, sg = 0, sb = 0, n = 0
  for (const b of r.items) {
    for (let y = b.y0; y <= b.y1; y += 2) for (let x = b.x0; x <= b.x1; x += 2) {
      const i = (y * W + x) * 4
      if (data[i + 3] > 40) { sr += data[i]; sg += data[i + 1]; sb += data[i + 2]; n++ }
    }
  }
  const avg = [(sr / n) | 0, (sg / n) | 0, (sb / n) | 0]
  const sug = nearestEl(...avg)
  console.log(`  r${String(ri).padStart(2)}  y≈${String(Math.round(r.cy)).padStart(4)}  ${String(r.items.length).padStart(2)} 列  rgb(${avg.join(',')})  → ${sug.el}（色距 ${sug.d}）`)
  const rowRec = { row: ri, cy: Math.round(r.cy), count: r.items.length, avg, suggest: sug.el, colorDist: sug.d, files: [] }
  for (let k = 0; k < r.items.length; k++) {
    const b = r.items[k]
    const out = new Uint8ClampedArray(SIZE * SIZE * 4)
    for (let y = 0; y < SIZE; y++) {
      for (let x = 0; x < SIZE; x++) {
        const sx = b.x0 + Math.min(b.bw - 1, Math.floor(x * b.bw / SIZE))
        const sy = b.y0 + Math.min(b.bh - 1, Math.floor(y * b.bh / SIZE))
        const si = (sy * W + sx) * 4, di = (y * SIZE + x) * 4
        out[di] = data[si]; out[di + 1] = data[si + 1]; out[di + 2] = data[si + 2]; out[di + 3] = data[si + 3]
      }
    }
    const nm = `r${String(ri).padStart(2, '0')}_c${String(k).padStart(2, '0')}__${sug.el}.png`
    fs.writeFileSync(path.join(OUT, nm), encodePng(SIZE, SIZE, out))
    rowRec.files.push(nm)
    idx++
  }
  manifest.push(rowRec)
}
fs.writeFileSync(path.join(OUT, 'manifest.json'), JSON.stringify({ source: path.relative(ROOT, SRC), total: idx, rows: manifest }, null, 1))
console.log(`\n✓ 裁出 ${idx} 个图标 → ${path.relative(ROOT, OUT)}`)
", "file_path": "_tools\slice-skill-atlas.mjs"}

{"content": "// 锚定：把 `assets/skills` 里**已知名字**的图标 与 新裁的图鉴图标 对上
//
// 【为什么这次应该能成】两者**同源同切法**（都来自 技能ICON.png、都裁紧到 64×64），
//   不像之前拿"用户给的合辑"去比（那个带白边、尺寸规则不同）。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const known = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills/index.json'), 'utf8')).icons.filter((i) => i.name)
const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))

const newIcons = []
for (const r of man.rows) {
  for (let k = 0; k < r.files.length; k++) {
    newIcons.push({ row: r.row, col: k, el: r.suggest, file: r.files[k], img: decodePng(fs.readFileSync(path.join(ATLAS, r.files[k]))) })
  }
}
console.log(`图鉴图标 ${newIcons.length} 个`)

const norm = (img) => {
  const S = 64
  const out = new Float32Array(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x * img.w / S)), sy = Math.min(img.h - 1, Math.floor(y * img.h / S))
    const si = (sy * img.w + sx) * 4, di = (y * S + x) * 4
    out[di] = img.data[si]; out[di + 1] = img.data[si + 1]; out[di + 2] = img.data[si + 2]; out[di + 3] = img.data[si + 3]
  }
  return out
}
const dist = (a, b) => {
  let s = 0, n = 0
  for (let i = 0; i < a.length; i += 4) {
    if (a[i + 3] < 40 && b[i + 3] < 40) continue
    s += Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2]); n++
  }
  return n ? s / n / 3 : 999
}

console.log('\n锚定结果：')
const hits = []
for (const k of known) {
  const A = norm(decodePng(fs.readFileSync(path.join(ROOT, k.file))))
  const scored = newIcons.map((n) => ({ n, d: dist(A, norm(n.img)) })).sort((x, y) => x.d - y.d)
  const best = scored[0], second = scored[1]
  const conf = best.d < 6 && (second.d - best.d) > 2 ? 'high' : best.d < 12 && (second.d - best.d) > 1 ? 'mid' : 'low'
  hits.push({ skill: k.name, row: best.n.row, col: best.n.col, el: best.n.el, d: best.d, conf })
  const mark = conf === 'high' ? '✓' : conf === 'mid' ? '~' : '?'
  console.log(`  ${mark} ${k.name.padEnd(6)} [${k.from || '?'}]  →  行 ${best.n.row} 列 ${best.n.col} (${best.n.el})  色差 ${best.d.toFixed(2)}（次近 ${second.d.toFixed(2)} 行${second.n.row}列${second.n.col}）`)
}
const good = hits.filter((h) => h.conf !== 'low')
console.log(`\n可信 ${good.length} / ${hits.length}`)
if (good.length) {
  console.log('\n=== 锚点（技能 → 图鉴行列）===')
  for (const h of good) console.log(`  「${h.skill}」= 行 ${h.row} 列 ${h.col}（${h.el}）  [${h.conf}]`)
}
fs.writeFileSync(path.join(ROOT, '_tmp_test_out/atlas-anchors.json'), JSON.stringify(hits, null, 1))
console.log('\n→ _tmp_test_out/atlas-anchors.json')
", "file_path": "_tools\match-atlas-anchors.mjs"}

{"content": "// 建立「技能 ID → 图鉴行列」映射并裁出图标
//
// 【依据（都可复核）】
//   · 图鉴 12 行，每行一个元素（平均色与元素参考色距离 0~20，实测：土 0、光 0、风 1、火 3、水 5、物理 10）
//   · 锚定验证：已知名字的「地之咆哮」= 行6列0、「大地之怒」= 行6列2 ——
//     与 `assets/skills/index.json` 记录的「图鉴 y=1164 第0列 / 第2列」**完全一致**
//   · 所以：行 = 元素组，行内列序 = 该元素组内技能 ID 升序
//
// 【做不到的部分（如实标注）】图鉴总计 74 个图标，官方技能 217 个 ——
//   图鉴只画了"每个元素的主要技能"，等级系列技能（力量祝福Lv1~Lv5 等）共用一个图标。
//   所以只有前 74 个技能能拿到专属图标，其余按元素沿用同组图标（conf=derived），
//   并**在 index.json 里写明是沿用**，不假装是原版专属图标（R1/R9）。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const OUTDIR = path.join(ROOT, 'assets/skills')
const DRY = process.argv.includes('--dry')

const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))

// 图鉴行 → 官方技能 ID 段（由元素色 + 数量决定；此处按已验证的对应写死，便于复核）
// 行号来自 slice-skill-atlas.mjs 的输出
const ROW_TO_SEG = [
  { rows: [1, 2], seg: 301, el: '物理' },   // 10 + 3 = 13
  { rows: [3], seg: 302, el: '火' },        // 8
  { rows: [4, 5], seg: 303, el: '水' },     // 8 + 4 = 12
  { rows: [6, 7], seg: 304, el: '土' },     // 10 + 1 = 11
  { rows: [8, 9], seg: 305, el: '风' },     // 10 + 1 = 11
  { rows: [10], seg: 306, el: '光' },       // 5
  { rows: [11], seg: 307, el: '暗' },       // 7
  { rows: [12], seg: 308, el: '毒' },       // 7
]

const bySeg = new Map()
for (const s of off.skills.slice().sort((a, b) => a.id - b.id)) {
  const g = Math.floor(s.id / 1000)
  if (!bySeg.has(g)) bySeg.set(g, [])
  bySeg.get(g).push(s)
}

console.log('=== 映射方案 ===')
const plan = []          // { skill, row, col, conf }
for (const m of ROW_TO_SEG) {
  const list = bySeg.get(m.seg) || []
  const icons = []
  for (const r of m.rows) {
    const row = man.rows.find((x) => x.row === r)
    if (!row) { console.log(`  ⚠️ 找不到行 ${r}`); continue }
    for (let c = 0; c < row.files.length; c++) icons.push({ row: r, col: c, file: row.files[c] })
  }
  console.log(`  ${m.el}（${m.seg}xxx）：图鉴 ${icons.length} 个图标 vs 技能 ${list.length} 个`)
  for (let i = 0; i < list.length; i++) {
    // 图标不够时按元素沿用同组第一个（并标注 derived）
    const direct = i < icons.length
    plan.push({
      skill: list[i],
      icon: direct ? icons[i] : icons[icons.length - 1],
      conf: direct ? 'official' : 'derived（沿用同元素图标：图鉴未单独绘制）',
    })
  }
}

console.log(`\n共 ${plan.length} 个技能可挂图标`)
const official = plan.filter((p) => p.conf === 'official').length
console.log(`  专属图标（图鉴直接对应）：${official}`)
console.log(`  沿用同元素图标：${plan.length - official}`)

if (DRY) {
  console.log('\n（--dry：未写出文件）')
  console.log('\n前 8 条：')
  for (const p of plan.slice(0, 8)) console.log(`  ${p.skill.id} ${p.skill.name.replace(/\n/g, '')}  ←  行${p.icon.row}列${p.icon.col}  [${p.conf}]`)
  process.exit(0)
}

// ---- 写出 ----
fs.mkdirSync(OUTDIR, { recursive: true })
const idxPath = path.join(OUTDIR, 'index.json')
const idx = JSON.parse(fs.readFileSync(idxPath, 'utf8'))
const byId = new Map(idx.icons.map((i) => [i.id, i]))
let n = 0
for (const p of plan) {
  const src = path.join(ATLAS, p.icon.file)
  if (!fs.existsSync(src)) continue
  const file = `assets/skills/skill_icon_${p.skill.id}.png`
  fs.copyFileSync(src, path.join(ROOT, file))
  n++
  const rec = {
    id: p.skill.id,
    name: p.skill.name.replace(/\n/g, ''),
    file,
    from: `技能ICON.png 行${p.icon.row} 列${p.icon.col}`,
    evidence: `第 55 轮：图鉴行=元素组、行内列序=技能ID升序（锚定验证见 _tools/match-atlas-anchors.mjs）`,
    element: p.skill.element,
    conf: p.conf.startsWith('official') ? 'official' : 'derived',
    confNote: p.conf.startsWith('official') ? '' : p.conf,
  }
  if (byId.has(p.skill.id)) Object.assign(byId.get(p.skill.id), rec)
  else { idx.icons.push(rec); byId.set(p.skill.id, rec) }
}
idx.generated = new Date().toISOString()
idx.note = (idx.note || '') + ` 第 55 轮：按官方技能表 + 图鉴行列对应补齐技能图标（写出 ${n} 张）。`
fs.writeFileSync(idxPath, JSON.stringify(idx, null, 1))
console.log(`\n✓ 写出 ${n} 张 → assets/skills/，index.json 现 ${idx.icons.length} 条`)
", "file_path": "_tools\map-skill-icons-official.mjs"}

{"content": "// 技能图标核对图：把 74 个"专属图标"按图鉴行列排开，带行列与对应技能序号
// 用途：让用户一眼核对映射对不对（比看数字强）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))
const bySeg = new Map()
for (const s of off.skills.slice().sort((a, b) => a.id - b.id)) {
  const g = Math.floor(s.id / 1000)
  if (!bySeg.has(g)) bySeg.set(g, [])
  bySeg.get(g).push(s)
}
const ROW_TO_SEG = [[1, 2, 301, '物理'], [3, 0, 302, '火'], [4, 5, 303, '水'], [6, 7, 304, '土'],
[8, 9, 305, '风'], [10, 0, 306, '光'], [11, 0, 307, '暗'], [12, 0, 308, '毒']]

const CELL = 72, GAP = 8, PAD = 16, LAB = 26
const cols = 13
const rowsOut = ROW_TO_SEG.length
const totW = PAD * 2 + cols * (CELL + GAP)
const totH = PAD * 2 + rowsOut * (CELL + GAP + LAB)
const fb = new Uint8ClampedArray(totW * totH * 4)
for (let i = 0; i < totW * totH; i++) { fb[i * 4] = 18; fb[i * 4 + 1] = 22; fb[i * 4 + 2] = 36; fb[i * 4 + 3] = 255 }

let oy = PAD
let total = 0
for (const [r1, r2, seg, el] of ROW_TO_SEG) {
  const rowNums = r2 ? [r1, r2] : [r1]
  const icons = []
  for (const rn of rowNums) {
    const row = man.rows.find((x) => x.row === rn)
    if (row) for (let c = 0; c < row.files.length; c++) icons.push({ rn, c, f: row.files[c] })
  }
  const list = bySeg.get(seg) || []
  let ox = PAD
  for (let i = 0; i < icons.length; i++) {
    const ic = icons[i]
    const p = path.join(ATLAS, ic.f)
    if (!fs.existsSync(p)) continue
    const im = decodePng(fs.readFileSync(p))
    for (let y = 0; y < CELL; y++) for (let x = 0; x < CELL; x++) {
      const sx = Math.min(im.w - 1, Math.floor(x * im.w / CELL)), sy = Math.min(im.h - 1, Math.floor(y * im.h / CELL))
      const si = (sy * im.w + sx) * 4, al = im.data[si + 3] / 255
      if (al <= 0) continue
      const d = ((oy + y) * totW + ox + x) * 4
      fb[d] = im.data[si] * al + fb[d] * (1 - al)
      fb[d + 1] = im.data[si + 1] * al + fb[d + 1] * (1 - al)
      fb[d + 2] = im.data[si + 2] * al + fb[d + 2] * (1 - al)
      fb[d + 3] = 255
    }
    // 底部色条：专属=绿，沿用=橙
    const direct = i < list.length
    for (let y = oy + CELL; y < oy + CELL + 4; y++) for (let x = ox; x < ox + CELL; x++) {
      const d = (y * totW + x) * 4
      fb[d] = direct ? 80 : 220; fb[d + 1] = direct ? 200 : 140; fb[d + 2] = direct ? 120 : 60
    }
    ox += CELL + GAP
    total++
  }
  oy += CELL + GAP + LAB
}

fs.mkdirSync(path.join(ROOT, 'docs/shots'), { recursive: true })
const OUT = path.join(ROOT, 'docs/shots/skill-icons-official.png')
fs.writeFileSync(OUT, encodePng(totW, totH, fb))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log(`行顺序（上→下）：${ROW_TO_SEG.map((x) => x[3]).join('  ')}`)
console.log(`共 ${total} 个图标（绿条=图鉴专属对应，橙条=沿用同元素）`)
console.log('\n每行对应技能（前 3 个）：')
for (const [r1, r2, seg, el] of ROW_TO_SEG) {
  const list = bySeg.get(seg) || []
  console.log(`  ${el.padEnd(3)} ${list.slice(0, 3).map((s) => s.id + ' ' + s.name.replace(/\n/g, '')).join('、')} …`)
}
