{"content": "// 用"已知名字的图标"反查它在图鉴的哪一行 —— 顺便确认"物理行/火行"的归属
//
// 已知图标来自 assets/skills/index.json（有 name 的那 7 个）。
// 图鉴行号来自 slice-skill-atlas.mjs 的 manifest（行内含平均色）。
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))
const idx = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills/index.json'), 'utf8')).icons.filter((i) => i.name)

// 图鉴每行的平均色（自己算一遍，避免依赖 manifest 的建议）
const W = 64
const avgOf = (p) => {
  const im = decodePng(fs.readFileSync(p))
  let r = 0, g = 0, b = 0, n = 0
  for (let i = 0; i < im.w * im.h; i++) {
    const o = i * 4
    if (im.data[o + 3] > 40) { r += im.data[o]; g += im.data[o + 1]; b += im.data[o + 2]; n++ }
  }
  return n ? [Math.round(r / n), Math.round(g / n), Math.round(b / n)] : [0, 0, 0]
}
console.log('=== 图鉴各行 ===')
for (const row of man.rows) {
  const avgs = row.files.map((f) => avgOf(path.join(ATLAS, f)))
  const m = [0, 1, 2].map((k) => Math.round(avgs.reduce((s, a) => s + a[k], 0) / avgs.length))
  console.log(`  行${String(row.row).padStart(2)}  y≈${String(row.cy).padStart(4)}  ${String(row.files.length).padStart(2)} 列  rgb(${m.join(',')})`)
}
console.log('\n=== 已知名字的图标（含其来源坐标与颜色）===')
for (const k of idx) {
  const a = avgOf(path.join(ROOT, k.file))
  console.log(`  ${k.name.padEnd(6)} 来源「${k.from || '?'}」  rgb(${a.join(',')})`)
}

// 已知图标的平均色 vs 图鉴各行的平均色 → 找最接近的行
console.log('\n=== 每个已知图标最接近哪一行 ===')
for (const k of idx) {
  const a = avgOf(path.join(ROOT, k.file))
  const scored = man.rows.map((row) => {
    const avgs = row.files.map((f) => avgOf(path.join(ATLAS, f)))
    const m = [0, 1, 2].map((x) => avgs.reduce((s, q) => s + q[x], 0) / avgs.length)
    const d = Math.sqrt((a[0] - m[0]) ** 2 + (a[1] - m[1]) ** 2 + (a[2] - m[2]) ** 2)
    return { row: row.row, cy: row.cy, n: row.files.length, m: m.map(Math.round), d: Math.round(d) }
  }).sort((x, y) => x.d - y.d)
  const b = scored[0]
  console.log(`  ${k.name.padEnd(6)} rgb(${a.join(',')})  →  行${b.row}（${b.n}列 rgb(${b.m.join(',')})）色距 ${b.d}   [次近 行${scored[1].row} 色距 ${scored[1].d}]`)
}
", "file_path": "_tools\_confirm-atlas-rows.mjs"}

