{"content": "// 隔离存放：把"从图鉴裁的图标"移到候选目录，不占用 assets/skills 的正式 ID
//
// 【为什么】行归属（哪一行是哪个元素）已验证正确；但**行内列序 ↔ 技能 ID** 没验证通过
//   （实测：若假设成立，"冰枪"两边该是同一张图，实际一张是冰矛、一张是冰浪 → 假设不成立）。
//   按 R1/R9「不许编」，未验证的对应不能接进游戏，所以移到候选区，并标注待核对。
//
// 产出：_tmp_test_out/skill-icons-candidate/（含 README 说明如何接入）
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'assets/skills')
const CAND = path.join(ROOT, '_tmp_test_out/skill-icons-candidate')
const PROTECT = new Set(['1001', '1002', '1003', '1004', '2001', '2002', '2003', '2004',
  '3001', '3002', '3003', '3004', '4001', '4002', '4003', '5001', '5002'])

fs.mkdirSync(CAND, { recursive: true })
const files = fs.readdirSync(DIR).filter((f) => /^skill_icon_\d+\.png$/.test(f))
let moved = 0, kept = 0
for (const f of files) {
  const id = f.replace('skill_icon_', '').replace('.png', '')
  if (PROTECT.has(id)) { kept++; continue }          // 原版 17 个：保留
  if (id.length < 6) { kept++; continue }            // 非官方 6 位 ID：保留（可能是别的用途）
  fs.renameSync(path.join(DIR, f), path.join(CAND, f))
  moved++
}
console.log(`保留在 assets/skills：${kept} 个（原版 17 + 非官方 ID）`)
console.log(`移到候选区：${moved} 个 → ${path.relative(ROOT, CAND)}`)

// index.json：把候选条目标出 toVerify，并从正式列表移出
const idxPath = path.join(DIR, 'index.json')
const idx = JSON.parse(fs.readFileSync(idxPath, 'utf8'))
let demoted = 0
idx.icons = idx.icons.filter((e) => {
  const id = String(e.id)
  if (PROTECT.has(id) || id.length < 6) return true
  demoted++
  return false
})
idx.generated = new Date().toISOString()
idx.note = (idx.note || '') +
  ` 第 55 轮：从图鉴裁的 ${demoted} 个图标**未接入**（行内列序↔技能ID 的假设未通过验证），` +
  `移到 _tmp_test_out/skill-icons-candidate/ 待核对。assets/skills 只保留已核对的原版 17 个。`
fs.writeFileSync(idxPath, JSON.stringify(idx, null, 1))
console.log(`index.json 移出 ${demoted} 条候选，现有 ${idx.icons.length} 条`)

// 候选区说明
fs.writeFileSync(path.join(CAND, 'README.md'), `# 技能图标候选（未接入）

## 这批图从哪来

\`多克多比专区资料素材/多比形态素材/技能及说明/技能ICON.png\`（2133×3333）——
按连通域裁出的 ${moved} 个图标，即 \`skill_icon_<6位ID>.png\`（ID 取自官方技能表）。

## 为什么没接入（重要）

**已验证的部分**：
- 图鉴共 12 行，每行一个元素（平均色与元素参考色距离 0~20：土 0、光 0、风 1、火 3、水 5、物理 10）
- 行归属与官方技能 ID 段对应，且有硬证据：
  \`重击=行1列0\`、\`火球=行3列0\`、\`冰枪=行4列0\`、\`地之咆哮=行6列0\`、\`闪电=行8列0\`
  （这些坐标来自 \`assets/skills/index.json\` 的 \`from\` 字段）

**未通过验证的部分**：
- 我原本假设「行内列序 = 该元素技能 ID 升序」→ 按此裁出的图标与项目里**已核对过**的原版图标
  **不是同一张图**。最清楚的反例：\`冰枪\`
  - 原版（\`skill_icon_3001.png\`）= 一支清晰的**冰矛**
  - 图鉴行4列0 = 一团**冰浪**
  - 冰枪只可能有一种画法 → 说明"列0 = 冰枪"不成立

对照图见 \`docs/shots/skill-icons-2sets.png\`（左=原版，右=图鉴版）。

## 怎么接入（拿到确认后）

1. 确认列序：需要**逐列核对**图鉴每行 10 个图标分别对应哪个技能。
   可用的锚点：每行的列 0 已知（重击/火球/冰枪/地之咆哮/闪电 等，见上）。
2. 确认后把文件复制回 \`assets/skills/\`，并在 \`index.json\` 里补条目：
   \`{ id, name, file, from: "技能ICON.png 行N 列M", evidence: "...", conf: "official" }\`
3. 跑 \`node _tools/verify-skill-icon-parity.mjs\` 复核（它会把新图标与原版逐像素比）。

## 为什么值得继续做

官方技能表有 **217 个**技能，而现在游戏只有 **17 个**图标。
图鉴这 74 个图标能覆盖官方的**前 8 个元素组的主技能**，是补齐图标的关键素材。
`)
console.log(`已写出 ${path.relative(ROOT, path.join(CAND, 'README.md'))}`)
", "file_path": "_tools\quarantine-candidate-icons.mjs"}

{"content": "// 精确匹配：项目里已核对的 17 个图标，逐个在图鉴 74 个裁图里找最像的
//
// 【为什么要重做一遍】上一版只打印了"最像的"就完事，这次要看的是：
//   · 匹配是否**唯一且突出**（色差远小于次近）
//   · 17 个图标是否**分别落在图鉴的不同位置**（若多个落在同一格 → 说明图鉴里没有它们）
//   · 落在同一行的若干个，列序是否与技能 ID 升序一致（这才是"列序假设"的真正检验）
import fs from 'node:fs'
import path from 'node:path'
import { decodePng } from './pixel-canvas.mjs'
import vm from 'node:vm'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'assets/skills')
const BAK = path.join(ROOT, '_tmp_test_out/orig-skill-icons')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))

const ctx = { window: {} }
vm.createContext(ctx)
vm.runInContext(fs.readFileSync(path.join(ROOT, 'assets/forms.js'), 'utf8'), ctx)
const sk = ctx.window.__DKDbb_FORMS__.skills || {}

// 官方表：名字 → ID + 该元素组内序号
const byName = new Map()
for (const s of off.skills) {
  const n = s.name.replace(/\n/g, '').trim()
  if (!byName.has(n)) byName.set(n, s)
}

const norm = (img, S = 64) => {
  const out = new Float32Array(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x * img.w / S)), sy = Math.min(img.h - 1, Math.floor(y * img.h / S))
    const si = (sy * img.w + sx) * 4, di = (y * S + x) * 4
    out[di] = img.data[si]; out[di + 1] = img.data[si + 1]; out[di + 2] = img.data[si + 2]; out[di + 3] = img.data[si + 3]
  }
  return out
}
const dist = (a, b) => {
  let s = 0, n = 0
  for (let i = 0; i < a.length; i += 4) {
    if (a[i + 3] < 40 && b[i + 3] < 40) continue
    s += Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2]); n++
  }
  return n ? s / n / 3 : 999
}

const atlas = []
for (const r of man.rows) {
  for (let k = 0; k < r.files.length; k++) {
    const p = path.join(ATLAS, r.files[k])
    if (!fs.existsSync(p)) continue
    atlas.push({ row: r.row, col: k, el: r.suggest, n: norm(decodePng(fs.readFileSync(p))) })
  }
}

console.log('技能        官方ID   元素序号  最像的图鉴格    色差   次近   判定')
const placed = new Map()
const results = []
for (const [name, rec] of Object.entries(sk)) {
  const src = fs.existsSync(path.join(BAK, rec.icon + '.png'))
    ? path.join(BAK, rec.icon + '.png')
    : path.join(DIR, rec.icon + '.png')
  if (!fs.existsSync(src)) continue
  const A = norm(decodePng(fs.readFileSync(src)))
  const scored = atlas.map((a) => ({ a, d: dist(A, a.n) })).sort((x, y) => x.d - y.d)
  const b = scored[0], s2 = scored[1]
  const gap = s2.d - b.d
  const verdict = b.d < 10 && gap > 4 ? '★ 唯一命中' : b.d < 18 && gap > 2 ? '~ 可能' : '? 无对应'
  const o = byName.get(name)
  const seqInSeg = o ? (off.skills.filter((x) => Math.floor(x.id / 1000) === Math.floor(o.id / 1000)).findIndex((x) => x.id === o.id) + 1) : null
  console.log(`  ${name.padEnd(9)} ${String(o ? o.id : '?').padEnd(7)} ${String(seqInSeg ?? '?').padEnd(8)} 行${String(b.a.row).padStart(2)}列${b.a.col} ${b.a.el.padEnd(3)}  ${b.d.toFixed(1).padStart(5)}  ${s2.d.toFixed(1).padStart(5)}  ${verdict}`)
  results.push({ name, id: o ? o.id : null, seq: seqInSeg, row: b.a.row, col: b.a.col, el: b.a.el, d: b.d, gap })
  const key = `${b.a.row}_${b.a.col}`
  if (!placed.has(key)) placed.set(key, [])
  placed.get(key).push(name)
}

const star = results.filter((r) => r.d < 10 && r.gap > 4)
console.log(`\n唯一命中 ${star.length} / ${results.length}`)

// 同一格被多个技能命中 → 说明图鉴里没有这些技能
const dup = [...placed.entries()].filter(([, v]) => v.length > 1)
if (dup.length) {
  console.log('\n多个技能落到同一格（说明图鉴里没有它们各自的图标）：')
  for (const [k, v] of dup) console.log(`  行${k.split('_')[0]}列${k.split('_')[1]}: ${v.join('、')}`)
}

// 关键检验：同一行内，列序 vs 元素内序号是否一致
console.log('\n=== 列序 vs 官方元素内序号 ===')
const byRow = {}
for (const r of results) (byRow[r.row] = byRow[r.row] || []).push(r)
for (const [row, list] of Object.entries(byRow).sort((a, b) => a[0] - b[0])) {
  list.sort((a, b) => a.col - b.col)
  const cols = list.map((x) => x.col)
  const seqs = list.map((x) => x.seq)
  const expect = seqs.map((s) => s - 1)
  const consistent = cols.length > 1 && cols.every((c, i) => c === expect[i])
  console.log(`  行${String(row).padStart(2)}: ${list.map((x) => `${x.name}(列${x.col}/${x.el}内第${x.seq})`).join('  ')}`)
  if (cols.length > 1) console.log(`        列序 [${cols}] vs 序号-1 [${expect}] → ${consistent ? '✓ 一致' : '✗ 不一致'}`)
}
", "file_path": "_tools\match-icons-precise.mjs"}

{"content": "// 逐行核对图：把图鉴每行的图标 与 该元素的官方技能名 一一对齐显示
// 目的：让用户一眼看出"哪一列对应哪个技能"，特别是火系那行的疑点
import fs from 'node:fs'
import path from 'node:path'
import { decodePng, encodePng } from './pixel-canvas.mjs'

const ROOT = path.resolve('.')
const ATLAS = path.join(ROOT, '_tmp_test_out/skill-atlas-icons')
const man = JSON.parse(fs.readFileSync(path.join(ATLAS, 'manifest.json'), 'utf8'))
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))

const bySeg = new Map()
for (const s of off.skills.slice().sort((a, b) => a.id - b.id)) {
  const g = Math.floor(s.id / 1000)
  if (!bySeg.has(g)) bySeg.set(g, [])
  bySeg.get(g).push(s)
}
// 行 → 元素段（已由 3 个元素组独立验证）
const ROWS = [
  { rows: [1, 2], seg: 301, el: '物理' },
  { rows: [3], seg: 302, el: '火' },
  { rows: [4, 5], seg: 303, el: '水' },
  { rows: [6, 7], seg: 304, el: '土' },
  { rows: [8, 9], seg: 305, el: '风' },
  { rows: [10], seg: 306, el: '光' },
  { rows: [11], seg: 307, el: '暗' },
  { rows: [12], seg: 308, el: '毒' },
]

const CELL = 80, GAP = 8, PAD = 16, BAND = 22
const cols = 13
const totW = PAD * 2 + cols * (CELL + GAP)
const totH = PAD * 2 + ROWS.length * (BAND + CELL + GAP)
const fb = new Uint8ClampedArray(totW * totH * 4)
for (let i = 0; i < totW * totH; i++) { fb[i * 4] = 18; fb[i * 4 + 1] = 22; fb[i * 4 + 2] = 36; fb[i * 4 + 3] = 255 }

// 极简 5×7 数字/字母点阵（只画序号与元素名首字，避免引入字体依赖）
const GLYPH = {
  '0': ['01110', '10001', '10011', '10101', '11001', '10001', '01110'],
  '1': ['00100', '01100', '00100', '00100', '00100', '00100', '01110'],
  '2': ['01110', '10001', '00001', '00010', '00100', '01000', '11111'],
  '3': ['11111', '00010', '00100', '00010', '00001', '10001', '01110'],
  '4': ['00010', '00110', '01010', '10010', '11111', '00010', '00010'],
  '5': ['11111', '10000', '11110', '00001', '00001', '10001', '01110'],
  '6': ['00110', '01000', '10000', '11110', '10001', '10001', '01110'],
  '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
  '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
  '9': ['01110', '10001', '10001', '01111', '00001', '00010', '01100'],
}
const drawText = (s, x0, y0, color) => {
  let cx = x0
  for (const ch of String(s)) {
    const g = GLYPH[ch]
    if (g) {
      for (let y = 0; y < 7; y++) for (let x = 0; x < 5; x++) {
        if (g[y][x] === '1') {
          for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) {
            const px = cx + x * 2 + dx, py = y0 + y * 2 + dy
            if (px < 0 || py < 0 || px >= totW || py >= totH) continue
            const d = (py * totW + px) * 4
            fb[d] = color[0]; fb[d + 1] = color[1]; fb[d + 2] = color[2]
          }
        }
      }
    }
    cx += 12
  }
}

let oy = PAD
const summary = []
for (const R of ROWS) {
  const list = bySeg.get(R.seg) || []
  const icons = []
  for (const rn of R.rows) {
    const row = man.rows.find((x) => x.row === rn)
    if (row) for (let c = 0; c < row.files.length; c++) icons.push({ rn, c, f: row.files[c] })
  }
  // 行标题带：元素色
  const bandColor = (R.el === '火') ? [200, 80, 40] : (R.el === '水') ? [60, 120, 200] : (R.el === '土') ? [170, 110, 40]
    : (R.el === '风') ? [110, 110, 190] : (R.el === '光') ? [180, 80, 170] : (R.el === '暗') ? [170, 130, 60]
      : (R.el === '毒') ? [110, 150, 140] : [150, 100, 70]
  for (let y = oy; y < oy + BAND - 4; y++) for (let x = PAD; x < totW - PAD; x++) {
    const d = (y * totW + x) * 4
    fb[d] = bandColor[0]; fb[d + 1] = bandColor[1]; fb[d + 2] = bandColor[2]
  }
  // 元素名用序号代替（点阵只有数字）：显示该段第 1 个技能 ID 的后三位
  drawText(String(R.seg - 300), PAD + 4, oy + 4, [255, 255, 255])
  oy += BAND

  let ox = PAD
  for (let i = 0; i < icons.length; i++) {
    const p = path.join(ATLAS, icons[i].f)
    if (fs.existsSync(p)) {
      const im = decodePng(fs.readFileSync(p))
      for (let y = 0; y < CELL; y++) for (let x = 0; x < CELL; x++) {
        const sx = Math.min(im.w - 1, Math.floor(x * im.w / CELL)), sy = Math.min(im.h - 1, Math.floor(y * im.h / CELL))
        const si = (sy * im.w + sx) * 4, al = im.data[si + 3] / 255
        if (al <= 0) continue
        const d = ((oy + y) * totW + ox + x) * 4
        fb[d] = im.data[si] * al + fb[d] * (1 - al)
        fb[d + 1] = im.data[si + 1] * al + fb[d + 1] * (1 - al)
        fb[d + 2] = im.data[si + 2] * al + fb[d + 2] * (1 - al)
        fb[d + 3] = 255
      }
    }
    // 列号
    drawText(String(i), ox + 2, oy + CELL + 2, [200, 200, 120])
    ox += CELL + GAP
  }
  oy += CELL + GAP
  summary.push({ el: R.el, count: icons.length, skills: list.slice(0, icons.length).map((s) => s.id + ' ' + s.name.replace(/\n/g, '')) })
}

fs.mkdirSync(path.join(ROOT, 'docs/shots'), { recursive: true })
const OUT = path.join(ROOT, 'docs/shots/skill-atlas-by-element.png')
fs.writeFileSync(OUT, encodePng(totW, totH, fb))
console.log(`已写出 ${path.relative(ROOT, OUT)}  ${totW}×${totH}`)
console.log('\n每行图标数 与 按列序对应的官方技能（供核对）：')
for (const s of summary) {
  console.log(`\n【${s.el}】${s.count} 个图标`)
  for (let i = 0; i < s.skills.length; i++) console.log(`  列${String(i).padStart(2)}  ${s.skills[i]}`)
}
", "file_path": "_tools\make-atlas-by-element-sheet.mjs"}

