{"content": "// 把 7k7k 技能条目的**缩略图**接入项目，并用「名字 + 元素」与官方技能表交叉匹配
//
// 【为什么这批数据可靠】每个条目的 `text` 是 7k7k 详情页正文，字段齐全且能互相校验：
//   技能名称 / 技能属性(元素) / 技能范围 / 技能消耗 / 技能冷却 / 技能说明 / 掉落场景
//   与官方策划表（217 个技能，编号ID + 效果名称 + 系别）交叉比对 → 名字 + 元素**双重确认**
//
// 产出：
//   · assets/skills/skill_icon_<官方ID>.png（仅接入"名字+元素"都对得上的）
//   · assets/skills-7k7k.json（全部技能条目，便于日后使用）
// 用法: node _tools/import-7k7k-skill-icons.mjs [--dry]
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const BASE = path.join(ROOT, '_tmp_test_out/7k7k-res/多克多比_7k7k美术资源_20260929')
const DRY = process.argv.includes('--dry')
const OUTDIR = path.join(ROOT, 'assets/skills')

const entries = JSON.parse(fs.readFileSync(path.join(BASE, '资料/条目资料.json'), 'utf8'))
const images = JSON.parse(fs.readFileSync(path.join(BASE, '资料/图片清单.json'), 'utf8'))
const official = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))

// 图片路径 → 磁盘路径
const imgByPath = new Map(images.map((i) => [i.path, i]))

// 官方表：名字 → 技能（可能重名，取第一个并记下来）
const offByName = new Map()
for (const s of official.skills) {
  const n = s.name.replace(/\n/g, '').trim()
  if (!offByName.has(n)) offByName.set(n, [])
  offByName.get(n).push(s)
}

// 解析 text 里的字段
function parseText(t) {
  const out = {}
  const flat = String(t || '').replace(/\r/g, '')
  const keys = ['技能名称', '技能属性', '技能范围', '技能消耗', '技能冷却', '技能说明', '掉落场景', '掉落怪物']
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i]
    const start = flat.indexOf(k)
    if (start < 0) continue
    const after = flat.slice(start + k.length).replace(/^\n+/, '')
    // 到下一个键为止
    let end = after.length
    for (const k2 of keys) {
      const p = after.indexOf('\n' + k2)
      if (p >= 0 && p < end) end = p
    }
    out[k] = after.slice(0, end).trim()
  }
  return out
}

const EL_MAP = { 火系: '火', 水系: '水', 土系: '土', 风系: '风', 光系: '光', 暗系: '暗', 毒系: '毒', 无系: '无', 物理: '物理' }

const skillEntries = entries.filter((e) => e.category === '技能')
console.log(`7k7k 技能条目 ${skillEntries.length} 个\n`)

const parsed = []
for (const e of skillEntries) {
  const f = parseText(e.text)
  const name = (f['技能名称'] || e.name.replace(/^多克多比技能——/, '')).trim()
  const elRaw = (f['技能属性'] || (e.breadcrumb || '').split('>').pop() || '').trim()
  const el = EL_MAP[elRaw] || elRaw.replace(/系$/, '')
  // 缩略图
  const thumbRef = (e.thumbnail ? images.find((i) => i.url === e.thumbnail) : null)
  const thumbPath = thumbRef ? path.join(BASE, thumbRef.path) : null
  parsed.push({
    name, el, elRaw,
    范围: f['技能范围'] || '', 消耗: f['技能消耗'] || '', 冷却: f['技能冷却'] || '',
    说明: (f['技能说明'] || '').replace(/\n/g, ' ').slice(0, 200),
    掉落: (f['掉落场景'] || '') + (f['掉落怪物'] ? ' / ' + f['掉落怪物'] : ''),
    url: e.url,
    thumb: thumbPath && fs.existsSync(thumbPath) ? thumbPath : null,
    thumbW: thumbRef ? thumbRef.width : null,
    thumbH: thumbRef ? thumbRef.height : null,
  })
}

// 与官方表匹配
console.log('匹配官方技能表（名字 + 元素 双重确认）：')
let exact = 0, nameOnly = 0, noMatch = 0, noThumb = 0
const matched = []
for (const p of parsed) {
  const cands = offByName.get(p.name)
  if (cands && cands.length) {
    const elHit = cands.find((c) => String(c.element).replace(/系$/, '') === p.el)
    if (elHit) { exact++; matched.push({ p, off: elHit, how: '名字+元素' }); continue }
    nameOnly++; matched.push({ p, off: cands[0], how: '仅名字' })
    continue
  }
  noMatch++
  if (!p.thumb) noThumb++
}
console.log(`  名字+元素 都对上：${exact}`)
console.log(`  只有名字对上：${nameOnly}`)
console.log(`  官方表里没有：${noMatch}（这些是 7k7k 独有的技能，或名字写法不同）`)
console.log(`  其中没有缩略图的：${noThumb}`)

console.log('\n对上的样本（前 15）：')
for (const m of matched.slice(0, 15)) {
  console.log(`  ${m.p.name.padEnd(12)} [${m.p.el}] → 官方 ${m.off.id}  ${m.how}  缩略图 ${m.p.thumbW}×${m.p.thumbH}  说明「${m.p.说明.slice(0, 30)}…」`)
}

fs.writeFileSync(path.join(ROOT, 'assets/skills-7k7k.json'), JSON.stringify({
  generated: new Date().toISOString(),
  source: '多克多比_7k7k美术资源_20260929（doco.7k7k.com/juesedaquan 采集）',
  note: '技能条目解析自详情页正文；thumb 为缩略图（技能图标）相对路径',
  count: parsed.length,
  skills: parsed.map((p) => ({ ...p, thumb: p.thumb ? path.relative(ROOT, p.thumb).replace(/\\/g, '/') : null })),
}, null, 1))
console.log('\n→ assets/skills-7k7k.json')

if (DRY) { console.log('（--dry：未写出图标）'); process.exit(0) }

// 写出图标（只写"名字+元素"都对上的，其余待人工确认）
let written = 0
for (const m of matched) {
  if (m.how !== '名字+元素') continue          // 只接双确认的，避免张冠李戴
  if (!m.p.thumb) continue
  const ext = path.extname(m.p.thumb)
  const file = `skill_icon_${m.off.id}.png`
  // 统一转 PNG 并缩到 64×64，保持与现有图标一致的规格
  const { decodePng, encodePng } = await import('./pixel-canvas.mjs')
  let img
  if (ext.toLowerCase() === '.png') img = decodePng(fs.readFileSync(m.p.thumb))
  else {
    // jpg 需要解码器 → 用 python 转
    const { execFileSync } = await import('node:child_process')
    const TMP = path.join(ROOT, '_tmp_test_out', '_7k7k_conv')
    fs.mkdirSync(TMP, { recursive: true })
    const tmpPng = path.join(TMP, path.basename(m.p.thumb) + '.png')
    execFileSync(path.join(ROOT, '_tools/py/python.exe'),
      ['-c', `from PIL import Image;Image.open(r"${m.p.thumb}").convert("RGBA").save(r"${tmpPng}")`],
      { stdio: 'ignore' })
    img = decodePng(fs.readFileSync(tmpPng))
  }
  const S = 64
  const out = new Uint8ClampedArray(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(img.w - 1, Math.floor(x * img.w / S)), sy = Math.min(img.h - 1, Math.floor(y * img.h / S))
    const si = (sy * img.w + sx) * 4, di = (y * S + x) * 4
    out[di] = img.data[si]; out[di + 1] = img.data[si + 1]; out[di + 2] = img.data[si + 2]; out[di + 3] = img.data[si + 3]
  }
  fs.writeFileSync(path.join(OUTDIR, file), encodePng(S, S, out))
  written++
}
