{"content": "// 只补"游戏没有的技能"图标；已核对的 10 个同名技能**保持官方图鉴版不动**
//
// 【为什么不覆盖】7k7k 是粉丝 wiki，图标是它的缩略图（67~73px）；
//   项目那 10 个同名技能用的是**官方图鉴**来源且已肉眼核对。
//   按 R1/R9「不许静默降级」，不能用社区图覆盖官方图 —— 想换必须显式决定。
//
// 产出：assets/skills/skill_icon_<官方ID>.png（仅新增）+ 清单
// 用法: node _tools\import-7k7k-fresh-only.mjs
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { decodePng, encodePng } from './pixel-canvas.mjs'
import vm from 'node:vm'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'assets/skills')
const BAK = path.join(ROOT, '_tmp_test_out/orig-skill-icons')
const TMP = path.join(ROOT, '_tmp_test_out/_7k7k_conv')

const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))
const k7 = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-7k7k.json'), 'utf8'))

const ctx = { window: {} }
vm.createContext(ctx)
vm.runInContext(fs.readFileSync(path.join(ROOT, 'assets/forms.js'), 'utf8'), ctx)
const gameSkills = ctx.window.__DKDbb_FORMS__.skills || {}
const gameSkillNames = new Set(Object.keys(gameSkills))

const normEl = (s) => {
  let t = String(s || '').trim().replace(/(属性|系)$/, '')
  return t
}
const byName = new Map()
for (const s of off.skills) {
  const n = s.name.replace(/\n/g, '').trim()
  if (!byName.has(n)) byName.set(n, [])
  byName.get(n).push(s)
}

// 1) 先把"已用技能的图标"从发布包恢复（它们已被 7k7k 覆盖过）
if (!fs.existsSync(BAK)) { console.log('✗ 缺少原版图标目录'); process.exit(1) }
let restored = 0
for (const f of fs.readdirSync(BAK)) {
  const dst = path.join(DIR, f)
  const src = fs.readFileSync(path.join(BAK, f))
  if (!fs.existsSync(dst) || !fs.readFileSync(dst).equals(src)) { fs.writeFileSync(dst, src); restored++ }
}
console.log(`恢复原版图标 ${restored} 个（这些技能游戏已在用，保持官方图鉴版）`)

// 2) 只写"游戏没有的技能"
fs.mkdirSync(TMP, { recursive: true })
const written = []
const skipped = []
for (const p of k7.skills) {
  const cands = byName.get(p.name)
  if (!cands) continue
  const hit = cands.find((c) => normEl(c.element) === p.el)
  if (!hit) continue
  if (gameSkillNames.has(p.name)) { skipped.push({ id: hit.id, name: p.name, why: '游戏已在用（保留官方图鉴版）' }); continue }
  if (!p.thumb) { skipped.push({ id: hit.id, name: p.name, why: '没有缩略图' }); continue }
  const kp = path.join(ROOT, p.thumb)
  if (!fs.existsSync(kp)) { skipped.push({ id: hit.id, name: p.name, why: '缩略图文件缺失' }); continue }
  // jpg → png（用 python 的 Pillow，项目已有）
  let imgPath = kp
  if (!/\.png$/i.test(kp)) {
    imgPath = path.join(TMP, path.basename(kp) + '.png')
    if (!fs.existsSync(imgPath)) {
      execFileSync(path.join(ROOT, '_tools/py/python.exe'),
        ['-c', `from PIL import Image;Image.open(r"${kp}").convert("RGBA").save(r"${imgPath}")`], { stdio: 'ignore' })
    }
  }
  const im = decodePng(fs.readFileSync(imgPath))
  const S = 64
  const out = new Uint8ClampedArray(S * S * 4)
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const sx = Math.min(im.w - 1, Math.floor(x * im.w / S)), sy = Math.min(im.h - 1, Math.floor(y * im.h / S))
    const si = (sy * im.w + sx) * 4, di = (y * S + x) * 4
    out[di] = im.data[si]; out[di + 1] = im.data[si + 1]; out[di + 2] = im.data[si + 2]; out[di + 3] = im.data[si + 3]
  }
  const file = `skill_icon_${hit.id}.png`
  fs.writeFileSync(path.join(DIR, file), encodePng(S, S, out))
  written.push({ id: hit.id, name: p.name, el: p.el, file })
}

console.log(`\n新增技能图标 ${written.length} 个：`)
for (const w of written) console.log(`  ${w.id}  ${w.name.padEnd(12)} [${w.el}]`)
console.log(`\n跳过 ${skipped.length} 个：`)
for (const s of skipped) console.log(`  ${s.id}  ${s.name.padEnd(12)}  ${s.why}`)

// 3) 更新 index.json
const idxPath = path.join(DIR, 'index.json')
const idx = JSON.parse(fs.readFileSync(idxPath, 'utf8'))
const byId = new Map(idx.icons.map((i) => [String(i.id), i]))
let added = 0
for (const w of written) {
  const rec = {
    id: w.id, name: w.name, file: `assets/skills/${w.file}`,
    from: '多克多比_7k7k美术资源_20260929（角色大全技能条目缩略图）',
    evidence: `第 55 轮：7k7k 详情页「技能名称+技能属性」与官方技能表双重确认（元素=${w.el}）`,
    element: w.el, conf: 'official', source: '7k7k',
  }
  if (byId.has(String(w.id))) Object.assign(byId.get(String(w.id)), rec)
  else { idx.icons.push(rec); added++ }
}
idx.generated = new Date().toISOString()
idx.note = (idx.note || '') + ` 第 55 轮：从 7k7k 角色大全接入 ${written.length} 个技能图标（名字+元素双确认；已用技能保持官方图鉴版）。`
fs.writeFileSync(idxPath, JSON.stringify(idx, null, 1))
console.log(`\nindex.json：新增 ${added} 条，现 ${idx.icons.length} 条`)
console.log(`assets/skills PNG：${fs.readdirSync(DIR).filter((f) => f.endsWith('.png')).length} 个`)
", "file_path": "_tools\import-7k7k-fresh-only.mjs"}

