{"content": "// 把 7k7k 那批图标按**游戏既有编号规则**改名，并生成 `assets/skill-icons-7k7k.json` 供 merge-skills3 使用
//
// 编号规则（沿用游戏既有约定，从已有 17 个图标反推）：
//   `skill_icon_<元素位><三位序号>`，元素位 1=物理 2=火 3=水 4=土 5=风。
//   序号 = 该技能在**官方元素组内**的序号（与官方 ID 后三位一致）。
//   毒在游戏里没有既有约定 → 用 6xxx。光/暗 7k7k 里没有图标 → 不动。
//
// 由来：官方 ID 301005 → 元素位 1 + 序号 005 → skill_icon_1005；
//      官方 ID 303026 → 元素位 3 + 序号 026 → skill_icon_3026（序号本就不足三位时保持原样）
//
// 用法: node _tools/gen-7k7k-icon-map.mjs
import fs from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve('.')
const DIR = path.join(ROOT, 'assets/skills')
const idxPath = path.join(DIR, 'index.json')
const idx = JSON.parse(fs.readFileSync(idxPath, 'utf8'))
const off = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets/skills-official.json'), 'utf8'))

const EL_DIGIT = { 物理: 1, 火: 2, 水: 3, 土: 4, 风: 5, 毒: 6 }
// 官方元素组 → 元素名（用于核对序号）
const SEG_EL = { 301: '物理', 302: '火', 303: '水', 304: '土', 305: '风', 306: '光', 307: '暗', 308: '毒' }

// 官方表：每个元素组内的技能顺序（用于验证"官方ID后三位 = 组内序号"）
const bySeg = new Map()
for (const s of off.skills.slice().sort((a, b) => a.id - b.id)) {
  const g = Math.floor(s.id / 1000)
  if (!bySeg.has(g)) bySeg.set(g, [])
  bySeg.get(g).push(s)
}

const targets = idx.icons.filter((i) => i.source === '7k7k')
console.log(`待改名的 7k7k 图标：${targets.length} 个\n`)

const bySkill = {}
let renamed = 0, failed = 0
for (const it of targets) {
  const idStr = String(it.id)              // 形如 "301005"
  const seg = Math.floor(Number(idStr) / 1000)
  const seq = Number(idStr) % 1000
  const el = SEG_EL[seg]
  const digit = EL_DIGIT[el]
  if (!digit) { console.log(`  ✗ ${it.name}：元素 ${el} 没有编号约定，跳过`); failed++; continue }

  // 自证：该技能在官方组内的序号确实等于官方 ID 后三位
  const list = bySeg.get(seg) || []
  const pos = list.findIndex((s) => s.id === Number(idStr))
  if (pos >= 0 && pos + 1 !== seq) {
    console.log(`  ⚠️ ${it.name}：官方 ID 后三位 ${seq} 与组内序号 ${pos + 1} 不一致（按 ID 后三位处理）`)
  }

  const gameId = `${digit}${String(seq).padStart(3, '0')}`
  const oldName = path.basename(it.file)
  const newName = `skill_icon_${gameId}.png`
  const src = path.join(ROOT, it.file)
  const dst = path.join(DIR, newName)
  if (!fs.existsSync(src)) { console.log(`  ✗ 缺文件 ${it.file}`); failed++; continue }

  // 目标已存在就不覆盖（保护已核对的原版）
  if (fs.existsSync(dst) && dst !== src) {
    const same = fs.readFileSync(dst).equals(fs.readFileSync(src))
    if (!same) {
      console.log(`  ⚠️ ${newName} 已存在且内容不同 —— 不覆盖（${it.name} 保持官方 ID 名）`)
      // 仍然登记映射，用官方 ID 名（文件留着）
      bySkill[it.name] = { gameIcon: `skill_icon_${idStr}`, officialId: Number(idStr), element: el }
      continue
    }
    fs.rmSync(src)
  } else if (dst !== src) {
    fs.renameSync(src, dst)
  }
  renamed++
  bySkill[it.name] = { gameIcon: `skill_icon_${gameId}`, officialId: Number(idStr), element: el }
  // 更新 index 记录
  it.file = `assets/skills/${newName}`
  it.gameIcon = `skill_icon_${gameId}`
  it.iconIdRule = `元素位 ${digit}（${el}）+ 组内序号 ${seq}`
}

const outPath = path.join(ROOT, 'assets/skill-icons-7k7k.json')
fs.writeFileSync(outPath, JSON.stringify({
  generated: new Date().toISOString(),
